L["Intro Text"] = "有些故事始于一封信、一则传闻、一位失踪的旅人，或是在镇子边缘被人悄声提起的一个名字。\n\nStory Mode将这些故事汇集起来，按章节逐一展开：从哪里开始，还有什么在等待，以及你已经见证过什么。\n\n已完成的章节会保存在你的日志中，静静记录下你遇见的人、你直面的危险，以及那些值得铭记的名字。\n\n重温你的冒险。"
L["Intro Text Complete"] = "所有标记的故事均已完成。信件、警告、失落的名字、隐秘的赞助人、地下城之门、家族旧债和奇异的宝藏，如今都汇聚在你的日志之中。\n\n这绝非易事。你追寻每一条线索，回应每一次召唤，将每一个章节坚持到底，直到一堆零散的传闻化作一部由你亲手铸就的功绩录。\n\n就让这本日志成为证明：这些故事不只是被发现，更是被完成、被铭记，并化为你冒险的一部分。"

