L["Scarlet Share Hint"] = "Shift+点击分享你的账簿"
L["Scarlet Link Compare Format"] = "对方的账簿：|cffe62929%d|r。你的：|cffffd200%d|r。"
L["Scarlet Ledger Korgal"] = "迈文·考加尔曾为丧钟镇的亡者传递死讯。而他自己的死讯，不会有人传递。"
L["Scarlet Ledger Perrine"] = "派瑞恩队长曾在布瑞尔的眼皮底下操练部下。如今，操练已经停了。"
L["Scarlet Ledger Vachon"] = "瓦松队长的营地依然矗立。营中却再无一物站立。"
L["Scarlet Ledger Melrache"] = "麦拉其队长向部下承诺，圣光会庇护他们。圣光却只是旁观。"
L["Scarlet Ledger Balnazzar"] = "大十字军战士不过是一件法衣。你已经见过披着它的究竟是什么。布道声却依旧回荡。"
L["Scarlet Ledger Radley"] = "猎人莱德雷追踪过这片田野上所有会动的东西。他却从未听见你的动静。"
L["Scarlet Ledger Durgen"] = "骑士杜尔根曾在壁炉谷的旗帜下策马出征。他的马独自回来了。"
L["Scarlet Ledger Abbendis"] = "阿比迪斯将军躲在高墙之后统领提尔之手。可高墙终有尽头。"
L["Scarlet Ledger BenedictusVoss"] = "高阶牧师本尼迪塔斯·沃斯把女儿献给了信条。这笔债，轮不到你来讨。"
L["Scarlet Ledger Thalnos"] = "血法师萨尔诺斯守护着他所属教团最古老的秘密。坟墓却没有替他守住任何秘密。"
L["Scarlet Ledger Vishas"] = "审讯员韦沙斯再也不会提问了。你却仍能听见沃瑞尔的声音。"
L["Scarlet Ledger Loksey"] = "驯犬者洛克希死在他的猎犬之间。它们对他的哀悼，胜过十字军所能给予的一切。"
L["Scarlet Ledger Doan"] = "奥法师杜安守护着不许任何人阅读的书籍。如今，图书馆更安静了。"
L["Scarlet Ledger Herod"] = "赫洛德，血色勇士。新兵们曾为他的名字欢呼。如今已无人欢呼。"
L["Scarlet Ledger Mograine"] = "雷诺·莫格莱尼倒在了他自己的祭坛前。无论他在为何赎罪，都远远不够。"
L["Scarlet Ledger Fairbanks"] = "大检察官法尔班克斯被封在一道假石墙之后。十字军总是把它的真相埋葬两次。"
L["Scarlet Ledger Whitemane"] = "她向圣光祈求，圣光回应了她。你已不再追问为什么。"
L["Scarlet Ledger Courier"] = "红衣信使的信件，如今再也送不到任何地方。"
L["Scarlet Ledger Demetria"] = "血色先知预见了许多事。却没有预见这条路，更没有预见你。"
L["Scarlet Section 100"] = "一个人的战争"
L["Scarlet Section 250"] = "节奏"
L["Scarlet Section 500"] = "镜子"
L["Scarlet Section 1000"] = "牧师之女"
L["Scarlet Tab Body 250"] = "这场战争如今有了节奏。你熟悉狂热者的祷告戛然而止时发出的声响。你知道他们在哪些道路上巡逻，又已经洗劫了哪些农舍。在提瑞斯法的某处，那位老妇人的提灯已经熄灭——你经过了它曾经亮着的那扇窗台，却没有停下脚步。\n\n你告诉自己，这些数字仍有意义。可你已不再核对总数。"
L["Scarlet Tab Body 500"] = "你已不再记得那些面孔。红色战袍、银色火焰、被打断的祷告——这些细节一出现，就已被归档。令你不安的不是数字，而是杀戮变得如此干净利落：不再有愤怒，也不再有悲伤。只剩下那本账簿，等着被结清。\n\n怀特迈恩的狂热者们相信，笃信就等于正义。在最难熬的夜里，你还没来得及说清两者有何不同，就已沉沉睡去。"
L["Scarlet Tab Body 1000"] = "十字军不只招募，还亲手培养。在你清剿的营地里，在你随手丢弃的信件中，一个名字开始浮现：一位牧师的女儿，在修道院的高墙后长大，学会了焚烧死者而面不改色。莉莉安。她的父亲——高阶牧师本尼迪塔斯·沃斯——把亲生骨肉献给了信条，就像别人缴纳什一税一样。据说她双手合十、宛如祈祷，也能取人性命。据说她从未问过一句为什么。\n\n总有一天，十字军会看着她，看到它在每一个无法利用之人身上看到的东西：感染。那一天发生的事并非出自你手——但你会比世上任何人都更明白其中的缘由。\n\n记住沃斯这个名字。账簿上的这一页还没有翻过去，你也还没有。"
L["Scarlet Tab Body"] = "你并非一开始就想成为他们的敌人。\n\n一切开始得悄无声息。你偶然路过提瑞斯法一座被焚毁的农舍。一位老妇人对着她为儿子点亮的提灯哭泣。她说，他穿上了红色战袍，就再也没有回过她的信。十字军教会了他一段新的祷词，而那段祷词里容不下她的名字。\n\n后来，是一个躲在南海镇外芦苇丛中的男孩，头发上沾着礼拜堂的灰烬。接着，是路上的一位商人，被一柄正义之剑砍得血流不止。再然后，是倒在自家门前的农夫。你告诉自己，这只是巧合。但每当一面红色旗帜映入眼帘，你的手总是先于意识动了。你每击倒一名血色十字军，就越发觉得这不像战争，而更像算术——向一个披着银色光芒的谎言清算的一笔债。\n\n你从未在任何信中写下这件事。也没有哪位指挥官给你下达过这项任务。没有命令，没有特许状，没有誓言。只有一份在沉默中记下的账目，不断增长。\n\n你是一名血色十字军战士——取这个词更古老的含义。不是他们的一员，而是与他们为敌的那一个。你斩倒的每一件红色战袍，都是又一个被记入账簿的名字，而那本账簿除了你，无人能读。"

