L["A \"Humble\" Request"] = "“卑微的”请求"
L["A Beastly Expedition"] = "兽性的探索"
L["A Better Future"] = "光明的前途"
L["A Big Score"] = "大收获"
L["A Bit of Chaos"] = "一点混乱"
L["A Bit of Espionage"] = "谍报先锋"
L["A Bitter Reunion"] = "苦涩的重聚"
L["A Body of Evidence"] = "特工尸体"
L["A Brewing Situation"] = "酿酒问题"
L["A Burden Shared"] = "休戚与共"
L["A Burning Distraction"] = "混淆视听"
L["A Challenge From Our Enemies"] = "敌人的挑衅"
L["A Change of Seasons"] = "季节的变换"
L["A Chilling Summons"] = "冰冷的召唤"
L["A Cold Front Approaches"] = "冷锋逼近"
L["A Conjuror's Duty"] = "大咒术师的责任"
L["A contagion strikes the Broken Shore. Cure the plague, recruit Aelthalyste, and seek the High Priest's Seeker mount."] = "破碎海滩爆发了一场传染病。治愈瘟疫，招募艾萨莱斯特，并寻得大牧师的探寻者坐骑。"
L["A courier brought word of Thas'dorah — the ancestral bow of the Windrunner family, carried by Alleria into the Twisting Nether and lost for decades. You followed the trail through ancient elven ruins, fighting off demons who sought to claim its power. The bow sang in your hands when you drew it, as if it had been waiting for a worthy archer all along."] = "一名信使带来了萨斯多拉的消息——那是风行者家族世代相传的长弓，曾被奥蕾莉亚带入扭曲虚空，从此失落了数十年。你循着线索穿过古老的精灵遗迹，击退了企图夺取其力量的恶魔。当你拉开弓弦时，长弓在你手中低吟，仿佛它一直在等待一位配得上它的弓手。"
L["A Courteous Guest"] = "谦谦来客"
L["A Covert Operation"] = "隐秘行动"
L["A cryptic summons led you into the sewers beneath Dalaran, where Lord Jorach Ravenholdt revealed The Uncrowned — a secret order of assassins operating outside the law. You proved your worth in the shadows and claimed a blade befitting the order's newest operative."] = "一封神秘的召唤信将你引入达拉然地下的下水道，乔拉齐·拉文霍德公爵在那里向你揭示了无冕者——一个游走于法律之外的秘密刺客组织。你在阴影中证明了自己的价值，并获得了一把与这个组织最新成员相称的利刃。"
L["A Culling of Souls"] = "灵魂甄选"
L["A Curious Contagion"] = "奇怪的传染病"
L["A curious contagion swept the Broken Shore — a plague that twisted both body and spirit. Aelthalyste, a banshee who had rediscovered her faith, helped you trace the disease to its source, craft a cure, and administer it to the fallen. With the contagion contained and Aelthalyste as your newest champion, you answered a final call to the Sunken Vault, where a creature of pure Light awaited — the High Priest's Seeker, a mount that would carry you above the battlefield."] = "一场奇怪的传染病席卷了破碎海滩——这种瘟疫会同时扭曲肉体与灵魂。重拾信仰的女妖艾萨莱斯特协助你追查病源、调制解药，并为倒下的人施治。传染病得到控制，艾萨莱斯特也成为了你最新的勇士。随后，你响应了最后的召唤，前往沉没宝库，一个由纯粹圣光构成的生物正在那里等待着你——那便是大牧师的探寻者，一头将载着你翱翔于战场上空的坐骑。"
L["A Cycle of Hatred"] = "仇恨循环"
L["A damaged Titan Keeper has been protecting the swamp's darkest secret — a proto-god of blood and shadow sealed beneath the earth."] = "一位受损的泰坦守护者一直守护着这片沼泽最黑暗的秘密——一位被封印在地下、执掌鲜血与暗影的原始神祇。"
L["A Dance With Dragons"] = "与龙共舞"
L["A Daring Rescue"] = "冒险救援"
L["A dark curse has fallen over Drustvar. Lord Waycrest has vanished, his lady has withdrawn behind manor walls, and old stories about witches have begun walking through the woods again.\n\nJoin Lucille Waycrest and the Order of Embers as they follow the coven's trail through cursed villages, haunted fens, and a land where buried grudges have a way of clawing back to the surface."] = "黑暗的诅咒笼罩了德鲁斯瓦。维克雷斯勋爵下落不明，他的夫人退隐于庄园高墙之后，那些关于女巫的古老传说也再度在林间游荡。\n\n加入露希尔·维克雷斯和灰烬骑士团，追寻女巫集会的踪迹，穿过被诅咒的村庄与闹鬼的沼泽。在这片土地上，被埋葬的宿怨总有办法重新爬回地面。"
L["A Daughter's Embrace"] = "女儿的拥抱"
L["A Deadly New Ally"] = "致命的新盟友"
L["A Defias plot has surfaced inside Stormwind's own walls, and Master Shaw needs someone he can trust to follow it to the source. The old grievances that shaped the Deadmines have not vanished just because the kingdom moved on.\n\nTrace the conspiracy through Stormwind's streets and forgotten debts, and decide what kind of human history is worth honoring when the past asks to be heard again."] = "一场迪菲亚阴谋在暴风城的城墙之内浮出水面，肖尔大师需要一个他信得过的人追查到底。造就死亡矿井的那些旧怨，并没有因为王国继续前行而烟消云散。\n\n在暴风城的大街小巷与被遗忘的旧债中追查这场阴谋。当往事再次要求被倾听之时，由你来决定哪一段人类的历史值得尊崇。"
L["A Desecrated Temple"] = "被亵渎的神庙"
L["A Display of Power"] = "展示力量"
L["A dying sprite's plea reveals mogu rituals at the Terrace of Ten Thunders and the spirits trapped beneath them."] = "一只垂死精灵的哀求，揭示了魔古族在十雷台举行的仪式，以及被困于其下的灵魂。"
L["A Final Offer"] = "最后的提议"
L["A Fitting Reward"] = "合适的奖励"
L["A Forlorn Hope"] = "被遗弃的希望"
L["A Friend of the Frogs"] = "青蛙之友"
L["A Friendly Accord"] = "合算的计划"
L["A Gathering of Champions"] = "勇士的会议"
L["A girl is singing by herself at an empty homestead. She asks you to find her stuffed animals for a tea party. As you collect each one, she recites little rhymes about what happened to the people who used to live here. The rhymes are not comforting."] = "一个女孩独自在一座空荡荡的农庄里唱歌。她请你帮她找回毛绒玩具，好举办一场茶话会。每找到一个玩具，她都会念一首小童谣，讲述曾经住在这里的人们遭遇了什么。这些童谣可一点也不让人宽心。"
L["A Glade Defense"] = "防守林地"
L["A Glimpse of Terror"] = "恐怖窥探"
L["A Glorious Reunion"] = "荣耀的再会"
L["A goblin named Patch and a crew of demolitions experts blast a way through the blood troll defenses."] = "一个名叫补丁的地精带着一队爆破专家，在血巨魔的防线上炸开了一条路。"
L["A Godly Invitation"] = "神之邀约"
L["A Golden Ticket"] = "金色的信"
L["A Grim Portent"] = "恐怖征兆"
L["A Growing Crisis"] = "日益严重的危机"
L["A Hero Remains"] = "弥留的英雄"
L["A Hero's Weapon"] = "英雄的武器"
L["A hooded figure is paying coin inside the Scarlet Halls — silver for Scarlet blood. She wants their membership records. She calls herself the Hooded Crusader, and she is very thorough."] = "一个蒙面人正在血色大厅里悬赏——用银币换取血色十字军的鲜血。她想要他们的成员名册。她自称蒙面的十字军战士，而且做事一丝不苟。"
L["A hooded priestess summons you to Netherlight Temple, where Alonsus Faol — the founder of the priesthood — reveals himself."] = "一位戴着兜帽的女祭司召唤你前往虚空之光神殿，牧师组织的创始人阿隆索斯·法奥在那里现出了真身。"
L["A Humble Offering"] = "寒酸的供品"
L["A Hungry Heritage"] = "饥饿遗产"
L["A Legend You Can Hold"] = "称手神兵"
L["A Lesson in Humility"] = "谦卑之训"
L["A Lesson in Witch Hunting"] = "猎巫经验"
L["A Light in the Darkness"] = "黑暗曙光"
L["A Line in the Sand"] = "划清界限"
L["A little girl stands alone at Glenbrook Homestead, singing a nursery rhyme about her empty village. The chimneys are still warm, the tables are still set, and the silence feels much too fresh.\n\nShe only wants help preparing a tea party: a few toys, a missing cat, and one more guest. In Drustvar, even the smallest errands can carry a shadow longer than the road ahead."] = "一个小女孩独自站在格伦布鲁克农庄，唱着一首关于她那空荡荡村庄的童谣。烟囱还是暖的，餐桌上的餐具还摆着，这片寂静来得太过突然。\n\n她只想请人帮忙准备一场茶话会：几个玩具、一只走失的猫，还有一位客人。在德鲁斯瓦，即便是最微不足道的差事，投下的阴影也可能比前方的路还要长。"
L["A Local Guide"] = "当地向导"
L["A Long Walk"] = "漫长的路程"
L["A Mage's Weapon"] = "法师的武器"
L["A Magical Glow"] = "魔幻萤光"
L["A Mark For A Protector"] = "守护者的印记"
L["A Matter of Finesse"] = "方法才是关键"
L["A Message From Ly'leth"] = "莉莉丝的消息"
L["A Message From Our Enemies"] = "敌人的消息"
L["A Message of Blood and Fire"] = "血与火的信息"
L["A Mile in My Shoes"] = "设身处地"
L["A More Wretched Hive of Scum and Villainy"] = "恶上加恶"
L["A mysterious courier delivers an urgent summons to the sewers beneath Dalaran, where a secret order of assassins watches from the shadows."] = "一位神秘的信使送来紧急召唤，将你引向达拉然地下的下水道，一个秘密刺客组织正在那里的阴影中暗暗注视。"
L["A mysterious paladin appeared with word of the Silver Hand — the holy mace wielded by the first paladins of Lordaeron. You followed the trail through ancient crypts and sacred sites, facing trials that tested your faith as much as your strength. The Silver Hand pulsed with warmth when you finally held it, and the spirits of the original knights seemed to nod in approval."] = "一位神秘的圣骑士带来了白银之手的消息——那是洛丹伦最初的圣骑士们挥舞的神圣战锤。你循着线索穿过古老的墓穴与圣地，经受了既考验信仰也考验力量的试炼。当你终于握住白银之手时，它散发出温暖的脉动，最初那批骑士的英灵似乎也在点头赞许。"
L["A mysterious priestess led you through a portal to Netherlight Temple, a sanctuary floating in the Twisting Nether between the forces of Light and Void. There, Alonsus Faol — the man who had founded the original priesthood of Lordaeron — revealed he had survived as an undead, guiding the faith from the shadows for centuries. Prophet Velen stood beside him, and together they asked you to lead a new Conclave. Calia Menethil and High Priestess Ishanah pledged as your first champions."] = "一位神秘的女祭司带你穿过传送门，来到虚空之光神殿——一座漂浮在扭曲虚空之中、介于圣光与虚空之力之间的圣所。在那里，阿隆索斯·法奥——洛丹伦最初的牧师组织的创立者——表明他以亡灵之身存活了下来，数百年来一直在暗中引导着信仰。先知维伦站在他身旁，两人一同请求你领导一个新的议会。佳莉娅·米奈希尔和高阶女祭司伊莎娜宣誓成为你最初的勇士。"
L["A Nation Divided"] = "分裂的国度"
L["A Nation United"] = "统一的国度"
L["A New Beginning"] = "新的开始"
L["A New Order"] = "新的组织"
L["A New Tradition"] = "新传统"
L["A New Vision"] = "新的视界"
L["A Pact of Necessity"] = "必要的选择"
L["A Pact With Death"] = "与死亡的契约"
L["A Particularly Potent Potion"] = "威力超强的药水"
L["A People in Need of Healing"] = "需要治愈的人民"
L["A People Shattered"] = "支离破碎"
L["A Perfect Match"] = "绝配"
L["A Personal Request"] = "私人请求"
L["A pirate legend speaks of cursed cutlasses buried with their last captain. Fleet Admiral Tethys knows the way."] = "一则海盗传说提到，一批受诅咒的弯刀与它们的最后一任船长葬在一起。舰队上将特塞斯知道该怎么去。"
L["A Plea to Revendreth"] = "向雷文德斯求助"
L["A Plea to the Harvesters"] = "向收割者的请求"
L["A Promise of Earth"] = "大地的许诺"
L["A Proper Disguise"] = "合身伪装"
L["A Proper Weapon"] = "称手的武器"
L["A Pungent Solution"] = "刺鼻的计划"
L["A Re-Warding Effort"] = "实用结界"
L["A Reflection of Truth"] = "镜中真影"
L["A Revealing Missive"] = "揭秘信函"
L["A Ring Reforged"] = "重铸大地之环"
L["A Ring Unbroken"] = "不屈的大地之环"
L["A Royal Escort"] = "皇家护卫"
L["A Royal Key"] = "皇家钥匙"
L["A Scarlet Letter"] = "血色信件"
L["A Second Weapon"] = "第二件武器"
L["A secret order of rogues operates from the shadows beneath Dalaran. The Uncrowned do not rule kingdoms, but they know where every kingdom keeps its secrets.\n\nAs the order's newest blade in the dark, gather legendary tools, follow a conspiracy through trusted halls, and learn who can still be trusted when everyone is trained to lie."] = "一个秘密的盗贼组织在达拉然地下的阴影中活动。无冕者并不统治王国，但他们知道每个王国把秘密藏在哪里。\n\n作为该组织在黑暗中最新的一把利刃，你要收集传奇武器，追查一场深入受信任殿堂的阴谋，并在人人都受过说谎训练的情况下，弄清还有谁值得信任。"
L["A secret society of rogue mages is hoarding dangerous knowledge. Infiltrate their ranks with Ravandwyr and Esara Verrinde."] = "一个由叛变法师组成的秘密结社正在囤积危险的知识。与拉文德维尔和艾莎拉·维林德一同潜入他们的队伍。"
L["A Short Fuse"] = "引线太短"
L["A Signal in Storm Peaks"] = "风暴峭壁内的信号"
L["A Simple Experiment"] = "一次简单的试验"
L["A Simple Plan"] = "简单计划"
