L["A Small Retreat"] = "小屋"
L["A Sound Plan"] = "计划周全"
L["A Special Delivery"] = "特别快递"
L["A Steady Ballast"] = "可靠的巴拉斯塔"
L["A Steady Hand"] = "稳健的双手"
L["A Stroll Through a Cemetery"] = "墓园漫步"
L["A Strong Back"] = "强壮的后背"
L["A Strong Right Hand"] = "强力助手"
L["A Summon to Orgrimmar"] = "奥格瑞玛的召唤"
L["A Summons From Moonglade"] = "月光林地的召唤"
L["A Tale of Valor"] = "勇气的传说"
L["A Taste of Freedom"] = "品尝自由"
L["A Tea Party"] = "茶话会"
L["A Terrible Loss"] = "巨大损失"
L["A Test of Endurance"] = "耐力的试炼"
L["A Thirst For Blood"] = "渴望鲜血"
L["A Thorn in Our Side"] = "如芒在背"
L["A Time of Revelation"] = "天启之时"
L["A Tribute for Death"] = "死神贡品"
L["A True Loa Feast"] = "神之盛宴"
L["A Tundra Conundrum"] = "苔原难题"
L["A United Force"] = "团结的力量"
L["A United Front"] = "统一战线"
L["A val'kyr claims you worthy of Odyn's attention. You ascend to Skyhold, the warrior paradise above the clouds, and take up a weapon of legend."] = "一位瓦格里宣称你配得上奥丁的关注。你登上苍穹要塞——云端之上的战士天堂，并拿起了一件传奇武器。"
L["A Very Special Kind of Fuel"] = "特殊燃料"
L["A Visit to the Doctor"] = "看医生"
L["A Visit with Lorewalker Cho"] = "拜访游学者周卓"
L["A Voice in the Dark"] = "黑暗中的声音"
L["A Walk with Ghosts"] = "往日阴影"
L["A Warrior's Death"] = "战士之死"
L["A Way Out"] = "逃脱之路"
L["A Weapon of Old"] = "古老的武器"
L["A Weather Eye"] = "雄鹰之眼"
L["A Well Placed Portal"] = "恰到好处的传送门"
L["A Window to the Past"] = "往事如昨"
L["A Worthy Blade"] = "称手武器"
L["A Worthy Offering"] = "适合的贡品"
L["A'dal"] = "阿达尔"
L["Abby has vanished. You find a village register — nearly every name crossed out. Three people may still be alive: the Hayeses and Samuel Hawthorne. They are not. Then Abby reappears, lights the candles, pours the tea, and introduces the last guest."] = "艾比失踪了。你找到一本村庄名册——几乎每个名字都被划掉了。也许还有三个人活着：海耶斯一家和萨缪尔·霍索恩。然而他们都已不在人世。随后，艾比再次出现，点亮蜡烛，倒好茶，并介绍了最后一位客人。"
L["Abby Lewis"] = "艾比·刘易斯"
L["Abby Lewis stood alone at Glenbrook Homestead, singing softly to herself. The houses were abandoned. The village was silent. She said she just wanted friends for a tea party — three stuffed animals: Mr. Munchykins, Trunksy, and Mayor Striggs. You found them, each one near a place where something had clearly gone very wrong. Abby appeared each time to recite a cheerful little rhyme. The rhymes were about the dead."] = "艾比·刘易斯独自站在格伦布鲁克农庄，轻声唱着歌。房屋早已废弃，村庄一片死寂。她说她只是想为茶话会找些朋友——三只毛绒玩具：芒奇金斯先生、特朗克西和斯崔格斯镇长。你找到了它们，每一只都在某个显然出过可怕事情的地方附近。每一次，艾比都会出现，念一首欢快的小童谣。而这些童谣，讲的都是死者。"
L["Above the ice, at the roof of the world, the Frozen Throne waits. The Ashen Verdict — Argent Crusade and Ebon Blade, bound by a single purpose — stands at the citadel's door. Highlord Tirion Fordring lifts the Ashbringer. Every victory in Northrend, every fallen soldier, every mile of ground bought in blood has led here. One way or another, the reign of Arthas Menethil ends at the summit."] = "在冰原之上、世界之巅，冰封王座正静静等待。灰烬审判军——因同一目标而结盟的银色北伐军与黑锋骑士团——已兵临城堡门前。大领主提里奥·弗丁高举灰烬使者。诺森德的每一场胜利、每一位阵亡的士兵、每一寸用鲜血换来的土地，都指向此处。无论如何，阿尔萨斯·米奈希尔的统治都将在巅峰终结。"
L["Absalan the Pious"] = "虔诚的阿布萨兰"
L["Absolon"] = "阿布索伦"
L["Ace Pilot Stormcog"] = "王牌飞行员斯托姆考格"
L["Acherus / Broken Isles"] = "阿彻鲁斯 / 破碎群岛"
L["Acid Beats Paper"] = "酸溅纸溶"
L["Acid Rain"] = "酸雨"
L["Actions on Azeroth"] = "艾泽拉斯总动员"
L["Additional Accoutrements"] = "额外配备"
L["Admiral Taylor"] = "海军上将泰勒"
L["Advancing the War Effort"] = "战火激烈"
L["Advisor Belgrum"] = "顾问贝尔格拉姆"
L["Advisor Sevel"] = "顾问塞维尔"
L["Aegira"] = "艾吉拉"
L["Aegrim's Study"] = "艾格利姆的书房"
L["Aelthalyste"] = "艾萨莱斯特"
L["Aerylia"] = "艾瑞莉娅"
L["Aethas Sunreaver"] = "艾萨斯·夺日者"
L["After Baine's rescue, the Horde fractured completely. Some followed Saurfang to Razor Hill, others remained loyal to Sylvanas in Orgrimmar. The stage was set for the final confrontation — not between Alliance and Horde, but within the Horde itself."] = "贝恩获救之后，部落彻底分裂。一些人追随萨鲁法尔前往剃刀岭，另一些人则留在奥格瑞玛，继续效忠希尔瓦娜斯。最终对决的舞台已经搭好——但这场对决并非发生在联盟与部落之间，而是在部落内部。"
L["After the fall of Lordaeron, Saurfang had surrendered to the Alliance rather than flee with Sylvanas. Now Nathanos was dispatched to retrieve him — or ensure he stayed quiet. You tracked the old orc through layers of Alliance intelligence, pieced together where he was held, and extracted him. Saurfang walked out of Stormwind on his own two feet, not as anyone's prisoner. He thanked Nathanos without warmth. Whatever he was planning, it wasn't a return to Sylvanas's service."] = "洛丹伦陷落后，萨鲁法尔选择向联盟投降，而不是随希尔瓦娜斯撤离。如今，纳萨诺斯奉命将他带回——或者确保他永远闭嘴。你抽丝剥茧地追查联盟的层层情报，拼凑出这位老兽人被关押的地点，并将他救了出来。萨鲁法尔是自己走出暴风城的，不是任何人的囚犯。他向纳萨诺斯道谢，语气却毫无温度。无论他在谋划什么，都不是重新为希尔瓦娜斯效力。"
L["Against Magatha's Will"] = "违背玛加萨的意志"
L["Against the Giants"] = "对抗巨人"
L["Agent Render"] = "特工伦德尔"
L["Aggra"] = "阿格娜"
L["Agmar's Hammer"] = "阿格玛之锤"
L["Agony Abounds"] = "痛苦不堪"
L["Aka'magosh"] = "历久弥新"
L["Alchemist Korlya"] = "炼金师科瑞娅"
L["Aldrachi Warblades"] = "奥达奇战刃"
L["Alexstrasza the Life-Binder"] = "阿莱克丝塔萨，生命的缚誓者"
L["All Aboard!"] = "全体登船！"
L["All Along the Waterways"] = "水路通行"
L["All Hail Roanauk!"] = "洛纳乌克万岁！"
L["All In"] = "孤注一掷"
L["All the threads came together when the Legion launched a full assault on Dalaran itself, breaching the Violet Hold with demonic forces. Halduron Brightwing helped you forge new weapons and prepare defenses, while Shandris Feathermoon rallied reinforcements. You led the Unseen Path into the Violet Hold and faced Hakkar the Houndmaster in a battle that shook the city. When the demon fell, Emmarel Shadewarden bestowed upon you the title of Huntmaster — the highest honor the Unseen Path could give."] = "当燃烧军团对达拉然发动全面进攻、以恶魔大军攻破紫罗兰监狱时，所有线索终于汇聚到了一起。哈杜伦·明翼协助你锻造新武器、布置防御，珊蒂斯·羽月则召集了援军。你率领隐秘之路攻入紫罗兰监狱，与驯犬者哈卡展开了一场震撼全城的激战。恶魔倒下后，伊墨瑞尔·影卫授予你狩猎大师的称号——这是隐秘之路所能给予的最高荣誉。"
L["All We Can Spare"] = "竭尽所能"
L["Allari the Souleater"] = "食魂者阿莱利"
L["Allegiance of Flame"] = "火焰联盟"
L["Alliance"] = "联盟"
L["Alliance city call-up"] = "联盟主城征召"
L["Allies of the Light"] = "圣光之友"
L["Alonsus Faol"] = "阿隆索斯·法奥"
L["Alonsus Faol sensed whispers in the Void — disturbances emanating from Azsuna that threatened the balance of Netherlight Temple itself. Prophet Velen sent his best: Zabra Hexx, a shadow priest of the Darkspear, and Yalia Sagewhisper, a Pandaren healer of quiet wisdom. Together you investigated the source, dealing with murloc mind control and disrupted ley lines. Both proved their worth and joined your Conclave as champions."] = "阿隆索斯·法奥察觉到虚空中的低语——来自阿苏纳的扰动，甚至威胁到了虚空之光神殿自身的平衡。先知维伦派出了他最得力的人选：暗矛巨魔暗影牧师扎布拉·海克斯，以及睿智沉静的熊猫人治疗者雅丽亚·圣言者。你们一同追查源头，一路上对付了遭受精神控制的鱼人，处理了紊乱的魔网。两人都证明了自己的价值，作为勇士加入了你的议会。"
L["Alonsus Faol spoke of Natalie Seline — a brilliant priest who had studied the Void so deeply that it had consumed her. She was trapped in a shadow realm between worlds, and only you could reach her. With Micah Belford guiding you through the darkness, you entered the Void itself and found Seline — transformed, but not lost. She returned to the Conclave carrying shadows that whispered secrets even the Light could not reveal."] = "阿隆索斯·法奥提到了娜塔莉·塞林——一位才华横溢的牧师，她对虚空钻研得太深，最终被其吞噬。她被困在世界之间的暗影领域，只有你才能触及她。在米该亚·贝尔福德的引导下，你穿过黑暗，进入虚空本身，找到了塞林——她已经改变，却并未迷失。她回到了议会，随身带回的暗影低语着连圣光都无法揭示的秘密。"
L["Alonsus Faol spoke of T'uure — a crystal of pure Light created by the naaru themselves, said to be a beacon that could pierce any darkness. You followed a vindicator's plea to its resting place and fought through the shadows to claim it. When T'uure's light filled the room, every wound healed, every doubt faded, and the darkness recoiled."] = "阿隆索斯·法奥提到了图雷——一枚由纳鲁亲手创造的纯净圣光水晶，据说是能够穿透一切黑暗的道标。你循着一位守备官的求助找到了它的安息之地，杀出重重暗影将其夺取。当图雷的光芒充满整个房间时，所有伤口尽皆愈合，所有疑虑烟消云散，黑暗也随之退却。"
L["Alpha Bat"] = "蝠群之首"
L["Already Among Us"] = "肘腋之患"
L["Altar Keeper Biehn"] = "祭坛守护者别恩"
