L["An Ancient Legend"] = "古老的传说"
L["An ancient vrykul artifact holds the key to unmasking the enemy. The search leads through the haunted halls of Black Rook Hold."] = "一件古老的维库人神器是揭开敌人真面目的关键。搜寻之路将穿过黑鸦堡垒那闹鬼的厅堂。"
L["An Artificer's Appeal"] = "技师的恳请"
L["An eagle leads you to Trueshot Lodge, where the Unseen Path — an ancient order of hunters — calls you to serve as champion."] = "一只雄鹰将你引至神射手营地。古老的猎人组织隐秘之路在此召唤你，请你成为他们的勇士。"
L["An Elven Problem"] = "精灵的麻烦"
