L["An Undead's Best Friend"] = "亡灵的好朋友"
L["An Uneventful Stroll"] = "悠闲漫步"
L["An Unexpected Advantage"] = "意外之喜"
L["An Unexpected Message"] = "意外讯息"
L["An unexpected message revealed the location of Felo'melorn — the legendary sword of the Sunstrider dynasty, lost when Kael'thas fell. You traced it to the frozen depths of Icecrown, where it had lain since Arthas shattered it in single combat. You reforged the blade in phoenix fire and carried it from the ice, its flames burning hotter than ever — as if centuries of cold had only made it angrier."] = "一条意外讯息揭示了费罗米伦的下落——逐日者王朝的传奇之剑，自凯尔萨斯陨落后便不知所踪。你一路追查到冰冠冰川的冰封深处，自从阿尔萨斯在单挑中将其击碎，它就一直躺在那里。你以凤凰之火重铸了这把剑，将它带离冰原，剑上的火焰比以往任何时候都更加炽烈——仿佛数百年的严寒只让它更加愤怒。"
L["An Unexpected Visitor"] = "意外到访"
L["An unexpected visitor brought troubling news — a secret society called the Empyrean Society was gathering forbidden knowledge across the Broken Isles. Ravandwyr, apprentice to the missing Archmage Vargoth, led you on a covert infiltration of their ranks. With Esara Verrinde's help, you discovered the Society had been experimenting with powers far beyond their control. You shut them down from the inside, but the trail left behind raised a darker question — where was Archmage Vargoth?"] = "一位意外到访的客人带来了令人不安的消息——一个名为天穹学会的秘密组织正在破碎群岛各地搜罗禁忌知识。失踪的大法师瓦格斯的学徒拉文德维尔带领你秘密潜入了他们的组织。在艾莎拉·维林德的帮助下，你发现学会一直在试验远超其掌控能力的力量。你从内部瓦解了他们，但留下的线索引出了一个更加阴暗的问题——大法师瓦格斯究竟身在何处？"
L["An Unlikely Ally"] = "意外的盟友"
L["An Unlikely Informant"] = "不寻常的线人"
L["An Urgent Gathering"] = "紧急集结"
L["An Urgent Matter"] = "紧急军务"
L["An Urgent Plea"] = "迫切的恳求"
L["An Urgent Situation"] = "事态紧急"
L["An Windfur"] = "安·风裘"
L["Ancestors and Enemies"] = "先祖与敌人"
L["Ancient Armor, Ancient Mystery"] = "古代铠甲，上古之谜"
L["Ancient Curses"] = "远古诅咒"
L["Ancient Magic"] = "远古魔法"
L["Ancient Mana"] = "远古魔力"
L["Ancient Power"] = "上古力量"
L["Ancient Statue"] = "古代雕像"
L["Ancient Tablet"] = "上古石板"
L["And a Heavy Fist"] = "沉重的拳头"
L["And Justice For All"] = "伸张正义"
L["And They Will Tremble"] = "他们将会颤抖"
L["Anduin Wrynn"] = "安度因·乌瑞恩"
L["Anduin's Decision"] = "安度因的决择"
L["Angrathar. The black gate beyond which the Lich King's frozen fortress waits. Bolvar Fordragon has gathered every shield the Alliance can spare. Dragons circle above. Somewhere to the east, the Horde marches its own road to the same gate. Ahead, the Scourge stands in ranks that do not end. This is the road to the Lich King's door."] = "安加萨。这扇漆黑的大门之后，便是巫妖王的冰封要塞。伯瓦尔·弗塔根集结了联盟所能调动的每一面盾牌。巨龙在头顶盘旋。东方某处，部落正沿着自己的道路向同一扇大门进军。前方，天灾军团的阵列绵延无尽。这就是通往巫妖王门前的道路。"
L["Angrathar. The Wrathgate. The final road to the Lich King's own door. Saurfang the Younger takes point, every Orc behind him blood-mad and ready for the reckoning. Somewhere to the west, the Alliance marches under a brittle truce toward the same gate. Above, dragons circle on wings of red flame. Whatever happens at this gate, the world will remember it."] = "安加萨。天谴之门。通往巫妖王门前的最后一段路。小萨鲁法尔一马当先，身后的每一个兽人都杀红了眼，准备迎接清算之时。西方某处，联盟在脆弱的停战协议下向同一扇大门进军。头顶上，巨龙展开燃着红焰的双翼盘旋。无论这扇门前发生什么，世界都将铭记。"
L["Angus Ballaster"] = "安古斯·巴拉斯塔"
L["Angus Ironfist"] = "安古斯·铁拳"
L["Anima Attrition"] = "心能消耗"
L["Annie Warren"] = "安妮·沃伦"
L["Another Arcan'dor Closes..."] = "又一扇门关闭了……"
L["Answer Baine Bloodhoof's call as the spirit realm and the living world begin to drift dangerously out of alignment. Across Mulgore and Thunder Bluff, the elders still remember an age before the Horde, and the ancestors have not gone silent.\n\nWalk with the spiritwalkers, restore rites interrupted by years of war, and listen for the balance between the living, the dead, and the land beneath your hooves."] = "灵魂领域与生者世界正危险地渐行渐远，响应贝恩·血蹄的召唤吧。在莫高雷与雷霆崖，长者们仍记得部落诞生之前的岁月，先祖们也从未沉默。\n\n与灵魂行者同行，恢复因多年战乱而中断的仪式，聆听生者、亡者与你蹄下大地之间的平衡。"
L["Answer Tess Greymane's call when the Nightbane begin to reappear in Duskwood and near the borders of the Emerald Dream. The Gilneans are a kingdom in exile, and the curse that gave them a second face has not stopped reshaping them.\n\nHunt through fog and shadow, confront the pull of the worgen curse, and uphold the discipline that has kept Gilnean tradition alive since Greymane Wall fell."] = "当夜之魇再度出现在暮色森林和翡翠梦境的边境附近时，响应苔丝·格雷迈恩的召唤吧。吉尔尼斯人是一个流亡的王国，而赋予他们第二副面孔的诅咒，至今仍在不断重塑着他们。\n\n穿越迷雾与暗影展开狩猎，直面狼人诅咒的诱惑，坚守那份自格雷迈恩之墙陷落以来让吉尔尼斯传统得以延续的自律。"
L["Answer the Call"] = "响应召唤"
L["Answer the Clarion Call from Maiev Shadowsong, who has heard rumors of demonic activity older than the Burning Legion's last invasion. The trail leads into Felwood and the Emerald Dream's borderlands, where corruption has roots ten thousand years deep.\n\nFollow the Wardens into old shadows, face threats tied to ancient Kaldorei memory, and stand with a people still carrying loss beneath the light of Elune."] = "响应玛维·影歌的号召。她听闻了一些恶魔活动的传言，其源头比燃烧军团上一次入侵还要古老。线索指向费伍德森林与翡翠梦境的边境地带，那里的腐化已扎根万年之久。\n\n追随守望者深入古老的暗影，直面与卡多雷远古记忆相关的威胁，与这个在艾露恩的光芒下依然背负着伤痛的民族并肩而立。"
L["Answering Aggression"] = "正面回应"
L["Answers Unknown"] = "未知的答案"
L["Anvil-Thane Thurgaden"] = "铁砧守卫索加登"
L["Apata Highmountain told the tale of Talonclaw — an eagle spear wielded by the greatest hunters of Highmountain since the age of the titans. You climbed into the highest peaks and proved yourself in trials of survival, tracking, and combat. When you claimed Talonclaw from its ancient resting place, the spirits of past hunters looked on with approval."] = "阿帕塔·高岭讲述了塔隆克拉的传说——自泰坦时代起，至高岭最伟大的猎手们便挥舞着这柄雄鹰长矛。你攀上最高的山峰，在生存、追踪和战斗的试炼中证明了自己。当你从古老的安息之地取得塔隆克拉时，历代猎手的英灵都投来了赞许的目光。"
L["Apocalypse"] = "天启"
L["Aponi Brightmane"] = "奥伯妮·亮鬃"
L["Aponi Brightmane studied the Codex of Command but needed a demon's mind to crack its encryption. The answer came from an unlikely source — a demon prisoner in the Violet Hold. Delas Moonfang, a night elf priestess drawn to the paladin's path, helped translate the demonic text. What you found inside chilled your blood: the Legion had captured Aponi Brightmane and was holding her on Niskara. The invasion plans were clear — and so was your next move."] = "奥伯妮·亮鬃研究了统御法典，却需要借助恶魔的思维才能破解其中的密文。答案来自一个意想不到的地方——紫罗兰监狱中的一名恶魔囚犯。投身圣骑士之道的暗夜精灵女祭司德拉丝·月牙协助翻译了这些恶魔文字。你在其中的发现令人不寒而栗：燃烧军团俘虏了奥伯妮·亮鬃，将她囚禁在尼斯卡拉。入侵计划已经一目了然——你的下一步行动也是如此。"
L["Aponi's Trail"] = "奥伯妮的踪迹"
L["Apostate Liberation"] = "解救变节者"
L["Apothecary Keever"] = "药剂师基佛"
L["Apprentice Beruun"] = "学徒贝鲁恩"
L["Apprentice Nelphi"] = "学徒奈尔菲"
L["Arcan'dor, Gift of the Ancient Magi"] = "阿坎多尔，上古法师的馈赠"
L["Arcane Communion"] = "奥术传动"
L["Arcane Thirst"] = "魔瘾"
L["Arcanist Kel'danath"] = "奥术师凯尔丹纳斯"
L["Arcanist Valtrois"] = "奥术师瓦尔托伊"
L["Archdruid Hamuul Runetotem"] = "大德鲁伊哈缪尔·符文图腾"
L["Archdruid Hamuul Runetotem's summons led you to Moonglade, where Malfurion Stormrage revealed the Emerald Dreamway — ancient paths woven through the Dream itself. Keeper Remulos guided you through to the Dreamgrove, a sanctuary hidden in Val'sharah. There, Rensar Greathoof asked you to claim an artifact weapon and plant the Seed of Ages, binding your fate to the land. You ascended the Cenarion Circle as its newest Archdruid."] = "在大德鲁伊哈缪尔·符文图腾的召唤下，你来到月光林地，玛法里奥·怒风在此向你揭示了翡翠梦境之路——在梦境中交织而成的古老道路。守护者雷姆洛斯引领你抵达梦境林地，那是隐藏在瓦尔莎拉的一处圣所。在那里，伦萨·巨蹄请你取得一件神器武器，并种下纪元之种，将你的命运与这片土地紧紧相连。你由此成为塞纳里奥议会最新的大德鲁伊。"
L["Archdruid's Campaign"] = "大德鲁伊的战役"
L["Archimonde, The Defiler"] = "污染者阿克蒙德"
L["Archmage Kalec"] = "大法师卡雷"
L["Archmage Khadgar"] = "大法师卡德加"
L["Archmage Melis"] = "大法师麦丽丝"
L["Archmage Modera"] = "大法师茉德拉"
L["Archmage Omniara"] = "大魔法师欧妮娅拉"
L["Archmage Vargoth"] = "大法师瓦格斯"
L["Archmage Vargoth has vanished. Khadgar leads the search through his retreat, but a darker threat lurks behind his disappearance."] = "大法师瓦格斯失踪了。卡德加带队在他的隐居处展开搜寻，但他的失踪背后潜藏着更加黑暗的威胁。"
L["Archmage Vargoth's Retreat"] = "大法师瓦格斯的居所"
L["Archmage's Campaign"] = "大法师的战役"
L["Argent Aid"] = "银色北伐军的协助"
L["Argent Vanguard"] = "银色前线基地"
L["Arko'narin Starshade"] = "亚科纳琳·星影"
L["Arluin"] = "阿鲁因"
L["Arluin's Request"] = "阿鲁因的请求"
L["Armies of Legionfall"] = "抗魔联军"
L["Arming Dalaran"] = "武装达拉然"
L["Arming the Army"] = "武装军队"
L["Arming the Rebels"] = "武装义军"
L["Armor Fit For A Deathlord"] = "死亡领主护甲"
L["Armor Stand"] = "护甲架"
L["Army of the Damned"] = "召唤大军"
L["Arom's Stand became the Order's new headquarters. Inquisitor Sterntide — one of the few who still remembered the old ways — gave you a crash course in witch hunting: silver weapons for the cursed, fire for the wicker, and sharp thinking for the witches themselves. You rooted out hidden dealings in the camp, exposed infiltrators wearing friendly faces, and trained new guards to replace the corrupted ones. When Lucille raised the Order's banner over Arom's Stand, the message was clear — the witches had hunted long enough. Now they were the prey."] = "阿罗姆之台成为了骑士团的新总部。审判官斯坦泰德——少数仍记得古老传统的人之一——为你上了一堂猎巫速成课：银质武器对付受诅咒者，火焰对付柳条怪，敏锐的头脑对付女巫本身。你揪出了营地里的暗中交易，揭穿了伪装成友人的奸细，并训练了新的卫兵来取代那些已被腐化的人。当露希尔在阿罗姆之台升起骑士团的旗帜时，传达的信息再清楚不过——女巫们猎杀得已经够久了。现在，她们成了猎物。"
L["Arthas died at the Frozen Throne. The moment he fell, the power of the Lich King's realm rippled outward — and Sylvanas, like every Forsaken sustained by that dark energy, briefly stopped. She died on her feet, alone at the pinnacle of Icecrown. A Val'kyr named Annhylde gave her life to pull her back. Sylvanas opened her eyes to wind and ice and herself, inexplicably, still breathing. She looked out at nothing for a long time. Then she went back to work. She never explained what she had seen. But the Val'kyr — the ones who would spend their own lives to keep her alive — suddenly became very important to her. Now she knew why."] = "阿尔萨斯死在了冰封王座。在他倒下的那一刻，巫妖王领域的力量向外震荡——希尔瓦娜斯就像每一个依靠那股黑暗能量维系存在的被遗忘者一样，短暂地停止了。她站着死去，孤身一人立于冰冠冰川之巅。一位名叫安希尔德的瓦格里献出了自己的生命，将她拉了回来。希尔瓦娜斯睁开双眼，迎面是寒风与冰雪，而她自己——不知为何——竟然仍在呼吸。她久久地凝望着虚无。然后，她重新投入了工作。她从未解释过自己看到了什么。但瓦格里——那些愿意献出自己生命让她活下去的存在——突然对她变得极其重要。现在她明白了原因。"
L["Arthas Menethil"] = "阿尔萨斯·米奈希尔"
L["Arzaal"] = "阿扎尔"
L["As Strong As Our Will"] = "如我们的意志般坚强"
L["Ascendant of Flames"] = "烈焰升腾者"
L["Ascending The Circle"] = "加入议会"
L["Ask and You Shall Receive"] = "有求必应"
L["Asking a Favor"] = "请求帮助"
L["Assassin Entrapment"] = "捕杀刺客"
L["Assault by Air"] = "空中突袭"
L["Assault by Ground"] = "地面突袭"
L["Assault on the Airstrip"] = "突袭机坪"
L["Assault on Violet Hold: The Fel Lexicon"] = "突袭紫罗兰监狱：邪能词典"
L["Assault the Scarlet Monastery to raise the third Horseman — High Inquisitor Whitemane, your oldest enemy turned servant."] = "进攻血色修道院，复活第三位天启骑士——大检察官怀特迈恩，你最古老的宿敌，如今将沦为你的仆从。"
L["Assemble the Forsaken"] = "集结被遗忘者"
L["Assessing the Enemy"] = "探敌底细"
L["Asset Security"] = "财产安全"
L["Assisting the Archmage"] = "协助大法师"
L["At Arom's Stand, recruit and train the first new Inquisitors. Learn the old ways of witch hunting — silver, fire, and sharp thinking."] = "在阿罗姆之台招募并训练第一批新的审判官。学习猎巫的古老之道——银器、火焰和敏锐的头脑。"
L["At Odyn's command, you rallied the finest warriors the world had to offer. Finna Bjornsdottir and Ragnvald Drakeborn pledged their blades to your cause. Under Skyseer Ghrent's guidance, you recruited troops, dispatched them to the Broken Isles, and established Skyhold as a true war machine — Einar the Runecaster fortifying your forces with ancient vrykul magic."] = "遵照奥丁的命令，你召集了世间最出色的战士。菲娜·伯恩多提尔和拉格瓦尔德·龙脉誓以刀剑效忠你的事业。在天空贤者格伦特的指导下，你招募部队，将他们派往破碎群岛，把苍穹要塞打造成一台真正的战争机器——符文法师艾纳尔则以古老的维库魔法强化你的部队。"
L["At the Bottom of the Sea"] = "海底深处"
L["At the Maelstrom's edge, the Earthen Ring struggles to keep Azeroth from tearing apart. The elements are restless, wounded, and not always willing to answer.\n\nAs Farseer, seek the elemental lords, restore balance where the world is breaking, and hold the center while the Legion tries to pull everything apart."] = "在大漩涡的边缘，大地之环正竭力阻止艾泽拉斯分崩离析。元素躁动不安、伤痕累累，并不总是愿意回应召唤。\n\n身为先知，你要寻访元素领主，在世界崩裂之处恢复平衡，并在燃烧军团企图撕裂一切时坚守中心。"
L["At the northern edge of the forest, a wounded sprite led you into an older, stranger grief. The mogu had bound spirits into vessels, rituals, and stone. Pei-Zhi needed those cycles broken before the dead were consumed by someone else's ambition. You shattered simulacrums, gathered ritual artifacts, released wayward spirits, returned beasts to nature, and offered the humility the terrace demanded. To bridge earth and sky, you had to answer the past without trying to own it."] = "在森林的北缘，一只受伤的小精灵将你引入了一段更古老、更奇异的哀伤。魔古族曾将灵魂禁锢在容器、仪式与石头之中。裴智需要打破这些循环，以免亡者被他人的野心所吞噬。你粉碎了拟像，收集了仪式器物，释放了迷途的灵魂，让野兽重归自然，并献上了这片台地所要求的谦卑。若要沟通天地，你就必须回应过去，而不是试图占有它。"
L["At the Source"] = "直击根源"
L["At Tian Monastery, training means discipline, hospitality, a proper weapon, and learning not to solve every problem as a soldier."] = "在天禅院，修行意味着纪律、待客之道、一件趁手的兵器，以及学会不再像士兵那样去解决每一个问题。"
