L["Baine Bloodhoof"] = "贝恩·血蹄"
L["Baine Bloodhoof has decided Derek Proudmoore cannot be used as a weapon against his own family and asks for your help freeing him. The plan runs through Plunder Harbor under false colors, with Thomas Zelling — the very tidesage Lilian helped raise — guiding the escape from the inside. When Baine and Zelling are punished for their defiance, Lilian says nothing to Sylvanas. She tells Zelling's family he died a hero. Then the War Campaign rolls on regardless — Warfang Hold needs securing, and Nathanos is already planning the next move."] = "贝恩·血蹄认定，德里克·普罗德摩尔不能被当作对付自己家人的武器，于是请你帮忙救他出来。计划需要你们伪装身份潜入劫掠港，而托马斯·泽林——正是莉莉安协助复活的那位潮汐贤者——将在内部接应出逃。当贝恩和泽林因违抗命令而受到惩处时，莉莉安对希尔瓦娜斯只字未提。她告诉泽林的家人，他是作为英雄死去的。然后，战争战役依旧照常推进——战牙要塞需要确保安全，而纳萨诺斯已经在筹划下一步行动了。"
L["Baine Bloodhoof is to be executed. Lor'themar has gathered allies to defy the Warchief and save the Tauren chieftain."] = "贝恩·血蹄即将被处决。洛瑟玛召集盟友，准备违抗大酋长，营救这位牛头人酋长。"
L["Baine Bloodhoof looked at Derek Proudmoore — raised, hollowed out, aimed at his own kin — and decided he would not be part of it. He asked for your help. Thomas Zelling, the tidesage whose raising Lilian had stood witness to in Stormsong, helped guide Derek out from the inside. They freed him.\n\nSylvanas had Baine arrested and Zelling killed. Lilian said nothing aloud. Later, quietly, she went to Zelling's family and told them he had died a hero. It was not defiance. It was a choice. Small enough that no one noticed. Large enough that she did.\n\nAnd then the war moved on. Warfang Hold needed to be secured for a leadership summit. Boss Mida handled the SI:7 spies and the gate-crashers. Nathanos arrived to make a display of the Horde's strength. The machine kept turning, indifferent to what had just been lost."] = "贝恩·血蹄看着德里克·普罗德摩尔——被复活、被掏空、被当作对付亲族的武器——决定不再参与其中。他请求你的帮助。托马斯·泽林，就是莉莉安在斯托颂谷地亲眼见证其复生的那位潮汐贤者，从内部协助引导德里克出逃。他们救出了他。\n\n希尔瓦娜斯下令逮捕贝恩，处死泽林。莉莉安没有说出一个字。后来，她悄悄找到泽林的家人，告诉他们他是作为英雄死去的。这不是违抗，而是一种选择。小到无人察觉，却又大到她自己无法视而不见。\n\n然后，战争继续向前推进。战牙要塞需要为一场领袖峰会做好安保。大老板米达负责对付军情七处的间谍和不速之客。纳萨诺斯也赶来展示部落的力量。战争机器依旧运转，对刚刚失去的一切漠不关心。"
