L["Belath's intelligence pointed to a Legion commander hiding in Stormheim. Malace Shade tracked the demon through vrykul lands while you disrupted their rune networks. The trail led to Niskara — a demon world that could only be reached by jumping the Fel Hammer through a portal. You forged deadlier warglaives, fueled the ship's engines with demonic power, and launched the invasion. On Niskara, you cut through the Legion's defenses, destroyed their command structure, and earned the title of Slayer — the demon hunters' highest honor."] = "贝拉斯的情报指向一名藏身于风暴峡湾的燃烧军团指挥官。玛拉丝·夜影穿越维库人的领地追踪这个恶魔，而你则负责破坏他们的符文网络。线索最终指向尼斯卡拉——一个只有让邪能之锤跃迁穿过传送门才能抵达的恶魔世界。你锻造了更致命的战刃，用恶魔之力为战舰引擎提供动力，随即发动了入侵。在尼斯卡拉，你突破燃烧军团的防线，摧毁了他们的指挥体系，赢得了杀戮者的称号——恶魔猎手的最高荣誉。"
L["Belmont's Report"] = "贝尔蒙特的报告"
L["Beneath Dalaran lies the Hall of the Guardian, seat of the ancient Tirisgarde: mages sworn to protect Azeroth from magical threats that ordinary armies cannot understand.\n\nAs the order's newest Archmage, investigate hidden enemies, recover lost allies, and defend the Kirin Tor from dangers that wear familiar faces."] = "达拉然地下坐落着守护者圣殿，那是古老的提瑞斯法守护者的驻地：这些法师立誓保卫艾泽拉斯，抵御那些寻常军队无法理解的魔法威胁。\n\n身为该组织最新的大法师，你要调查隐藏的敌人，寻回失散的盟友，保护肯瑞托免受那些披着熟悉面孔的危险侵害。"
L["Beneath Light's Hope Chapel lies the Sanctum of Light, where the Knights of the Silver Hand reform under your command. The Legion threatens every oath the order was built to keep.\n\nAs Highlord, unite paladins of many traditions, investigate demonic plans, and bring the Light into battles where hope has started to thin."] = "圣光之愿礼拜堂地下坐落着圣光秘殿，白银之手骑士团将在你的统领下于此重组。燃烧军团威胁着骑士团立誓守护的每一项誓言。\n\n身为大领主，你要团结各种传统的圣骑士，调查恶魔的阴谋，将圣光带入希望日渐渺茫的战场。"
