L["Boarding the Skybreaker is the moment Icecrown changes scale. High Captain Justin Bartlett runs the deck. Sky-Commander Keller handles the flight line. Absalan the Pious blesses every salvo. The first sortie drops into Ymirheim, where the Scourge mines its saronite. The second swings west to the Broken Front, where a Scourge vanguard once mauled the 7th Legion's first landing. After that comes the grind: Poke and Prod, Against the Giants, Coprous the Defiled, the tinker Kibli Killohertz and his lightning-based sarcasm. Farther west, past the Valley of Lost Hope, Thassarian cracks open the Desolation Gate with borrowed Scourge ordnance and a half-broken jumpbot. By the time the Skybreaker swings east again, the Guardians of Corp'rethar are already in the crosshairs."] = "登上破天者号的那一刻，冰冠冰川之战的规模就此改变。高级指挥官加斯汀·巴雷特掌管甲板，天空指挥官凯勒负责飞行编队，虔诚的阿布萨兰为每一轮齐射祈福。第一次出击降落在伊米海姆，天灾军团在那里开采萨隆邪铁。第二次则向西转往破碎前线，那里曾有一支天灾先锋重创第七军团的首批登陆部队。此后便是一连串苦战：“知己知彼”、“对抗巨人”、污染者科普洛斯，还有工匠吉普利·基罗赫斯和他那带着电火花的冷嘲热讽。再往西，越过失落希望之谷，萨萨里安借来天灾军团的军械和一台半坏的跳跃机器人，炸开了荒芜之门。等到破天者号再次转向东方时，科普雷萨的守护者已经进入了瞄准范围。"
L["Bodies are turning up across the Broken Isles, and the trail leads to a chilling conspiracy deep within SI:7 itself."] = "破碎群岛各地接连出现尸体，线索指向军情七处内部一桩令人胆寒的阴谋。"
L["Bodies started appearing across the Broken Isles — agents killed with surgical precision. The trail led you through a web of betrayal reaching into SI:7 itself. Working with Fleet Admiral Tethys and Marin Noggenfogger, you gathered evidence and allies while throwing SI:7 off your scent, uncovering a conspiracy far deeper than anyone suspected."] = "破碎群岛各地开始出现尸体——特工们被精准无比地杀害。线索引你穿过一张背叛之网，一直延伸到军情七处内部。你与舰队上将特塞斯和马林·诺格弗格合作，一边收集证据、招揽盟友，一边甩开军情七处的追踪，最终揭开了一个远比任何人想象的都要深的阴谋。"
