L["Brewmaster Blanche fell to a Legion poison on the Broken Shore, her spirit lingering to guide you. You brewed a cure from fel ingredients, saved who you could, and secured the Shore for the monks. Then came word of Ban-Lu — a celestial tiger who had served every Grandmaster since the order's founding. Master Bu led you across Pandaria following the tiger's trail through history: his shadow in the Jade Forest, his river in the Valley, his trial at the peak. When Ban-Lu finally appeared, he spoke — and declared you worthy. The Grandmaster had found a companion."] = "酒仙布兰琪在破碎海滩身中燃烧军团的剧毒而亡，她的灵魂却留了下来为你指引方向。你用邪能材料酿出了解药，尽力救下了能救的人，并为武僧们守住了海滩。随后，班禄的消息传来——这只神虎自武僧组织创立以来便侍奉着每一位大宗师。卜大师带领你走遍潘达利亚，沿着这只猛虎在历史中留下的足迹前行：翡翠林中的身影，山谷里的河流，峰顶上的试炼。当班禄终于现身时，他开口说话了——宣布你配得上他。大宗师找到了自己的伙伴。"
L["Brick By Brick"] = "为胜利添砖加瓦"
