L["Build the Illidari's strength on the Fel Hammer. Recruit champions, train troops, and prove yourself leader of the demon hunters."] = "在邪能之锤上壮大伊利达雷的力量。招募勇士，训练部队，证明你配得上恶魔猎手领袖之位。"
L["Build the order hall's strength by recruiting legendary rogues as champions and establishing operations throughout the Broken Isles."] = "招募传奇盗贼作为勇士，在破碎群岛各地展开行动，壮大职业大厅的实力。"
L["Build, test, and defend the X-52 while goblin politics and greed explode all around you."] = "在地精的权谋与贪婪四处爆发之际，建造、测试并保卫X-52。"
L["Building Our Troops"] = "组建部队"
L["Buried Power"] = "被埋葬的力量"
L["Burn Doctor Olakin Sainrith's plague lab, save Father Kamaros's people, and finish the Runesmiths' work."] = "焚毁奥拉金·塞恩里斯博士的瘟疫实验室，拯救卡玛洛斯神父的部众，完成符文铁匠未竟的工作。"
L["Burning Down the House"] = "烧毁那座房子"
L["Burning Within"] = "燃烧之心"
L["Business, betrayal, and big explosions: a proper goblin story. You helped Hobart finish the X-52, survived every reckless test, crushed Gallywix's takeover, and earned the right to wear the pride of Kezan."] = "生意、背叛和大爆炸：这才是地道的地精故事。你帮助霍巴特完成了X-52，挺过了每一次鲁莽的测试，粉碎了加里维克斯的夺权阴谋，赢得了身披科赞荣耀的资格。"
L["Buyers Wanted!"] = "寻求买家！"
L["Bwon Voyage"] = "死路顺风"
L["Bwonsamdi"] = "邦桑迪"
L["By Any Means"] = "不择手段"
L["By Fire Be Purged"] = "净化的火焰"
L["Cages For All Occasions"] = "一笼应万变"
L["Calamity Jade"] = "玉石灾星"
L["Calia Menethil"] = "佳莉娅·米奈希尔"
L["Call of the Illidari"] = "伊利达雷的召唤"
L["Call of The Uncrowned"] = "无冕者的召唤"
L["Call of the Wilds"] = "野性的呼唤"
L["Call to Lordaeron"] = "洛丹伦的召唤"
L["Calling Hilaire Home"] = "召回希莱尔"
L["Calydus"] = "卡里杜斯"
L["Calydus pointed you toward Ulthalesh — the Deadwind Harvester, a scythe of terrible power that had reaped souls for millennia. You followed the curse through Deadwind Pass, where the Dark Riders still haunted the roads. In their shadowed lair, you tore Ulthalesh from their grasp. The scythe's whispers joined the chorus in your mind — a weapon that was never truly silent."] = "卡里杜斯为你指明了乌萨雷什的方向——逆风收割者，一柄拥有可怕力量的镰刀，千百年来一直在收割灵魂。你追随诅咒的踪迹穿过逆风小径，黑暗骑手仍在那里的道路上游荡。在他们阴暗的巢穴中，你从他们手中夺走了乌萨雷什。镰刀的低语加入了你脑海中的合唱——这是一件从未真正沉默过的武器。"
L["Calydus revealed the location of the Scepter of Sargeras — a weapon capable of tearing holes between dimensions, wielded by the Dark Titan's own lieutenants. You found it sealed in a vault warded against mortal hands. But a warlock's hands were never quite mortal. You broke the wards, claimed the Scepter, and felt the fabric of reality shudder around you. The power to break worlds was now in your grip."] = "卡里杜斯揭示了萨格拉斯的权杖的下落——一件能够在维度之间撕开裂口的武器，曾由黑暗泰坦麾下的副官们亲自执掌。你发现它被封存在一座防范凡人之手的宝库中。但术士的手从来都不算是凡人之手。你破除了结界，取得了权杖，感觉到周围现实的结构在颤抖。毁灭世界的力量如今已握在你的手中。"
L["Calydus spoke of the Skull of the Man'ari — an eredar artifact of staggering summoning power. The ritual reagents alone were dangerous enough to kill a lesser warlock. You gathered them, performed the summoning, and wrested the Skull from the eredar lord who guarded it. The Skull's eyes glowed with malevolent intelligence, as if the demon trapped within was already planning its next move."] = "卡里杜斯提到了曼阿瑞之颅——一件拥有惊人召唤之力的艾瑞达神器。光是仪式所需的材料，就足以要了一个寻常术士的命。你收集齐材料，完成了召唤，从守护它的艾瑞达领主手中夺下了这颗头骨。头骨的双眼闪烁着邪恶的智慧之光，仿佛困在其中的恶魔已经在谋划下一步行动。"
