L["Chief Plaguebringer Middleton"] = "首席药剂师米德尔顿"
L["Chief Plaguebringer Middleton has been busy in the Carrion Fields. He has something new to test — a blight meant to undo the Scourge where steel cannot reach. The formula wants a subject. Middleton smiles through gritted teeth and swears the first dose is always the worst. Whatever the Apothecaries are cooking under the Horde's banner, it may reshape this war."] = "首席药剂师米德尔顿一直在腐尸原野忙个不停。他有新东西要测试——一种专门用来瓦解天灾军团的疫病，能触及刀剑所不能及之处。这个配方需要一名试验对象。米德尔顿咬着牙挤出微笑，发誓第一剂永远是最难受的。无论药剂师们在部落的旗帜下鼓捣着什么，它都可能改变这场战争的走向。"
L["Chief Telemancer Oculeth"] = "首席传送师欧库勒斯"
L["Chieftain Hatuun"] = "酋长哈顿"
L["Cho slows the Horde campaign long enough to teach the land's memory, then the hozen pull you back into motion."] = "周卓让部落的征程暂缓片刻，向你讲述这片土地的记忆，随后猢狲又把你拉回了奔忙之中。"
L["Chon Po Stormstout"] = "重波·风暴烈酒"
L["Choppertunity"] = "土制火箭筒"
L["Chosen by Odyn himself, you ascend to Skyhold: the legendary warrior paradise above the clouds. The Valarjar measure worth in courage, scars, and the battles a champion is still willing to fight.\n\nAs Battlelord, recover ancient symbols of war, seek alliances with titan-forged powers, and lead warriors who believe glory is something earned in motion."] = "你被奥丁亲自选中，登上了苍穹要塞：那是云端之上传说中的战士天堂。瓦拉加尔以勇气、伤疤以及一名勇士仍愿投身的战斗来衡量其价值。\n\n身为战争领主，你要寻回古老的战争象征，与泰坦造物的力量结盟，并率领那些坚信荣耀须在征战中赢取的战士。"
L["Chromie"] = "克罗米"
L["Chromie of the Bronze Dragonflight sends you back to Stratholme, to a day history remembers in silence. The Infinite Dragonflight would rewrite this moment. Yours is the harder task: walk beside a young Prince Arthas Menethil and keep time honest, whatever price the past demands."] = "青铜龙军团的克罗米将你送回斯坦索姆，回到历史只能以沉默铭记的那一天。永恒龙军团企图改写这一刻。而你的任务更为艰难：陪伴年轻的阿尔萨斯·米奈希尔王子，守护时间的真实，无论过去要求付出怎样的代价。"
L["Cities in Dust"] = "死灰之城"
L["Citizens' Army"] = "全民皆兵"
L["Claim the Ashbringer, the legendary blade that burned with holy fire and shattered the Scourge."] = "取得灰烬使者——这把传奇之剑曾燃烧着神圣之火，令天灾军团溃不成军。"
L["Claim the Fists of the Heavens, a pair of enchanted handwraps charged with the fury of storms."] = "取得天堂之拳——一对注满风暴之怒的附魔裹手。"
L["Claim Xal'atath, a dagger that whispers with the voice of the Void and remembers the Black Empire that ruled before the titans."] = "取得萨拉塔斯——这把匕首以虚空之声低语，至今仍记得泰坦降临之前统治世界的黑暗帝国。"
L["Claws of Ursoc"] = "乌索克之爪"
L["Clear the Air"] = "清除烟雾"
L["Clear Victory"] = "大获全胜"
L["Clear-Cutting"] = "入木三分"
L["Climb the spire of Icecrown Citadel and write the last page of Arthas Menethil's story."] = "登上冰冠堡垒之巅，为阿尔萨斯·米奈希尔的故事写下最后一页。"
L["Cloak and Dagger"] = "暗里藏刀"
L["Cloaked in Moonshade"] = "月影里的秘密"
L["Close Enough"] = "近在咫尺"
L["Closing In"] = "接近了"
