L["Coercing a Confession"] = "强迫认罪"
L["Cog Captain Winklespring"] = "齿轮队长闪簧"
L["Commander and Captain"] = "指挥官和队长"
L["Communication Breakdown"] = "通讯中断"
L["Communication Orbs"] = "通讯宝珠"
L["Communing With Malorne"] = "与玛洛恩交流"
L["Complete Armies of Legionfall on the Broken Shore, then return to the Hall of Shadows to begin the final class mount chapter."] = "在破碎海滩完成抗魔联军任务线，然后返回暗影大厅，开始最终的职业坐骑章节。"
L["Complete the Forsaken Heritage questline as an Undead character. Requires having sided with Sylvanas during the war campaign."] = "以亡灵角色完成被遗忘者传承任务线。需要在战争战役中站在希尔瓦娜斯一方。"
L["Complete the Horde War Campaign introduction and travel to Zuldazar to unlock this chapter."] = "完成部落战争战役的序章并前往祖达萨，即可解锁本章。"
L["Complete the Horde War Campaign through Stormsong Valley to unlock this chapter."] = "将部落战争战役推进至斯托颂谷地部分完成后，即可解锁本章。"
L["Complete the Kul Tiras intro and War Campaign chapters to unlock, then speak with Mathias Shaw in Proudmoore Keep."] = "完成库尔提拉斯序章和战争战役章节后解锁，随后在普罗德摩尔要塞与马迪亚斯·肖尔交谈。"
L["Complete the Silver Hand's reformation. Recruit Arator and Lothraxion, and accept the title of Highlord."] = "完成白银之手的重组。招募阿拉托尔和洛萨克森，并接受大领主的头衔。"
L["Complete the Zereth Mortis campaign and defeat the Jailer in the Sepulcher of the First Ones raid."] = "完成扎雷殁提斯战役，并在初诞者圣墓团队副本中击败典狱长。"
L["Confront Mueh'zala's influence, recover forgotten loa, and complete a Trial of the Loa worthy of the Darkspear."] = "直面缪扎拉的影响，寻回被遗忘的洛阿，完成一场配得上暗矛部族的洛阿试炼。"
L["Confrontation at the Black Temple"] = "黑暗神殿之战"
L["Consular Celestos"] = "赛莱托斯大使"
L["Consulting Our Allies"] = "咨询盟友"
L["Containment Procedure"] = "抑制程序"
L["Continuing the Cure"] = "继续治疗"
L["Controlling the Situation"] = "控制局势"
L["Convincin' Old Yancey"] = "说服老扬希"
L["Cook Torka"] = "厨师托尔卡"
L["Coprous the Defiled"] = "污染者科普洛斯"
L["Corlain was a nightmare — hexed citizens wandered the streets, ruinous rituals played out in every alley, and the coven's strongest witches guarded the approach to the manor. You cut through them all. Lucille led the final charge to the gates of Waycrest Manor itself, where her mother — Lady Waycrest, consumed by Gorak Tul's power — waited in the depths. In the dungeon beneath the manor, you faced the fallen mother and broke the Drust king's hold on her. The curse over Drustvar shattered like glass. Lucille knelt beside her mother's body, the heir of a house that would rebuild. The witchwood was silent at last."] = "克莱因宛如一场噩梦——中了妖术的市民在街头游荡，每条小巷里都在上演毁灭性的仪式，女巫集会中最强大的女巫们把守着通往庄园的道路。你将她们统统击溃。露希尔带领最后的冲锋直抵维克雷斯庄园的大门，她的母亲——被高莱克·图尔的力量吞噬的维克雷斯夫人——就在庄园深处等待着。在庄园下方的地下城中，你与这位堕落的母亲正面交锋，打破了德鲁斯特之王对她的控制。笼罩德鲁斯瓦的诅咒如玻璃般粉碎。露希尔跪在母亲的遗体旁，她是这个即将重建的家族的继承人。女巫林地终于归于寂静。"
L["Corner Crossing"] = "调查路口"
