L["Dahlia's Tears"] = "达莉亚之泪"
L["Dalaran"] = "达拉然"
L["Dalaran / Broken Isles"] = "达拉然 / 破碎群岛"
L["Danica the Reclaimer"] = "接引者丹妮卡"
L["Danica the Reclaimer appeared to you in Dalaran bearing a message from Odyn himself — the All-Father had been watching, and he found you worthy. You ascended to Skyhold, the legendary warrior paradise suspended above the clouds, where Odyn named you champion of the Valarjar and bade you claim an artifact weapon fit for the battles ahead."] = "接引者丹妮卡在达拉然现身，为你带来了奥丁本人的口信——众神之父一直在注视着你，并认为你配得上这份荣耀。你登上了苍穹要塞，那座悬浮于云端之上的传奇战士天堂。奥丁在那里册封你为瓦拉加尔的勇士，命你取得一件足以应对未来战斗的神器武器。"
L["Darion Mograine revealed the Lich King's plan — to raise the Four Horsemen, death knights of legendary power, to serve as the Ebon Blade's vanguard. The first was Nazgrim, the Horde general who fell defending the gates of Orgrimmar. You tore his spirit from the grave and bound it in service. Thassarian and Nazgrim pledged as your champions, and the order's forces began to take shape — troops recruited, missions dispatched, and a war machine built from bone and shadow."] = "达里安·莫格莱尼揭示了巫妖王的计划——复活天启四骑士，让这些拥有传奇力量的死亡骑士成为黑锋骑士团的先锋。第一位是纳兹戈林，那位在保卫奥格瑞玛大门时战死的部落将军。你将他的灵魂从坟墓中扯出，令其俯首效命。萨萨里安和纳兹戈林宣誓成为你的勇士，骑士团的力量开始成形——招募部队，派遣任务，一台由白骨与暗影铸就的战争机器就此建成。"
L["Darion Mograine spoke of Frostmourne — the Lich King's blade, shattered atop Icecrown Citadel. Its shards still radiated power, and the call of Icecrown pulled you north. In the frozen throne room, you gathered the remnants and reforged them into the Blades of the Fallen Prince — twin runeblades that carried echoes of Arthas, Ner'zhul, and every soul the original sword had devoured."] = "达里安·莫格莱尼提到了霜之哀伤——巫妖王之剑，在冰冠堡垒之巅被击碎。它的碎片仍散发着力量，冰冠冰川的召唤将你引向北方。在冰封的王座大厅中，你收集起残片，将其重铸为堕落王子之剑——这对双持符文剑中回荡着阿尔萨斯、耐奥祖以及原剑吞噬过的每一个灵魂的声音。"
L["Dark Iron Machinations"] = "黑铁钻探机"
L["Dark Ranger Alina"] = "黑暗游侠阿莉娜"
L["Dark Ranger Velonara"] = "黑暗游侠维罗娜拉"
L["Dark Ranger Vorel"] = "黑暗游侠沃蕾尔"
L["Dark Secrets and Shady Deals"] = "黑暗的秘密和不可告人的交易"
L["Darkhaven's crisis brought you into the shadow of Castle Nathria. Lord Chamberlain showed you the Stoneborn, Revendreth's gargoyle guardians, and carried your request to the Harvesters. Then you met Sire Denathrius: ancient, immaculate, and utterly certain of his own necessity. He promised aid, but only after you helped him discipline the rebellion tearing through his realm. His authority filled the court like perfume and poison. Revendreth's nobles bowed. The Stoneborn obeyed. And for the moment, you were expected to do the same."] = "暗港的危机将你带入纳斯利亚堡的阴影之下。宫务大臣向你引见了石裔魔——雷文德斯的石像鬼守卫——并将你的请求转达给收割者。随后，你见到了德纳修斯大帝：古老、无瑕，并且对自身存在的必要性深信不疑。他答应给予援助，但前提是你先帮他镇压正在撕裂其领地的叛乱。他的威严如香水与毒药般弥漫整个宫廷。雷文德斯的贵族们俯首鞠躬，石裔魔唯命是从。而此时此刻，你也被期望如此。"
L["Darkheart Thicket"] = "黑心林地"
L["Darkheart Thicket: Nightmare Oak"] = "黑心林地：梦魇橡木"
L["Darkheart Thicket: The Nightmare Lash"] = "黑心林地：梦魇之鞭"
L["Darkrider Arly"] = "黑暗骑士阿尔蕾"
L["Darkspeaker R'khem"] = "黑暗低语者阿克希姆"
L["Daughter of the Sea"] = "大海的女儿"
L["Dawn's Blossom"] = "晨芳园"
L["Dawn's Blossom slowed the campaign down long enough for you to see the people under it. Cho, Toya, and the villagers asked for something different than victory. An Windfur's missing cubs led to the Jade Witch and a curse hiding behind a grandmother's smile. The Goldendraft and Wanderbrew families needed courage more than soldiers, and the Arboretum needed ink, color, and permission before a marriage could heal an old feud. It was not a detour. It was the point: Pandaria was full of lives that had nothing to do with the Alliance or Horde until the war made everything their problem."] = "晨芳园让征程放慢了脚步，让你得以看清战火之下的人们。周卓、托亚和村民们所求的并非胜利。安·风裘失踪的幼崽将你引向翡翠女巫，以及隐藏在一位老奶奶笑容背后的诅咒。金酿和游酿两家需要的是勇气，而不是士兵；植物园则需要墨水、色彩和许可，一场婚事才能化解一段宿怨。这不是绕路，而正是关键所在：潘达利亚到处都是与联盟或部落毫无瓜葛的生命，直到战争让一切都成了他们的麻烦。"
L["Dazar'alor"] = "达萨罗"
L["De Darkspear Loa"] = "暗矛之神"
L["De Loa of de Past"] = "往昔之神"
L["De Old Loa"] = "旧日神灵"
L["De Power of Death"] = "死神之力"
L["Dead in the Water"] = "水下亡魂"
L["Deadlier Warglaives"] = "强化战刃"
L["Deadmines"] = "死亡矿井"
L["Deal With It Personally"] = "亲自出马"
L["Death Becomes Him"] = "死亡化身"
L["Death of a Tidesage"] = "潮汐贤者之死"
L["Death to the Living"] = "消灭活人"
L["Death Trap"] = "死亡陷阱"
L["Death... and Decay"] = "枯萎……凋零"
L["Death's Gaze"] = "死亡的凝视"
L["Deathguard Simmer"] = "亡灵卫兵希米尔"
L["Deathknell, Tirisfal Glades"] = "丧钟镇（提瑞斯法林地）"
L["Deathlord's Campaign"] = "死亡领主的战役"
L["Deathlord's Vilebrood Vanquisher"] = "死亡领主的邪巢征服者"
L["Deathstalker Commander Belmont"] = "死亡猎手指挥官贝尔蒙特"
L["Debt Collection!"] = "收债！"
L["Debt Repaid"] = "报恩"
L["Decipher the Legion's Codex of Command. The Violet Hold holds a demon who can translate it — but at what cost?"] = "破译燃烧军团的统御法典。紫罗兰监狱中关押着一名能够翻译它的恶魔——但代价是什么？"
L["Deciphering the Letter"] = "破译信件"
L["Deep beneath the earth, a titan research facility holds the worst mistake the Pantheon ever made. G'huun has to die."] = "在大地深处，一座泰坦研究设施中封存着万神殿犯下的最严重的错误。戈霍恩必须死。"
L["Deep Dive"] = "纵身深潜"
L["Deep Doubts, Deep Wisdom"] = "深虑与睿智"
L["Deep in the Bowels of The Underhalls"] = "地下大厅的深处"
L["Deep in the mountains of Highmountain lay a shield forged from a scale of Neltharion, the Earth-Warder — before madness claimed him and he became Deathwing. You braved the ancient caverns and faced the guardians left behind to protect it. The Scale of the Earth-Warder was heavier than any shield you had ever held, but it was unyielding — and so were you."] = "在至高岭的群山深处，有一面以大地守护者耐萨里奥的鳞片锻造的盾牌——那时他还未被疯狂吞噬，尚未化身为死亡之翼。你闯入古老的洞穴，直面那些被留下来守护它的卫士。大地守护者之鳞比你握过的任何盾牌都要沉重，但它坚不可摧——你也一样。"
L["Deep in the Swamp"] = "沼泽深处"
L["Deep in the tunnels beneath Suramar, you found Arcanist Kel'danath on the edge of withering, his brilliant mind nearly consumed by mana starvation. You fought through packs of feral withered to reach him, recovering his scattered research notes and the remnants of his arcane experiments. His knowledge of ancient Nightborne magic proved invaluable to the growing rebellion."] = "在苏拉玛地下隧道的深处，你找到了濒临枯萎的奥术师凯尔丹纳斯，他那聪慧的头脑几乎已被魔力饥渴所吞噬。你杀穿成群的狂野枯法者来到他身边，找回了他散落的研究笔记和奥术实验的残余成果。他对古老夜之子魔法的了解，对日益壮大的反抗军而言弥足珍贵。"
L["Deeper into the Woods"] = "深入森林"
L["Deepholm stirs with twilight corruption. Seek Therazane the Stonemother and purge the Twilight's Hammer from her domain."] = "深岩之洲因暮光腐化而动荡不安。寻找石母塞拉赞恩，将暮光之锤从她的领地中清除。"
L["Defenders of the Dream"] = "梦境守护者"
L["Defenders of the World"] = "世界守护者"
L["Defending the Isles"] = "保卫群岛"
L["Defending The Vanguard"] = "保卫前线基地"
L["Defense of Aviana"] = "保卫艾维娜"
L["Defense of Quel'Danas"] = "奎尔丹纳斯保卫战"
L["Defense of the Fel Hammer"] = "邪能之槌号防御战"
L["Defense of Tian Monastery"] = "保卫天禅院"
L["Defiance"] = "抗争"
L["Delas Moonfang"] = "德拉丝·月牙"
L["Delegation"] = "有事相求"
L["Deliverance from the Pit"] = "深渊的裁决"
L["Delivery for Kasea"] = "凯西亚的快递"
L["Delve into a demonic vault to claim a pair of shadow-forged blades that hunger for souls."] = "深入一座恶魔宝库，取得一对渴求灵魂的暗影锻造之刃。"
L["Delve into Ironforge's deepest archives with Brann Bronzebeard, who has kept the chronicles longer than most dwarves have been alive. An old relic of the Bronzebeard line has been broken and scattered across roads with long memories.\n\nWalk those roads again, recover what was lost, and return to the great anvils where dwarven legacy is measured in craft, stubbornness, and stone."] = "与布莱恩·铜须一同深入铁炉堡最深处的档案库，他编纂编年史的时间比大多数矮人的寿命还要长。铜须家族的一件古老圣物已经破碎，散落在一条条承载着久远记忆的道路上。\n\n重走这些道路，寻回失落之物，然后回到那些巨大的铁砧前——在那里，矮人的传承以技艺、倔强与岩石来衡量。"
L["Demonic Improvements"] = "魔化提升"
L["Demonic Runes"] = "恶魔符文"
L["Demons Among Us"] = "恶魔四伏"
L["Denathrius sends you after the Accuser, a rebel Harvester whose sinstone may prove she is no righteous dissenter."] = "德纳修斯派你追捕指控者——一名叛变的收割者，而她的罪石或许能证明她并非什么正义的异见者。"
L["Derek Proudmoore had barely been hauled out of the sea before Sylvanas found a use for him — not as a weapon yet, but as bait. The Kul Tiran fleet chased his ghost while you and Nathanos hit Stormsong Monastery. Thomas Zelling, the tidesage whose raising Lilian had stood witness to, guided you from inside. He was doing what he was told. So was she. The Horde got its scepter. Lilian got her champion tabard. No one asked if any of it was right."] = "德里克·普罗德摩尔刚被从海里捞出来，希尔瓦娜斯就为他找到了用途——还不是作为武器，而是作为诱饵。库尔提拉斯人的舰队追逐着他的幽魂，而你和纳萨诺斯则突袭了斯托颂修道院。托马斯·泽林，就是莉莉安曾亲眼见证其复生的那位潮汐贤者，在内部为你们引路。他只是在服从命令。她也一样。部落得到了权杖。莉莉安得到了她的勇士战袍。没有人问过这一切是否正确。"
L["Derek Proudmoore's body is put to use before Lilian ever gets her orders: the Horde deploys him as bait to draw Kul Tiran warships away from Boralus, then drives a strike force into Stormsong Monastery to seize the Abyssal Scepter. Thomas Zelling — raised against his will just weeks ago — now fights for the Horde from inside the monastery walls. Lilian watches what the war makes of people."] = "在莉莉安接到命令之前，德里克·普罗德摩尔的躯体就已派上了用场：部落用他作诱饵，把库尔提拉斯人的战舰从伯拉勒斯引开，随后派出一支突击部队攻入斯托颂修道院，夺取深渊权杖。托马斯·泽林——几周前才违背本人意愿被复活——如今在修道院的高墙之内为部落而战。莉莉安看着战争把人变成了什么样子。"
L["Descend into the depths to recover Sharas'dal, a scepter that commands the tides themselves."] = "潜入深海，寻回沙拉斯达尔——一柄能够号令潮汐的权杖。"
L["Desperate Strike"] = "殊死抗击"
L["Destroying the Altars"] = "摧毁祭坛"
L["Destroying the Cult"] = "铲除邪教"
L["Devastating Effects"] = "灾难性的影响"
L["Devil's in the Details"] = "细节线索"
L["Devour This"] = "吞此一试"
L["Digger Golad"] = "挖掘者格拉德"
L["Dire Growth"] = "可怕的增长"
L["Direct Our Wrath"] = "同仇敌忾"
L["Discover the nightfallen exiles hiding in the ruins of Shal'Aran and learn the desperate truth behind Suramar's shimmering barrier."] = "发现藏身于沙尔艾兰废墟中的堕夜精灵流亡者，了解苏拉玛那道闪烁屏障背后令人绝望的真相。"
L["Disguise yourself as a Nightborne noble and infiltrate Suramar City to gather intelligence for the rebellion."] = "伪装成夜之子贵族，潜入苏拉玛城，为反抗军收集情报。"
L["Disillusioned Defector"] = "幡然醒悟"
L["Dispelling Illusions"] = "驱除幻象"
L["Dispensing Compassion"] = "发放爱心"
L["Dispersion of the Discs"] = "消磁"
L["Diversionary Tactics"] = "声东击西"
L["Do Your Worst"] = "竭尽全力"
L["Doctor Sintar Malefious"] = "辛塔尔·玛菲奥斯博士"
L["Doom and Gloom"] = "厄运降临"
L["Doomhammer"] = "毁灭之锤"
L["Dori'thur"] = "多莉苏尔"
L["Down by the Riverside"] = "前往河畔"
L["Down Kitty!"] = "教训小猫！"
L["Down to Business"] = "直入正题"
L["Draconic Secrets"] = "巨龙的秘密"
L["Drag and Drop"] = "从天而“降”"
L["Dragonblight / Icecrown"] = "龙骨荒野 / 冰冠冰川"
L["Dragonflight"] = "巨龙时代"
L["Dread Commander Thalanor"] = "恐怖指挥官萨拉诺尔"
L["Dread Infiltrators"] = "恐惧渗透者"
L["Dread Priming"] = "恐惧激荡"
L["Dreadscar Rift / Broken Isles"] = "恐痕裂隙 / 破碎群岛"
L["Dreadtick Combustion"] = "焚烧恐虱"
L["Dredhollow"] = "惧谷镇"
L["Dress in Scarlet cloth, take the Vault for the Ebon Blade, and ride up to Malykriss to kill four riders."] = "换上血色十字军的服饰，为黑锋骑士团夺下暗影拱顶，再骑马登上玛里克里斯，击杀四名骑手。"
L["Drust Do It."] = "德鲁一家亲"
L["Drustfall"] = "德鲁斯特之殇"
L["Drustvar"] = "德鲁斯瓦"
L["Duke August Foehammer"] = "奥古斯特公爵"
L["Duke Lankral"] = "兰克拉尔公爵"
L["Duke Lankral appeared in Dalaran with an urgent summons — the Knights of the Ebon Blade needed you at Acherus. The Ebon Hold floated above the Broken Isles like a fortress of iron and frost, and Highlord Darion Mograine spoke of a pact of necessity: the living would fight the Legion their way, and the dead would fight it theirs. You claimed an artifact weapon forged for death itself."] = "兰克拉尔公爵带着紧急召令出现在达拉然——黑锋骑士团需要你前往阿彻鲁斯。黑锋要塞如一座钢铁与寒冰铸成的堡垒般悬浮在破碎群岛上空，大领主达里安·莫格莱尼谈起了一份迫不得已的盟约：生者以他们的方式对抗燃烧军团，亡者则以自己的方式作战。你取得了一件为死亡本身而锻造的神器武器。"
L["Duke Lankral summons you to Acherus, where the Ebon Blade prepares for a war that only the dead can fight."] = "兰克拉尔公爵召你前往阿彻鲁斯，黑锋骑士团正在那里准备一场唯有亡者才能投身的战争。"
L["Duke Lankral told of the Maw of the Damned — a vampiric greataxe that drank the blood of its enemies and fed it to its wielder. The weapon had been lost in a Legion stronghold, guarded by demons who had learned to fear it. You stormed their fortress and tore the Maw from the hands of its demonic captor. The axe drank deep on the way out."] = "兰克拉尔公爵讲述了诅咒之喉的传说——一柄嗜血的巨斧，能吸食敌人的鲜血并将其输送给持有者。这件武器遗失在燃烧军团的一座要塞中，由一群已经学会畏惧它的恶魔看守。你攻入他们的堡垒，从恶魔看守者手中夺下了诅咒之喉。杀出去的路上，这柄巨斧痛饮了一番。"
L["Durak"] = "杜莱克"
L["Dvalen Ironrune"] = "德夫伦·铁符"
L["Dying Berserker"] = "濒死的狂战士"
L["Earthen Blessing"] = "大地赐福"
L["Eastern Escape"] = "向东而去"
L["Eating Before the Meeting"] = "会前进食"
