L["Ebonchill"] = "黑檀之寒"
L["Echelon"] = "艾谢朗"
L["Echo Isles / Northern Stranglethorn"] = "回音群岛 / 北荆棘谷"
L["Echoes of Tortured Souls"] = "痛苦灵魂的回声"
L["Eekle Eekle"] = "埃克埃克"
L["Einar the Runecaster"] = "符文法师艾纳尔"
L["Either With Us"] = "要么加入我们"
L["Eitrigg"] = "伊崔格"
L["Elder Lusshan"] = "长老卢山"
L["Elder Sage Rain-Zhu"] = "大贤者朱雨"
L["Elder Sage Wind-Yi"] = "大贤者易风"
L["Eliminate the Competition"] = "消灭竞争者"
L["Elisande seals Suramar's gates and tightens her grip. The resistance must find a way through the lockdown."] = "艾利桑德封锁了苏拉玛的城门，进一步收紧了控制。抵抗军必须设法突破封锁。"
L["Elisande struck back with the full power of the Nightwell, warping time itself to halt the rebellion's advance. You worked with Valtrois to investigate the temporal distortions, scouted breaches in the Nighthold's defenses, and uncovered how the Grand Magistrix channeled the Nightwell's energy through ancient seals. Breaking those seals would be the key to reaching her."] = "艾利桑德以暗夜井的全部力量发起反击，扭曲时间本身以阻止反抗军的推进。你与瓦尔托伊一同调查时间扭曲现象，侦察暗夜要塞防御中的破绽，并查明了大魔导师是如何通过古老的封印引导暗夜井能量的。打破这些封印，将是接近她的关键。"
L["Elisande's forces captured and experimented on nightfallen prisoners, transforming them into felborne abominations. You stormed the Felsoul experiments alongside Kel'danath and Oculeth, freeing those who could still be saved and putting down those who could not. The horrors you witnessed only strengthened the resolve of every rebel who fought beside you."] = "艾利桑德的部队抓捕堕夜精灵囚犯并拿他们做实验，将他们变成了邪能缠身的憎恶。你与凯尔丹纳斯和欧库勒斯一同突袭了邪魂实验场，解救了那些尚能得救的人，并了结了那些已无法挽回的人。你所目睹的恐怖景象，只让每一位与你并肩作战的反抗者更加坚定。"
L["Elisande's Retort"] = "艾利桑德的反击"
L["Embodiment"] = "魔药化形"
L["Emerald Dragon Tears"] = "翡翠龙泪"
L["Emergency Efforts"] = "应急行动"
L["Emergency Response"] = "紧急救援"
L["Emissary"] = "使者"
L["Emissary Brighthoof"] = "特使艾米萨·闪蹄"
L["Emmarel Shadewarden"] = "伊墨瑞尔·影卫"
L["Empire of Dirt"] = "被摧残的帝国"
L["Empower the Council's soul reserves. Dungeon delves, mad alchemists, and the question: who is truly worthy of power?"] = "充实议会的灵魂储备。深入地下城，对付疯狂的炼金师，并回答一个问题：谁才真正配得上力量？"
L["Empty Package"] = "空包裹"
L["Empyrean Society Report"] = "苍穹会报告"
L["Ending the Blood Trolls"] = "终结鲜血巨魔"
L["Ending the Crescent Curse"] = "终结新月诅咒"
L["Ending the Inquisitor"] = "终结审判官"
L["Enemies Within"] = "内忧"
L["Enter Nightmare"] = "进入梦魇"
L["Enter the Crimsonwood, face Gorak Tul's grand rite, and drive a stake into the heart of the Drust king's power."] = "进入绯红林地，直面高莱克·图尔的盛大仪式，将木桩钉入德鲁斯特之王力量的核心。"
L["Enter the dungeon, cleanse Yu'lon's sacred temple, and destroy the Sha of Doubt where it has taken root."] = "进入地下城，净化玉珑的圣殿，在疑之煞扎根之处将其摧毁。"
L["Enter the Firelands and negotiate with Smolderon, the new Firelord, to secure the fire elementals' allegiance."] = "进入火焰之地，与新任火焰之王斯莫德隆谈判，争取火元素的效忠。"
L["Enter the Nightmare itself to relive the War of the Ancients and awaken Malorne, the great white stag, to fight once more."] = "进入梦魇本身，重温上古之战，唤醒伟大的白鹿玛洛恩，让他再度投入战斗。"
L["Envoy of the Alliance"] = "联盟使节"
L["Ephemeral Manastorm Projector"] = "瞬灭法力风暴发射器"
L["Epilogue (Sylvanas Loyalists)"] = "尾声（希尔瓦娜斯效忠者）"
L["Ernest Carlisle"] = "欧内斯特·卡莱尔"
L["Erunak Stonespeaker called you to the deeps — Sharas'dal, the Scepter of Tides, had been sensed stirring beneath the ocean floor. You descended into the crushing darkness where water elementals guarded the weapon with fierce devotion. The Scepter of Tides chose to rise with you, and the seas themselves seemed to bow as you surfaced."] = "石语者埃鲁纳克将你召往深海——有人感应到潮汐之杖沙拉斯达尔正在海床之下苏醒。你潜入令人窒息的黑暗深处，水元素在那里以狂热的忠诚守护着这件武器。潮汐之杖选择与你一同升起，当你浮出水面时，大海本身仿佛也在俯首致意。"
L["Esara Verrinde"] = "艾莎拉·维林德"
L["Essence of Plague"] = "魔药营养"
L["Essence Triangulation"] = "三角测量"
L["Establish a supply of ancient mana to sustain the nightfallen rebels and prevent them from withering."] = "建立远古魔力的补给，维持堕夜精灵反抗者的生存，防止他们枯萎。"
L["Establishing a Connection"] = "取得联系"
L["Establishing Superiority"] = "确立优势"
L["Establishing The Uncrowned"] = "建立无冕者"
L["Eternal Unrest"] = "不得安宁"
L["Eternal Vigil"] = "不懈警戒"
L["Evelyn Pare"] = "艾芙琳·佩尔"
L["Ever Eastward"] = "一路向东"
L["Everburning"] = "薪火相传"
L["Everything Contained"] = "尽数封存"
L["Everything In Its Place"] = "完好如初"
L["Examining the Epitaphs"] = "查看墓志铭"
L["Exarch Maladaar"] = "大主教玛拉达尔"
L["Excision"] = "精准铲除"
L["Executor Zygand"] = "执行官塞加德"
L["Exodar / Outland / Bloodmyst Isle"] = "埃索达/外域/秘血岛"
L["Experimental Instability"] = "不稳定性"
L["Exploiting an Opening"] = "缺口"
L["Explore ancient ley line tunnels beneath Suramar, discovering forgotten power that could turn the tide."] = "探索苏拉玛地下古老的魔网隧道，发掘足以扭转局势的被遗忘之力。"
L["Explosives in the Foundry"] = "铸造厂里的炸药"
L["Explosivity"] = "爆炸性"
L["Eye of Azshara: A Magical Affliction"] = "艾萨拉之眼：魔法诅咒"
L["Eye of Azshara: The Frozen Soul"] = "艾萨拉之眼：冰封之魂"
L["Face Grand Magistrix Elisande herself as she unleashes the power of the Nightwell against the rebellion."] = "直面大魔导师艾利桑德本人，她正释放暗夜井的力量对付反抗军。"
L["Face to Face With Consequence"] = "自食恶果"
L["Falconhurst is under siege. Break the hag's hold on the village, forge weapons of old, and learn to fight the Drust with fire."] = "鹰林镇正遭受围攻。打破老巫婆对村庄的控制，锻造古老的武器，学会用火焰对抗德鲁斯特人。"
L["Falconhurst was overrun — a hag had enslaved the village, and wicker monsters patrolled the streets. Inquisitor Cleardawn led the charge: you broke the hag's spell, freed the villagers, and held the barricade against waves of cursed attackers. Warren Ashton, the village blacksmith, remembered the old ways — weapons of silver and iron, blessed in ember. You forged an arsenal from his teachings and learned the most important lesson of all: the Drust feared fire. With blessed blades and burning brands, you were ready for the Crimsonwood."] = "鹰林镇已经沦陷——一个老巫婆奴役了整个村庄，柳条怪物在街道上巡逻。审判官克利多恩带头冲锋：你破除了老巫婆的法术，解救了村民，并坚守路障，抵挡一波又一波受诅咒的袭击者。村里的铁匠瓦伦·艾什顿还记得古老的方法——以余烬祝福的银铁武器。你按照他的指点打造出一整套武器，并学到了最重要的一课：德鲁斯特人畏惧火焰。手握受祝福的刀刃与燃烧的火把，你已准备好进军绯红林地。"
L["Fall Back!"] = "撤退！"
L["Fall of the Lich King"] = "巫妖王的陨落"
L["Fallen Idols"] = "遗落的雕像"
L["False Orders"] = "伪造的指令"
L["Family Heirlooms"] = "传家宝"
L["Family Tree"] = "族谱"
L["Fancy Lads and Buccaneers"] = "棒小伙与海盗"
L["Fangs of Ashamane"] = "阿莎曼之牙"
L["Fangs of the Devourer"] = "吞噬者之牙"
L["Faol warned you about Light's Wrath — a staff of such devastating holy power that the Kirin Tor had sealed it in the Nexus Vault, deeming it too dangerous for any mortal. But desperate times demanded desperate weapons. You breached the Vault's defenses and claimed the staff, feeling its barely contained fury surge through you. Light's Wrath was not a gentle weapon — it was the Light's anger given form."] = "法奥曾警告过你圣光之怒的危险——这根法杖蕴含着毁天灭地的神圣力量，肯瑞托认为它对任何凡人来说都太过危险，于是将其封存在魔枢宝库中。但非常时期需要非常的武器。你突破了宝库的防御，取得了这根法杖，感受到它那几乎无法遏制的怒火在你体内奔涌。圣光之怒并非温和的武器——它是圣光的怒火化作的实体。"
L["Farseer Aggralan"] = "先知阿格娜兰"
L["Farseer Nobundo"] = "预言者努波顿"
L["Farseer's Campaign"] = "先知的战役"
L["Farseer's Raging Tempest"] = "先知的狂怒风暴"
