L["Fate of the Nightborne"] = "堕夜精灵的命运"
L["Fate's End"] = "命途之末"
L["Father Gustav"] = "古斯塔夫神父"
L["Father Kamaros"] = "卡玛洛斯神父"
L["Fear is Our Weapon"] = "吓人诛心"
L["Fearsome Jang"] = "蒋震魂"
