L["Fight through cursed Corlain, storm Waycrest Manor, and confront Lady Waycrest and Gorak Tul in the dungeon's depths."] = "杀穿被诅咒的克莱因，攻入维克雷斯庄园，在地下城深处与维克雷斯夫人和高莱克·图尔对决。"
L["Fighting With Fire"] = "火攻"
L["Final Exit"] = "最后出口"
L["Finality"] = "终结"
L["Find Ebonchill, the staff of Alodi — the first Guardian of Tirisfal — frozen in time within a pocket dimension."] = "找到黑檀之寒——第一位提瑞斯法守护者阿洛迪的法杖，它被封冻在一处袖珍次元的时光之中。"
L["Find Lulubelle Fizzlebang in Stormheim, coerce a demon confession, and complete the Council's final selection."] = "前往风暴峡湾寻找露露贝拉·菲兹班，逼迫恶魔招供，完成议会的最终遴选。"
L["Find the Ancient Hero"] = "找到古代英雄"
L["Find the Boy"] = "找到男孩"
L["Find the Scepter of Sargeras, a weapon that can tear rifts between worlds with a single strike."] = "找到萨格拉斯的权杖——一件只需一击便能在世界之间撕开裂隙的武器。"
L["Finding Ebonchill"] = "寻找黑檀之寒"
L["Finding Fizzlebang"] = "寻找菲兹班"
L["Finding the Scepter"] = "寻找权杖"
L["Finding Your Center"] = "集中精神"
L["Finish Me!"] = "让我解脱吧！"
L["Finish Them!"] = "干掉他们！"
L["Finishing the Job"] = "完成工作"
L["Finna Bjornsdottir"] = "菲娜·伯恩多提尔"
L["Fire Is Always the Answer"] = "火总是那么管用"
L["Firelord Smolderon"] = "炎魔领主斯莫德隆"
L["First Arcanist Thalyssra"] = "首席奥术师塔莉萨"
L["First Contact"] = "第一次接触"
L["First Legion Forward Camp"] = "第一军团前线营地"
L["Fists of the Heavens"] = "天堂之拳"
L["Fit For a Pirate"] = "海盗伙伴"
L["Fizzi Tinkerbow"] = "菲姬·匠弓"
L["Fleet Admiral Tethys"] = "舰队上将特塞斯"
L["Fleet Admiral Tethys told the tale of the Dreadblades — cursed cutlasses that brought ruin to every captain who wielded them. You sailed to the burial site and pried them from the skeletal grip of their last owner, accepting the curse along with the power. The sea itself seemed to shudder as you brought them aboard."] = "舰队上将特塞斯讲述了恐惧之刃的故事——这对被诅咒的弯刀给每一位挥舞过它们的船长都带来了毁灭。你扬帆前往埋葬之地，从它们最后一任主人的枯骨手中撬出了双刀，在接受力量的同时也接受了诅咒。当你把它们带上船时，大海本身似乎都在颤抖。"
L["Fletcher's Hollow is cursed — villagers turned to wicker constructs. Track the three witch sisters responsible and expose their matron."] = "箭谷镇遭到了诅咒——村民们变成了柳条构造体。追踪罪魁祸首女巫三姐妹，揭露她们的女首领。"
L["Fletcher's Hollow was worse than Fallhaven. The curse here had turned villagers into wicker constructs — living husks of thorns and hatred. Lucille led you through the ruins, saving who you could and putting down those beyond help. The trail pointed to three witch sisters working in concert. You charmed the lifeless, followed a revealing missive, and tracked the murderous matron to her lair. With the coven cell destroyed and an airtight alibi for who was truly behind the corruption, the pattern became clear — this was no scattered curse. It was organized. It was a war."] = "箭谷镇的情况比萧湾镇还要糟糕。这里的诅咒把村民变成了柳条构造体——由荆棘与仇恨构成的活体空壳。露希尔带领你穿过废墟，救下能救的人，了结那些已无药可救的人。线索指向三位联手作恶的女巫姐妹。你迷惑了那些行尸走肉，循着一封暴露真相的密信，一路追踪到那位凶残女首领的巢穴。随着这个女巫集会分支被摧毁，幕后真凶的身份也得到了确凿的证实，规律变得清晰起来——这不是零星的诅咒。这是有组织的。这是一场战争。"
L["Flockmaster Sergio"] = "群落之主塞吉奥"
L["Flow Control"] = "流量控制"
L["Flying Colors"] = "流光溢彩"
L["Flynn Fairwind"] = "弗林·法温德"
L["Focusing the Energies"] = "聚焦能量"
L["Fog of War"] = "战场迷雾"
L["Follow Matthias Lehner through Arthas' own memories to the foot of the citadel and Tirion's final gambit."] = "跟随米斯希尔萨·阿奈尔穿越阿尔萨斯自己的记忆，来到堡垒脚下，见证提里奥的最后一搏。"
L["Follow old friends across Pandaria, retracing the journey that shaped the Wandering Isle and the pandaren who left it behind. The mists have lifted, the war has moved on, and a new generation needs to understand what its elders carried into exile.\n\nWalk the slopes of Kun-Lai, sit at the brewmaster's hearth in the Valley of the Four Winds, and listen to stories the rest of the world has only just begun to hear."] = "跟随老朋友们走遍潘达利亚，重温那段塑造了迷踪岛以及离开它的熊猫人的旅程。迷雾已经散去，战争已经远去，新一代需要明白他们的长辈曾将什么带入了流亡之路。\n\n漫步于昆莱山的山坡，在四风谷酒仙的炉火旁坐下，聆听那些世界其他地方才刚刚开始听闻的故事。"
L["Following In His Footsteps"] = "追寻他的足迹"
L["Following the Curse"] = "追踪诅咒"
L["For Gnomeregan!"] = "为了诺莫瑞根！"
L["For those who once swore loyalty to the Banshee Queen, a final message arrives — not to excuse the past, but to acknowledge it. The Forsaken move forward, but the echoes of old vows still linger in the ruins of Lordaeron."] = "对于那些曾宣誓效忠女妖之王的人，最后一则讯息送达了——不是为了开脱过去，而是为了正视它。被遗忘者继续前行，但旧日誓言的回响仍萦绕在洛丹伦的废墟之中。"
L["Forcing Fate's Hand"] = "降下命运之手"
L["Foreman Mann"] = "孟工头"
L["Foreman Raike"] = "工头雷科"
L["Forensic Science"] = "法医学"
L["Forfeit Souls"] = "赔上灵魂"
L["Forging the Armor"] = "铸造铠甲"
L["Forgotten Shadows"] = "遗忘之影"
L["Fortifying the Temple"] = "驻防神殿"
L["Forward Camp is the last flat ground on the way to the citadel. Sappers finish what the bomb chain started. Sky-Commander Keller and Sky-Commander Ichman land their gunship crews to patch what the bombing shook loose. Matthias Lehner, the voice from the saronite pits, begins to speak plainly — and sends you into the Army of the Damned, into the wreckage beneath Sindragosa's broken hill, and into the futility of a hero's last charge. Everything he shows you has the shape of a confession."] = "先锋营地是通往堡垒途中的最后一片平地。工兵们完成了连环爆破未竟的工作。天空指挥官凯勒和天空指挥官伊希曼让各自的炮艇机组人员降落，修补被轰炸震松的地方。米斯希尔萨·阿奈尔——那个来自萨隆邪铁矿坑的声音——开始坦率地说话，他将你送入“召唤大军”，送入辛达苟萨崩塌山丘下的残骸之中，送入一位英雄最后冲锋的徒劳之中。他向你展示的一切，都带着忏悔的模样。"
L["Four dungeons. Four keys. Harlan Sweete and his pirates in Freehold, Overseer Korgus in Tol Dagor, Vol'zith the Whisperer beneath the Shrine of the Storm, the Drust Gorak Tul in Waycrest Manor — all of them fell. The Kul Tiran fleet, locked away by enemies and time and a nation that had stopped believing in itself, was free again. Then came the Siege of Boralus: Priscilla Ashvane, revealed as the architect of Kul Tiras's rot, made her last stand in the harbor. She fell too.\n\nIn Unity Square, Katherine Proudmoore stood before her daughter for the first time in years. She spoke the words no one had expected her to say: she stepped aside. She named Jaina Lord Admiral. She called her back — not as a Kul Tiran returning home, but as the heir to a seat her mother had been keeping warm. The fleet sailed. The song that Jaina's father had sung to her as a child played across the harbor."] = "四座地下城。四把钥匙。自由镇的哈兰·斯威提和他的海盗们、托尔达戈的科古斯狱长、风暴神殿之下的低语者沃尔兹斯、维克雷斯庄园的德鲁斯特人高莱克·图尔——他们全都倒下了。库尔提拉斯人的舰队曾被敌人、时间，以及一个不再相信自己的国家所禁锢，如今终于重获自由。随后便是围攻伯拉勒斯：普里西拉·艾什凡被揭露为库尔提拉斯腐朽的始作俑者，她在港口做了最后的抵抗。她也倒下了。\n\n在联合广场，凯瑟琳·普罗德摩尔多年来第一次站在了女儿面前。她说出了谁也没有料到的话：她选择退位。她任命吉安娜为海军上将。她召唤女儿回来——不是作为一个回家的库尔提拉斯人，而是作为母亲一直为她保留着的那个位置的继承人。舰队扬帆起航。吉安娜的父亲在她儿时为她唱过的那首歌，在港口上空回荡。"
L["Fractured Forces"] = "内讧"
L["Fragments of Disaster"] = "灾难碎片"
L["Frazzle Geargrinder"] = "弗拉索·磨轮"
L["Free Your Mind"] = "解放你的思想"
L["Freeing Our Brothers"] = "拯救同胞"
L["Friends in Cages"] = "笼中伙伴"
L["Friends On the Outside"] = "外面的朋友"
L["Friends With Benefits"] = "朋友的好处"
L["Fringe Science Benefits"] = "边缘科学的好处"
L["From Acherus: The Ebon Hold, the Knights of the Ebon Blade wage their own war against the Burning Legion. The order has no king. It has a Deathlord, and the Deathlord is you.\n\nRaise champions from graveyards across history, gather an army that does not fear death, and decide how far the Ebon Blade is willing to go when the living world needs monsters on its side."] = "黑锋骑士团以阿彻鲁斯：黑锋要塞为据点，对燃烧军团展开他们自己的战争。骑士团没有国王。它只有一位死亡领主，而那位死亡领主就是你。\n\n从历史上的座座墓地中唤起勇士，召集一支无惧死亡的大军，并决定当生者的世界需要怪物站在自己一边时，黑锋骑士团愿意走多远。"
L["From Dreadscar Rift, a pocket of the Twisting Nether claimed by force, the Council of the Black Harvest commands demons to fight demons. It is dangerous work, which is exactly why warlocks are suited to it.\n\nAs Netherlord, rebuild the council, bargain with powers that should not be trusted, and prove that a stolen weapon can still be aimed."] = "恐痕裂隙是扭曲虚空中一处以武力夺取的角落，黑暗收割议会在此驱使恶魔与恶魔作战。这是危险的工作，而这正是术士适合它的原因。\n\n身为虚空领主，你要重建议会，与那些不可信任的力量讨价还价，并证明一件偷来的武器同样可以瞄准敌人。"
L["From the Depths of Azjol-Nerub"] = "艾卓-尼鲁布的深渊"
L["From the Fel Hammer on Mardum, the Illidari wage war against the Burning Legion with the very weapons of the enemy. Their methods are feared, their purpose is absolute, and their enemies know them well.\n\nAs the chosen Slayer, unite the demon hunters, reclaim old ground, and carry the fight into places where fel fire has ruled for ages."] = "伊利达雷以马顿上的邪能之锤为据点，用敌人自己的武器对燃烧军团开战。他们的手段令人畏惧，他们的目标坚定不移，他们的敌人对他们再熟悉不过。\n\n身为天选的杀戮者，你要团结恶魔猎手，夺回旧日的领土，将战火燃向那些邪能之火统治了无数岁月的地方。"
L["From Trueshot Lodge high in the mountains, the Unseen Path watches over Azeroth. Its hunters know the old trails, the hidden passes, and the signs most armies march past without seeing.\n\nAs the order's newest champion, recruit legendary trackers, root out Legion threats, and defend the wild places and cities that still need sharp eyes on the horizon."] = "隐秘之路在高山之上的神射手营地守望着艾泽拉斯。这里的猎手熟知古老的小径、隐秘的山口，以及大多数军队经过时都视而不见的迹象。\n\n身为该组织最新的勇士，你要招募传奇追踪者，铲除燃烧军团的威胁，守护那些仍需锐利目光眺望地平线的荒野与城市。"
L["From Whence They Came"] = "来去无踪"
L["Frostmourne"] = "霜之哀伤"
L["Frozen Memories"] = "冰冻的回忆"
L["Fu Zan, the Wanderer's Companion"] = "福赞，流浪者的伙伴"
L["Full Might of the Elves"] = "精灵的实力"
L["Fun With Landmines"] = "快乐地雷"
L["Furious Familiars"] = "愤怒的爪牙"
L["Furious Fowl"] = "愤怒的飞禽"
L["Futility"] = "徒劳"
L["G.E.A.R. Up"] = "全新G.E.A.R.，迎接挑战！"
L["G'Hanir, the Mother Tree"] = "迦尼尔，母亲之树"
L["Gaining the Upper Hand"] = "占据优势"
L["Gakin the Darkbinder"] = "黑暗缚灵者加科因"
L["Gakin the Darkbinder dispatched troops while Ritssyn uncovered troubling archives — bloodstones were appearing across the Broken Isles, corrupting the land with fel energy. You traveled to Azsuna where Kira Iresoul was already investigating. Together you traced the bloodstone bandits to their source, tested a theory on the stones' hunger for blood, and repaid the debt with fire. Jubeka Shadowbreaker and Zinnin Smythe joined the Council as champions. A daring rescue followed — the Council looked after its own."] = "黑暗缚灵者加科因负责派遣部队，雷特森则发现了一些令人不安的档案——血石正在破碎群岛各地出现，以邪能腐蚀着大地。你前往阿苏纳，奇拉·艾索尔已在那里展开调查。你们一同追查血石匪徒的源头，验证了血石嗜血的推论，并以烈火偿还了这笔血债。裘碧卡·碎影和泽宁·斯米瑟作为勇士加入了议会。随后是一场冒险救援——议会从不抛弃自己人。"
L["Galakrond and the Scourge"] = "迦拉克隆与天灾军团"
L["Galgar's Cactus Apple Surprise..."] = "戈加尔的清凉果……"
L["Garona Halforcen"] = "半兽人迦罗娜"
L["Garrosh sent the Horde to seize whatever had been hidden in the mists. Instead, Hellscream's Fist fell burning into the Jade Forest. Nazgrim drove the survivors forward with fire and discipline, but the first victory curdled quickly. Taran Zhu named the consequence of the Horde's fury: sha. The Horde regrouped at Honeydew Village, pulled its scattered officers out of danger, and learned that Pandaria would answer violence with something far older than either faction expected."] = "加尔鲁什派部落去夺取迷雾中隐藏的一切。结果，地狱咆哮之拳号却燃烧着坠入了翡翠林。纳兹戈林以烈火与铁律驱使幸存者前进，但最初的胜利很快就变了味。祝踏岚道出了部落怒火的后果：煞。部落在蜜露村重整旗鼓，将失散的军官们救出险境，并认识到，潘达利亚会用一种比两大阵营所料想的都要古老得多的东西来回应暴力。"
L["Gates of the Nighthold"] = "要塞大门"
L["Gathering of the Storms"] = "风暴汇聚"
L["Gauging Our Progress"] = "评估进度"
L["Geirrvif"] = "基尔莉芙"
L["General Draven"] = "德莱文将军"
L["General Nazgrim"] = "纳兹戈林将军"
L["Generosity Abounds"] = "深信不疑"
L["Genn Greymane"] = "吉恩·格雷迈恩"
L["Gentle Mother Hanae"] = "温柔的大妈韩妮"
L["Get Back Here!"] = "快回来！"
L["Get the Key"] = "夺取钥匙"
L["Get to Ymirheim!"] = "前往伊米海姆！"
L["Get Your Bearings"] = "熟悉环境"
L["Getting Permission"] = "长辈的许可"
L["Getting the Message"] = "获得消息"
L["Gi-Oh"] = "季鸥"
L["Gilneas survived exile through loyalty, discipline, and the will to endure. By facing the darkness within and without, you helped carry that legacy forward."] = "吉尔尼斯凭借忠诚、自律与坚韧的意志熬过了流亡岁月。你直面内心与外界的黑暗，帮助这份传承延续下去。"
L["Give Me Fuel, Give Me Fire"] = "火上浇油"
L["Giving It All We've Got"] = "全力以赴"
L["Glenbrook Homestead, Drustvar"] = "格伦布鲁克农庄（德鲁斯瓦）"
L["Gnomercy!"] = "无情的侏儒！"
L["Gnomeregan"] = "诺莫瑞根"
L["Gnomeregan's Finest"] = "诺莫瑞根最强王者"
L["Go with Honor, Friend"] = "光荣前行，朋友"
L["Goldrinn"] = "戈德林"
L["Good Fiery Boy"] = "暴脾气的好朋友"
L["Good For Something?"] = "有价值的帮手？"
L["Gorkun Ironskull"] = "戈库恩·铁颅"
L["Grab and Go"] = "拿了就走"
L["Grand Anchorite Almonen"] = "资深学者奥蒙纳"
L["Grand Artificer Romuul"] = "大技师罗姆尔"
L["Grand Executor Mortuus"] = "大执行官摩尔图斯"
L["Grand Magistrix Elisande sealed the city, sending her Duskwatch to crush any hint of dissent. The crackdown was swift and merciless. You fought through patrols and barricades to evacuate nightfallen sympathizers before they could be captured, but not everyone made it out. As the gates slammed shut, the rebellion was forced deeper underground."] = "大魔导师艾利桑德封锁了城市，派出暮色卫队镇压任何异见的苗头。镇压来得迅速而无情。你杀穿巡逻队与路障，赶在堕夜精灵的同情者被捕之前将他们撤离，但并非所有人都逃了出来。随着城门轰然关闭，反抗军被迫转入更深的地下。"
L["Grandmaster's Campaign"] = "大宗师的战役"
L["Greatmother Icemist"] = "冰雾祖母"
L["Greatmother Icemist weeps over a quiet fire. Her son is chained somewhere beneath this frozen plain, and her daughter Banthok is ready to cut every Anub'ar web in the world to bring him home. The Taunka are a proud and wounded people, shaggy cousins to the Tauren whose strength the Scourge has long bled for sport. If they rise again, they rise with the Horde."] = "冰雾祖母在一堆静静燃烧的火旁哭泣。她的儿子被锁在这片冰原之下的某处，而她的女儿班索克已经准备好斩断世上每一张阿努巴尔蛛网，把他带回家。牦牛人是一个骄傲而伤痕累累的民族，他们是牛头人毛发蓬松的远亲，天灾军团长久以来以榨取他们的力量为乐。如果他们再度崛起，必将与部落并肩。"
L["Green Technology"] = "绿色科技"
L["Green-ish Energy"] = "绿色能源"
L["Grif Wildheart spoke of Titanstrike — a rifle of immense power forged by Mimiron himself in the halls of Ulduar. You embarked on a beastly expedition to recover the weapon, facing titan constructs and wild guardians. When you finally held Titanstrike, its mechanisms hummed with the power of a thousand storms."] = "格瑞夫讲述了泰坦之击的故事——一把由米米尔隆亲手在奥杜尔的大厅中锻造、威力无穷的步枪。你踏上了一场与野兽为伍的远征去寻回这件武器，一路上直面泰坦造物和狂野的守护者。当你终于握住泰坦之击时，它的机械装置中嗡鸣着千百场风暴的力量。"
L["Grim Tidings"] = "可怕的消息"
L["Grip of Nightmare"] = "梦魇之握"
L["Grommash Hold, Orgrimmar"] = "格罗玛什要塞（奥格瑞玛）"
L["Grookin Hill"] = "古鲁金猴山"
L["Grookin Hill roared to life in exactly the way a hozen fortress would: loud, improvised, and enthusiastic about explosives. Chief Kah Kah had given the Horde a foothold, but Nazgrim still needed scouts, maps, and pressure against the Alliance. Rivett sent messages through ridiculous means, Shokia and the scouts reported enemy positions, and the Horde learned how the jinyu, SI:7, and Alliance soldiers fit together. By the end, Guerrillas in our Midst became Burning Down the House. The hozen pact held, and the road to Dawn's Blossom opened through smoke."] = "古鲁金猴山以猢狲要塞特有的方式热闹了起来：吵闹、随性，而且对炸药充满热情。酋长卡哈卡哈为部落提供了一处立足点，但纳兹戈林仍然需要斥候、地图，以及对联盟持续施压。利维特用荒唐可笑的方式传递消息，夏琪亚和斥候们回报了敌军阵地，部落也弄清了锦鱼人、军情七处和联盟士兵之间的关联。到最后，“身边的游击队”变成了“烧毁那座房子”。猢狲的盟约得以维持，通往晨芳园的道路在硝烟中打开了。"
L["Ground Commander Koup"] = "地面指挥官库普"
L["Ground Commander Xutjja"] = "地面指挥官科特亚"
L["Groundskeeper Wu"] = "园丁老吴"
L["Grovebound"] = "回到林地"
L["Growing Power"] = "力量增长"
L["Grumnus Steelshaper"] = "格鲁努斯·削钢"
L["Guerrillas in our Midst"] = "身边的游击队"
L["Guided by Kel'danath's research, you descended into ancient caverns beneath Suramar, where moonlight filtered through crystal and the memories of the city's founding still lingered. You discovered the hidden legacy of Valewalker Farodin and the Arcan'dor — a tree of immense power that might hold the key to curing the nightfallen's addiction to the Nightwell."] = "在凯尔丹纳斯研究成果的指引下，你深入苏拉玛地下的古老洞穴，月光透过水晶洒落，城市建立之初的记忆仍在此萦绕。你发现了山谷行者法罗丁隐藏的遗产，以及奥坎多——一棵拥有巨大力量的树，它或许是治愈堕夜精灵对暗夜井依赖的关键。"
L["Gunpowder Research"] = "火药研究"
L["Guts and Gore"] = "鲜血淋漓的内脏"
L["Halduron Brightwing"] = "哈杜伦·明翼"
L["Halford Wyrmbane"] = "哈尔弗·维姆班恩"
L["Hall of the Guardian / Broken Isles"] = "守护者圣殿 / 破碎群岛"
L["Halls of Valor"] = "英灵殿"
L["Halls of Valor: Odyn's Cauldron"] = "英灵殿：奥丁的大锅"
L["Halls of Valor: The Brewmaster"] = "英灵殿：酿酒大师"
L["Halting the Empire's Fall"] = "阻止帝国的陨落"
L["Hamuul Runetotem sends an urgent summons. Through the Emerald Dreamway, you discover the Dreamgrove and take up a weapon of legend."] = "哈缪尔·符文图腾发来紧急召唤。你穿过翡翠梦境之路，发现了梦境林地，并拿起一件传奇武器。"
L["Hanzabu"] = "汉扎布"
L["Hanzabu leads you to Bwonsamdi, loa of death, deep in his Necropolis. He will fight the blood trolls — for one million souls."] = "汉扎布带领你深入亡者之城，去见死亡洛阿邦桑迪。他愿意对抗血巨魔——代价是一百万个灵魂。"
L["Hanzabu, servant of the death loa, led you into Bwonsamdi's Necropolis — a place where the veil between the living and the dead was thin enough to talk through. Bwonsamdi was many things: charming, unsettling, and entirely in control of any room he entered. He had watched the blood trolls desecrate his death shrines and steal souls that were owed to him. He was not pleased. The deal he offered was simple — his power in exchange for one million souls delivered to his realm. You cleansed his temple of spirits who had fled to G'huun, repelled Grand Ma'da Ateena's interruption of the sealing ritual, and sealed the pact. A deal with a death loa is not something you walk back from."] = "死亡洛阿的仆从汉扎布领你进入邦桑迪的亡者之城——在那里，生者与亡者之间的帷幕薄得几乎可以隔着交谈。邦桑迪身上有许多特质：迷人、令人不安，而且无论走进哪个房间，都能完全掌控全场。他眼睁睁看着血巨魔亵渎他的死亡神龛，偷走那些本该归他的灵魂。他很不高兴。他提出的交易很简单——以他的力量，换取送入他领域的一百万个灵魂。你清除了他神殿中投奔戈霍恩的灵魂，击退了长母阿提娜对封印仪式的干扰，并缔结了契约。与死亡洛阿的交易，一旦达成就无法反悔。"
L["Hao Mann"] = "孟豪"
L["Harmful If Swallowed"] = "吞食有害"
L["Harnessing Power"] = "驾驭力量"
L["Hatred's Focus"] = "憎恨焦镜"
L["He Who Walks in the Light"] = "与圣光同行之人"
L["He's Gone to Pieces"] = "支离破碎"
L["Head of the Viper"] = "毒蛇首领"
L["Heart of Lukou"] = "露可之心"
L["Heart of the Issue"] = "症结之心"
L["Held Captive!"] = "俘虏！"
L["Hellscream's Fist crashes into Pandaria, leaving Nazgrim to turn wreckage, survivors, and frightened locals into a foothold."] = "地狱咆哮之拳号坠毁在潘达利亚，纳兹戈林只能依靠残骸、幸存者和惊恐的当地人建立起一处立足点。"
L["Help Chief Telemancer Oculeth restore the teleportation network, opening new paths across Suramar."] = "帮助首席传送师欧库勒斯修复传送网络，在苏拉玛各地开辟新的通路。"
L["Helping the Cause"] = "略尽绵力"
L["Helya's Horn"] = "海拉之角"
L["Hemet Nesingwary"] = "赫米特·奈辛瓦里"
L["Hemet Nesingwary joined the hunt in Highmountain, his expertise invaluable as you tracked the Legion's movements. But the true threat emerged in Azsuna — leyworms corrupted by demonic energy, twisting the beasts of the land into weapons. Working with Kira Iresoul, you lured out the source of the corruption and tamed it, proving that a hunter's bond with nature was stronger than any demon's magic."] = "赫米特·奈辛瓦里在至高岭加入了狩猎，在你追踪燃烧军团动向时，他的专业知识弥足珍贵。但真正的威胁出现在阿苏纳——被恶魔能量腐化的魔网蠕虫，正将这片土地上的野兽扭曲成武器。你与奇拉·艾索尔合作，引出了腐化的源头并将其驯服，证明了猎人与自然之间的羁绊比任何恶魔魔法都更加强大。"
L["Herald Their Demise"] = "死亡宣告"
L["Herding Goats"] = "牧羊"
L["Heritage o' the Dark Iron"] = "黑铁的传承"
L["Heritage of Draenor"] = "德拉诺传承"
L["Heritage of Gilneas"] = "吉尔尼斯传承"
L["Heritage of Gnomeregan"] = "诺莫瑞根传承"
L["Heritage of Kezan"] = "科赞传承"
L["Heritage of the Bronzebeard"] = "铜须传承"
L["Heritage of the Darkspear"] = "暗矛传承"
L["Heritage of the Draenei"] = "德莱尼传承"
