L["Highlord Bolvar Fordragon"] = "大领主伯瓦尔·弗塔根"
L["Highlord Bolvar Fordragon leads you up the spiral of Wyrmrest Temple. Alexstrasza the Life-Binder has watched the war in Dragonblight with ancient, weary eyes. She owes the Alliance nothing. She owes the living everything. If she can be moved, her fire will answer for Azeroth's dead — and a ruby wing will carry you over ground no army could cross."] = "大领主伯瓦尔·弗塔根带你沿着龙眠神殿的螺旋阶梯向上攀登。阿莱克丝塔萨，生命的缚誓者，一直以古老而疲惫的双眼注视着龙骨荒野的战事。她对联盟毫无亏欠，却对一切生灵责无旁贷。如果能打动她，她的烈焰将为艾泽拉斯的亡者讨回公道——红龙的双翼将载着你飞越任何军队都无法穿越的土地。"
L["Highlord Darion Mograine"] = "大领主达里安·莫格莱尼"
L["Highlord Demitrian"] = "德米提恩"
L["Highlord Tirion Fordring"] = "大领主提里奥·弗丁"
L["Highlord's Campaign"] = "大领主的战役"
L["Highlord's Golden Charger"] = "大领主的金色战马"
L["Highmountain Hunters"] = "至高岭猎人"
L["Hir'eek, the Bat Loa"] = "蝙蝠之神希里克"
L["Hired Help"] = "雇佣帮手"
L["Hobart Grapplehammer"] = "霍巴特·钩锤"
L["Hobart Grapplehammer has a masterpiece, a deadline, and a former employer determined that neither will reach completion. Trade Prince Gallywix has eyes everywhere, and the workshop where the work has to happen is exactly as glamorous as Crapopolis sounds.\n\nReunite old allies, outplay better-funded saboteurs, and keep one bombastic invention from being seized, sold, stolen, exploded, or all four in sequence."] = "霍巴特·钩锤手头有一件杰作、一个最后期限，还有一位决意让这两者都无法完成的前雇主。贸易大王加里维克斯的眼线无处不在，而必须在那里完工的车间，就和“渣客城”这个名字听起来一样“光鲜体面”。\n\n召集昔日的盟友，智胜资金更雄厚的破坏者，保护一项夸张至极的发明不被没收、变卖、偷走、炸毁——或者四者依次发生。"
L["Hodir"] = "霍迪尔"
L["Hold The Barricade!"] = "坚守路障"
