L["Hunt a Legion commander through Stormheim, prepare the Fel Hammer for interdimensional travel, and invade the demon world Niskara."] = "在风暴峡湾追猎一名燃烧军团指挥官，让邪能之锤做好跨维度航行的准备，然后入侵恶魔世界尼斯卡拉。"
L["Hunt down the Twinblades of the Deceiver — warglaives forged in felfire and wielded by a champion of the Legion."] = "追寻欺诈者的双刃——这对战刃在邪火中锻造，由一名燃烧军团的勇士所持。"
L["Hunt the Hunter"] = "猎人与猎物"
L["Hunt the legendary hero-slayer in Stormheim to claim a pair of rune-etched swords forged for the fury of battle."] = "在风暴峡湾追猎传说中的英雄杀手，取得一对为战斗之怒而锻造的符文刻印双剑。"
L["Huntmaster's Campaign"] = "狩猎大师的战役"
