L["I Am the Slayer!"] = "屠魔者！"
L["I Don't Get My Hands Dirty"] = "别脏了我的手"
L["I Have an Idea, But First..."] = "我有一计……"
L["I Have No Jade And I Must Scream"] = "疯狂的石头"
