L["Impending Dooooooom!"] = "末日降临！"
L["Implements of Ill Intent"] = "恶意道具"
L["Improper Burial"] = "超度已逝的赞达拉巨魔"
L["In ancient Drust ruins, Lucille discovers the Order of Embers — an old organization of witch hunters. She vows to rebuild it."] = "在古老的德鲁斯特遗迹中，露希尔发现了灰烬骑士团——一个古老的猎巫组织。她发誓要重建它。"
L["In Case of Ambush"] = "预防伏击"
L["In Deep Slumber"] = "进入沉眠"
L["In Defense of Dalaran"] = "保卫达拉然"
L["In Gloom Hollow, the great frog loa Krag'wa hungers — and he is willing to fight if you can earn his trust. Become a friend of the frogs."] = "在林荫巨木，伟大的蛙洛阿克拉格瓦饥肠辘辘——只要你能赢得他的信任，他就愿意出战。成为青蛙们的朋友吧。"
L["In Netherlight Temple, priests of the Light and the Void unite under one banner. Faith, shadow, discipline, and doubt all have a place when the world is facing annihilation.\n\nAs High Priest, bridge old divides, investigate zealots and lost allies, and hold together a conclave built from powers that do not always agree they should stand side by side."] = "在虚空之光神殿，圣光与虚空的牧师们团结在同一面旗帜之下。当世界面临毁灭之时，信仰、暗影、戒律与怀疑都有一席之地。\n\n身为大主教，你要弥合旧日的分歧，调查狂热者与失散的盟友，维系这个由不同力量组成的议会——而这些力量并不总是认同彼此应该并肩而立。"
L["In Search of the Eye"] = "寻找渡鸦之眼"
L["In Search of Wisdom"] = "寻求智慧"
L["In the Bag"] = "囊中之物"
L["In the Business of Souls"] = "出卖灵魂"
L["In the Forest Ward, the Venthyr teach humility by giving souls hope and then hunting them down. The Accuser helps you see the cruelty beneath the lesson."] = "在森林区，温西尔以先给予灵魂希望、再将其猎杀的方式来教导谦卑。指控者帮助你看清了这种教诲背后的残忍。"
L["In the Hall of the Drust King"] = "德鲁斯特之王大厅"
L["In the Ruin of Rebellion"] = "叛乱废墟之下"
L["In the wake of the Peak of Serenity's fall, you prepared to strike back. The Fists of the Heavens — enchanted handwraps that crackled with storm energy — were said to channel the very fury of the skies. You fought through the Legion's forces to claim them, and with each punch, thunder rolled across the battlefield."] = "晴日峰陷落之后，你准备发起反击。据说天堂之拳——一对闪烁着风暴能量的附魔裹手——能够引导苍穹之怒。你杀穿燃烧军团的部队将其夺取，每一拳挥出，雷声都滚过战场。"
L["In twilight shadows, Faol revealed the existence of Xal'atath — a blade forged in the age of the Black Empire, before even the titans came to Azeroth. The dagger whispered constantly, its voice ancient and knowing, full of secrets that could drive lesser minds mad. You claimed it from a twilight cult's grasp, and from that moment on, the whispers never stopped. Xal'atath remembered everything — and it wanted you to know."] = "在暮光的阴影中，法奥揭示了萨拉塔斯的存在——一把在黑暗帝国时代锻造的匕首，那时甚至连泰坦都尚未降临艾泽拉斯。这把匕首不停地低语，它的声音古老而洞悉一切，充满了足以让意志薄弱者发狂的秘密。你从一个暮光教派手中夺下了它，从那一刻起，低语就再也没有停止过。萨拉塔斯记得一切——而且它想让你知道。"
L["Infiltrate the Nightborne wine trade, disrupting the flow of arcwine that keeps the populace loyal to the Grand Magistrix."] = "渗透夜之子的酒类贸易，切断让民众对大魔导师保持忠诚的魔法酒供应。"
L["Infiltrate the Scarlet Onslaught, the fanatical remnant of the Scarlet Crusade, and recruit a defector to your cause."] = "潜入血色十字军的狂热残部血色突袭军，招募一名叛逃者加入你的事业。"
L["Infiltrate Zalamar disguised as a blood troll. The bat loa Hir'eek has been corrupted — you must end the corruption and the loa with it."] = "伪装成血巨魔潜入扎拉玛。蝙蝠洛阿希里克已经被腐化——你必须终结这腐化，连同这位洛阿一起。"
L["Infiltrating Our Enemies"] = "渗透敌军"
L["Information at Any Cost"] = "不计代价获得情报"
L["Informing Our Allies"] = "汇报情况"
L["Initiate Da-Nel"] = "新兵达尼尔"
L["Inkmaster Wei"] = "墨水大师魏"
L["Inquisitor Cleardawn"] = "审判官克利多恩"
L["Inquisitor Cleardawn leads the southern campaign through the old roads, clearing Drust strongholds along the way."] = "审判官克利多恩沿着古老的道路率领南方战役，一路清除德鲁斯特据点。"
L["Inquisitor Cleardawn took command of the southern front. Through the old roads you marched — ancient paths the Drust had walked millennia before. The pieces of history you uncovered told a chilling story: the Drust had not simply been defeated in the past. They had been driven into hiding, and they had been waiting. You gave their soldiers an honorable discharge — the permanent kind — and pushed through to a clear victory. But the Drust ruins at Gol Osigr loomed ahead, and the fall of the Drust was far from over."] = "审判官克利多恩接管了南方战线。你们穿越老路行军——那是德鲁斯特人数千年前走过的古道。你发掘出的历史碎片讲述了一个令人胆寒的故事：德鲁斯特人在过去并非仅仅是被击败了。他们被迫隐匿起来，一直在等待。你给了他们的士兵一次光荣退役——永久的那种——并一路推进，取得了明确的胜利。但前方的戈尔奥希格德鲁斯特遗迹若隐若现，德鲁斯特的覆灭远未结束。"
L["Inquisitor Stelia's Sinstone"] = "审判官斯泰丽雅的罪碑"
L["Inquisitor Sterntide"] = "审判官斯坦泰德"
L["Inquisitor Vilhelm's Sinstone"] = "审判官威尔海姆的罪碑"
L["Inside the Frozen Citadel"] = "进入寒冰堡垒"
L["Instant Messaging"] = "即时通信"
L["Instructor Myang"] = "孟教头"
L["Instructor Xann"] = "夏教头"
L["Insurrection"] = "起义"
L["Insurrection: Crafting War"] = "起义：备战"
L["Intense Concentration"] = "超高浓度"
L["Interest Yah In A Pint?"] = "想来点儿酒吗？"
L["Into Darkness"] = "堕入黑暗"
L["Into Duskwood"] = "进入暮色森林"
L["Into Hostile Territory"] = "进入敌占区"
L["Into Our Ranks"] = "提拔勇士"
L["Into the Crevasse"] = "深入裂缝"
L["Into the Crimsonwood"] = "深入赤林"
L["Into The Darkness"] = "深入黑暗"
L["Into the Dragonblight"] = "深入龙骨荒野"
L["Into the Fold"] = "深入密林"
L["Into The Frozen Heart Of Northrend"] = "进入诺森德的冰冷腹地"
L["Into the Heart of Tiragarde"] = "进入提拉加德之心"
L["Into the Light"] = "没入圣光"
L["Into the Mists"] = "深入迷雾"
L["Into the Oculus"] = "进入魔环"
L["Into the Void"] = "踏入虚空"
L["Into The Wild Green Yonder"] = "空中救兵"
L["Investigate bloodstone corruption in Azsuna. Kira Iresoul proves her worth as the Council recruits new champions."] = "调查阿苏纳的血石腐化。在议会招募新勇士之际，奇拉·艾索尔证明了自己的价值。"
L["Investigate conspiracy and betrayal tied to Stormwind's past and the Defias Brotherhood."] = "调查与暴风城的往事以及迪菲亚盗贼有关的阴谋与背叛。"
L["Investigate void disturbances in Azsuna alongside Zabra Hexx and Yalia Sagewhisper."] = "与扎布拉·海克斯和雅丽亚·圣言者一同调查阿苏纳的虚空扰动。"
L["Invitation of the Master"] = "主人的邀请"
L["Invitation to the Spirit Festival"] = "古灵节邀请"
L["Iron-Body Ponshu"] = "金刚不坏彭戍"
L["Iron-Body Ponshu received a desperate report — Tian Monastery was under attack. You rushed to its defense alongside Taran Zhu, the grim Shado-Pan lord, and The Monkey King, whose tricks proved as deadly as any blade. Instructor Myang held the line while you slowed the Legion's spread, and together you struck down the Hand of Keletress who led the assault. High Elder Cloudfall oversaw the monastery's rebuilding, and both Taran Zhu and The Monkey King pledged themselves as your champions."] = "金刚不坏彭戍收到一份紧急报告——天禅院遭到了攻击。你与冷峻的影踪派宗主祝踏岚，以及诡计和利刃一样致命的美猴王一同赶去驰援。孟教头坚守防线，你则遏制了燃烧军团的蔓延，最终你们合力击倒了率领这次进攻的克雷特斯之手。云瀑长老主持了天禅院的重建工作，祝踏岚和美猴王也都宣誓成为你的勇士。"
L["Iron-Body Ponshu revealed that Sheilun — the staff of Emperor Shaohao himself — had been hidden since the emperor used it to shroud Pandaria in mist ten thousand years ago. You followed the trail of ancient magic to its resting place, where Shaohao's mists still swirled protectively around the staff. When you claimed Sheilun, the mists parted willingly — as if the emperor had been waiting for someone to carry his burden."] = "金刚不坏彭戍透露，雪伦——皇帝少昊本人的法杖——自一万年前皇帝用它将潘达利亚笼罩在迷雾之中后，便一直隐藏于世。你循着古老魔法的踪迹找到了它的安息之地，少昊的迷雾仍护卫般地环绕在法杖周围。当你取得雪伦时，迷雾主动散开——仿佛皇帝一直在等待有人来承担他的重任。"
L["Iron-Body Ponshu spoke of a legend — the Storm Brew, a drink of such power it could turn the tide of any battle. The recipe was held by Aegira, a vrykul brewmaster who had perfected her craft in the Halls of Valor over centuries. You entered Odyn's domain, earned the right to brew alongside Aegira, and retrieved the ingredients from Odyn's own cauldron. The Storm Brew was unlike anything brewed on Azeroth — and with it, your weapon was reforged to its full power. The Grandmaster's campaign was complete."] = "金刚不坏彭戍讲述了一个传说——风暴蜜酒，一种威力强大到足以扭转任何战局的饮品。它的配方掌握在艾吉拉手中，这位维库酒仙在英灵殿中花了数百年时间完善自己的技艺。你进入奥丁的领域，赢得了与艾吉拉一同酿酒的资格，并从奥丁本人的大锅中取得了原料。风暴蜜酒与艾泽拉斯上酿造过的任何酒都截然不同——借助它，你的武器被重铸，恢复了全部力量。大宗师的战役就此完成。"
L["Iron-Body Ponshu told you of Fu Zan — a simple-looking staff that had been passed from wanderer to wanderer since the dawn of the monk tradition. It looked like a walking stick, but those who carried it found that no enemy could stand against them. You tracked it through remote monasteries and dangerous wilds, and when you took it up, it felt like an old friend settling into your hand."] = "金刚不坏彭戍向你讲述了福赞的故事——这根看似朴素的法杖，自武僧传统诞生之初便在一位又一位流浪者之间传承。它看上去就像一根手杖，但持有它的人会发现，没有敌人能够抵挡他们。你穿过偏远的寺院和危险的荒野追寻它的踪迹，当你将它握在手中时，感觉就像一位老朋友安然落入你的掌心。"
L["Ironforge / Dun Morogh / Loch Modan"] = "铁炉堡 / 丹莫罗 / 洛克莫丹"
L["Isolating Zalamar"] = "隔离扎拉玛"
L["It Could Kill Us All"] = "危险的能量"
L["It Hungers for Blood"] = "嗜血之石"
L["It's All Fun and Games"] = "乐趣十足"
L["It's Called Borrowing"] = "有借不还"
L["It's Not a Spirit Festival Without Spirits"] = "没有古灵不叫古灵节"
L["Iterating Upon Success"] = "延续成功"
L["Izzy"] = "小静"
L["Jace Darkweaver"] = "杰斯·织暗"
L["Jace Darkweaver told the story of the Aldrachi — a warrior race so fierce they defeated the demon lord Sargeras sent to enslave them. Rather than serve, they fell on their own blades. Those weapons had been lost for millennia, but Jace had found a lead. You followed it through a series of trials, establishing a connection to the blades through sheer will. The Aldrachi Warblades chose you — the first wielder since the race that forged them chose extinction over submission."] = "杰斯·织暗讲述了奥达奇的故事——一个骁勇无比的战士种族，他们击败了萨格拉斯派来奴役他们的恶魔领主。他们不愿屈从，宁可以刃自尽。这些武器已失落数千年，但杰斯找到了一条线索。你循着它经历了一系列试炼，凭借纯粹的意志与这对战刃建立起联系。奥达奇战刃选择了你——自锻造它们的种族宁可灭绝也不屈服以来，你是第一位持有者。"
L["Jaded Heart"] = "灵玉之心"
L["Jagged Shards"] = "粗糙的碎片"
L["Jailbreak"] = "越狱"
L["Jaina brought you to Kul Tiras aboard the Alliance fleet, and the moment she stepped off the ship she was surrounded by Proudmoore Guard acting on Katherine's orders. Her own mother had her arrested for treason. You were thrown in Tol Dagor prison alongside her — until Flynn Fairwind, a sailor with nothing to lose and excellent lock-picking instincts, got you both out. Cyrus Crestfall and the 7th Legion met you on the outside. The road to earning Kul Tiras back for the Alliance runs through three zones — and through a rift between mother and daughter that has been open for years."] = "吉安娜随联盟舰队带你来到库尔提拉斯，她刚一下船，就被奉凯瑟琳之命行事的库尔提拉斯卫兵团团围住。她的亲生母亲以叛国罪逮捕了她。你和她一起被关进了托尔达戈监狱——直到弗林·法温德，一个一无所有却极擅开锁的水手，把你们俩都救了出去。赛勒斯·克雷斯弗和第七军团在外面接应你们。要为联盟赢回库尔提拉斯，必须走遍三个地区——还要跨越一道横亘在母女之间多年的裂痕。"
L["Jaina Proudmoore"] = "吉安娜·普罗德摩尔"
L["Jaina Proudmoore brings the Alliance to Kul Tiras — and is immediately arrested by her own mother's guards the moment she sets foot on the docks. Katherine Proudmoore, Lord Admiral in her daughter's absence, has not forgiven Jaina for the death of her father Daelin. Jaina is imprisoned in Tol Dagor. You break out with the help of a disgraced sailor named Flynn Fairwind, surface in a Kul Tiras rebuilding itself from the inside out, and learn that three zones of unrest must be addressed before Kul Tiras will trust the Alliance — or her."] = "吉安娜·普罗德摩尔带着联盟来到库尔提拉斯——却在踏上码头的那一刻就被她母亲的卫兵逮捕。在女儿离开期间执掌海军上将之位的凯瑟琳·普罗德摩尔，始终没有原谅吉安娜对其父戴林之死所负的责任。吉安娜被关进了托尔达戈。你在一位名叫弗林·法温德的落魄水手帮助下越狱，来到了一个正由内而外重建自身的库尔提拉斯，并得知必须先平息三个地区的动乱，库尔提拉斯才会信任联盟——或者她。"
L["Jaina Proudmoore was once Theramore's defender and the Alliance's most celebrated mage. When the Horde dropped a mana bomb on her city, she emerged from the wreckage transformed: her hair turned white, her grief hardened into fury, and old friendships began to fall away.\n\nWhen Battle for Azeroth begins, Jaina returns to Kul Tiras, the home that remembers her not as a hero, but as the daughter who let Daelin Proudmoore die. What follows is a journey through estrangement, politics, old guilt, and the question of whether a broken bond can still be mended."] = "吉安娜·普罗德摩尔曾是塞拉摩的守护者，也是联盟最负盛名的法师。当部落将法力炸弹投向她的城市时，她从废墟中走出，从此判若两人：她的头发变得雪白，悲痛化为怒火，昔日的友谊也开始逐渐疏远。\n\n当争霸艾泽拉斯的故事拉开帷幕时，吉安娜回到了库尔提拉斯，而故乡记得她的方式不是英雄，而是那个任由戴林·普罗德摩尔死去的女儿。接下来的旅程关乎疏离、政治、旧日的愧疚，以及一个问题：破碎的亲情是否还能弥合。"
L["Jaina Proudmoore, now Lord Admiral, turns the Kul Tiran fleet against the Zandalari Empire. The plan: draw the Horde's forces deep into Nazmir with the Abyssal Scepter while the Alliance fleet strikes Zuldazar harbor from the south. Jaina personally freezes the harbor, and the Battle of Dazar'alor begins."] = "如今已是海军上将的吉安娜·普罗德摩尔，率领库尔提拉斯人的舰队调转矛头指向赞达拉帝国。计划是：用深渊权杖将部落的部队引入纳兹米尔深处，同时联盟舰队从南面突袭祖达萨港。吉安娜亲手冰封了港口，达萨罗之战就此打响。"
L["Jarum Skymane"] = "贾鲁·天鬃"
L["Jeek Jeek"] = "叽克叽克"
L["Ji Firepaw"] = "季·火掌"
L["Ji Firepaw (Horde)"] = "吉·火爪（部落）"
L["Join Maiev and the Wardens against old corruption and reclaim a symbol of night elf devotion."] = "与玛维和守望者一同对抗古老的腐化，夺回象征暗夜精灵虔诚信仰的圣物。"
L["Join the Gnomeregan Engineering and Aviation Reserve as it tests the most ambitious aircraft to leave a workshop since the Great War. Old Gnomeregan is still dangerous, and not every threat beneath the city is content to stay buried.\n\nRecruit specialists, salvage prototypes, and turn brilliant schematics into machines that actually fly, preferably with all limbs and eyebrows accounted for."] = "加入诺莫瑞根工程航空预备队，参与测试自大战以来走出车间的最雄心勃勃的飞行器。旧诺莫瑞根依然危机四伏，城市地下的威胁也并非全都甘愿长埋不出。\n\n招募专家，回收原型机，把天才的设计图变成真正能飞的机器——最好还能保证四肢和眉毛一样不少。"
L["Joining the Assault"] = "协助突袭"
L["Jojo Ironbrow"] = "乔乔·铁眉"
L["Jorach's Calling"] = "乔拉齐的召唤"
L["Jorhuttam"] = "尤胡塔姆"
L["Jotunheim"] = "尤顿海姆"
L["Journey deep into the Emerald Dream to recover G'Hanir, the branch from which all world trees grew."] = "深入翡翠梦境，寻回迦尼尔——所有世界之树皆由此枝生长而来。"
L["Journey to Icecrown Citadel to reforge the shattered remnants of Frostmourne into twin runeblades."] = "前往冰冠堡垒，将霜之哀伤的残片重铸为一对符文剑。"
L["Journey to Nazmir"] = "前往纳兹米尔"
L["Journey to the ancient groves of Val'sharah to find a seed that could save the Arcan'dor."] = "前往瓦尔莎拉的古老林地，寻找一颗能够拯救奥坎多的种子。"
L["Journey to the Broken Shore and the ruins of Stromgarde to claim the legendary two-handed sword once wielded by the troll-slaying king."] = "前往破碎海滩和激流堡废墟，取得那位屠戮巨魔的国王曾经挥舞的传奇双手剑。"
L["Journey to the Middle of Nowhere"] = "前往与世隔绝之地"
L["Journey to the ruins of Stromgarde to raise King Thoras Trollbane, the second Horseman, from his defiled grave."] = "前往激流堡废墟，将第二位天启骑士索拉斯·托尔贝恩国王从他遭亵渎的坟墓中唤起。"
L["Jubeka Shadowbreaker"] = "裘碧卡·碎影"
L["Judgment"] = "审判"
L["Judgment Awaits"] = "审判降临"
L["Judgment Day Comes!"] = "审判日降临！"
L["Jump-Capable"] = "实现迁跃"
L["Jungo, Herald of G'huun"] = "加恩诺，血神使徒"
L["Just for Safekeeping, Of Course"] = "当然，只是为了保管"
L["Justicar Julia Celeste"] = "裁决者朱莉亚·塞雷斯蒂"
L["Kai Wanderbrew"] = "凯·游酒"
L["Kai-Lin Honeydew"] = "林凯·蜜露"
L["Kalec's Plan"] = "卡雷的计划"
L["Kaltunk"] = "卡尔图克"
L["Kanrethad Ebonlocke"] = "坎雷萨德·埃伯洛克"
L["Kasea Angerforge"] = "凯西亚·怒炉"
L["Katherine Proudmoore"] = "凯瑟琳·普罗德摩尔"
L["Kathra'natir has possessed Meryl Felstorm. Storm the Oculus with Khadgar to save the Tirisgarde's founder and destroy the dreadlord."] = "卡斯拉纳提尔附身了梅瑞尔·邪风。与卡德加一同攻入魔环，拯救提瑞斯法守护者的创始人，消灭这名恐惧魔王。"
L["Kayn Sunfury"] = "凯恩·日怒"
L["Kayn Sunfury arranged the hunt for the Twinblades of the Deceiver — a pair of warglaives crackling with felfire, wielded by one of the Legion's own champions. You tracked the demon through shadowed ruins and claimed the blades in combat. They burned in your hands, eager for the blood of their former masters."] = "凯恩·日怒安排了对欺诈者的双刃的追猎——这对战刃迸溅着邪火，由燃烧军团的一名勇士所持。你穿过阴暗的废墟追踪这个恶魔，在战斗中夺取了双刃。它们在你手中燃烧，渴望饮下其旧主的鲜血。"
L["Keep Yer Feet On The Ground"] = "一路走好"
L["Keep Your Friends Close"] = "亲近你的朋友"
L["Keeper Remulos"] = "守护者雷姆洛斯"
L["Keeper Remulos spoke of G'Hanir — the mother branch from which Nordrassil, Teldrassil, and every world tree had grown. It slumbered deep in the Emerald Dream, and the Nightmare sought to consume it. You ventured into the Dream's purest heart and returned with G'Hanir in hand, its leaves still green with the life of an entire world."] = "守护者雷姆洛斯提到了迦尼尔——诺达希尔、泰达希尔以及每一棵世界之树的母枝。它沉睡在翡翠梦境深处，而梦魇企图将其吞噬。你深入梦境最纯净的核心，带着迦尼尔归来，它的叶片依旧青翠，饱含着整个世界的生命。"
L["Kel'danath's Legacy"] = "凯尔丹纳斯的遗产"
L["Keritose Bloodblade"] = "克里托斯·血刃"
L["Keula"] = "寇拉"
L["Kevo ya Siti"] = "希蒂-柯沃"
L["Key members of the resistance have vanished. Search the city to find them before it's too late."] = "抵抗军的关键成员失踪了。在一切为时已晚之前，搜遍全城找到他们。"
L["Key members of the resistance vanished without a trace — taken in the night by Elisande's agents. You tracked them through Suramar's twisting streets, from soul cages to smuggler's routes, pulling allies from the jaws of captivity. The message was clear: the Grand Magistrix knew about the rebellion, and she was coming for them all."] = "抵抗军的关键成员消失得无影无踪——他们在夜里被艾利桑德的特工带走了。你穿过苏拉玛蜿蜒曲折的街道追踪他们，从灵魂囚笼到走私者的通道，将盟友们从囚禁的魔爪中救出。信号再清楚不过：大魔导师已经知晓了反抗军的存在，她要将他们一网打尽。"
L["Khadgar's Discovery"] = "卡德加的发现"
L["Kibli Killohertz"] = "吉普利·基罗赫斯"
L["Kill Kher Shan"] = "杀死柯山"
L["Killing Two Scourge With One Skeleton"] = "一举两得"
L["Killohertz"] = "吉普利·基罗赫斯"
L["King of the Hill"] = "山丘之王"
L["King of the Mountain"] = "占山为王"
L["King Varian's command sent you after the missing White Pawn: Prince Anduin Wrynn. The Skyfire found Pandaria and immediately found the Horde. Admiral Rogers turned the gunship into a weapon, Sully McLeary got you onto the ground, and Paw'don Village became the Alliance's first real foothold. Every step inland was paid for in smoke, wounded soldiers, stolen supplies, and the first glimpse of sha born from the armies' violence. By the time Ga'trul fell at Twinspire Keep, the Alliance had survived its landing - but Taylor and Anduin were still missing."] = "瓦里安国王一声令下，你奉命追寻失踪的“白兵”：安度因·乌瑞恩王子。天火号找到了潘达利亚，随即也撞上了部落。罗杰斯上将将炮艇化作武器，萨利·麦克雷把你送上地面，坡东村成为了联盟第一个真正的立足点。向内陆挺进的每一步，都是用硝烟、负伤的士兵、被劫的补给换来的，人们也第一次瞥见了由军队暴行催生的煞。当加图尔在双塔堡垒倒下时，联盟终于挺过了登陆战——但泰勒和安度因依然下落不明。"
L["Kira Iresoul"] = "奇拉·艾索尔"
L["Kitty?"] = "猫咪？"
L["Knight-Captain Drosche"] = "骑士队长德洛斯彻"
L["Knights of the Ebon Blade"] = "黑锋骑士团"
L["Knock It Off!"] = "快停下！"
L["Knowing Our Enemy"] = "知己知彼"
L["Knowledge is a Terrible Burden"] = "知识是可怕的负担"
L["Koltira Deathweaver"] = "库尔迪拉·织亡者"
L["Kor'kron Squad Leader"] = "库卡隆班长"
L["Kor'vas Bloodthorn"] = "考瓦斯·血棘"
L["Kor'vas Bloodthorn calls you to the Fel Hammer on Mardum, where the Illidari prepare for war against the Legion."] = "考瓦斯·血棘召你前往马顿上的邪能之锤，伊利达雷正在那里准备与燃烧军团开战。"
L["Kor'vas Bloodthorn found you in Dalaran with an urgent message — the Illidari needed a leader. You answered the call and claimed a weapon forged from the demons' own power. On Mardum, the Fel Hammer became your stronghold — a Legion command ship turned against its former masters. With Kayn Sunfury at your side, you gazed through the Hunter's Gaze across the Broken Isles and directed the Illidari's wrath."] = "考瓦斯·血棘在达拉然找到你，带来了一条紧急消息——伊利达雷需要一位领袖。你响应了召唤，取得了一件以恶魔自身力量锻造的武器。在马顿，邪能之锤成为了你的要塞——这艘军团指挥舰调转矛头，对准了它的旧主。在凯恩·日怒的陪伴下，你透过猎手凝视俯瞰破碎群岛，指引伊利达雷的怒火。"
L["Koukou's Rampage"] = "丧失理智的扣扣"
L["Krag'wa the Terrible"] = "强大的卡格瓦"
L["Kul Tiras"] = "库尔提拉斯"
L["Kung Din"] = "恐钉"
L["Kvaldir on Call"] = "随叫随到"
L["Lady Jaina Proudmoore"] = "吉安娜·普罗德摩尔女士"
L["Lady Jaina Proudmoore — or Lady Sylvanas Windrunner, if you ride under a darker banner — has found a door. Not a welcome one. A seam in the citadel's foundation, wide enough for a small party willing to see what they should not. Through the Forge of Souls. Through the Pit of Saron. Into the Halls of Reflection, where something waits that has been waiting a long time."] = "吉安娜·普罗德摩尔——如果你在更黑暗的旗帜下作战，那就是希尔瓦娜斯·风行者——找到了一扇门。一扇并不友善的门。那是堡垒地基中的一道缝隙，宽度刚好够一支愿意目睹禁忌之物的小队通过。穿过灵魂洪炉。穿过萨隆矿坑。进入映像大厅，在那里，有某种东西已经等待了很久很久。"
L["Lady Liadrin"] = "女伯爵莉亚德琳"
L["Lady Liadrin and the blood elves of Silvermoon answer the call, joining the fight for their distant kin."] = "女伯爵莉亚德琳和银月城的血精灵响应号召，为他们远方的同胞而战。"
L["Lady Lunastre"] = "月郡女士"
L["Lady Remor'za"] = "莱莫扎夫人"
L["Lady S'theno"] = "赛丝诺女士"
L["Lady Sylvanas Windrunner"] = "希尔瓦娜斯·风行者"
L["Lament of the Highborne"] = "上层精灵的挽歌"
L["Lashk"] = "拉什克"
L["Lashk brought you to Torga, and what you found broke something in the air around you. The sea turtle loa — ancient beyond reckoning, the kind of creature that outlasted empires — had been slowly bled by the blood trolls for years. He was almost gone when you arrived. You fought through the blood trolls claiming his shores, sought Bwonsamdi's intercession for a dying loa, and freed the souls trapped around him. Torga died. He just did it on his own terms, with the Horde at his side. Bwonsamdi, for once, was almost respectful. Lashk said nothing. Some losses don't require words."] = "拉什克带你见到了托加，眼前的景象让周遭的空气都仿佛碎裂了。这位海龟洛阿古老得难以计数，是那种比帝国存续得更久的生灵——多年来一直被血巨魔慢慢地榨取鲜血。当你赶到时，他已奄奄一息。你杀退了占据他海岸的血巨魔，为这位垂死的洛阿向邦桑迪寻求斡旋，并解放了困在他周围的灵魂。托加死了。只是他以自己的方式离去，有部落陪在身旁。邦桑迪难得地表现出了几分敬意。拉什克一言不发。有些失去，无需言语。"
L["Last Piece of the Puzzle"] = "最后一块拼图"
L["Lay of the Land"] = "事态"
L["Lea Stonepaw told of the Claws of Ursoc — weapons that carried the strength of the bear god who had given his life defending Azeroth. You entered the nightmare-touched dens where the Claws had been hidden and fought through the corruption to reclaim them. The weight of Ursoc's sacrifice settled into your hands along with the weapons — a guardian's burden, willingly carried."] = "莉娅·石爪讲述了乌索克之爪的故事——这对武器承载着那位为保卫艾泽拉斯而献出生命的熊神之力。你进入被梦魇侵染的兽穴，那里藏着乌索克之爪，你杀穿腐化将其夺回。乌索克牺牲的重量随着武器一同落入你的手中——这是守护者的重担，你心甘情愿地扛起。"
L["Lead a covert strike beneath Icecrown Citadel, closer to Frostmourne than any living hand has come."] = "率领一支秘密突击队潜入冰冠堡垒之下，比任何活人都更接近霜之哀伤。"
L["Lead G.E.A.R. through a high-tech campaign against old enemies and reclaim gnomish pride."] = "率领诺莫瑞根工程航空预备队，以一场高科技战役对抗宿敌，重拾侏儒的荣耀。"
L["Lead the allied armies through the streets of Suramar in a desperate push toward the Nighthold."] = "率领盟军穿过苏拉玛的街道，向暗夜要塞发起孤注一掷的进攻。"
L["Lead the Ebon Blade to the Broken Shore, tame a frost wyrm, and claim the Vilebrood Vanquisher as your mount."] = "率领黑锋骑士团前往破碎海滩，驯服一头冰霜巨龙，将邪巢征服者收为坐骑。"
L["Lead the Illidari to the Broken Shore. Defend the Fel Hammer, recruit Lady S'theno, and earn the Slayer's Felbroken Shrieker."] = "率领伊利达雷前往破碎海滩。保卫邪能之锤，招募赛丝诺女士，赢得杀戮者的邪碎尖啸者。"
L["Lead the united Conclave to Niskara, rescue captured allies, and earn the title of High Priest."] = "率领团结一心的议会前往尼斯卡拉，营救被俘的盟友，赢得大主教的头衔。"
L["Leader of the Illidari"] = "伊利达雷的领袖"
L["Leaders of the Horde"] = "部落领袖"
