L["Leave None Standing"] = "一个不留"
L["Leave Our Mark"] = "彰显军威"
L["Legacy of the Bronzebeard"] = "铜须部族的遗产"
L["Legacy of the Icebreaker"] = "破冰者的遗产"
L["Legion"] = "军团再临"
L["Legion Commander Tyralion"] = "军团司令泰拉里安"
L["Legion Commander Yorik"] = "军团司令尤瑞克"
L["Legion: The Legion Returns"] = "军团再临：军团回归"
L["Lending a Hand"] = "搭把手"
L["Let Sleeping Wolves Lie"] = "梦境之狼"
L["Let the Baron Know"] = "通知男爵"
L["Let the Hunt Begin"] = "狩猎开始"
L["Let Them Burn"] = "烧死他们"
L["Let's Rumble!"] = "我们动手吧！"
L["Lethal Efficiency"] = "瞬间致命"
L["Leyworm Lure"] = "魔虫诱饵"
L["Li Li Stormstout"] = "丽丽·风暴烈酒"
L["Liadrin's Command"] = "莉亚德琳的要求"
L["Lieutenant Sanders"] = "杉德斯中尉"
L["Life Held Hostage"] = "人质劫持"
L["Light Within the Darkness"] = "黑暗中的光明"
L["Light's Wrath"] = "圣光之怒"
L["Lighting Up the Sky"] = "点亮天空"
L["Lilian Voss"] = "莉莉安·沃斯"
L["Lilian Voss was raised by the Scarlet Crusade to hate the undead, and then she died, rose, and became one. Trained from childhood to purify the Forsaken, she wakes in Deathknell as the very thing her father taught her to burn.\n\nFollow her from the cellars of the Crusade through Scholomance and the politics of Lordaeron, where vengeance, identity, and belonging keep asking for different answers."] = "莉莉安·沃斯在血色十字军中长大，被教导憎恨亡灵，后来她死去、复生，自己也成了亡灵。她自幼受训去净化被遗忘者，却在丧钟镇醒来，成了父亲教她焚烧的那种存在。\n\n跟随她从十字军的地窖出发，穿过通灵学院，走进洛丹伦的政治漩涡——在那里，复仇、身份与归属总在索求不同的答案。"
L["Lilian's hunt for dark knowledge leads her into the cursed academy of Scholomance. Within its halls she confronts Darkmaster Gandling — but the darkness she wields threatens to consume her entirely. She must destroy the forbidden tomes and end the suffering, or become the very evil she hunts."] = "莉莉安对黑暗知识的追寻将她引入了被诅咒的学院——通灵学院。她在学院的大厅中与黑暗院长加丁对峙——但她所驾驭的黑暗也险些将她彻底吞噬。她必须摧毁禁忌典籍，终结这里的苦难，否则就会变成她所猎杀的那种邪恶。"
L["Lilian's pursuit of power led her into Scholomance, the cursed academy of necromancy. Through a talking skull she guided you to destroy the Four Tomes of forbidden knowledge and end the suffering within those walls. But when she faced Darkmaster Gandling, the darkness she wielded nearly consumed her. She survived — but the line between hunter and monster grew thinner."] = "莉莉安对力量的追求将她引入了通灵学院，那座被诅咒的死灵学院。她借一颗会说话的头骨指引你摧毁四本禁忌典籍，终结那座高墙之内的苦难。但当她面对黑暗院长加丁时，她所驾驭的黑暗几乎将她吞噬。她活了下来——但猎人与怪物之间的界线变得更加模糊了。"
L["Lin Applebloom"] = "林·苹花"
