L["Loramus, Is That You?"] = "洛拉姆斯，是你吗？"
L["Lord Chamberlain"] = "宫务大臣"
L["Lord Chamberlain escorts you toward Castle Nathria. Sire Denathrius receives your plea with perfect elegance — and asks you to help restore order first."] = "宫务大臣护送你前往纳斯利亚堡。德纳修斯大帝以无可挑剔的优雅接受了你的请求——却要你先帮他恢复秩序。"
L["Lord Grayson Shadowbreaker"] = "格雷森·沙东布瑞克公爵"
L["Lord Jorach Ravenholdt"] = "乔拉齐·拉文霍德公爵"
L["Lord Maxwell Tyrosus"] = "玛克斯韦尔·泰罗索斯男爵"
L["Lord Maxwell Tyrosus calls paladins from every order to the Sanctum of Light beneath Light's Hope Chapel."] = "玛克斯韦尔·泰罗索斯男爵召集各个教团的圣骑士，前往圣光之愿礼拜堂地下的圣光秘殿。"
L["Lord Maxwell Tyrosus issued an urgent summons — the Silver Hand was reforming, and Light's Hope Chapel would be its heart. You descended into the Sanctum of Light, hidden beneath the chapel for centuries, where paladins of every faith gathered. Tyrosus named you champion, and you claimed a weapon of legend. Lady Liadrin pledged the Blood Knights' strength, and the Silver Hand rode again."] = "玛克斯韦尔·泰罗索斯男爵发出了紧急召令——白银之手正在重建，而圣光之愿礼拜堂将成为它的核心。你深入隐藏在礼拜堂之下数百年的圣光秘殿，各种信仰的圣骑士都聚集于此。泰罗索斯推举你为勇士，你也取得了一把传说中的武器。女伯爵莉亚德琳许诺献上血骑士的力量，白银之手再度出征。"
L["Lord Maxwell Tyrosus pointed you toward Truthguard — a shield forged by the titans themselves, imbued with the power to protect the righteous and shatter the deceitful. You traveled to the Shrine of the Truthguard and faced the shield's ancient tests. Truthguard weighed nothing in the hands of the pure — and everything in the hands of the unworthy. It chose you."] = "玛克斯韦尔·泰罗索斯男爵为你指明了真理守护者的所在——那是一面由泰坦亲手锻造的盾牌，蕴含着庇护正直之人、粉碎欺诈之徒的力量。你前往真理守护者神殿，接受这面盾牌古老的考验。在纯洁者手中，真理守护者轻如无物；在不配者手中，它却重逾千钧。它选择了你。"
L["Lord Maxwell Tyrosus spoke the name that every paladin knew — the Ashbringer. The blade that had burned with holy fire in Alexandros Mograine's hands, that had been corrupted and redeemed, that had shattered the Scourge at Light's Hope Chapel. You sought guidance and followed the weapon's trail to its resting place. When you drew the Ashbringer, holy fire erupted along its edge, and the weight of every paladin who had carried it settled onto your shoulders."] = "玛克斯韦尔·泰罗索斯男爵说出了每个圣骑士都耳熟能详的名字——灰烬使者。这把剑曾在亚历山德罗斯·莫格莱尼手中燃起神圣之火，曾经堕落又重获救赎，也曾在圣光之愿礼拜堂击溃天灾军团。你寻求指引，追随这把武器的踪迹找到了它的安息之所。当你拔出灰烬使者时，圣火沿着剑刃喷薄而出，每一位曾执掌它的圣骑士所背负的重担，都落在了你的肩上。"
L["Lord Thorval"] = "索瓦尔勋爵"
L["Lord Waycrest has vanished and a curse grips the village of Fallhaven. Lucille Waycrest enlists your help to hunt the witches responsible."] = "维克雷斯勋爵下落不明，一个诅咒笼罩着萧湾镇。露希尔·维克雷斯请你协助猎杀幕后作祟的女巫。"
L["Lordaeron"] = "洛丹伦"
L["Lordaeron has been reclaimed, the penance accepted. But for those who once swore loyalty to the Banshee Queen, a message finds its way back through the dark — one last task, carried by a familiar messenger."] = "洛丹伦已被夺回，赎罪也已被接受。但对于那些曾向女妖之王宣誓效忠的人，一条讯息穿过黑暗找到了他们——最后一项任务，由一位熟悉的信使带来。"
L["Lordaeron is in Forsaken hands again, but old enemies still haunt the forests beyond its walls. The Scarlet Crusade clings to its strongholds, Gilneas has not forgotten, and a former queen's absence leaves difficult questions behind.\n\nLilian Voss has a mission in Silverpine, and she needs someone who knows what it means to be Forsaken: to stand at a graveside, remember, and choose again what the second life is for."] = "洛丹伦再度回到被遗忘者手中，但宿敌仍在城墙外的森林中阴魂不散。血色十字军死守着他们的据点，吉尔尼斯也未曾遗忘，而一位前女王的离去留下了诸多难题。\n\n莉莉安·沃斯在银松森林有一项任务，她需要一个懂得身为被遗忘者意味着什么的人：站在墓前，铭记过往，再一次为第二次生命选择意义。"
L["Lorewalker Cho"] = "游学者周卓"
L["Lorewalker Cho did not answer Nazgrim's campaign with orders. He answered with tea, old stones, and the patient insistence that Pandaria had a story before the Horde arrived. You walked a mile in another person's shoes, listened to the forest's dead, peered into the past, and traced the branches of Cho's own family. The lesson was not gentle, but it was necessary: this land remembers what people bring into it. Then the river swallowed you, the hozen found you, and Chief Kah Kah's orders dragged the lesson back into the campaign. You left Cho with more questions than victories, which was probably the point."] = "游学者周卓没有用命令来回应纳兹戈林的战役。他用的是茶、古老的石头，以及耐心的坚持：早在部落到来之前，潘达利亚就有它自己的故事。你设身处地体会他人的境遇，倾听森林中的亡者，窥探过去，还追溯了周卓自己家族的脉络。这一课并不温和，却必不可少：这片土地会记住人们带来的一切。随后河水吞没了你，猢狲找到了你，酋长卡哈卡哈的命令又把这一课拖回了战役之中。离开周卓时，你收获的疑问比胜利还多——而这或许正是用意所在。"
L["Lorewalker Cho's Lesson"] = "游学者周卓的教诲"
L["Lorewalker Stonestep"] = "游学者石步"
L["Lost in Darkness"] = "迷失于黑暗"
L["Lost in the Desiccation"] = "涸光迷失"
L["Lost My Spark"] = "失落火花"
L["Lost Shipment"] = "失踪货物"
L["Lothraxion"] = "洛萨克森"
L["Love's Labor"] = "爱的劳动"
L["Lucille realized that scattered witch hunting would never be enough. A slight detour through the mountains — past yetis and salvaged supplies — led to the ruins of Gol Var, where ancient bones whispered of the Order of Embers. Centuries ago, the Order had been Drustvar's shield against the Drust and their dark magic. Lucille read the histories carved in stone and rune-etched bone, and made her decision: the Order of Embers would rise again. She would lead it, and you would be her blade."] = "露希尔意识到，零散的猎巫行动永远不够。你们稍微绕点远路翻越群山——途经雪人出没之地，收集散落的补给——来到了戈尔瓦的遗迹，那里的古老骸骨低语着灰烬骑士团的往事。数百年前，这个骑士团曾是德鲁斯瓦抵御德鲁斯特及其黑暗魔法的坚盾。露希尔读过刻在石头和符文骨片上的历史后，作出了决定：灰烬骑士团将再度崛起。由她来领导，而你将成为她的利刃。"
L["Lucille stands accused of witchcraft herself. Marshal Reade demands proof of her innocence through superstitious trials."] = "露希尔本人也被控施行巫术。里德元帅要求她通过迷信的审判来证明自己的清白。"
