L["Mathias Shaw laid out the strategy in Proudmoore Keep: use the Abyssal Scepter to create a false assault on Nazmir and lure the Horde fleet away from Zuldazar. While Zandalari forces rushed south to repel the distraction, the Alliance fleet would hit the harbor directly. You spent two weeks fighting through Nazmir swamps, disabling Zandalari machinery, and holding the line at the Blood Gate — long enough for the fleet to round the coast.\n\nThen Jaina froze the harbor. The water turned to ice beneath Zandalari hulls. The Alliance sailed straight through. The Battle of Dazar'alor — the most audacious naval assault in a generation — had begun. Lord Admiral Jaina Proudmoore, fighting in her own waters, had brought the war home."] = "马迪亚斯·肖在普罗德摩尔要塞制定了战略：利用深渊权杖对纳兹米尔发动佯攻，将部落舰队引离祖达萨。当赞达拉部队急忙南下抵御佯攻时，联盟舰队将直取港口。你花了两周时间在纳兹米尔的沼泽中奋战，破坏赞达拉的机械，并在鲜血关口坚守防线——一直坚持到舰队绕过海岸。\n\n随后，吉安娜冰封了港口。赞达拉船只下方的海水化为坚冰。联盟舰队长驱直入。达萨罗之战——一代人以来最大胆的海上突袭——就此打响。海军上将吉安娜·普罗德摩尔在她最熟悉的海域作战，将战火直接烧到了敌人的家门口。"
L["Mathias Shaw, spymaster of SI:7, had been captured and replaced by a dreadlord impostor. You infiltrated the enemy stronghold alongside Taoshi, cutting through guards and wards to reach Shaw's cell. The rescue was harrowing — but when the real Shaw stood free and the impostor was exposed, the conspiracy's days were numbered."] = "军情七处的情报首脑马迪亚斯·肖遭到俘虏，并被一个恐惧魔王冒名顶替。你与陶矢一同潜入敌方要塞，突破守卫与结界，抵达肖的牢房。这场营救惊心动魄——而当真正的肖重获自由、冒牌货的身份被揭穿时，这场阴谋便已时日无多。"
L["Mathias Shaw, spymaster of SI:7, has gone missing. A daring rescue mission takes you deep behind enemy lines."] = "军情七处的情报首脑马迪亚斯·肖失踪了。一次冒险救援将带你深入敌后。"
L["Matron Mother Malevolence"] = "主母玛沃伦丝"
