L["Mercy or Misery"] = "悲慈一念间"
L["Meryl Felstorm"] = "梅瑞尔·邪风"
L["Meryl Felstorm appeared with an urgent plea — Kathra'natir, a cunning dreadlord, had broken free of his prison and threatened all of Dalaran. You fought the demon back and descended into the Hall of the Guardian, an ancient sanctum beneath the city. There, Meryl revealed the Tirisgarde — an ancient order of mages sworn to defend Azeroth against the Burning Legion. With a weapon of legend in hand and The Great Akazamzarak's theatrical assistance, you reforged the order and took your place as its champion."] = "梅瑞尔·邪风带着紧急的求助出现——狡诈的恐惧魔王卡斯拉纳提尔挣脱了牢笼，威胁着整个达拉然。你击退了这个恶魔，并深入城市地下的古老圣所守护者圣殿。在那里，梅瑞尔向你揭示了提瑞斯法守望者——一个誓言守护艾泽拉斯、抵御燃烧军团的古老法师组织。手握传说中的武器，再加上伟大的阿卡扎曼扎拉克浮夸的协助，你重建了这个组织，并成为它的勇士。"
L["Meryl Felstorm pointed you toward Aluneth — the Greatstaff of the Magna, once wielded by Aegwynn, Guardian of Tirisfal. The staff had been sealed away for good reason: it was sentient, willful, and dangerously powerful. You found it in an arcane vault crackling with unbound energy, and when you grasped it, Aluneth's voice echoed in your mind — condescending, impatient, and undeniably brilliant. You had a weapon. It had opinions."] = "梅瑞尔·邪风为你指明了艾露尼斯的所在——这根玛格纳巨杖曾由提瑞斯法守护者艾格文执掌。它被封印起来是有充分理由的：这根法杖拥有自我意识，任性固执，力量危险。你在一座充斥着失控能量的奥术宝库中找到了它。当你握住它时，艾露尼斯的声音在你脑海中回响——居高临下、急不可耐，却又无可否认地才华横溢。你得到了一件武器。而它很有主见。"
L["Meryl Felstorm, an ancient mage, pleads for help against a dreadlord. Together you reforge the Tirisgarde in the Hall of the Guardian."] = "远古法师梅瑞尔·邪风恳求你协助对抗一名恐惧魔王。你们一同在守护者圣殿重建提瑞斯法守望者。"
L["Meryl spoke of Ebonchill — the staff of Alodi, the very first Guardian of Tirisfal, sealed within a pocket dimension of frozen time. You breached the dimensional barrier and entered a world where time stood still, ice crystals hanging motionless in the air. At its heart, Ebonchill waited — cold, patient, and ancient beyond measure. When you took it, the pocket dimension shattered, and the staff's frost spread through your veins like a promise."] = "梅瑞尔讲述了黑檀之寒——那是第一位提瑞斯法守护者阿洛迪的法杖，被封印在一处时间冻结的口袋维度之中。你突破维度屏障，进入一个时间静止的世界，冰晶一动不动地悬在半空。在世界的中心，黑檀之寒静静等待——冰冷、耐心，古老得无法估量。当你取走它时，口袋维度随之崩碎，法杖的寒意如同一个承诺，流遍你的血管。"
