L["Mogu raiders, exhausted farmers, trapped miners, and a starving jade project show what the forest needs before Yu'lon can return."] = "魔古劫掠者、精疲力竭的农夫、被困的矿工，还有一项急缺玉石的雕像工程——这一切都揭示了在玉珑归来之前，森林需要什么。"
L["Monstrosity"] = "怪物"
L["Moonshade Holdout"] = "月影秘地"
L["Mor'zul Bloodbringer"] = "莫苏尔·召血者"
L["More Like Me"] = "志同道合"
L["Morhun Rivertamer"] = "莫胡·驯河"
L["Most Loyal"] = "至高忠诚"
L["Moth-Ridden"] = "飞蛾满屋"
L["Moths to a Flame"] = "飞蛾扑火"
