L["Muln Earthfury"] = "穆恩·大地之怒"
L["Murloc Mind Control"] = "鱼人心灵控制"
L["My Terrible Morning"] = "倒霉一上午"
L["Mylune"] = "米露恩"
L["Mystery at Citrine Bay"] = "黄金海湾之谜"
L["Nadjia the Mistblade"] = "娜德佳，迷雾之刃"
L["Naralex"] = "纳拉雷克斯"
L["Naralex revealed the location of the Scythe of Elune — an artifact of immense power forged from Elune's staff and the Fang of Goldrinn. You journeyed through cursed lands to claim it, feeling the pull of both the moon's light and the beast within. The Scythe chose you, and with it came the weight of every druid who had wielded it before."] = "纳拉雷克斯揭示了艾露恩之镰的所在——这件力量无比强大的神器由艾露恩的法杖和戈德林之牙锻造而成。你穿越受诅咒的土地去夺取它，同时感受着月光与内心野兽的双重牵引。艾露恩之镰选择了你，随之而来的是每一位曾执掌它的德鲁伊所背负的重担。"
L["Naralex, the druid who once fell to the Nightmare in the Wailing Caverns, sensed dire growth spreading through the Dream. Together you ventured into nightmare-twisted lands, sampling the corruption to understand its nature. In Malorne's Refuge you found the great stag's sanctuary under siege. You tracked the source of the corruption to its heart and recovered the Idol of the Wilds — an ancient artifact that could turn the tide against the Nightmare."] = "纳拉雷克斯——这位曾在哀嚎洞穴中堕入梦魇的德鲁伊——察觉到可怕的滋生正在梦境中蔓延。你们一同深入被梦魇扭曲的土地，采集腐化样本以了解其本质。在玛洛恩的庇护所，你发现这头巨鹿的圣所正遭到围攻。你一路追查到腐化的源头，夺回了荒野神像——一件足以扭转对抗梦魇局势的古老神器。"
L["Natalie Seline"] = "娜塔莉·塞林"
L["Nathanos Blightcaller"] = "纳萨诺斯·凋零者"
L["Nathanos Blightcaller and Lilian Voss lead a covert strike into the heart of Tiragarde Sound. While Nathanos secures the mountain outpost, Lilian takes command of the Bridgeport operation — sabotaging Ashvane foundries, planting explosives, and riding through the chaos she created."] = "纳萨诺斯·凋零者与莉莉安·沃斯率领一次秘密突袭，直插提拉加德海峡的腹地。纳萨诺斯负责拿下山间前哨，莉莉安则指挥桥港行动——破坏艾什凡铸造厂、安放炸药，并在她亲手制造的混乱中纵马驰骋。"
L["Nathanos led an expedition to dig up a fallen Kul Tiran war hero for resurrection. As you searched the graveyards of Drustvar, Lilian grew quiet. Unearthing the dead, raising them against their will — it was exactly what had been done to her. She carried out her orders, but the questions in her eyes said everything her lips would not."] = "纳萨诺斯率领一支远征队，去挖掘一位阵亡的库尔提拉斯战争英雄并使其复活。当你们在德鲁斯瓦的墓地中搜寻时，莉莉安变得沉默。掘出死者，违背他们的意愿将其唤醒——这正是当年别人对她所做的事。她执行了命令，但她眼中的疑问说出了她嘴上不愿说的一切。"
L["Navigate the treacherous politics of Suramar's noble houses alongside the cunning Ly'leth Lunastre."] = "与狡黠的莉莉丝·月郡一同周旋于苏拉玛贵族家族之间险恶的政治斗争。"
L["Nazgrim"] = "纳兹戈林"
L["Nazgrim rescues Zin'jun, breaks the Alliance airstrip, and follows the trail to the edge of Cho's lesson."] = "纳兹戈林救出金祖恩，摧毁联盟的飞行跑道，并循着线索来到周卓那一课的边缘。"
L["Nazgrim's Command"] = "纳兹戈林的命令"
L["Nazmir"] = "纳兹米尔"
L["Nazmir is a dying land: ancient, cursed, and crawling with blood trolls whose rituals stain the swamp red. Stranded among loa whose temples have fallen and whose followers have turned to darker powers, you will need help from gods who rarely give anything freely.\n\nForge uneasy bargains, follow the trail through fetid ruins and broken pacts, and learn why the oldest powers in Zandalar still fear what waits beneath the mud."] = "纳兹米尔是一片垂死的土地：古老、受诅，到处都是血巨魔，他们的仪式将沼泽染成了血红色。洛阿的神殿已经倾颓，追随者也已转投更黑暗的力量。困于这些洛阿之间，你需要那些很少无偿施予的神明伸出援手。\n\n达成令人不安的交易，循着线索穿过腐臭的废墟与破碎的契约，弄清为何赞达拉最古老的力量至今仍畏惧那潜伏在泥沼之下的东西。"
L["Nazmir is swallowed by blood and shadow. Princess Talanji leads the Horde into the swamp to find the loa and stop the blood troll advance."] = "纳兹米尔已被鲜血与阴影吞没。塔兰吉公主率领部落进入沼泽，寻找洛阿并阻止血巨魔的推进。"
L["Nazmir, the Forbidden Swamp"] = "禁忌沼泽，纳兹米尔"
L["Nectarbreeze Orchard was not a battlefield until the mogu made it one. Shao the Defiant and Gentle Mother Hanae needed survivors rallied, hardware recovered, and slavers driven off before the orchard became another wound. From there the road bent toward Emperor's Omen and Greenstone Quarry, where the Serpent's Heart had stalled. Foreman Mann had no jade, Hao Mann was trapped, and the miners were running on fear. By freeing farmers, saving workers, and bringing jade back to the statue, you helped the forest rebuild something sacred while the armies outside kept finding reasons to break things."] = "在魔古到来之前，蜜风果园从来不是战场。挑战者邵傲和温柔的大妈韩妮需要集结幸存者、找回器械、赶走奴隶贩子，以免果园成为又一道伤口。从那里出发，道路转向皇帝的预言地和绿石采掘场，神龙之心的工程在那里陷入了停滞。孟工头没有玉石，孟豪被困，矿工们全凭恐惧支撑。你解救农夫、营救工人、把玉石送回雕像，帮助森林重建神圣之物，而外面的军队却总能找到破坏的理由。"
L["Need More Info"] = "需要更多情报"
L["Needs of the Hunters"] = "猎人的需求"
