L["No Sanctuary"] = "无处可藏"
L["Nobundo spoke of Ra-den, the titan keeper who had shaped Azeroth's storms. His weapon — the Fist of Ra-den — lay hidden in a vault sealed since the ordering of the world. You braved the coming storm to claim it, and when lightning struck the weapon in your hands, the power of a titan keeper surged through you."] = "努波顿讲述了莱登——那位塑造了艾泽拉斯风暴的泰坦守护者。他的武器莱登之拳藏在一座自世界规整之初便已封闭的宝库中。你冒着即将来临的风暴去夺取它，当闪电击中你手中的武器时，泰坦守护者的力量涌遍你的全身。"
L["Nodd Codejack"] = "诺德·杰码"
L["Noggenfogger's Reasonable Request"] = "诺格弗格的合理请求"
L["Noressa"] = "诺瑞莎"
L["Not a Bug"] = "活动窃听器"
L["Not A Toothless Dragon"] = "龙有利齿"
L["Not everyone who followed the Banshee Queen has made peace with what came after. A message finds its way to the ruins of Lordaeron for those who haven't."] = "并非每个追随过女妖之王的人都已坦然接受此后发生的一切。一条讯息来到洛丹伦的废墟，送给那些仍未释怀的人。"
L["Not Fit for This Plane"] = "不应在此界"
L["Not-So-Honorable Combat"] = "不那么光彩的战斗"
L["Nothing Like the Classic"] = "经典永流传"
