L["Now With More Mechanical Fowl"] = "更多的机械猛禽"
L["Nullified"] = "消除魔法"
L["Oath Breaker"] = "背誓者"
L["Oath of Service"] = "宣誓"
L["Oath of the Windlord"] = "风领主的誓言"
L["Oculeth Ex Machina"] = "救星欧库勒斯"
L["Oculeth's Workshop"] = "欧库勒斯的工作室"
L["Odds and Ends"] = "零碎工作"
L["Odyn"] = "奥丁"
L["Odyn and the Valarjar"] = "奥丁和瓦拉加尔"
L["Odyn called you to battle, but the Gjallarhorn — the sacred horn that summons the Valarjar to war — had been stolen. Hymdall sent you into Stormheim where you found Svergan Stormcloak, a vrykul king whose honor had been stripped by the thieves. Together you broke his chains, recovered the horn, and tracked a massive worm to the summit of Highmountain. With Svergan's oath sworn and the beast Jorhuttam slain, the Valarjar stood ready for war once more."] = "奥丁召你参战，但迦拉尔之角——召唤瓦拉加尔奔赴战场的神圣号角——已经失窃。海姆达尔派你前往风暴峡湾，你在那里找到了瑟维甘·风篷，一位被窃贼剥夺了荣誉的维库国王。你们一同挣断了他的锁链，夺回了号角，并追踪一条巨型蠕虫来到至高岭之巅。瑟维甘立下誓言，巨兽尤胡塔姆被斩杀，瓦拉加尔再次整装待战。"
L["Odyn reaches out to old allies in Ulduar and sends you to deliver a message to Helya in the Maw of Souls. Titan keepers join the fight."] = "奥丁向奥杜尔的旧日盟友求援，并派你前往噬魂之喉向海拉传递讯息。泰坦守护者们加入了战斗。"
L["Odyn sent you into the Maw of Souls with a defiant message for Helya — the Valarjar would not be broken. In the ancient halls of Ulduar, you rallied the titan keepers to the cause. Dvalen Ironrune, steadfast guardian of the forge, and Thorim, Odyn's own son, pledged themselves to the Valarjar. You retrieved Ymiron's broken blade from the Maw as proof that even the mightiest of Helya's champions could fall."] = "奥丁派你带着一条挑衅的讯息深入噬魂之喉，交给海拉——瓦拉加尔绝不会屈服。在奥杜尔古老的殿堂中，你召集泰坦守护者共襄大业。熔炉的坚定守护者德夫伦·铁符，以及奥丁的亲生儿子托里姆，都宣誓效忠瓦拉加尔。你从噬魂之喉中取回了伊米隆的断刃，证明即便是海拉麾下最强大的勇士也会倒下。"
L["Odyn spoke of Strom'kar, the Warbreaker — a blade forged in the ancient empire of Arathor and wielded by King Thoradin against the Amani trolls. You traveled to the ruins of Stromgarde and fought through the shadows to reclaim the sword from its cursed resting place. The blade hummed with ancient power as you raised it — a weapon worthy of the Battlelord."] = "奥丁讲述了碎军者斯多姆卡——一把在古老的阿拉索帝国锻造、曾由索拉丁国王执掌以对抗阿曼尼巨魔的利刃。你前往激流堡的废墟，在阴影中杀出一条血路，从受诅咒的安息之地夺回了这把剑。当你举起它时，剑身嗡鸣着古老的力量——这是一件配得上战争领主的武器。"
L["Odyn summons the greatest warriors to serve under your command. Build your forces and prepare Skyhold for war against the Legion."] = "奥丁召集最伟大的战士听候你的调遣。壮大你的部队，让苍穹要塞做好对抗燃烧军团的准备。"
L["Odyn's Summons"] = "奥丁召唤"
L["Of Myth and Fable"] = "如梦似幻"
L["Of Water and Blood"] = "流水与鲜血"
L["Off to Court"] = "前往庭院"
L["Old Allies"] = "老朋友"
L["Old Colleagues"] = "老同事"
L["Old Friends, New Opportunities"] = "老友新活"
L["Old Man Misteye"] = "雾眼老人"
L["Old Soldier"] = "老兵"
L["On Daumyr's Wings"] = "多米尔之翼"
L["On Eagle's Wings"] = "雄鹰之翼"
L["On Her Majesty's Secret Service"] = "女王密令"
L["On Public Display"] = "公开处刑"
L["On Ruby Wings"] = "红龙之翼"
L["On the Broken Shore, brew a cure for a fallen brewmaster, then follow the trail of Ban-Lu — a legendary celestial tiger."] = "在破碎海滩，为一位倒下的酒仙酿制解药，然后追寻班禄的踪迹——那是一只传说中的天神之虎。"
L["On the Broken Shore, Lady Liadrin led the Silver Hand's assault. Delas Moonfang's past caught up with her — an ancestor's curse threatened her family. You broke the curse, freed Nerus Moonfang from his torment, and earned another champion for the order. When the Shore was secured, Lord Grayson Shadowbreaker sent you to the Hammer of Dalaran — the legendary forge — where Alard Schmied crafted armor worthy of a Highlord. In the shadows beneath the city, a golden charger waited, and it carried you into the light."] = "在破碎海滩，女伯爵莉亚德琳率领白银之手发起进攻。德拉丝·月牙的过去找上了她——一个先祖的诅咒威胁着她的家族。你破除了诅咒，将奈鲁斯·月牙从折磨中解脱出来，并为骑士团赢得了又一位勇士。破碎海滩被肃清后，格雷森·沙东布瑞克公爵派你前往传奇熔炉达拉然之锤，奥拉尔德·施米尔在那里为你打造了配得上大领主的护甲。在城市下方的阴影中，一匹金色战马正在等候，载着你奔向光明。"
L["On the Broken Shore, rescue Kanrethad Ebonlocke from imprisonment and earn the Netherlord's Chaotic Wrathsteed."] = "在破碎海滩，将坎雷萨德·埃伯洛克从囚禁中救出，并赢得虚空领主的混沌怒马。"
L["On the Broken Shore, the Legion had corrupted wild beasts into felbound monstrosities. Shandris Feathermoon coordinated the assault while Nighthuntress Syrenne led you deep into enemy territory to soothe the wounded creatures and strike at the source of the corruption. When the Broken Shore was secured, you answered a final call — the Night of the Wilds, where a wolfhawk tested your worth as a hunter. It found you worthy, and pledged its loyalty to the Huntmaster."] = "在破碎海滩，燃烧军团已将野兽腐化成被邪能束缚的怪物。珊蒂斯·羽月统筹进攻，暗夜女猎手塞琳则带你深入敌境，安抚受伤的生灵，并打击腐化的源头。破碎海滩被肃清后，你回应了最后的召唤——荒野之夜，一只狼鹰在那里考验你身为猎人的价值。它认可了你，并向狩猎大师献上了忠诚。"
