L["Orders are Orders"] = "唯命是从"
L["Orgrim's Hammer"] = "奥格瑞姆之锤"
L["Orgrim's Hammer is Warchief Garrosh's answer to the Skybreaker — a Horde gunship with a bone to pick. Sky-Reaver Korm Blackscar runs the deck. Sky-Commander Ichman flies the line. Brother Keltan blesses the cannons. The first sortie drops into Ymirheim, where the Scourge mines its saronite. The second swings west to the Broken Front, where a Horde column was hit broadside and left scattered. After that comes the grind: Poke and Prod, Against the Giants, Coprous the Defiled, the goblin Nargle Lashcord and his Fringe Engineer Tezzla. Farther west, past the Valley of Lost Hope, Koltira Deathweaver pries the Desolation Gate open with bent Scourge gear and colder patience. By the time Orgrim's Hammer swings east, the Guardians of Corp'rethar are already bleeding."] = "奥格瑞姆之锤是加尔鲁什酋长对破天者号的回应——一艘憋着一肚子火的部落炮舰。掠天者考尔姆·黑痕掌管甲板。天空指挥官伊克曼巡航战线。凯尔坦修士为火炮祈福。第一次出击降落在伊米海姆，天灾军团在那里开采萨隆邪铁。第二次转向西边的破碎前线，一支部落纵队在那里遭到侧面猛击，溃散四方。之后便是一场苦战：知己知彼、对抗巨人、污染者科普洛斯，还有地精纳格尔·鞭索和他的边缘技师塔兹拉。再往西，越过失落希望之谷，库尔迪拉·织亡者正用变形的天灾装置和更冷峻的耐心撬开荒芜之门。等到奥格瑞姆之锤转向东方时，克尔普雷萨的守护者们早已血流不止。"
L["Orgrimmar / Durotar"] = "奥格瑞玛 / 杜隆塔尔"
