L["Pandaren heritage lives in stories carried by many voices. Through festival rites, old memories, and shared traditions, you helped weave those voices into a new legacy."] = "熊猫人的传承存在于众多声音讲述的故事之中。通过节庆仪式、古老的记忆和共同的传统，你帮助将这些声音编织成一份新的传承。"
L["Pandaria / Wandering Isle"] = "潘达利亚/迷踪岛"
L["Panic at the Brewery"] = "酒厂之乱"
L["Parting Gifts"] = "离别礼物"
L["Parqual Fintallas"] = "帕科瓦·芬塔拉斯"
L["Dorn Plainstalker"] = "多恩·平原行者"
L["Past the Argent line, the Ebon Blade works in cruder tools. Uzo Deathcaller keeps a pen of vrykul prisoners the Crusade cannot know about. Bragi the Mad waits at Jotunheim with a grudge, a list of vargul he wants back, and an increasingly unhinged plan for their recovery. The Bone Witch sells her favors in bones. And at Valhalas, the vrykul hold court for the worthy dead — which means admission, for the right kind of monster, can be earned. Read the bones. Kill the water terror. Find the ancient hero. Win the challenge rounds. Put on their skin. Walk out over their corpses. By the time the hall goes quiet, the Ebon Blade has one last errand — a banshee's revenge, and a Duke who needs his competition eliminated."] = "越过银色北伐军的防线，黑锋骑士团使用的手段要粗暴得多。乌索·唤死者看守着一圈北伐军绝不能知道的维库人囚犯。疯子布拉基在尤顿海姆等着，心怀怨恨，列着一份他想要找回的瓦格尔名单，还有一个越来越疯狂的营救计划。白骨女巫用骨头来换取她的恩惠。而在瓦哈拉斯，维库人为配得上荣耀的亡者设下审判——这意味着，只要是合适的怪物，就能赢得入场资格。解读骨头。杀死水中恐魔。找到古代英雄。赢下挑战回合。披上他们的皮。踏着他们的尸体走出去。等到大厅归于寂静时，黑锋骑士团还有最后一件差事——一个女妖的复仇，以及一位需要除掉竞争对手的公爵。"
L["Patch"] = "补丁"
L["Patch rallied the assault force at Bloodfire Ravine. Talanji stood at the front. The loa — Krag'wa, what remained of Bwonsamdi's power, even the memory of Torga — were with you. The blood trolls had held the Blood Gate as the last barrier between Nazmir and the heart of their god's prison. You blew through their defenses, toppled their totems, and drove a path of fire through their strongest ranks. Grand Ma'da Ateena fell. In the silence after, Titan Keeper Hezrel delivered the final revelation: G'huun still breathed beneath the earth. Nazmir had been reclaimed — but the blood god's prison was cracking. The raid on Uldir was no longer optional."] = "帕奇在血火峡谷集结了突击部队。塔兰吉站在最前线。洛阿们——克拉格瓦、邦桑迪残存的力量，甚至还有托加的记忆——都与你同在。血巨魔一直坚守着鲜血关口，那是纳兹米尔与他们神祇监牢核心之间的最后一道屏障。你冲破他们的防线，推倒他们的图腾，在他们最强大的阵列中烧出一条火路。长母阿提娜倒下了。在随后的寂静中，泰坦守护者赫兹雷尔带来了最终的启示：戈霍恩仍在地下呼吸。纳兹米尔已被收复——但血神的牢笼正在开裂。突袭奥迪尔已势在必行。"
