L["Princess Tess Greymane guided you through a web of coded messages and hidden vaults to recover the Kingslayers — Garona's legendary daggers, stained with the blood of a king. You infiltrated a Stormwind prison, broke codes, and retrieved the blades from their resting place, returning them to the hands of an assassin who knew their weight better than anyone."] = "苔丝·格雷迈恩公主引导你穿过层层密信与隐秘宝库，寻回了弑君者——迦罗娜的传奇匕首，上面沾染着一位国王的鲜血。你潜入暴风城的一座监狱，破解密码，从安息之所取回这对利刃，将它们交还到一位比任何人都更清楚其分量的刺客手中。"
L["Priorities!"] = "最优先事项！"
L["Priscilla Ashvane has been quietly dismantling the Proudmoore Admiralty from within — bribing officials, sabotaging trade, and positioning herself to absorb the family's political legacy while Katherine grieves her son Derek and her estrangement from Jaina. Unraveling the conspiracy takes you across Tiragarde Sound, from Boralus's counting houses to Ashvane prison cells, until the truth lands at Genn Greymane's feet in Boralus Harbor."] = "普里西拉·艾什凡一直在暗中从内部瓦解普罗德摩尔海军部——收买官员、破坏贸易，并伺机吞并这个家族的政治遗产，而凯瑟琳仍在为儿子德里克的死以及与吉安娜的疏离而悲伤。追查这场阴谋将带你踏遍提拉加德海峡，从伯拉勒斯的账房到艾什凡的牢房，直到真相被呈到伯拉勒斯港的吉恩·格雷迈恩面前。"
