L["Pushing through the farmlands around Deathknell, you clashed with the Scarlet Crusade at their palisade. Inside the fortifications you found Lilian — captured by the zealots she once served. Her captors didn't care that she had been one of them. To the Crusade, she was just another undead abomination to be purged."] = "穿过丧钟镇周围的农田，你在血色十字军的栅栏营地与他们交锋。在防御工事中，你找到了莉莉安——她被自己曾经效力的狂热分子俘虏了。抓她的人根本不在乎她曾是他们中的一员。在十字军眼中，她不过是又一个需要净化的亡灵怪物。"
L["Put on vrykul skin, fight through Valhalas's trials, and pay a Bone Witch's debt in blood."] = "披上维库人的皮，闯过瓦哈拉斯的试炼，用鲜血偿还白骨女巫的债。"
