L["Recover Felo'melorn, the Flamestrike — the ancient blade of the Sunstrider dynasty, lost in the frozen halls of Icecrown."] = "寻回烈焰之击费罗梅隆——逐日者王朝的古老利刃，遗失在冰冠冰川的冰冷殿堂之中。"
L["Recover Light's Wrath, a staff of terrible holy power sealed away in the Nexus Vault because it was too dangerous to wield."] = "寻回圣光之怒——一根蕴含可怕神圣力量的法杖，因为太过危险而被封存在魔枢宝库中。"
L["Recover lost tradition, confront painful history, and stand against lingering eredar corruption."] = "找回失落的传统，直面痛苦的历史，抵御挥之不去的艾瑞达腐化。"
L["Recover Natalie Seline, a priest who delved too deep into the Void, from the shadow realm where she has been lost."] = "前往暗影领域，救回迷失其中的娜塔莉·塞林——这位牧师在虚空中陷得太深了。"
L["Recover Sheilun, the staff of Emperor Shaohao, who shrouded Pandaria in mist for ten thousand years."] = "寻回雪伦——皇帝少昊的法杖，他曾用迷雾笼罩潘达利亚长达一万年。"
L["Recover the ancient bow of the Windrunner family, lost when Alleria Windrunner vanished beyond the Dark Portal."] = "寻回风行者家族的古老长弓——它随着奥蕾莉亚·风行者消失在黑暗之门彼端而一同失落。"
L["Recover the Claws of Ursoc, the great bear god's weapons, from the nightmares that have claimed them."] = "从吞噬了乌索克之爪的梦魇中，夺回这对属于伟大熊神的武器。"
L["Recover the Maw of the Damned, a vampiric axe that drains the life from its victims to sustain its wielder."] = "寻回诅咒之喉——一把吸血战斧，能汲取受害者的生命来维持持有者的生存。"
L["Recover the Silver Hand, the holy mace of the original paladins, lost since the founding of the order."] = "寻回白银之手——最初的圣骑士们所用的神圣战锤，自骑士团创立以来便已失落。"
L["Recover the Skull of the Man'ari, a demonic focus of immense summoning power used by the eredar lords."] = "寻回曼阿瑞之颅——艾瑞达领主们使用的恶魔聚能器，拥有强大的召唤之力。"
L["Recover, restore, and reforge an ancient Bronzebeard relic."] = "寻回、修复并重铸一件古老的铜须圣物。"
L["Recovering Remnants"] = "取回护甲残片"
L["Recruit Archmage Kalec and Archmage Modera as champions. Build the Tirisgarde's forces and establish operations."] = "招募大法师卡雷和大法师茉德拉作为勇士。壮大提瑞斯法守望者的力量，并展开行动。"
L["Recruit the first champions of the Unseen Path and send troops into the field across the Broken Isles."] = "招募隐秘之路的首批勇士，并派遣部队前往破碎群岛各地执行任务。"
