L["Rell Nightwind"] = "利尔·夜风"
L["Remnants of the Damned"] = "邪恶残留"
L["Ren Whitepaw"] = "任·白爪"
L["Renathal gathered the Harvesters and turned Sinfall's mirrors against Castle Nathria. Light cut across the ramparts, loyalists scattered, and the rebellion surged toward Denathrius. Then the Master stopped pretending. He had not failed to save the Shadowlands from the anima drought — he had helped cause it, hoarding the realm's lifeblood and pouring it into the Maw for the Jailer. Revendreth's gothic theater became something far larger and worse: the first clear proof that the machinery of Death itself had been betrayed. Denathrius retreated into Castle Nathria, and the fight for the Shadowlands changed forever."] = "雷纳索尔集结了收割者，将堕罪堡的镜子对准了纳斯利亚堡。光芒划过城墙，效忠者四散奔逃，起义军向德纳修斯汹涌而去。随后，这位雷文德斯之主不再伪装。他并非未能将暗影国度从心能枯竭中拯救出来——他正是这场枯竭的元凶之一：他囤积着这个国度的生命之源，并将其灌注进噬渊，献给典狱长。雷文德斯的哥特式戏剧变成了某种远为宏大、也远为可怕的东西：这是第一个确凿的证据，证明死亡本身的运转机制遭到了背叛。德纳修斯退回纳斯利亚堡，暗影国度之战从此彻底改变。"
L["Renathal's rebellion marches on Castle Nathria. Denathrius reveals the truth: Revendreth's stolen anima is being sent into the Maw."] = "雷纳索尔的起义军向纳斯利亚堡进发。德纳修斯揭示了真相：雷文德斯被窃取的心能正被送入噬渊。"
L["Rendezvous with the Courier"] = "去见信使"
L["Rendezvous with the Libation"] = "与祭酒号会合"
L["Rendle"] = "伦德尔"
L["Rensar Greathoof"] = "伦萨·巨蹄"
L["Report from Tian Monastery"] = "天禅院的报告"
L["Repurposing Their Village"] = "肃清村庄"
L["Requesting Reinforcements"] = "请求增援"
L["Requires completing all three Kul Tiras zone storylines (Tiragarde Sound, Drustvar, and Stormsong Valley). Speak to Cyrus Crestfall in Boralus to begin. This chapter includes four dungeon quests: Tol Dagor, Shrine of the Storm, Waycrest Manor, and Siege of Boralus."] = "需要完成库尔提拉斯全部三个区域的故事线（提拉加德海峡、德鲁斯瓦和斯托颂谷地）。与伯拉勒斯的赛勒斯·克雷斯弗交谈即可开始。本章包含四个地下城任务：托尔达戈、风暴神殿、维克雷斯庄园和围攻伯拉勒斯。"
L["Requires completing the Tiragarde Sound main storyline (\"Trouble in Tiragarde Sound\"). Begin with the Ashvane Trading Company investigation in Boralus."] = "需要完成提拉加德海峡的主线故事（“提拉加德海峡的麻烦”）。从伯拉勒斯的艾什凡贸易公司调查开始。"
L["Rescue a brilliant arcanist trapped by withered nightfallen and secure his knowledge for the growing rebellion."] = "营救一位被枯法者困住的杰出奥术师，为日益壮大的起义军保全他的知识。"
L["Rescue a captive High Chief and bring a new people into the Horde."] = "营救一位被俘的大酋长，将一个新的种族带入部落。"
L["Rescue Koltira Deathweaver from imprisonment and forge deathchargers worthy of the Four Horsemen."] = "营救库尔迪拉·织亡者，并锻造配得上天启四骑士的死亡战马。"
L["Rescue monks captured by the vrykul in Stormheim. Recruit Angus Ironfist, Hiro, and Sylara Steelsong as champions."] = "营救在风暴峡湾被维库人俘虏的武僧。招募安古斯·铁拳、希罗和赛莱拉·钢咏作为勇士。"
