L["Return to the Echo Isles where the Darkspear first made landfall in exile, and listen for loa whose voices have grown quieter since the tribe took its place inside the Horde. The new generation has forgotten more than it realizes.\n\nSeek the loa where they still answer, perform the rites where they are still owed, and remember the Darkspear as a people with roots deeper than any banner."] = "重返回音群岛——暗矛部族在流亡时最初登陆的地方，聆听那些自部族在部落中站稳脚跟后便日渐沉寂的洛阿之声。新一代遗忘的东西，比他们意识到的还要多。\n\n在洛阿仍会回应的地方寻找它们，在仍需偿还的地方举行仪式，并铭记暗矛是一个根基比任何旗帜都更深厚的民族。"
L["Return to the Firelands"] = "重返火焰之地"
L["Return to the Harbor"] = "回到港口"
L["Return to the Surface"] = "返回地面"
L["Revendreth"] = "雷文德斯"
L["Revendreth is a gothic realm of sinstones, vampire courts, and ritual penance: the place where prideful souls are meant to be broken open, judged, and remade. Sent to seek anima for the starving Shadowlands, you arrive in a kingdom that is already fraying.\n\nPrince Renathal and the Court of Harvesters are gathering resistance, Sire Denathrius still rules from above, and every misted street carries another rumor about where Revendreth's loyalty truly lies."] = "雷文德斯是一个充满罪碑、吸血鬼宫廷与仪式性赎罪的哥特式国度：骄傲的灵魂在这里被剖开、审判并重塑。你奉命为饥渴的暗影国度寻找心能，却来到了一个早已摇摇欲坠的王国。\n\n雷纳索尔王子和收割者之庭正在集结反抗力量，德纳修斯大帝仍在高处统治，每条雾气弥漫的街道都流传着新的传言，诉说着雷文德斯真正效忠于谁。"
L["Revenge for the Vargul"] = "瓦古的复仇"
