L["Ride the Alliance gunship from Ymirheim to the Broken Front to the Desolation Gate."] = "乘坐联盟炮舰，从伊米海姆前往破碎前线，再到荒芜之门。"
L["Ride the Horde gunship from Ymirheim to the Broken Front to the Desolation Gate."] = "乘坐部落炮舰，从伊米海姆前往破碎前线，再到荒芜之门。"
L["Ride to Wyrmrest Temple and kneel before Alexstrasza, the Life-Binder."] = "骑马前往龙眠神殿，跪拜生命的缚誓者阿莱克丝塔萨。"
