L["Ritssyn Flamescowl"] = "雷特森·焰怒"
L["Ritssyn Flamescowl appeared in Dalaran with a proposition — the Council of the Black Harvest needed a sixth member, and you had been chosen. The Council operated from Dreadscar Rift, a pocket of the Twisting Nether they had ripped from demonic control and claimed as their own. You proved your worth, claimed an artifact weapon steeped in dark power, and took your seat on the Council. Calydus — a demon bound to serve the warlocks — helped establish the Rift as your base of operations."] = "雷特森·焰怒带着一项提议出现在达拉然——黑暗收割议会需要第六位成员，而你已被选中。议会以恐痕裂隙为据点，那是他们从恶魔手中夺来、据为己有的一块扭曲虚空碎片。你证明了自己的价值，取得了一件浸透黑暗力量的神器武器，并在议会中占据了一席之地。卡里杜斯——一个被束缚为术士效力的恶魔——帮助你们将裂隙打造成行动基地。"
L["Ritssyn Flamescowl needs a sixth member for the Council of the Black Harvest. You are chosen — but the seat comes with a price."] = "雷特森·焰怒需要为黑暗收割议会寻找第六位成员。你被选中了——但这个席位是有代价的。"
L["Ritual Artifacts"] = "仪式神器"
L["Ritual Effects"] = "仪式效应"
L["Ritual Reagents"] = "仪式材料"
L["Ritual Recovery"] = "仪式复原"
L["Rivett Clutchpop"] = "利维特·急刹"
L["Road Rations"] = "行军口粮"
L["Rokhan"] = "洛坎"
L["Rokhan led you into Gloom Hollow, where the ancient frog loa Krag'wa brooded in the dark. The blood trolls had massacred his followers and desecrated his totems, and Krag'wa was in no mood for diplomacy. You hunted the hunters who had slaughtered his priests, restored his shrines, and prepared the kind of feast that only a frog loa the size of a temple could appreciate. Krag'wa was pleased. He was also terrifying. The agreement was simple enough: he would fight with the Horde against the blood trolls and G'huun. In Gloom Hollow, that counted as a warm welcome."] = "洛坎带你来到林荫巨木，远古的蛙之洛阿克拉格瓦正在那片黑暗中沉思。血巨魔屠杀了他的追随者，亵渎了他的图腾，克拉格瓦根本没心情谈什么外交。你猎杀了那些屠戮他祭司的猎手，修复了他的神龛，还准备了一场只有体型堪比神殿的蛙之洛阿才懂得欣赏的盛宴。克拉格瓦很满意。他也很吓人。协议再简单不过：他将与部落并肩对抗血巨魔和戈霍恩。在林荫巨木，这已经算得上热情款待了。"
