L["Saurfang is gone. Nathanos Blightcaller has been dispatched to find him — and bring him back before he becomes a problem."] = "萨鲁法尔失踪了。纳萨诺斯·凋零者奉命去找到他——并在他成为麻烦之前把他带回来。"
L["Saurfang leads the charge on the gate to the Lich King's domain."] = "萨鲁法尔率军冲向巫妖王领地的大门。"
L["Saurfang leads the Horde up the spiral of Wyrmrest to bargain with the Dragon Queen."] = "萨鲁法尔率领部落登上龙眠神殿的螺旋阶梯，与巨龙女王谈判。"
L["Saurfang the Younger"] = "小萨鲁法尔"
L["Saurfang the Younger calls you to the Kor'kron Vanguard. The Taunka are blood-sworn, the Nerubians silenced, and the Forsaken have their weapons. The old Orc himself takes you to Wyrmrest Temple — to kneel, or rather to bargain, before Alexstrasza the Life-Binder. The dragons remember every Horde blade that ever flashed in anger at the Second War. Whether they answer the Warchief's call is another matter."] = "小萨鲁法尔召你前往库卡隆先锋营地。牦牛人已立下血誓，蛛魔已被消灭，被遗忘者也拿到了他们的武器。那位老兽人亲自带你前往龙眠神殿，去面见阿莱克丝塔萨，生命的缚誓者——名义上是下跪，实则是谈判。巨龙们记得第二次战争中每一把愤怒挥向它们的部落之刃。它们是否会响应酋长的号召，就是另一回事了。"
L["Saurfang's last act before the gate was a summons sent to every Horde leader still standing. By the time the crowd outside Orgrimmar thinned and the silence settled in, they were already gathering: Baine, Lor'themar, Ji Firepaw, and Lilian Voss, who now spoke for a Forsaken people their former Warchief had used as weapons and discarded. In the middle of it, Lilian stepped away from the main hall to broker a quieter conversation — one that had to happen before anything else could move: Forsaken leadership, face to face with Calia Menethil and Derek Proudmoore. Hidden, necessary, and hers to arrange. Then the full council assembled. The Warchief's throne was empty. Lilian made the case for leaving it that way. No single voice, no single will — a council, the way the Horde had always needed to work but never quite managed. The others listened. Then they agreed."] = "萨鲁法尔在大门前的最后一件事，是向每一位仍屹立不倒的部落领袖发出召集令。等到奥格瑞玛城外的人群散去、寂静降临时，他们已经开始集结：贝恩、洛瑟玛、季·火掌，还有莉莉安·沃斯——她如今代表着被遗忘者，这个民族曾被他们的前任酋长当作武器利用，然后抛弃。在这一切之中，莉莉安离开大厅，促成了一场更隐秘的会谈——这场会谈必须先于其他一切进行：被遗忘者的领袖与佳莉娅·米奈希尔和德里克·普罗德摩尔当面会晤。隐秘、必要，并且由她一手安排。随后，全体议会召开。酋长的王座空着。莉莉安主张让它继续空着。没有单一的声音，没有单一的意志——而是一个议会，这正是部落一直需要、却从未真正做到的运作方式。其他人静静听着。然后，他们同意了。"
