L["Scouting reports painted a grim picture — Legion assassins had infiltrated the Broken Isles, targeting the Unseen Path's agents. You tracked them through Stormheim, rescuing Hudson Crawford from an ambush and calling Beastmaster Hilaire home from the wilds. In Highmountain, you found Rexxar living among the beasts and convinced the legendary hunter to join your cause. With new champions at your side, the Unseen Path's eyes grew sharper."] = "斥候报告描绘出一幅严峻的图景——燃烧军团的刺客已渗透进破碎群岛，目标直指隐秘之路的特工。你一路追踪他们穿过风暴峡湾，从伏击中救出胡德森·克劳福德，又将兽王希莱尔从荒野中召回。在至高岭，你发现雷克萨正生活在野兽之间，并说服这位传奇猎人加入你的事业。有了新勇士相伴，隐秘之路的目光愈发敏锐。"
L["Scouting reports reveal Legion assassins targeting the Unseen Path. Track them across Stormheim while recruiting Rexxar and Hilaire."] = "斥候报告显示，军团刺客正以隐秘之路为目标。在招募雷克萨和希莱尔的同时，追踪他们穿越风暴峡湾。"
