L["Seek aid from the night elves and blood elves, bridging ten thousand years of division for a common cause."] = "向暗夜精灵和血精灵寻求援助，为了共同的目标弥合一万年的隔阂。"
L["Seek Fu Zan, a legendary staff carried by monks across the ages, now lost in the wilds."] = "寻找伏赞——一根世代由武僧携带的传奇法杖，如今遗失在荒野之中。"
L["Seek out a shield forged from a scale of Neltharion himself, hidden deep within the mountains where the earth remembers."] = "寻找一面用耐萨里奥本人的鳞片锻造的盾牌，它藏在群山深处，那里的大地仍铭记着过往。"
L["Seek out Aegira, a vrykul brewmaster in the Halls of Valor, and brew the legendary Storm Brew to empower your forces."] = "前往英灵殿寻找维库酒仙艾吉拉，酿造传说中的风暴蜜酒来增强你的部队。"
L["Seek Out the Lorewalker"] = "找到游学者"
L["Seek T'uure, a crystal beacon forged by the naaru, whose light has guided the faithful through the darkest ages."] = "寻找图雷——一座由纳鲁打造的水晶信标，它的光芒曾指引信徒度过最黑暗的岁月。"
L["Seek the Aldrachi Warblades, weapons of a race that defeated a demon lord and chose death over servitude."] = "寻找奥达奇战刃——这对武器属于一个曾击败恶魔领主、宁死也不愿受奴役的种族。"
L["Seek the ancient eagle spear Talonclaw in the peaks of Highmountain, a weapon sacred to the hunters of old."] = "在至高岭的群峰之间寻找古老的鹰神长矛“鹰爪”——这件神圣的武器为古代猎人所尊崇。"
L["Seek the Fist of Ra-den, a weapon forged by the titan keeper who tamed the storms of Azeroth."] = "寻找莱登之拳——这件武器由驯服了艾泽拉斯风暴的泰坦守护者打造。"
L["Seek the Scythe of Elune, a weapon of terrible power tied to the worgen curse and the moon goddess herself."] = "寻找艾露恩之镰——这件力量可怕的武器与狼人诅咒和月神本身息息相关。"
L["Seek the staff of the Guardian Aegwynn — Aluneth, a weapon of pure arcane power that has a mind of its own."] = "寻找守护者艾格文的法杖艾露尼斯——这件蕴含纯粹奥术力量的武器拥有自己的意志。"
L["Seek the Unsavory"] = "找到坏人"
L["Seek Truthguard, a titan-forged shield that protects the worthy and strikes down the false."] = "寻找真理守护者——一面泰坦锻造的盾牌，守护值得守护之人，击倒虚伪之徒。"
L["Seek Ulthalesh, a scythe that reaps souls from the living and binds them in eternal torment."] = "寻找乌萨雷斯——一把能从生者身上收割灵魂、并将其束缚于永恒折磨之中的镰刀。"
