L["Sinfall gave the rebels a foothold, but they still needed their prince. In the ruins of his first rebellion, you found what Denathrius had left behind: cages, broken allies, and Renathal himself, imprisoned as an example. With Theotar, the Accuser, and General Draven at your side, you tore open the prison, stole the key, and pulled Renathal back from Torghast's shadow. The prince returned humbled but unbroken. He had lost a rebellion once. This time, he would not stand alone."] = "堕罪堡为起义军提供了立足之地，但他们仍需要他们的王子。在他第一次起义的废墟中，你发现了德纳修斯留下的东西：牢笼、残破的盟友，以及被囚禁以儆效尤的雷纳索尔本人。在西塔尔、指控者和德莱文将军的陪同下，你攻破了监牢，偷走了钥匙，将雷纳索尔从托加斯特的阴影中拉了回来。王子归来时虽已谦卑，却未被击垮。他曾经输掉过一场起义。这一次，他不会再孤军奋战。"
L["Sinstone Delivery"] = "罪碑速递"
L["Siouxsie the Banshee"] = "女妖希奥克丝"
L["Sire Denathrius"] = "德纳修斯大帝"
L["Sire Denathrius pointed you at the Accuser, one of the Harvesters standing against him. Lord Chamberlain's hunt was brutal and theatrical: tear through her followers, read the sinstones of her inquisitors, and use those names to drag the guilty into judgment. But the deeper you went, the less clean the story became. The Accuser had punished pride for ages, and she understood what Denathrius's court had become. When her own secret was revealed, it was not simple innocence that saved her — it was the terrible truth that Revendreth's ruler had turned repentance into control."] = "德纳修斯大帝让你去对付指控者，她是反抗他的收割者之一。宫务大臣主持的这场猎杀既残酷又充满戏剧性：撕碎她的追随者，读取她手下审判官的罪碑，再用那些名字将有罪之人拖去受审。但你越深入，这个故事就越不清白。指控者惩罚傲慢已有无数岁月，她明白德纳修斯的宫廷已经变成了什么。当她自己的秘密被揭开时，拯救她的并非单纯的无辜——而是一个可怕的真相：雷文德斯的统治者已将忏悔变成了控制的工具。"
L["Skull of the Man'ari"] = "曼阿瑞之颅"
L["Sky Admiral Rogers"] = "空军上将罗杰斯"
L["Sky-Reaver Korm Blackscar"] = "掠天者考尔姆·黑痕"
L["Skybreaker Squad Leader"] = "破天号班长"
L["Skyhold / Broken Isles"] = "苍穹要塞 / 破碎群岛"
L["Skylord Omnuron"] = "啸天者欧穆隆"
L["Skyseer Ghrent"] = "天空贤者格伦特"
L["Slaves to Saronite"] = "萨隆邪铁的奴隶"
L["Slayer's Campaign"] = "屠魔者的战役"
L["Slowing the Spread"] = "阻止邪能扩散"
L["Slumber No More"] = "不再沉睡"
L["Smarter Than Your Average Trogg"] = "比一般穴居人聪明得多"
