L["Snowfeather"] = "雪羽"
L["Snowfeather, a majestic eagle, arrived in Dalaran bearing an urgent summons. You followed the bird to Trueshot Lodge high in the mountains, where Emmarel Shadewarden revealed the Unseen Path — a secret order of hunters that had watched over Azeroth for generations. You swore the Oath of Service, claimed a weapon of legend, and took your place among their ranks."] = "雄伟的雄鹰雪羽带着紧急召令飞抵达拉然。你跟随它来到高山之上的神射手营地，伊墨瑞尔·影卫在那里向你揭示了隐秘之路——一个世代守护艾泽拉斯的秘密猎人组织。你宣誓效忠，取得了一件传说中的武器，并在他们的队伍中占据了一席之地。"
L["So Long, Sister"] = "再见，女巫"
L["Some Knowledge Shouldn't Be Shared"] = "不应分享的知识"
L["Someone Else's Mess"] = "别人的麻烦"
L["Something broke inside Lilian Voss. Shadow magic erupted from her hands as she tore through the crusaders with a fury that terrified even the Forsaken. She marched to the tower where her father, High Priest Benedictus Voss, waited — and when he condemned her as a monster, she killed him. Then she vanished, leaving nothing but silence and the smell of burning."] = "莉莉安·沃斯内心有什么东西崩断了。暗影魔法从她手中迸发，她以连被遗忘者都为之胆寒的狂怒撕碎了十字军。她走向那座塔楼，她的父亲高阶牧师本尼迪塔斯·沃斯正在那里等待——当他斥责她是个怪物时，她杀了他。随后她消失了，只留下一片死寂和燃烧的气味。"
L["Something in the Water"] = "水源污染"
L["Something Valuable, Perhaps?"] = "有什么有价值的东西吗？"
L["Something's Not Quite Right..."] = "有点不对劲……"
L["Soothing Wounds"] = "缓解伤势"
L["Soul Beacon"] = "灵魂信标"
L["Soulbound"] = "缚魂契约"
L["Souls for the Death Loa"] = "献给死神的灵魂"
L["South of the Pinnacle, past the rim of the Valley of Echoes, a little Scarlet outpost called Blackwatch keeps quiet company with the Scourge it claims to hate. The Argent Crusade has questions about that. Grimly wants the plague altars in pieces. Father Kamaros, somehow still alive, has a list of his own wounded. Doctor Olakin Sainrith is busy inside the lab cooking something that was never meant to breathe. Overhead, the Flesh Giant Champion walks the ice. Inside Malykriss's foundry, the Runesmiths still pound the Scourge's armor — and one old vrykul skeleton is about to do more work dead than it ever did alive."] = "在北伐军之峰以南，越过回音谷的边缘，一座名为黑色观察站的血色十字军小前哨，正与它声称憎恨的天灾军团暗中为伍。银色北伐军对此颇有疑问。格林姆利想把瘟疫祭坛砸个粉碎。不知怎么还活着的卡玛洛斯神父，手里有一份他自己的伤员名单。奥拉金·塞恩里斯医生正在实验室里忙着炮制某种本不该会呼吸的东西。高处，血肉巨人勇士在冰面上巡行。在玛雷克里斯的铸造厂里，符文铁匠们仍在锻打天灾军团的盔甲——而一具古老的维库骷髅即将在死后干出比生前更多的活。"
