L["Stand on the Pinnacle beside a dying paladin while the world's powers weigh his fate."] = "站在北伐军之峰上，守在一位垂死的圣骑士身旁，而世间的各方势力正在权衡他的命运。"
L["Stand with Eitrigg, Aggra, and the clans as the Kosh'harg, the great festival of clan and ancestor, is reborn on Azeroth. The Horde has crossed worlds and survived wars, but some rites still need hands to carry them forward.\n\nWalk through Durotar and Nagrand with shamans and young initiates, hear the names of forebears spoken aloud, and remember that orc heritage is more than fang or blade."] = "与伊崔格、阿格娜和各个氏族并肩而立，见证柯什哈格——这场属于氏族与先祖的盛大节庆——在艾泽拉斯重生。部落跨越了世界，熬过了战争，但有些仪式仍需有人亲手传承下去。\n\n与萨满和年轻的启蒙者一同走过杜隆塔尔和纳格兰，聆听先祖的名字被高声念出，并铭记兽人的传承远不止獠牙与刀刃。"
L["Stand with Moira Thaurissan as the Dark Iron clan steps out of Blackrock's shadow and claims its place beside the other dwarven clans. Old pride still smolders in the forges, and old enemies still know the names of the halls beneath the mountain.\n\nWalk through places where fire shaped a people, recover what was scattered, and prove that Dark Iron loyalty is earned in heat, craft, and memory."] = "与茉艾拉·索瑞森并肩而立，见证黑铁氏族走出黑石山的阴影，在其他矮人氏族之间占据一席之地。古老的骄傲仍在熔炉中闷燃，宿敌也依然记得山脉之下那些殿堂的名字。\n\n走过烈火塑造了一个民族的地方，找回散落的一切，并证明黑铁的忠诚要在炽热、技艺与记忆中赢得。"
L["Stand with Tess and the Gilneans to face the Nightbane and reaffirm your people's resolve."] = "与苔丝和吉尔尼斯人并肩对抗夜之魇，重申你的族人的决心。"
