L["Stormwind's legacy was tested by old enemies and old mistakes. You followed the trail from the city to Westfall and Northshire, exposed the conspiracy, and helped preserve the honor of the kingdom."] = "暴风城的遗产受到了宿敌与旧日过错的考验。你从城中一路追查到西部荒野和北郡，揭穿了阴谋，帮助维护了王国的荣誉。"
