L["Stranglethorn / Crapopolis"] = "荆棘谷/渣客城"
L["Strategic Deployment"] = "战略部署"
L["Strength of Icemist"] = "冰雾的力量"
L["Strengthen the Dreamgrove by recruiting champions, training troops, and establishing flight paths through the ancient dreamways."] = "招募勇士、训练部队，并开辟穿过古老梦境之路的飞行路线，以壮大梦境林地。"
L["Strom'kar, the Warbreaker"] = "斯多姆卡，碎军者"
L["Strongarm Jarden"] = "铁腕贾登"
L["Strongarm Tactics"] = "铁腕战术"
L["Stunning View"] = "壮观的景象"
L["Subject 16"] = "16号实验体"
L["Subtlety had its limits in Nazmir. Patch — a goblin with strong opinions about explosives and personal safety — had a solution for the blood troll barricades that was loud, expensive, and effective. You wrangled his scattered crew, gathered everything they needed, and let them do what goblins do best. The blood troll fortifications that had blocked the advance for weeks turned to rubble in an afternoon. Talanji watched the smoke rise with something close to satisfaction. The path deeper into Nazmir was open."] = "在纳兹米尔，低调行事是有极限的。帕奇——一个对炸药和人身安全都有着强烈主见的地精——对付血巨魔路障的办法又响、又贵、又管用。你把他四散的手下召集起来，备齐他们所需的一切，然后让他们干地精最擅长的事。阻挡推进数周的血巨魔工事，一个下午就化为了瓦砾。塔兰吉望着升起的浓烟，脸上露出近乎满意的神情。深入纳兹米尔的道路打开了。"
L["Sufficient Motivation"] = "高效激励"
L["Sully \"The Pickle\" McLeary"] = "“腌菜”苏利·麦克莱利"
L["Summoner Morn"] = "召唤师摩恩"
L["Summoning the Sisters"] = "召唤双子"
L["Sunke Khang"] = "康顺可"
L["Sunwell Plateau"] = "太阳之井高地"
L["Supply Only the Finest Goons"] = "精选优质打手"
L["Suramar"] = "苏拉玛"
L["Suramar is an ancient elven city sealed behind a magical barrier for ten thousand years, now opened under the shadow of the Burning Legion. Within the walls, the highborne depend on the arcwine of the Nightwell; outside them, the nightfallen wither without its magic.\n\nAid First Arcanist Thalyssra and her rebellion as they gather allies, infiltrate noble houses, and learn how to challenge a city that has survived by hiding from the world."] = "苏拉玛是一座古老的精灵城市，被魔法屏障封闭了一万年，如今在燃烧军团的阴影下重新开启。城墙之内，上层精灵依赖暗夜井的魔泉酒；城墙之外，堕夜精灵因失去它的魔力而日渐枯萎。\n\n协助首席奥术师塔莉萨和她的起义军召集盟友、渗透贵族家族，并学会如何挑战一座靠避世而存续至今的城市。"
L["Survey Says..."] = "传送侦测"
L["Survey the City"] = "调查城市"
L["Survival Skills"] = "求生技能"
L["Survive the Night"] = "活过一夜"
L["Svergan Stormcloak"] = "瑟维甘·风篷"
L["Svergan's Promise"] = "瑟维甘的承诺"
L["Swallowed Whole"] = "整个吞下"
L["Swear the blood oath at Agmar's Hammer and dig the Horde's claws into the frozen plain."] = "在阿格玛之锤立下血誓，让部落的利爪深深扎进这片冰冻平原。"
L["Sweete's Strongbox"] = "斯威提的保险箱"
L["Sylvanas found a crack in Icecrown's defenses and sent you in alongside her. The Forge of Souls. The Pit of Saron. And finally the Halls of Reflection, where she came face to face with the memory of the man who murdered her and enslaved her people. She asked Uther the Lightbringer what would become of Arthas when he died. He told her the only way to truly end the Lich King was at the Frozen Throne where he was made. Then he warned her, in the same breath, that her own fate in death would not be kind. She said nothing. She called for the gunship and got everyone out."] = "希尔瓦娜斯在冰冠冰川的防线上找到了一道裂缝，派你随她一同潜入。灵魂洪炉。萨隆矿坑。最后是映像大厅，在那里，她直面了那个杀害她、奴役她子民的男人的记忆。她问光明使者乌瑟尔，阿尔萨斯死后会怎样。乌瑟尔告诉她，真正终结巫妖王的唯一方法，就在造就他的冰封王座。紧接着，他又警告她，她自己死后的命运不会好过。她什么也没说。她叫来炮舰，把所有人都带了出去。"
L["Sylvanas has found a crack in Icecrown's defenses. She leads a covert strike through three dungeons — the Forge of Souls, the Pit of Saron, and the Halls of Reflection — to reach something she has been waiting years to confront."] = "希尔瓦娜斯在冰冠冰川的防线上找到了一道裂缝。她率领一次秘密突袭，穿过三座地下城——灵魂洪炉、萨隆矿坑和映像大厅——去面对一个她已经等了许多年的存在。"
L["Sylvanas is gone. The Horde's leaders gather to decide what it becomes without her — and Lilian Voss speaks for the Forsaken."] = "希尔瓦娜斯走了。部落的领袖们齐聚一堂，决定失去她之后的部落将何去何从——而莉莉安·沃斯代表被遗忘者发言。"
L["Sylvanas is gone. What remains of the Horde gathers to decide what it becomes without her."] = "希尔瓦娜斯走了。部落仅存的力量聚集起来，决定失去她之后的部落将何去何从。"
L["Sylvanas shatters the Helm of Domination and tears open the sky above Icecrown. The leaders of Azeroth follow her into death itself — and find that she left someone behind."] = "希尔瓦娜斯击碎了统御头盔，撕开了冰冠冰川上空的天幕。艾泽拉斯的领袖们追随她进入了死亡本身——却发现她留下了一个人。"
L["Sylvanas went to Icecrown and took the Helm of Domination from Bolvar Fordragon's head. Then she broke it. The veil between the living world and the realm of death split apart where she stood, and she stepped through and left. Bolvar used the shards to open a second rift — he and Jaina, Thrall, Baine, and Anduin went in after her. They landed in the Maw, the prison at the bottom of the Shadowlands, a place no soul had ever escaped from. Sylvanas was already gone deeper in. She had left Anduin behind, locked in a cage in the Tremaculum, to be broken slowly by the Jailer's forces — a message, maybe, or an experiment. Jaina found him. The Jailer's magic had already started working on Baine, poisoning his spirit through a cursed dagger. There was no clean escape: the river of souls, Gorgoa, cut across the only path out, and the Jailer's armies were moving to seal it. The group fought their way through, kept each other standing, and crossed. They came out the other side with Anduin freed and the full shape of the threat finally visible. Sylvanas had not just started a war. She had chosen a side in one that had been running since before Azeroth existed."] = "希尔瓦娜斯前往冰冠冰川，从伯瓦尔·弗塔根头上取下了统御头盔。然后她将其击碎。生者世界与死亡国度之间的帷幕在她脚下裂开，她跨了过去，就此离去。伯瓦尔用头盔的碎片打开了第二道裂隙——他和吉安娜、萨尔、贝恩、安度因追了进去。他们落入了噬渊，那是暗影国度最底层的监牢，从未有任何灵魂从那里逃脱。希尔瓦娜斯早已深入其中。她把安度因留在了身后，锁在特雷马库伦的一座牢笼里，任由典狱长的部队慢慢将他摧垮——这或许是一条讯息，也或许是一场实验。吉安娜找到了他。典狱长的魔法已经开始侵蚀贝恩，通过一把受诅咒的匕首毒害他的灵魂。没有轻松的逃生之路：灵魂之河戈尔高亚横亘在唯一的出路上，而典狱长的大军正在逼近，要将它彻底封死。众人一路杀出重围，相互扶持，渡过了河。抵达彼岸时，安度因已获自由，威胁的全貌也终于清晰可见。希尔瓦娜斯不只是挑起了一场战争。她在一场早在艾泽拉斯诞生之前就已开始的战争中选择了立场。"
L["Sylvanas Windrunner"] = "希尔瓦娜斯·风行者"
L["Sympathizers Among the Shal'dorei"] = "夏多雷盟友"
L["Syra Goldendraft"] = "塞拉·金酿"
L["T'uure, Beacon of the Naaru"] = "图雷，纳鲁的信标"
L["Tactical Matters"] = "战术考量"
L["Tactical Planning"] = "战术商讨"
L["Tactician Tinderfell"] = "战术家蒂德菲尔"
L["Taelia"] = "泰莉亚"
L["Taelia sent you to Drustvar, where Lord Waycrest had vanished and a dark curse was spreading. In Fallhaven, Cyril White led you through the signs of witchcraft — hexed villagers, twisted familiars, and effigies that pulsed with dark magic. You met Lucille Waycrest, the lord's daughter, who refused to sit idle while her land rotted. Together you hunted the witches through Fallhaven, cracking their curses and burning their effigies. The final effigy crumbled, but the witches' power ran far deeper than one village."] = "泰莉亚派你前往德鲁斯瓦，维克雷斯勋爵在那里失踪，黑暗的诅咒正在蔓延。在萧湾镇，西里尔·怀特带你察看巫术的种种迹象——中了妖术的村民、扭曲的魔宠，以及散发着黑暗魔力的雕像。你见到了勋爵的女儿露希尔·维克雷斯，她不愿坐视自己的土地腐朽。你们一同在萧湾镇猎杀女巫，破解她们的诅咒，焚毁她们的雕像。最后的雕像崩塌了，但女巫的力量远不止扎根于一座村庄。"
L["Take Me To Your Leader"] = "领袖会晤"
L["Take part in the Spirit Festival and walk both Tushui and Huojin threads of pandaren heritage."] = "参加灵魂节，体验熊猫人传承中天水与火金两条脉络。"
L["Take the High Road"] = "高山之路"
L["Takes One to Know One"] = "知根知底"
L["Taking a Promenade"] = "侦察步道"
L["Taking Charge"] = "身先士卒"
L["Taking Control"] = "夺回控制权"
L["Taking the Blood Gate"] = "拿下鲜血关口"
L["Tal-Inara"] = "塔尔-伊纳拉"
L["Tal-Inara sent you toward Revendreth with a plea for aid: Ardenweald was starving, the Heart of the Forest was weakening, and Sire Denathrius was said to be a master of anima. Revendreth greeted you with teeth behind every smile. Rendle introduced the rules of the realm — sinstones, punishment, service, and the long work of repentance. Lord Chamberlain offered polished courtesy while rebels struck at the roads and Darkhaven buckled under the anima drought. The place looked like a vampire court and spoke like a church of atonement, but something in its foundations was already cracking."] = "塔尔-伊纳拉派你前往雷文德斯求援：炽蓝仙野正在挨饿，森林之心日渐衰弱，而据说德纳修斯大帝精通心能。雷文德斯迎接你的，是每张笑脸背后的獠牙。伦德尔向你介绍了这个国度的规矩——罪碑、惩罚、侍奉，以及漫长的忏悔之路。宫务大臣表现得彬彬有礼，与此同时，叛军袭击道路，暗湾镇在心能枯竭中摇摇欲坠。这里看起来像一座吸血鬼宫廷，说起话来却像一座赎罪的教堂，但它的根基早已开始崩裂。"
L["Talanji brought you to Nazmir, the oldest and most cursed of the Zandalari lands. The swamp had been swallowed — blood trolls pressed inward from every angle, their offerings feeding something dark and hungry beneath the earth. Rokhan read the signs: to push back the blood tide, you'd need the loa. Ancient, capricious, and rarely willing to be asked. You cut through the blood troll front lines, took in the full scope of the devastation, and prepared to seek out the only powers old enough to matter in Nazmir."] = "塔兰吉带你来到纳兹米尔，这是赞达拉领土中最古老、受诅咒最深的地方。沼泽已被吞没——血巨魔从四面八方步步进逼，他们的祭品喂养着地下某种黑暗而饥渴的东西。洛坎读懂了征兆：要击退血潮，你们需要洛阿的力量。它们古老、反复无常，而且很少愿意应人所求。你杀穿血巨魔的前线，亲眼见证了这场浩劫的全貌，并准备去寻找纳兹米尔唯一足够古老、足以左右局势的力量。"
L["Talking Skull"] = "缚魂魔袋"
L["Talon Terror"] = "利爪恐慌"
L["Talon's Call"] = "利爪的召唤"
L["Talonclaw"] = "鹰爪"
L["Taming their Beasts"] = "驯服敌人的野兽"
L["Taoshi"] = "陶矢"
L["Tapping the Leylines"] = "引流魔网能量"
L["Taran Zhu"] = "祝踏岚"
L["Target of Opportunity"] = "意外目标"
L["Tavernkeeper's Fate"] = "酒馆老板的命运"
L["Tea Party"] = "茶话会"
L["Tech It Up a Notch"] = "更上一层楼"
L["Tech It Up A Notch"] = "更上一层楼"
L["Technical Wizardry"] = "魔法技师"
L["Teddies and Tea"] = "泰迪熊和茶"
L["Telemantic Expanse"] = "传送扩张"
L["Temel, the Sin Herald"] = "泰梅尔，罪行通报官"
L["Temple of the Jade Serpent"] = "青龙寺"
L["Temporal Investigations"] = "时空调查"
L["Ten thousand years of division between the elven peoples had to be bridged if Suramar was to be freed. You stood between night elf and blood elf, forging an uneasy alliance from shared purpose. Lady Liadrin and Tyrande Whisperwind each brought their people's strength to the cause, while you cleared the Promenade of Elisande's defenses."] = "若要解放苏拉玛，就必须弥合精灵各族之间一万年的隔阂。你站在暗夜精灵与血精灵之间，以共同的目标缔结了一个脆弱的同盟。女伯爵莉亚德琳和泰兰德·语风各自为这项事业带来了本族的力量，而你则清除了长廊上艾利桑德的防御。"
L["Teng Applebloom"] = "邓·苹花"
L["Terrace of Ten Thunders"] = "十雷台"
L["Testing a Theory"] = "理论测试"
L["Testing Loyalties"] = "忠诚的考验"
L["Thalyssra's Abode"] = "塔莉萨的住所"
L["Thalyssra's Drawers"] = "塔莉萨的抽屉"
L["Thank Your Guide"] = "感谢指引"
L["Thas'dorah, Legacy of the Windrunners"] = "萨斯多拉，风行者的遗产"
L["Thassarian"] = "萨萨里安"
L["Thassarian came with a personal request — Koltira Deathweaver, his old friend and fellow death knight, had been imprisoned beneath the Undercity by Sylvanas Windrunner. You freed Koltira from his chains, and he pledged himself to your cause. Then came the steeds — Salanar the Horseman forged deathchargers in Neltharion's Lair and the Darkheart Thicket, crafting mounts worthy of the Horsemen from nightmares and shadow."] = "萨萨里安带来了一个私人请求——他的老友、同为死亡骑士的库尔迪拉·织亡者被希尔瓦娜斯·风行者囚禁在幽暗城地下。你解开了库尔迪拉的锁链，他宣誓投身于你的事业。随后是战马——骑手萨拉纳尔在奈萨里奥的巢穴和黑心林地锻造死亡战马，以梦魇与阴影打造出配得上天启骑士的坐骑。"
L["That Which Haunts the Dead"] = "亡灵作祟"
L["That's Abominable!"] = "你的憎恶伙伴"
L["The Accuser"] = "指控者"
L["The Accuser sent you to find Prince Renathal, and the trail led to Theotar, the Mad Duke. He was scattered, brilliant, and broken in a way that made perfect sense in Revendreth. His morning was a catastrophe of lost servants, forged warrants, forbidden research, and tea. Beneath the absurdity was the Ember Ward, a district burned by the Light so fiercely that even Venthyr feared its glow. You crossed that desiccated ruin, pieced together Theotar's memories, and secured Sinfall as a rebel refuge. Revendreth's comedy had teeth, but it also had a heart: the rebellion finally had a home."] = "指控者派你去寻找雷纳索尔王子，线索指向了疯公爵西塔尔。他思绪涣散、才华横溢，又以一种在雷文德斯再合理不过的方式支离破碎。他的早晨是一场灾难：走失的仆从、伪造的逮捕令、禁忌的研究，还有茶。在这荒诞之下，是灰烬荒野——一个被圣光灼烧得如此猛烈、连温西尔都畏惧其光芒的街区。你穿过那片干涸的废墟，拼凑起西塔尔的记忆，并将堕罪堡确立为叛军的避难所。雷文德斯的喜剧暗藏獠牙，却也有一颗真心：起义军终于有了一个家。"
L["The Accuser's Fate"] = "指控者的命运"
L["The Accuser's Secret"] = "指控者的秘密"
L["The Accuser's Sinstone"] = "指控者的罪碑"
L["The Advisor and the Arcanist"] = "顾问与奥术师"
L["The Afflictor's Key"] = "折磨者的钥匙"
L["The Aid of the Loa"] = "神灵相助"
L["The Aid of the Tides"] = "潮汐助力"
L["The Air Stands Still"] = "凝固的空气"
L["The Alliance and Horde did not discover Pandaria gently. They arrived as wreckage, orders, pursuit, and fire, then tried to make allies before they understood what the land would remember.\n\nThe Jade Forest is the first lesson of Pandaria: every doubt, every grudge, and every easy answer has weight. Follow the campaign from the first landings into a land where war leaves marks deeper than banners in the mud."] = "联盟和部落并非以温和的方式发现了潘达利亚。他们是带着残骸、命令、追击和战火来到这里的，还没弄明白这片土地会铭记什么，就急于结交盟友。\n\n翡翠林是潘达利亚的第一课：每一份疑虑、每一份积怨、每一个轻率的答案都有其分量。跟随这场战役，从最初的登陆出发，深入一片战争所留痕迹比泥泞中的旗帜更深的土地。"
L["The Alliance finds Taylor, courts the Pearlfin jinyu, and follows Cho's strange methods to Prince Anduin."] = "联盟找到了泰勒，争取珠鳍锦鱼人的支持，并追随周卓奇特的方法找到了安度因王子。"
L["The Alliance fleet came while Dazar'alor was still recovering from everything the Horde had sacrificed to protect it. Jaina Proudmoore led the assault through the sacred pyramid, floor by floor, past every guardian the Zandalari could muster. King Rastakhan, knowing the city could not hold, made a desperate bargain — calling on Bwonsamdi's power directly, burning his own life force to drive the invaders back.\n\nBwonsamdi got his king in the end. Rastakhan fell. But the death loa was there to receive him, and the deal struck in Nazmir had never promised anything more than that — the power to fight, not the guarantee of survival. Talanji watched her father die holding a city that still stood. Bwonsamdi, for his part, was exactly as somber as a loa of death ever gets. The soul of a king is not nothing."] = "联盟舰队来袭之时，达萨罗仍未从部落为保护它而付出的一切牺牲中恢复过来。吉安娜·普罗德摩尔率军一层一层地攻入神圣的金字塔，突破了赞达拉人所能召集的每一位守卫。拉斯塔哈大王深知城市守不住，于是做出了一个孤注一掷的交易——直接借用邦桑迪的力量，燃烧自己的生命之力来击退入侵者。\n\n邦桑迪最终还是得到了他的国王。拉斯塔哈倒下了。但死亡洛阿就在那里迎接他，而在纳兹米尔达成的交易从未承诺过更多——那只是战斗的力量，而非生存的保证。塔兰吉眼睁睁看着父亲死去，而他守护的城市依然屹立。至于邦桑迪，他表现出了一个死亡洛阿所能有的最大肃穆。一位国王的灵魂，可不是小事。"
L["The Alliance has come for Lordaeron. Sylvanas holds the walls of the Forsaken capital as Jaina and Anduin lead the siege."] = "联盟兵临洛丹伦。希尔瓦娜斯坚守被遗忘者都城的城墙，吉安娜和安度因则率军围城。"
L["The Alliance strikes at the heart of the Zandalari empire. King Rastakhan calls on Bwonsamdi — and pays the price."] = "联盟直击赞达拉帝国的心脏。拉斯塔哈大王向邦桑迪求助——并为此付出了代价。"
L["The allied armies — nightfallen, blood elves, night elves, and vrykul — marched through the streets of Suramar in a united front. You fought alongside Thalyssra at the vanguard, pushing through Elisande's desperate defenses block by block. The fighting was brutal, but the staging point was secured — the Nighthold was within reach."] = "联军——堕夜精灵、血精灵、暗夜精灵和维库人——组成统一战线，穿过苏拉玛的街道进军。你在先锋部队中与塔莉萨并肩作战，逐个街区地突破艾利桑德垂死挣扎的防线。战斗异常残酷，但集结点已被拿下——暗夜要塞已近在咫尺。"
L["The allied forces breach the Nighthold itself, confronting the source of Elisande's power."] = "联军攻入暗夜要塞本身，直面艾利桑德力量的源头。"
L["The Anub'ar Nerubians boil up from the Pit of Narjun — spider-warriors of a civilization that should have stayed dead. They strike the Horde's supply lines by night and drag the wounded into the dark by morning. Senior Sergeant Juktok wants them ended at the source. Valnok Windrager is already saddling the wyverns. Agmar will not leave this flank open."] = "阿努巴尔蛛魔从纳尔准之坑中蜂拥而出——它们是一个本应早已灭亡的文明所留下的蜘蛛战士。它们在夜间袭击部落的补给线，到了早晨就把伤员拖进黑暗。军士长祖托克想从源头上消灭它们。瓦诺克·风怒已经在给双足飞龙备鞍。阿格玛不会让这一侧翼门户大开。"
L["The Anvil-Thane's Designs"] = "铁砧守卫索加登的设计图"
L["The Arcan'dor — the ancient tree nurtured in Shal'Aran — began to wither, its roots cracking and leaves curling despite all efforts. Valewalker Farodin led you on a desperate search for fragments of arcane power scattered across Suramar's ruins. In the end, you secured a branch of the Arcan'dor itself, stabilizing the tree and keeping alive the dream of a cure for the nightfallen."] = "阿坎多尔——这棵在沙尔艾兰培育的古树——开始枯萎，无论众人如何努力，它的根系仍在开裂，叶片仍在卷曲。山谷行者法罗丁带你展开了一场孤注一掷的搜寻，寻找散落在苏拉玛废墟中的奥术力量碎片。最终，你取得了阿坎多尔自身的一根枝条，稳住了这棵树，也让治愈堕夜精灵的梦想得以延续。"
L["The Arcan'dor is struggling to survive. Race against time to find what it needs before the tree withers."] = "阿坎多尔正在为生存而挣扎。与时间赛跑，在这棵树枯萎之前找到它所需的东西。"
L["The Arcan'dor needed something that could not be found in Suramar — a seed blessed by the wild magic of Val'sharah. You journeyed with Thalyssra's allies to retrieve it, channeling ley energy through Oculeth's projectors and Valtrois's calculations. The seed took root, and the Arcan'dor bloomed with renewed strength, its fruit offering the first true cure for the nightfallen's dependence on the Nightwell."] = "阿坎多尔需要一样在苏拉玛找不到的东西——一颗受过瓦尔莎拉野性魔法祝福的种子。你随塔莉萨的盟友们前去取回它，借助奥库雷斯的投影仪和瓦尔托伊斯的计算引导魔网能量。种子生根发芽，阿坎多尔重新焕发生机，它结出的果实第一次真正为堕夜精灵带来了摆脱暗夜井依赖的解药。"
L["The Arcane Way"] = "奥术之道"
L["The Arcane Way opened a path back to the Black Temple — Illidan's fortress, now empty and echoing with memories. Belath Dawnblade led you through its halls where the ghosts of the Illidari's past still lingered. A confrontation with the temple's remaining defenses proved that the demon hunters had grown beyond what they once were. New recruits joined from among the temple's guards, and the Fel Hammer's ranks swelled."] = "奥术之道开辟了一条重返黑暗神殿的道路——那是伊利丹的要塞，如今空荡荡的，回荡着往昔的记忆。贝拉斯·黎明之刃带你穿过殿堂，伊利达雷过去的幽灵仍在那里徘徊。与神殿残余守军的一场交锋证明，恶魔猎手们早已超越了过去的自己。神殿守卫中有新兵加入，邪能之槌号的队伍日益壮大。"
L["The Archdruid's Campaign"] = "大德鲁伊的战役"
L["The Archmage's Campaign"] = "大法师的战役"
L["The Arcway: Long Buried Knowledge"] = "魔法回廊：掩埋已久的知识"
L["The Arcway: Opening the Arcway"] = "魔法回廊：打开魔法回廊"
L["The Argent Vanguard is the last friendly ground at the southern edge of Icecrown. Crusade Commander Entari drills the new arrivals into shape. Father Gustav's engineers run the fleshbeast bombardier; Siegemaster Fezzik's jumpbot waits for one more idiot willing to take the breach. Past the tent line, the ground sours into the Valley of Echoes — and past that, Crusaders' Pinnacle, where Tirion Fordring means to draw a line the Scourge cannot cross."] = "银色前线基地是冰冠冰川南缘最后一片友方阵地。北伐军指挥官恩塔里将新来的士兵操练成型。古斯塔夫神父的工程师们操纵着血肉轰炸兽；攻城大师菲斯克的跳跃机器人还在等待下一个愿意冲向缺口的傻瓜。越过营帐区，地面逐渐腐坏，化为回音谷——再往前，便是北伐军之峰，提里奥·弗丁打算在那里划下一道天灾军团无法逾越的防线。"
L["The Art of Being a Water Terror"] = "恐怖之水"
L["The Art of Flow"] = "上善若水"
L["The Art of War"] = "战争的艺术"
L["The Ashbringer"] = "灰烬使者"
L["The Authority of Revendreth"] = "雷文德斯的掌权者"
L["The Banshee Queen"] = "女妖之王"
L["The Battle for Broken Shore"] = "破碎海滩之战"
L["The Battle For Crusaders' Pinnacle"] = "北伐军之峰的战斗"
L["The Battle for Lordaeron"] = "洛丹伦之战"
L["The Battle of Bloodfire Ravine"] = "血火峡谷之战"
L["The Battle of Dazar'alor"] = "达萨罗之战"
L["The Battlelord's Campaign"] = "战争领主的战役"
L["The Bees' Knees"] = "上等虫腿"
L["The Best and Brightest"] = "聪明加能干"
L["The Big Bad Wolfe"] = "大坏蛋沃尔菲"
L["The Blessing of the Ancestors"] = "先祖祝福"
L["The Blessing of the Clan"] = "氏族祝福"
L["The Blessing of the Land"] = "大地祝福"
L["The Blight Congress"] = "凋零会议"
L["The Blood of Demons"] = "恶魔血液"
L["The Bloody Truth"] = "血淋淋的真相"
L["The Bone Witch"] = "白骨女巫"
L["The Boon of A'dal"] = "阿达尔的恩赐"
L["The Boon of Alexstrasza"] = "阿莱克丝塔萨的恩赐"
L["The Boon of Remulos"] = "雷姆洛斯的恩赐"
L["The Brand of Damnation"] = "诅咒烙印"
L["The Bridgeport Ride"] = "桥港之旅"
L["The Broken Front"] = "破碎前线"
L["The Broken Shore"] = "破碎海滩"
L["The Broken Shore brought an unwelcome ally — Magatha Grimtotem, the elder crone who had murdered Cairne Bloodhoof. She demanded a place in the Earthen Ring in exchange for her considerable power, and the elements themselves seemed to agree. You worked alongside her through gritted teeth, breaking chains and quelling snakes, while Nobundo led the main assault. Firelord Smolderon's offense scorched the Legion's fortifications, and when the calm came after the storm, Consular Celestos summoned you to a gathering of storms — where a tempest given form became your mount, the Farseer's Raging Tempest."] = "破碎海滩带来了一位不受欢迎的盟友——玛加萨·恐怖图腾，那个谋害了凯恩·血蹄的老巫婆。她以自己可观的力量为筹码，要求在大地之环中占有一席之地，而元素们似乎也认可了这一点。你咬紧牙关与她共事，挣断锁链、平息蛇患，努波顿则率领主力发起进攻。炎魔领主斯莫德隆的攻势烧毁了军团的防御工事。当风暴过后归于平静时，赛莱托斯大使召你参加一场风暴集会——在那里，一场化为实体的暴风成了你的坐骑：先知的狂暴风暴。"
L["The Broken Shore burned with felfire, and Odyn sent you to lead the Valarjar into the heart of the assault. You recruited new forces, armed them for the battles ahead, and ventured into Helheim itself to recover stolen souls and claim Helya's own horn as a trophy. When Kvaldir raiders answered your call and the last of the missing champions returned, Odyn summoned you for one final trial — the Trial of Rage. You emerged victorious, and a bloodthirsty war wyrm knelt before its new master."] = "破碎海滩燃烧着邪能之火，奥丁派你率领瓦拉加尔直捣进攻的核心。你招募新的部队，为即将到来的战斗武装他们，还深入冥狱深渊，夺回被窃取的灵魂，并将海拉自己的号角作为战利品带回。当克瓦迪尔掠夺者响应你的号召、最后一批失踪的勇士也已归来时，奥丁召你接受最后一场试炼——狂怒试炼。你凯旋而归，一条嗜血的战龙跪伏在它的新主人面前。"
L["The Broken Shore called, and the Ebon Blade answered. Minerva Ravensorrow joined as your newest champion, harnessing power from the very demons you slew. You led an expedition to the Peak of Bones where an army of undead rose at your command, fought alongside Thorim's flame, and defeated the Bonemother. On Daumyr's wings you soared above the battlefield, and when the final ride came, you claimed the Vilebrood Vanquisher — a frost wyrm that knelt before the Deathlord."] = "破碎海滩发出召唤，黑锋骑士团给予了回应。米妮瓦·悲鸦作为你最新的勇士加入，她能驾驭你所斩杀的恶魔身上的力量。你率领远征队前往白骨之巅，一支亡灵大军在那里应你的号令而起；你与托里姆之焰并肩作战，击败了骨母。你乘着多米尔之翼翱翔于战场之上，而当最后的骑行到来时，你获得了邪巢征服者——一头跪伏在死亡领主面前的冰霜巨龙。"
L["The Broken Shore demanded the Dreamgrove's strength. Thisalee Crow, fierce and fearless, joined your cause as the war escalated. Rensar Greathoof channeled the Dreamgrove's power to aid the Legionfall assault, granting you the ability to call upon nature even in the most fel-scarred land. When the battle was won, Thisalee brought word of Aviana under attack — you rushed to defend the mother of flight and earned the Lunarwing form, soaring above the world as only an Archdruid could."] = "破碎海滩需要梦境林地的力量。勇猛无畏的希萨莉·黑鸦在战事升级之际加入了你的事业。伦萨·巨蹄引导梦境林地的力量援助军团陷落的攻势，让你即便在被邪能玷污最深的土地上也能召唤自然之力。战斗胜利后，希萨莉带来了艾维娜遭到攻击的消息——你急忙赶去保卫这位飞翔之母，并获得了月翼形态，以只有大德鲁伊才能做到的方式翱翔于世界之上。"
L["The Broken Shore demanded the Tirisgarde's full power. Aethas Sunreaver, once exiled from Dalaran, returned to lead the mage offensive. You uncovered a nightborne workshop hidden on the Shore, secured its secrets, and armed Dalaran's defenses against a Legion counterattack. When the dust settled, Khadgar entrusted you with one final task — recovering the legendary Discs of Norgannon. From their power, the Archmage's Prismatic Disc was forged — a flying platform that shifted between arcane, fire, and frost as you willed it."] = "破碎海滩需要提瑞斯法守望者倾尽全力。曾被逐出达拉然的艾萨斯·夺日者回归，领导法师们的攻势。你在海滩上发现了一座隐秘的夜之子工坊，获取了其中的秘密，并加强了达拉然的防御以抵御军团的反击。尘埃落定后，卡德加托付给你最后一项任务——寻回传说中的诺甘农圆盘。大法师的棱彩圆盘便由它们的力量锻造而成——这座飞行平台能随你的心意在奥术、火焰与冰霜之间变换。"
L["The Broken Shore held a prisoner the Council had long sought — Kanrethad Ebonlocke, the warlock who had tried to bind a pit lord and paid the price with his freedom. Shinfel and Jubeka led the search while you culled the Legion cult guarding him and contained the fel crystals keeping him sealed. Kanrethad was freed, scarred but unbroken, and joined as your newest champion. Then came the final rite — Mor'zul Bloodbringer opened a portal to Xoroth, where a wrathsteed of chaotic fire waited. You broke its will and bent it to yours, and the Netherlord's Chaotic Wrathsteed carried you from the flames."] = "破碎海滩关押着一名议会寻找已久的囚犯——坎雷萨德·埃伯洛克，这位术士曾试图束缚一名深渊领主，并为此付出了失去自由的代价。辛菲儿和裘碧卡负责搜寻，你则清剿了看守他的军团教派，并控制住将他封印的邪能水晶。坎雷萨德获救了，虽伤痕累累却未被击垮，并成为你最新的勇士。随后是最后的仪式——莫苏尔·召血者打开了通往克索诺斯的传送门，一匹燃烧着混沌之火的愤怒战马正在那里等待。你击溃了它的意志，令它屈从于你，虚空领主的混沌愤怒战马载着你冲出了烈焰。"
L["The Broken Shore was a rout. The Horde threw everything at the Legion's landing force and bled for it. Vol'jin took a wound that no healer could close. By the time the retreat was called, he was dying. He summoned Sylvanas, told her the loa had whispered her name, and asked her to lead. She stood there for a moment — the Dark Lady of the Forsaken, who had never wanted anything to do with the Horde's politics — and said yes. She walked out of that room as Warchief. Nobody, including her, fully understood what that meant yet."] = "破碎海滩是一场溃败。部落倾尽全力攻击军团的登陆部队，并为此血流成河。沃金受了一道任何治疗者都无法愈合的伤。等到撤退命令下达时，他已奄奄一息。他召来希尔瓦娜斯，告诉她洛阿低语了她的名字，并请求她来领导部落。她在那里站了片刻——这位被遗忘者的黑暗女王，从来都不想与部落的政治有任何瓜葛——然后答应了。她走出那个房间时，已是部落酋长。包括她自己在内，当时还没有人完全明白这意味着什么。"
L["The Broken Shore was crawling with demons, and Kor'vas coordinated the Illidari's assault from the Fel Hammer itself. When the Legion counterattacked, you defended the ship in a desperate battle above the battlefield. Lady S'theno, a naga exile who had fought demons for millennia, joined your cause after you restored balance to the Broken Shore's ley lines. When the war was won, a felbat — the Felbroken Shrieker — recognized you as its master, and the Slayer took to the skies."] = "破碎海滩上恶魔横行，考瓦斯在邪能之槌号上统筹伊利达雷的进攻。当军团发起反击时，你在战场上空的一场殊死战斗中保卫了这艘飞船。赛丝诺女士是一位与恶魔战斗了上千年的纳迦流亡者，在你恢复了破碎海滩魔网的平衡之后，她加入了你的事业。战争胜利后，一只邪蝠——邪碎尖啸者——认你为主，屠魔者从此翱翔天际。"
L["The Bulk of the Guard"] = "大批守卫"
L["The Burden of Proof"] = "举证责任"
L["The Call of Battle"] = "战斗的召唤"
L["The Call of Icecrown"] = "冰冠的召唤"
L["The Call to War"] = "战争的召唤"
L["The Calm After the Storm"] = "风暴后的宁静"
L["The Campaign Begins"] = "反击开始"
L["The campaign pushes into the ruins of Gilneas. A traitor needs to be dealt with, and the Gilneas Liberation Front is running out of room to maneuver."] = "战役推进到吉尔尼斯的废墟。有个叛徒需要处理，而吉尔尼斯解放阵线的回旋余地也越来越小。"
L["The Captive Spymaster"] = "被关押的间谍大师"
L["The Chain Gun And You"] = "重机枪与你"
L["The Champion's Return"] = "勇士归来"
L["The citadel's gates are not for hammering. Sergeant Stackhammer knows it. Sergeant Kregga knows it. The Alliance and Horde sappers have quieter work — crawl into the saronite pits beneath Sindragosa's Fall and set the charges that will shake the foundations from below. Before the pits go up, a voice begins to whisper out of the saronite dark. Whoever he is, he knows a name. He wants it spoken. He wants you to come back when the dust settles and hear the rest of his story at the First Legion Forward Camp."] = "堡垒的大门不是靠锤子砸开的。斯塔克哈默中士明白这一点。克蕾迦中士也明白。联盟和部落的工兵们有更安静的活要干——爬进辛达苟萨之墓下方的萨隆邪铁矿坑，安放炸药，从下方撼动根基。在矿坑被炸毁之前，一个声音开始从萨隆邪铁的黑暗中低语。不管他是谁，他知道一个名字。他想让这个名字被说出来。他希望你在尘埃落定后回到第一军团前线营地，听完他剩下的故事。"
L["The clans gathered once more, and old ways found new meaning. Through trials of land, clan, and ancestors, you helped the orcs reclaim identity not as they were, but as they choose to be now."] = "各氏族再度齐聚，古老的传统焕发出新的意义。通过大地、氏族与先祖的试炼，你帮助兽人重拾自我——不是他们过去的样子，而是他们如今选择成为的样子。"
L["The Clarion Call"] = "号角之召"
L["The Clessington Will"] = "克莱辛顿的意志"
L["The Codex of Command"] = "命令法典"
L["The Coming Storm"] = "风雨欲来"
L["The Conclave was united — Light and Shadow standing together for the first time. The final test came on Niskara, a Legion prison world where priests and paladins alike were held captive. With Aponi Brightmane and Lord Maxwell Tyrosus lending their strength, you crossed Legion lines and broke the chains. United as one, the Conclave shattered the demon garrison. Alonsus Faol himself pledged as your champion, and Moira Thaurissan forged your weapon anew. You were named High Priest of Netherlight — a title that carried the weight of every faith you had united."] = "秘密议会团结起来——圣光与暗影第一次并肩而立。最后的考验在尼斯卡拉到来，那是一个军团监牢世界，牧师和圣骑士都被囚禁于此。在奥伯妮·亮鬃和玛克斯韦尔·泰罗索斯男爵的助力下，你穿越军团的防线，打碎了枷锁。团结一致的秘密议会击溃了恶魔驻军。阿隆索斯·法奥亲自宣誓成为你的勇士，茉艾拉·索瑞森重新锻造了你的武器。你被授予虚空之光大祭司的称号——这个头衔承载着你所团结的每一种信仰的分量。"
L["The Cost of War"] = "战争的代价"
L["The Council convened to address Archmage Vargoth's disappearance. Khadgar led you to Vargoth's retreat, where the signs of struggle told a grim story. Following in his footsteps, you traced magical residue across the Broken Isles. Kalec's investigation revealed the truth was worse than anyone feared — Vargoth hadn't simply vanished. Something had taken him, and that something was connected to the dreadlord Kathra'natir."] = "议会召开会议，商讨大法师瓦格斯失踪一事。卡德加带你来到瓦格斯的居所，那里的搏斗痕迹讲述着一个阴暗的故事。你追寻他的足迹，在破碎群岛各地追踪魔法残留。卡雷的调查揭示出比任何人担心的都更糟的真相——瓦格斯并不是简单地失踪了。有什么东西带走了他，而那东西与恐惧魔王卡斯拉纳提尔有关。"
L["The Council is in Session"] = "要事会谈"
L["The Council needed more power — souls to fuel the Dreadscar Rift's defenses. You retrieved an unclaimed soul from Black Rook Hold, built a soul beacon to gather energy, and recruited Ernest Carlisle — a mad alchemist who turned goat herding into an art form. Shinfel Blightsworn and Kira Iresoul earned their champion marks, and the Council debated who among them was truly worthy of the power they wielded. The Vault of the Wardens provided the answer: power belonged to those who could take it and hold it."] = "议会需要更多的力量——需要灵魂来为恐痕裂隙的防御提供能量。你从黑鸦堡垒取回了一个无主的灵魂，建造了一座灵魂信标来聚集能量，还招募了欧内斯特·卡莱尔——一个把放山羊变成了艺术的疯狂炼金术士。辛菲儿·疫誓和奇拉·艾索尔赢得了勇士的标记，议会则争论着他们之中谁才真正配得上自己所掌握的力量。守望者地窟给出了答案：力量属于那些能够夺取并守住它的人。"
L["The Council's sixth seat remained contested — and the answer lay with Lulubelle Fizzlebang, a gnome warlock with more ambition than common sense. You found her in Stormheim, coerced a confession from a captured demon, and cleaned up someone else's mess along the way. Lulubelle proved her worth through sheer stubborn brilliance, and the Summoning of the Sisters sealed the pact. With all six members chosen and your weapon forged to its full dark potential, the Council of the Black Harvest was complete. You were named Netherlord."] = "议会的第六个席位仍有争议——而答案就在露露贝拉·菲兹班身上，一个野心远大于常识的侏儒术士。你在风暴峡湾找到了她，从一个被俘的恶魔口中逼出了供词，顺便还收拾了别人留下的烂摊子。露露贝拉凭着一股纯粹的倔强和才华证明了自己的价值，而姐妹召唤仪式则为这份契约盖上了封印。六名成员全部选定，你的武器也被锻造至其黑暗潜能的极致，黑暗收割议会终于完整。你被授予虚空领主之名。"
L["The Crimsonwood was the Drust king's domain — a forest so thick with dark magic that the trees themselves attacked. You saved Master Ashton from the thorns, gathered what you needed from the cursed woods, and went deeper. Inquisitor Cleardawn never flinched as you faced the matrons of the Crimsonwood one by one. At the heart of it all stood Gorak Tul's hall, where the grand rite would have brought the Drust back in full force. You stopped it — barely — and stuck the embers into the heart of his power. Gorak Tul retreated, wounded but not destroyed. Lucille was waiting."] = "赤红林是德鲁斯特之王的领地——这片森林中的黑暗魔法浓重到连树木本身都会发起攻击。你从荆棘中救出了阿什顿大师，在受诅咒的树林中收集了所需之物，然后继续深入。当你逐一面对赤红林的女巫首领时，审判官克利多恩从未退缩。在这一切的核心矗立着高莱克·图尔的大厅，那里进行的宏大仪式本将让德鲁斯特全面回归。你阻止了它——险之又险——并将余烬刺入了他力量的核心。高莱克·图尔撤退了，身负重伤，却未被消灭。露希尔正在等待。"
L["The Crusaders' Pinnacle"] = "北伐军之峰"
L["The Crux of the Plan"] = "展望未来"
L["The Crypt Keeper"] = "守墓人"
L["The Culling of Stratholme"] = "净化斯坦索姆"
L["The Curse of Fletcher's Hollow"] = "箭谷镇的诅咒"
L["The Dark Heart of Nazmir"] = "纳兹米尔的黑暗之心"
L["The Dark Iron legacy is forged, not inherited. By proving your worth in brawls, smithing, and service, you helped secure the clan's heritage for a new era."] = "黑铁的传承是锻造出来的，而非继承而来。通过在斗殴、锻造和效力中证明自己的价值，你帮助氏族在新时代守住了自己的传承。"
L["The Dark Lady Calls"] = "黑暗女王的召唤"
L["The Darkness Within"] = "掘地三尺"
L["The Darkspear were pulled toward old fears and dark power, but chose another path. By restoring their ties to Kevo ya Siti, Lukou, and Jani, you helped your people remember who they are and what they stand for."] = "暗矛部族曾被古老的恐惧与黑暗力量所牵引，但他们选择了另一条路。通过恢复与希蒂-柯沃、露可和加尼的联系，你帮助你的族人记起了他们是谁、他们为何而立。"
L["The Dawning Light"] = "曙光"
L["The Day Hope Died"] = "希望泯灭之日"
L["The Dead and the Damned"] = "死亡与诅咒"
L["The Deathlord's Campaign"] = "死亡领主的战役"
L["The Defense of Tian Monastery"] = "保卫天禅院"
L["The Delicate Art of Telemancy"] = "精妙的传送艺术"
L["The Demi-God's Return"] = "半神的回归"
L["The Desolate Council"] = "荒芜议会"
L["The Double Hozen Dare"] = "胆比猢狲大"
L["The draenei's strength comes from memory, faith, and resilience. By sharing burdens old and new, you helped your people move forward without forgetting what they endured."] = "德莱尼人的力量源自记忆、信仰与坚韧。通过分担新旧重担，你帮助你的族人向前迈进，同时不忘他们所经历的苦难。"
L["The Dragonblight Campaign"] = "龙骨荒野战役"
L["The Dreadblades"] = "恐惧之刃"
L["The dreadlord has been hiding among your allies all along. The hunt ends on the Broken Shore in a final confrontation."] = "恐惧魔王一直藏身于你的盟友之中。这场猎杀行动将在破碎海滩的最终对决中画上句号。"
L["The dreadlord Kathra'natir had been one step ahead all along — and his final move was possessing Meryl Felstorm himself. With the Tirisgarde's founder corrupted from within, Khadgar rallied every resource: a magical affliction cured in the Eye of Azshara, the might of the Tirisgarde focused into a single strike. You stormed the Oculus and faced Kathra'natir in Meryl's body, tearing the demon free without destroying the mage. Meryl stood free, Vargoth was rescued, and your weapon was reforged. The Kirin Tor bestowed upon you the title of Archmage."] = "恐惧魔王卡斯拉纳提尔始终领先一步——而他的最后一招，是附身于梅瑞尔·邪风本人。提瑞斯法守望者的创始人从内部被腐化，卡德加调动了一切资源：在艾萨拉之眼治愈一种魔法顽疾，并将提瑞斯法守望者的力量汇聚成一击。你攻入魔环，与占据梅瑞尔身体的卡斯拉纳提尔对峙，在不伤及这位法师的情况下将恶魔从他体内剥离。梅瑞尔重获自由，瓦格斯获救，你的武器也得以重铸。肯瑞托授予你大法师的称号。"
L["The Dreadlord's Prize"] = "恐惧魔王的战利品"
L["The Dreamgrove"] = "梦境林地"
L["The Dreamgrove / Broken Isles"] = "梦境林地 / 破碎群岛"
L["The Dreamgrove needed defenders. Rensar Greathoof tasked you with growing the order's power — recruiting champions to stand at your side and training troops drawn from every corner of Azeroth's wilds. Skylord Omnuron opened new paths through the Dreamway, connecting the Dreamgrove to the wider world. With each branch that grew, the sanctuary's roots dug deeper."] = "梦境林地需要守护者。伦萨·巨蹄交给你壮大教派力量的任务——招募勇士与你并肩作战，并训练来自艾泽拉斯荒野各个角落的部队。啸天者欧穆隆开辟了穿越梦境之路的新通道，将梦境林地与更广阔的世界相连。每长出一根新枝，这座圣所的根便扎得更深一分。"
L["The Dreamway"] = "梦境之路"
L["The Duke"] = "公爵"
L["The Ebon Watcher"] = "黑锋观察者"
L["The Elder's Instruments"] = "长老的道具"
L["The Elements Call..."] = "元素的召唤"
L["The Emerald Nightmare"] = "翡翠梦魇"
L["The Emerald Nightmare spreads unchecked. Naralex leads you into the corrupted wilds to find the Idol of the Wilds before the Nightmare claims it."] = "翡翠梦魇肆无忌惮地蔓延。纳拉雷克斯带你深入被腐化的荒野，抢在梦魇之前找到荒野神像。"
L["The Emperor's Gift"] = "皇帝的礼物"
L["The Empyrean Society"] = "天穹学会"
L["The Enemy of My Enemy..."] = "我敌人的敌人……"
L["The Eve of Battle"] = "战争前夕"
L["The Eye of Odyn"] = "奥丁之眼"
L["The faction war reaches the Serpent's Heart, shatters the seal, and releases the Sha of Doubt."] = "阵营战争蔓延至神龙之心，封印被打碎，疑之煞随之释放。"
L["The Fall of Ga'trul"] = "消灭加图尔"
L["The Fall of the Sunwell"] = "太阳井之殇"
L["The Fall of Zuldazar"] = "祖达萨沦陷"
L["The Fangs of Ashamane"] = "阿莎曼之牙"
L["The Fangs of Ashamane — twin daggers blessed by the wild god of the hunt — had been lost in the wilds of Val'sharah. You tracked them through ancient feral grounds, facing guardians left by Ashamane herself. When you grasped the Fangs, the spirit of the great cat surged through you, and the wilds themselves seemed to sharpen around your senses."] = "阿莎曼之牙——一对受到狩猎野性之神祝福的双匕首——遗失在了瓦尔莎拉的荒野中。你穿过古老的野性之地追踪它们的下落，面对阿莎曼亲自留下的守护者。当你握住阿莎曼之牙时，这只巨猫的灵魂涌遍你的全身，周围的荒野仿佛都在你的感官中变得愈发鲜明。"
L["The Farseer's Campaign"] = "先知的战役"
L["The Fate of Bloodbane"] = "血毒的命运"
L["The Fate of Hodir"] = "霍迪尔的命运"
L["The Fate of Kanrethad"] = "坎雷萨德的命运"
L["The Fate of Saurfang"] = "萨鲁法尔的命运"
L["The Fate of Sylvanas"] = "希尔瓦娜斯的命运"
L["The Fearstalker"] = "猎惧者"
L["The Fel Hammer / Broken Isles"] = "邪能之槌号 / 破碎群岛"
L["The Fel Hammer needed to become more than a ship — it needed to become an army. Battlelord Gaardoun helped recruit champions while Kor'vas organized the broken warriors scattered across the Broken Isles. You proved your immortal soul was strong enough to lead, and the Illidari acknowledged you as their commander. The demon hunters were no longer scattered outcasts — they were a blade pointed at the Legion's heart."] = "邪能之槌号需要成为的不只是一艘战舰——它需要成为一支军队。战争领主加尔顿协助招募勇士，考瓦斯则召集散落在破碎群岛各地的残兵。你证明了自己不朽的灵魂足够强大，足以担当领袖，伊利达雷也承认你是他们的指挥官。恶魔猎手们不再是四散的流亡者——他们已成为一柄直指军团心脏的利刃。"
L["The Felsoul Experiments"] = "邪魂实验"
L["The final assault on Grand Ma'da Ateena. The Horde, the loa, and a death god march together into the Blood Gate. G'huun waits beneath."] = "向长母阿提娜发起最终进攻。部落、洛阿与一位死神并肩攻入鲜血关口。戈霍恩在下方等待。"
L["The Final Blow!"] = "致命一击！"
L["The final breach. You entered the Nighthold itself, fighting through the last of Elisande's loyalists to reach the seat of her power. When the Grand Magistrix fell and the Nightwell's corrupting influence was severed, Thalyssra stepped forward to lead her people into a new era. The nightfallen were nightborne once more — free to choose their own fate."] = "最后的突破。你攻入暗夜要塞，杀穿艾利桑德最后的效忠者，抵达她的权力宝座。当大魔导师倒下、暗夜井的腐化影响被切断时，塔莉萨挺身而出，带领她的人民走向新的时代。堕夜精灵再次成为了夜之子——可以自由选择自己的命运。"
L["The final campaign began with demonic runes appearing across the Broken Isles — the Legion was closing in. You deciphered their meaning in Black Rook Hold, captured a Legion gateway, and stormed Niskara to rescue Hodir, imprisoned by demons since the war began. With every titan keeper free and every rune decoded, Odyn forged your weapon anew and declared you Battlelord of the Valarjar — a title not bestowed in ten thousand years."] = "最后的战役始于破碎群岛各地出现的恶魔符文——军团正在步步逼近。你在黑鸦堡垒破译了符文的含义，夺取了一座军团传送门，并突袭尼斯卡拉，营救自战争开始以来便被恶魔囚禁的霍迪尔。随着所有泰坦守护者获得自由、所有符文被破译，奥丁重新锻造了你的武器，并宣布你为瓦拉加尔的战争领主——这个头衔已有一万年未曾授予他人。"
L["The Final Effigy"] = "最后的雕像"
L["The final Horseman must be raised from the most sacred ground in Azeroth. Darion Mograine makes the ultimate sacrifice."] = "最后一位骑士必须从艾泽拉斯最神圣的土地上唤起。达里安·莫格莱尼做出了终极的牺牲。"
L["The final hunt led to the Broken Shore, where a dreadlord had been hiding among your allies in plain sight. With Lilian Voss at your side, you set the trap — false orders, planted evidence, and a trail that led the demon straight into your blade. The Uncrowned had done what armies could not: killed a devil wearing a friend's face."] = "最后的猎杀将你引向破碎海滩，一名恐惧魔王一直明目张胆地藏身于你的盟友之中。在莉莉安·沃斯的协助下，你设下陷阱——伪造的命令、栽赃的证据，以及一条将恶魔直接引向你刀锋的线索。无冕者做到了军队都做不到的事：杀死了一个披着朋友面孔的恶魔。"
L["The Final Shadow"] = "最后一席"
L["The final test. Decipher demonic runes, rescue Hodir from a Legion prison world, and prove yourself worthy of the Battlelord title."] = "最后的考验。破译恶魔符文，从军团监牢世界中救出霍迪尔，证明你配得上战争领主的称号。"
L["The Firelord's Command"] = "炎魔之命"
L["The Firelord's Offense"] = "炎魔之王的攻势"
L["The First Assault"] = "第一次进攻"
L["The First to Fall"] = "第一滴血"
L["The First Watch"] = "第一座塔楼"
L["The Firstborn Rises"] = "勇士复生"
L["The Fist of Ra-den"] = "莱登之拳"
L["The Flesh Giant Champion"] = "最强大的血肉巨人"
L["The Flight of the Banshee"] = "女妖之翱"
L["The Fog of War"] = "战场迷雾"
L["The Forest Ward revealed Revendreth at its most predatory. The Fearstalker and his hounds called it penance: let condemned souls glimpse escape, then chase them until pride broke under terror. You learned the ritual, stalked the quarry, and watched the Accuser's doubts harden into rebellion. The hunt was supposed to humble sinners, but it had become sport for nobles who fed on fear. By the time you reached Dredhollow and broke the Hopebreakers, the shape of the war was clear. This was not order against chaos. It was cruelty against the last pieces of Revendreth still trying to remember mercy."] = "森林区展现了雷文德斯最具掠夺性的一面。猎惧者和他的猎犬称之为赎罪：让被定罪的灵魂瞥见逃脱的希望，然后追捕他们，直到他们的傲慢在恐惧下崩溃。你学会了这项仪式，追踪猎物，并目睹指控者的疑虑逐渐坚定为反叛。这场猎杀行动本该让罪人谦卑，却已沦为以恐惧为食的贵族们的消遣。当你抵达惧谷镇并击败碎望者时，这场战争的面目已经清晰。这不是秩序对抗混乱。这是残暴对抗雷文德斯中仍在努力记住怜悯的最后残片。"
L["The Forlorn Soul"] = "被遗弃的灵魂"
L["The Forsaken are marching on Silverpine Forest. Warchief Garrosh Hellscream has heard what Sylvanas is doing to grow their numbers — and he is not pleased."] = "被遗忘者正向银松森林进军。酋长加尔鲁什·地狱咆哮已经听说了希尔瓦娜斯为扩充人数所做的事——他很不高兴。"
L["The Forsaken Blight"] = "被遗忘者的凋零药剂"
L["The Forsaken Blight and You: How Not to Die"] = "凋零药剂与你：如何自保"
L["The Forsaken Daughter"] = "被遗忘者之女"
L["The Forsaken High Command was busy when Garrosh Hellscream showed up with a grievance. He'd heard what Sylvanas was doing — using the Val'kyr to raise human dead as new Forsaken, growing her forces beyond what the Horde had sanctioned. He told her to stop. She asked him, face to face, what the difference was between her and the Lich King. He didn't have a good answer. The campaign continued."] = "加尔鲁什·地狱咆哮带着不满找上门时，被遗忘者统帅部正忙得不可开交。他听说了希尔瓦娜斯的所作所为——利用瓦格里将人类死者复活为新的被遗忘者，令她的军力超出了部落认可的范围。他命令她住手。她当面问他，她和巫妖王之间有什么区别。他答不上来。战役仍在继续。"
L["The Forsaken moved on. Lordaeron was theirs again, and the long war had its accounting. But some loyalties don't dissolve with a verdict. Dori'thur arrived in the ruins of Lordaeron bearing a message — not from a queen, not a command, just acknowledgment. The hunt Sylvanas began in death has no end date. The souls in the Maw number in the countless. She is still there, freeing them one by one. The message asked nothing. It only said: she remembers who stood with her."] = "被遗忘者继续前行。洛丹伦再度归他们所有，漫长的战争也有了清算。但有些忠诚不会因一纸裁决而消散。多莉苏尔来到洛丹伦的废墟，带来了一条讯息——不是来自一位女王，也不是一道命令，只是一份认可。希尔瓦娜斯在死亡中开始的猎杀行动没有终点。噬渊中的灵魂多到无法计数。她仍在那里，一个接一个地解救他们。这条讯息别无所求。它只是说：她记得谁曾与她并肩而立。"
L["The Forsaken Plague"] = "被遗忘者瘟疫"
L["The Forsaken push into the farmlands of Tirisfal, where the Scarlet Crusade holds a fortified palisade. Someone from Deathknell has gone missing."] = "被遗忘者推进到提瑞斯法的农田，血色十字军在那里据守着一座设防的栅栏营地。丧钟镇有人失踪了。"
L["The Four Tomes"] = "四部古籍"
L["The Fourth Horseman"] = "第四骑士"
L["The Frozen Halls"] = "冰封大殿"
L["The Frozen Throne"] = "冰封王座"
L["The Fruit of Our Efforts"] = "工作成果"
L["The Gilneas Liberation Front"] = "吉尔尼斯解放阵线"
L["The Gjallarhorn"] = "迦拉尔之角"
L["The Gjallarhorn — the horn that calls the worthy to battle — has been stolen. Hunt down the thieves across Stormheim and reclaim it."] = "迦拉尔之角——召唤勇者奔赴战场的号角——失窃了。在风暴峡湾追捕窃贼，夺回号角。"
L["The Gnome Behind the Trogg"] = "穴居人背后的侏儒"
L["The Gondolier"] = "贡多拉船娘"
L["The Grandmaster's Campaign"] = "大宗师的战役"
L["The graveyards of Drustvar hold fallen Kul Tiran war heroes — soldiers too valuable to leave buried. Nathanos leads the expedition to unearth Marshal M. Valentine, while Lilian questions what separates the Horde's methods from the horrors she once suffered at the hands of the Scarlet Crusade."] = "德鲁斯瓦的墓地中埋葬着阵亡的库尔提拉斯战争英雄——这些士兵太有价值，不能让他们长眠地下。纳萨诺斯率领远征队去挖掘M·瓦伦丁元帅的遗体，而莉莉安则开始质疑，部落的手段与她当年在血色十字军手中遭受的恐怖究竟有何区别。"
L["The Great Akazamzarak"] = "伟大的阿卡扎曼扎拉克"
L["The Great Banquet"] = "盛大的宴会"
L["The Great Escape"] = "胜利大逃亡"
L["The Great Stonemother"] = "伟大的石母"
L["The Greatest Duelist"] = "最伟大的决斗者"
L["The Grove of Terror"] = "恐惧林地"
L["The Guardians of Corp'rethar"] = "科雷萨的守卫者"
L["The Hand of Keletress"] = "凯丽翠丝之手"
L["The Heart of the Dreadscar"] = "恐痕之心"
L["The Hidden City"] = "隐藏的城市"
L["The Hidden Need"] = "隐藏的需求"
L["The High Elder"] = "拜会长老"
L["The High Overlord"] = "萨鲁法尔大王"
L["The High Priest's Campaign"] = "大祭司的战役"
L["The Highlord's Campaign"] = "大领主的战役"
L["The Hooded Crusader's campaign reached the Scarlet Monastery itself. You retrieved the blessed blades of the Anointed — weapons consecrated to destroy the undead — and drove them into High Inquisitor Whitemane. The irony was not lost on Lilian: the Crusade's holiest weapons, wielded by the dead, against the Crusade's own champion."] = "蒙面的十字军战士的战役推进到了血色修道院。你取回了受膏者的祝福之刃——专为毁灭亡灵而祝圣的武器——并将它们刺入了大检察官怀特迈恩的身体。莉莉安深知其中的讽刺：十字军最神圣的武器，被亡者挥舞着，刺向十字军自己的勇士。"
L["The Hooded Crusader's campaign reaches the Scarlet Monastery. Two blessed blades rest within its halls — consecrated weapons anointed to destroy the undead. High Inquisitor Whitemane commands everything inside."] = "蒙面的十字军战士的战役推进到了血色修道院。两把祝福之刃就安放在修道院的大厅中——这些经过祝圣的武器专为毁灭亡灵而生。大检察官怀特迈恩掌控着里面的一切。"
L["The Horde has split in two. Saurfang rallies those who oppose Sylvanas, while loyalists prepare to crush the rebellion."] = "部落已一分为二。萨鲁法尔集结反对希尔瓦娜斯的人，而效忠者们正准备镇压这场叛乱。"
L["The Horde marched into Ashenvale with speed and purpose. You pushed through Night Elf defenses, secured the roads, and drove toward the coast beneath Teldrassil. The Night Elves fought well but the Horde had the numbers and Sylvanas had a plan. The World Tree loomed at the end of it — massive, ancient, and full of civilians who had not escaped in time. Sylvanas stood at its base with the battle won and the tree in reach. A Night Elf prisoner asked what the people inside had done to deserve this. Sylvanas spoke about hope being the enemy. Then she gave the order. Teldrassil burned. The smoke was visible from Stormwind. Whatever Sylvanas had been building toward, this was no longer a war anyone could call limited."] = "部落以迅捷而坚定的步伐挺进灰谷。你突破了暗夜精灵的防线，控制了道路，一路向泰达希尔脚下的海岸推进。暗夜精灵奋勇作战，但部落兵力占优，而希尔瓦娜斯早有谋划。这场进军的尽头，是巍然耸立的世界之树——庞大、古老，树中满是来不及逃离的平民。希尔瓦娜斯站在树下，战斗已胜，巨树近在咫尺。一名暗夜精灵俘虏质问她，树里的人究竟做了什么，竟要落得如此下场。希尔瓦娜斯说，希望才是敌人。随后，她下达了命令。泰达希尔燃起了大火，远在暴风城都能望见浓烟。无论希尔瓦娜斯一直以来在谋划什么，这场战争都已不再是任何人口中的“有限战争”。"
L["The Horde needs a tidesage's power over the sea. Lilian and Rexxar track one down in Stormsong Valley — Thomas Zelling, a dying man willing to trade his humanity for a few more years with his family. When the ritual is done, Lilian must watch Zelling's wife recoil from the husband she no longer recognizes. The scene is painfully familiar."] = "部落需要潮汐贤者驾驭大海的力量。莉莉安和雷克萨在斯托颂谷地找到了一位——托马斯·泽林，一个将死之人，愿意舍弃人性，只为与家人多相守几年。仪式完成后，莉莉安只能眼睁睁看着泽林的妻子惊恐地躲开那个她再也认不出的丈夫。这一幕，她再熟悉不过，也再痛苦不过。"
L["The Horde's banner flies over Agmar's Hammer, driven into the permafrost like a spear into a cold chest. Emissary Brighthoof calls for warriors willing to bind themselves to the Warchief's campaign. Overlord Agmar tolerates no softness — the Scourge presses on every side, and a red-eyed gate on the horizon waits to be broken."] = "部落的旗帜在阿格玛之锤上空飘扬，旗杆扎进永冻土中，犹如长矛刺入冰冷的胸膛。特使艾米萨·闪蹄正在召集愿为大酋长的战役效命的勇士。阿格玛大王容不得半点软弱——天灾军团从四面八方步步紧逼，而地平线上，一座红眼闪烁的大门正等待着被攻破。"
L["The Horde's hozen alliance becomes a proper forward campaign from Grookin Hill."] = "部落与猢狲的结盟，以古鲁金猴山为据点，演变成了一场真正的前线攻势。"
L["The Horde's war at sea claims a significant prize: Derek Proudmoore, son of the Lord Admiral, goes down with his ship in the waters off Kul Tiras. Hobart Grapplehammer equips you with experimental diving gear as Dread-Admiral Tattersail leads the expedition into the deep. What Sylvanas intends to do with the body is not yet spoken aloud — but the silence on the ship ride home says enough."] = "部落的海上战争夺得了一份重大战利品：海军上将之子德里克·普罗德摩尔随舰沉没在库尔提拉斯附近的海域。霍巴特·钩锤为你配备了实验性的潜水装备，亡灵舰长塔特赛尔则率领远征队潜入深海。希尔瓦娜斯打算如何处置这具遗体，眼下还无人明说——但归程船上的沉默已经说明了一切。"
L["The Hunt"] = "猎杀行动"
L["The Hunter and the Prince"] = "猎人与王子"
L["The Hunter of Heroes"] = "英雄猎杀者"
L["The Hunter's Call"] = "猎人的召唤"
L["The Hunter's Gaze"] = "亲自监视"
L["The Huntmaster's Campaign"] = "狩猎大师的战役"
L["The Idol of the Wilds breathed new life into the Dreamgrove. Archdruid Hamuul Runetotem and the irrepressible Mylune pledged themselves as champions, along with the spirited Brightwing. Together you focused the Dreamgrove's energies into its portal, strengthening the connection between the waking world and the Dream. The Cenarion Circle stood united — and the Nightmare would feel its wrath."] = "荒野神像为梦境林地注入了新的生机。大德鲁伊哈缪尔·符文图腾和活力无穷的米露恩，连同朝气蓬勃的光明之翼，都宣誓成为你的勇士。你们一同将梦境林地的能量汇聚到传送门中，强化了现实世界与梦境之间的联系。塞纳里奥议会团结一致——梦魇必将尝到它的怒火。"
L["The Imposter"] = "冒名顶替"
L["The Invasion of Niskara"] = "入侵尼斯卡拉"
L["The Iron Fist"] = "铁拳"
L["The Jade Forest"] = "翡翠林"
L["The Jade Serpent"] = "青龙"
L["The Jade Witch"] = "青玉巫婆"
L["The Jailer was dead. Sylvanas was whole again — every fragment of her soul restored from where she had given it away. She stood in silence with the full weight of what she had done pressing down on her at last. Then she walked. Down the long road through Oribos, past the faces of the people she had condemned, she came before Tyrande Whisperwind — who had more right to judge her than anyone alive or dead. Tyrande spoke her sentence. Sylvanas accepted it without a word of protest. She would spend eternity freeing the souls she had imprisoned in the Maw, sending them through the veil one by one. Not as punishment. As penance, freely chosen."] = "典狱长死了。希尔瓦娜斯重获完整——她曾交出的每一块灵魂碎片都已归位。她默然而立，所作所为的全部重量终于压在了她的身上。然后，她迈开了脚步。她沿着奥利波斯的漫漫长路走去，经过那些被她判下厄运之人的面孔，来到泰兰德·语风面前——无论生者还是死者，没有谁比泰兰德更有资格审判她。泰兰德宣布了判决。希尔瓦娜斯一言不发地接受了。她将用永恒的时间解救那些被她囚禁在噬渊中的灵魂，将他们一个个送过帷幕。这不是惩罚，而是她自愿选择的赎罪。"
L["The Jailer's Defeat"] = "典狱长的败亡"
L["The kaldorei endured calamity without abandoning duty. By hunting corruption in Felwood and standing beside the Wardens, you helped preserve the legacy of Elune's people."] = "卡多雷历经浩劫，却从未放弃职责。你在费伍德森林猎除腐化，与守望者并肩作战，帮助守护了艾露恩子民的传承。"
L["The Keeper's Favor"] = "守护者的帮助"
L["The Keys to Success in Freehold"] = "自由镇成功之匙"
L["The King Rises"] = "国王复生"
L["The King's Command"] = "国王的密令"
L["The Kingslayers"] = "弑君者"
L["The Kor'kron at Wyrmrest"] = "龙眠神殿的库卡隆"
L["The Kor'kron Vanguard!"] = "库卡隆先锋！"
L["The Kosh'harg"] = "克许哈格祭典"
L["The Kul Tiran fleet — decades of Proudmoore naval heritage — is scattered and locked behind four keys held by enemies who have taken root across the nation: pirates in Freehold, corrupt wardens in Tol Dagor, drowned tidesages in the Shrine of the Storm, and Drust witches in Waycrest Manor. The keys must be taken by force. At the end, Priscilla Ashvane makes one final move — and Jaina faces her mother in a square in Boralus, in front of the entire fleet, for the first time since Theramore fell."] = "库尔提拉斯的舰队承载着普罗德摩尔家族数十年的海军传统，如今却七零八落，被四把钥匙封锁，而钥匙掌握在已在这个国家各处扎根的敌人手中：自由镇的海盗、托尔达戈的腐败狱卒、风暴神殿的溺亡潮汐贤者，以及维克雷斯庄园的德鲁斯特女巫。钥匙只能用武力夺取。最后，普里西拉·艾什凡走出了最后一步棋——而吉安娜将在伯拉勒斯的一座广场上，当着整支舰队的面，与她的母亲相见。这是塞拉摩陷落以来的第一次。"
L["The Last Line Of Defense"] = "最后一道防线"
L["The Last Witch Doctor of Krag'wa"] = "卡格瓦最后的巫医"
L["The Leaper"] = "跳跃者"
L["The Legion has established a foothold in Azsuna. Lead the Silver Hand to Faronaar and recruit new champions in battle."] = "燃烧军团已在阿苏纳站稳脚跟。率领白银之手前往法罗纳尔，在战斗中招募新的勇士。"
L["The Legion has landed on the Broken Shore. The Horde answers the call — but this battle will cost far more than anyone expected."] = "燃烧军团已登陆破碎海滩。部落响应了号召——但这场战斗的代价将远超所有人的预料。"
L["The Legion launches a direct assault on Dalaran through the Violet Hold. Rally the Unseen Path's champions for the final defense."] = "燃烧军团穿过紫罗兰监狱，直接进攻达拉然。召集无形之路的勇士，展开最后的防御。"
L["The Legion's grip on Faronaar in Azsuna was tightening. Lord Grayson Shadowbreaker dispatched you to break it. With Vindicator Boros at your side, you cut through demon ranks and destroyed their communication orbs. Justicar Julia Celeste fought with a fury that earned her a place among your champions. The Codex of Command — a Legion tactical manual — was recovered from the battlefield, but its contents were locked behind demonic encryption."] = "军团对阿苏纳法罗纳尔的控制日益收紧。格雷森·沙东布瑞克公爵派你前去打破这一局面。在守备官波鲁斯的协助下，你杀穿了恶魔的阵线，摧毁了它们的通讯宝珠。裁决者朱莉亚·塞雷斯蒂作战时怒火如炽，因此在你的勇士中赢得了一席之地。你从战场上缴获了军团的战术手册《命令法典》，但其内容被恶魔密文所封锁。"
L["The Librarian's Quandary"] = "藏书人的困境"
L["The Lich King commands you to raise the Four Horsemen anew. The first to rise is Nazgrim, the fallen Horde general."] = "巫妖王命令你重新唤起天启四骑士。第一位复生的是陨落的部落将军纳兹戈林。"
L["The Lich King reveals the location of Apocalypse, a runesword that brings death to everything it touches."] = "巫妖王揭示了天启的下落——一把能为所触及的一切带来死亡的符文剑。"
L["The Lich King's reign ends at the Frozen Throne. For Sylvanas, the aftermath is more personal than anyone outside Icecrown will ever know."] = "巫妖王的统治在冰封王座终结。对希尔瓦娜斯而言，这场战后余波意味着什么，冰冠冰川之外无人能够知晓。"
L["The Lich King's voice echoed through Acherus, pointing you toward Apocalypse — a blade of pure death forged in an age of darkness. You followed the trail through Duskwood alongside Revil Kost, hunting the Dark Riders who had stolen the sword. In the depths of Deadwind Pass, you wrested Apocalypse from their skeletal grip. The blade hummed with necrotic power, eager to fulfill the promise of its name."] = "巫妖王的声音回荡在阿彻鲁斯，为你指明了天启的所在——一柄在黑暗年代铸成的纯粹死亡之刃。你与瑞维尔·考斯特一同追踪线索穿过暮色森林，猎杀盗走这把剑的黑暗骑士。在逆风小径深处，你从它们的骷髅之手中夺回了天启。剑身因死灵之力而嗡鸣，渴望兑现它名字中的承诺。"
L["The Light and the Void"] = "圣光与虚空"
L["The Light Below"] = "地底之光"
L["The Light's Wrath"] = "圣光之怒"
L["The Lion's Cage"] = "狮笼"
L["The Loa Trials"] = "神灵的试炼"
L["The Long Hunt"] = "漫漫长猎"
L["The Long Knives"] = "长匕"
L["The Lost Glacier"] = "失落冰川"
L["The Mad Duke"] = "疯狂公爵"
L["The Maelstrom / Broken Isles"] = "大漩涡 / 破碎群岛"
L["The Maelstrom's Air Pillar was failing, and only an elemental lord could restore it. Advisor Sevel tracked the Blessed Blade of the Windseeker — the key to freeing Thunderaan, Prince of Air. You journeyed to Highlord Demitrian, reforged the blade, and climbed to the skies above. There, you recharged the weapon and broke Thunderaan's bonds. The Windlord surged free, his winds howling across the Broken Isles. He swore an oath to the Earthen Ring, and Consular Celestos and Nobundo stood with you as the Air Pillar blazed back to life."] = "大漩涡的风之柱正在衰竭，只有元素领主才能将其恢复。顾问塞维尔追查到了逐风者的祝福之剑——解放风之王子桑德兰的关键。你前去拜见大领主德米提恩，重铸了这把剑，然后攀上高空。你在那里为武器重新充能，打破了桑德兰的束缚。风领主挣脱桎梏，狂风呼啸着席卷破碎群岛。他向大地之环立下誓言，赛莱托斯大使和努波顿站在你身边，见证风之柱重新焕发光芒。"
L["The Maelstrom's Air Pillar weakens. Reforge the Blessed Blade of the Windseeker and return Thunderaan to power."] = "大漩涡的风之柱日渐衰弱。重铸逐风者的祝福之剑，让桑德兰重掌力量。"
L["The March to Nazmir"] = "进军纳兹米尔"
L["The Marshal's Grave"] = "元帅之墓"
L["The Masks We Wear"] = "面具之下"
L["The Master"] = "主宰者"
L["The Master Awaits"] = "主宰者在等待"
L["The Master of Lies"] = "谎言主宰者"
L["The Master of Revendreth"] = "雷文德斯的主宰者"
L["The Master of Swords"] = "剑术大师"
L["The Master's Plan"] = "宗主的计划"
L["The Mead Master"] = "蜜酒大师"
L["The Mech of Death"] = "死亡机械"
