L["The Next Level Has Arrived"] = "打击升级"
L["The Nightborne Apprentice"] = "夜之子学徒"
L["The Nightborne Pact"] = "夜之子"
L["The Nightfallen"] = "堕夜精灵"
L["The Nighthold"] = "暗夜要塞"
L["The Nighthold: Lord of the Shadow Council"] = "暗夜要塞：暗影议会首领"
L["The Nighthold: The Eye of Aman'Thul"] = "暗夜要塞：阿曼苏尔之眼"
L["The Nighthuntress Beckons"] = "暗夜女猎手的召唤"
L["The Old Bear"] = "老熊"
L["The Old Fashioned Way"] = "经典方法"
L["The Old Knight"] = "老迈骑士"
L["The Only Way Out is Through"] = "唯一出路"
L["The Only Way to Travel"] = "旅行的唯一方式"
