L["The Peak of Bones"] = "白骨峰"
L["The Peak of Serenity falls to the Legion. Rally the surviving monks at the Temple of Five Dawns on the Wandering Isle."] = "晴日峰落入燃烧军团之手。前往迷踪岛的五晨寺，召集幸存的武僧。"
L["The Pearlfin Situation"] = "审时度势"
L["The Penitent Hunt"] = "悔悟狩猎"
L["The Perfect Opportunity"] = "完美机会"
L["The Pinnacle is won. Its flagstaff flies the white hand of the Argent Crusade above the whole of southern Icecrown. But at the edge of the Fleshwerks below, Crusader Bridenbrad is dying. The plague has him. Father Gustav cannot let a hero end this way. Keeper Remulos, Alexstrasza the Life-Binder, and A'dal — three ancient powers who still remember the Light — each in turn weigh the cost. Whatever answer comes will come in its own time. Meanwhile, gryphon-riders and wyvern-masters circle the Pinnacle, waiting to lift the next wave of soldiers up to the gunships — the Skybreaker and Orgrim's Hammer — hanging over the northern gates."] = "北伐军之峰已被攻下。旗杆上，银色北伐军的白手旗帜飘扬在整个冰冠冰川南部的上空。但在下方血肉工坊的边缘，北伐军战士布雷登布莱德奄奄一息。瘟疫已侵入他的身体。古斯塔夫神父不忍见一位英雄就此殒命。守护者雷姆洛斯、生命的缚誓者阿莱克丝塔萨与阿达尔——三位仍铭记圣光的古老存在——依次权衡着代价。无论答案是什么，都只会在它该来的时候到来。与此同时，狮鹫骑手和双足飞龙驯手在北伐军之峰上空盘旋，等待着把下一波士兵送上悬停在北方大门上空的炮舰——破天号和奥格瑞姆之锤。"
L["The Pirate's Bay"] = "海盗湾"
L["The Pit of Saron"] = "萨隆矿坑"
L["The Power of Thousands"] = "万千之力"
L["The Power to Survive"] = "生存下去的必要力量"
L["The Power Within"] = "深藏的力量"
L["The Price of Victory"] = "胜利的代价"
L["The Pride of Kul Tiras"] = "库尔提拉斯的骄傲"
L["The Pride of the Sin'dorei"] = "辛多雷的骄傲"
L["The Purging Of Scourgeholme"] = "净化天灾城"
L["The Raven's Eye"] = "渡鸦之眼"
L["The rebellion emerged from hiding and seized the Waning Crescent district in an act of open defiance. You helped Oculeth triangulate and rescue an imprisoned ally put on public display as a warning, then established the first openly rebel-held territory in Suramar City. The Dusk Lily — the rebellion's symbol — flew for the first time where Elisande's banners once hung."] = "反抗军走出藏身之处，公然起事，夺取了残月区。你协助欧库勒斯通过三角定位找到并救出了一名被公开示众、以儆效尤的被俘盟友，随后在苏拉玛城建立了第一块由反抗军公开控制的领地。反抗军的象征——暮色百合——第一次飘扬在曾经悬挂艾利桑德旗帜的地方。"
L["The rebellion grows bolder, establishing a foothold in the Waning Crescent district of Suramar City."] = "反抗军愈发大胆，在苏拉玛城的残月区站稳了脚跟。"
L["The Remedy of Lordaeron"] = "洛丹伦的解药"
L["The Restless Dead"] = "永不安息的亡者"
L["The Return of Twilight"] = "暮光再现"
L["The Rider of Blood"] = "鲜血骑士"
L["The Rider of Frost"] = "冰霜骑士"
L["The Rider of the Unholy"] = "邪恶骑士"
L["The Rider's Bind"] = "骑士的羁绊"
L["The Right Tool For The Job"] = "物尽其用"
L["The Ritual of Tides"] = "潮汐仪式"
L["The Road of Pain"] = "痛苦之路"
L["The Road to Corlain"] = "通往克莱因之路"
L["The Ruined Kingdom"] = "失落王国"
L["The Ruins of Gol Var"] = "戈尔瓦遗迹"
L["The Rumpus"] = "大乱斗"
L["The Runesmiths of Malykriss"] = "玛雷卡里斯的符文锻造师"
L["The Rush'kah"] = "鲁希卡"
L["The saronite mines beneath Ymirheim are not just a supply line. They are something older, colder, and hungrier than any ore vein on Azeroth. The metal whispers. Miners chained to the walls hear their names called by voices they once loved. The Argent Crusade has quiet questions about what prolonged exposure does to a living mind. The answers do not make it out of the tunnels."] = "伊米海姆地下的萨隆邪铁矿井不只是一条补给线。那里潜藏着某种比艾泽拉斯上任何矿脉都更古老、更冰冷、更饥渴的东西。这种金属会低语。被锁在矿壁上的矿工会听见曾经深爱之人的声音在呼唤他们的名字。银色北伐军私下里有些疑问：长期接触这种金属，会对活人的心智造成什么影响。而答案从未走出过这些隧道。"
L["The Scarlet Assault"] = "血色突击"
L["The Scarlet Commander"] = "血色指挥官"
L["The Scarlet Crusade has returned to Silverpine Forest. Lilian Voss needs a champion to go in quietly, earn their trust, and open the way for the Forsaken to strike."] = "血色十字军卷土重来，回到了银松森林。莉莉安·沃斯需要一位勇士悄悄潜入，赢得他们的信任，为被遗忘者的进攻打开道路。"
L["The Scarlet Halls"] = "血色大厅"
L["The Scarlet Massacre"] = "血色屠杀"
L["The Scarlet Monastery"] = "血色修道院"
L["The Scarlet Onslaught — fanatical remnants of the Crusade — were gathering strength, and Faol saw an opportunity. You infiltrated their ranks disguised as an envoy, walking among zealots who would have burned you alive. Deep inside, you found Mariella — a heretic within their own ranks who had seen through the madness. You liberated her fellow apostates and brought Mariella Ward into the Conclave, her faith tempered by hard truth rather than blind fury."] = "血色先锋军——十字军的狂热残部——正在积蓄力量，而法奥从中看到了机会。你伪装成使者混入他们的队伍，行走在那些本会将你活活烧死的狂热分子之间。在深处，你找到了马丽拉——一名身处他们队伍之中的异端，早已看穿了这份疯狂。你解救了她的叛教同伴，并将马丽拉·瓦尔德带入了议会。她的信仰经由残酷的真相淬炼而成，而非出于盲目的狂怒。"
L["The Scarlet Onslaught has buried itself in the black ice of western Icecrown. The fortress is called the Shadow Vault. High Abbot Landgren commands it now. The Ebon Blade's plan is ugly — wear the Scarlet's own colors, pray nobody looks twice, and open every door from the inside. When the Vault falls, Baron Sliver holds court in its upper halls. Vereth the Cunning sketches the roads out in blood. The Lich King's saronite quarries are pried open. Above the Vault, the flying necropolis of Malykriss still hangs, with four riders of the Bloodbane order riding out the apocalypse in miniature: one of the Unholy, one of Frost, one of Blood, and the name that binds them."] = "血色先锋军躲进了冰冠冰川西部的黑冰深处。那座要塞名为暗影拱顶，如今由大修道院长兰德格伦坐镇指挥。黑锋骑士团的计划并不体面——穿上血色先锋军自己的服色，祈祷没人多看一眼，然后从内部打开每一扇门。暗影拱顶陷落后，斯利文男爵在其上层大厅主持事务。狡诈者维雷斯用鲜血勾勒出前路。巫妖王的萨隆邪铁采石场被撬开。拱顶上方，玛雷克里斯浮空城依然悬在空中，血祸骑士团的四名骑手在那里上演着一场缩小版的天启：一位邪恶，一位冰霜，一位鲜血，还有一个将他们联结在一起的名字。"
L["The Scarlet Palisade"] = "血色关哨"
L["The Scarlet Spy"] = "血色细作"
L["The Scent of Magic"] = "魔法气息"
L["The School of Roguery"] = "盗贼学校"
L["The Scourgestone"] = "天灾石"
L["The Scouts Return"] = "斥候归来"
L["The Scryer's Dilemma"] = "占卜师的困境"
L["The Scythe of Elune"] = "月神镰刀"
L["The Seal is Broken"] = "破损的封印"
L["The Seal's Power"] = "封印之力"
L["The Search for Vargoth"] = "寻找瓦格斯"
L["The search for Zin'jun began as a rescue and became a campaign. The hozen had stripped him of his gear, the Alliance had dug in at Strongarm Airstrip, and Nazgrim needed every advantage he could improvise. You recovered Zin'jun's belongings, assaulted the airstrip, broke key Alliance officers, and learned that Captain Doren had been consumed by the darkness Taran Zhu warned about. Kiryn and Rivett turned Alliance wreckage into intelligence and acid rain, and Nazgrim sent you to read the shape of the land itself. Lay of the Land was the hinge: the war had carried you this far, but Cho was waiting to show you what the Horde had actually stepped into."] = "寻找金祖恩起初是一次营救，后来却演变成一场战役。猢狲夺走了他的装备，联盟在铁腕机坪据守不退，而纳兹戈林需要他能临时拼凑出的每一分优势。你找回了金祖恩的物品，突袭了机坪，击垮了联盟的几名关键军官，并得知多伦上尉已被祝踏岚警告过的那股黑暗吞噬。琪麟和利维特把联盟的残骸变成了情报和酸雨，纳兹戈林则派你去摸清这片土地本身的形势。“事态”正是转折点：战争把你带到了这里，而周卓正等着向你展示部落究竟踏入了怎样的境地。"
L["The Seat of the Triumvirate"] = "执政团之座"
L["The second Horseman would be Thoras Trollbane, the warrior-king of Stromgarde who had been murdered by his own son. You traveled to the ruined kingdom where Trollbane's restless spirit lingered, betrayed even in death. Prince Galen, the traitor-son, stood in your way — but regicide was a small price for the Ebon Blade. You cut Galen down and raised his father, and Thoras Trollbane rode once more, his fury undimmed by centuries in the grave."] = "第二位骑士将是索拉斯·托尔贝恩——激流堡的战士之王，死于亲生儿子之手。你前往那座残破的王国，托尔贝恩不得安息的亡魂仍在那里徘徊，即便死后也遭到背叛。叛逆之子加伦王子挡住了你的去路——但对黑锋骑士团来说，弑君不过是微不足道的代价。你斩杀了加伦，唤起了他的父亲。索拉斯·托尔贝恩再度策马而出，在墓中沉睡的漫长岁月丝毫没有消磨他的怒火。"
L["The Seed of Ages"] = "纪元之种"
L["The Serpent's Heart"] = "神龙之心"
L["The Serpent's Heart gave the temple the jade it needed, but Yu'lon could not simply appear on command. Elder Sage Rain-Zhu sent you through the temple's doubts and duties: Wise Mari's scrying, Lorewalker Stonestep's living library, Fei's cloud serpents, and the fireworks that would light the sky for a rebirth. At last Yu'lon emerged, ancient and luminous, and thanked you for helping the forest remember hope. For a moment, it felt like the war might be smaller than the wonder around it."] = "神龙之心为寺院带来了所需的玉石，但玉珑不会一经召唤便现身。大贤者朱雨让你去应对寺院中的种种疑虑与职责：贤者马里的占卜、游学者石步的活体图书馆、菲的云端翔龙，还有将为重生点亮夜空的烟花。玉珑终于现身，古老而光辉，感谢你帮助森林重新记起了希望。那一刻，与周围的奇景相比，这场战争仿佛也显得渺小了。"
L["The Setting Sun"] = "逐日残阳"
L["The Shadow of Death"] = "死亡之影"
L["The Shadow of Gilneas"] = "吉尔尼斯之影"
L["The Shadow Vault"] = "暗影拱顶"
L["The Shadowblade's Campaign"] = "暗影之刃的战役"
L["The Shadows Reveal"] = "暗影现形"
L["The Shardmaidens"] = "碎石侍女"
L["The Silkwood Road"] = "丝木林之路"
L["The Silver Hand"] = "白银之手"
L["The Silver Hand marshaled for war. You led the assault on Niskara — a demon world where Aponi Brightmane was held captive. Through waves of demons you fought, Aponi's libram serving as a beacon. When you found her, she was wounded but unbroken. Together with Delas Moonfang — who chose to become a paladin that day — you shattered the Legion's forces on Niskara. The mind of the enemy lay open, and the Silver Hand's unity was forged in fire."] = "白银之手整军备战。你率军进攻尼斯卡拉——一个关押着奥伯妮·亮鬃的恶魔世界。你杀穿一波又一波恶魔，奥伯妮的圣契如灯塔般为你指引方向。你找到她时，她虽已负伤，意志却未曾动摇。你与当天决意成为圣骑士的德拉丝·月牙并肩作战，在尼斯卡拉粉碎了军团的部队。敌军情报尽在掌握，而白银之手的团结也在烈火中铸就。"
L["The Sin'dorei remember through ritual, grief, and endurance. You carried the Sunwell's flame through Ghostlands and Quel'Danas, stood witness to the fall of legends, and helped preserve the memory that still defines your people."] = "辛多雷以仪式、哀悼与坚忍铭记过往。你带着太阳之井的火焰穿过幽魂之地和奎尔丹纳斯岛，见证了传奇的陨落，并帮助守护了至今仍定义着你的族人的记忆。"
L["The Sinstone"] = "罪碑"
L["The Sixth"] = "第六人"
L["The Skies Above"] = "天空国度"
L["The Skybreaker"] = "破天号"
L["The Skyfire reaches Pandaria hunting for Admiral Taylor and Prince Anduin, but the Alliance lands in the middle of a Horde war zone."] = "天火号抵达潘达利亚，搜寻海军上将泰勒和安度因王子的下落，但联盟却降落在了部落战区的正中央。"
L["The Slayer's Campaign"] = "屠魔者的战役"
L["The Solution Solution"] = "偷来的解决方案"
L["The Speaker Awaits"] = "久等的代言人"
L["The Spirit of the Hunter"] = "猎人之魂"
L["The Spirit of Thunder Ridge"] = "雷霆山之魂"
L["The spirits called, and you answered. By walking between worlds and standing with Baine and the spiritwalkers, you helped the Shu'halo restore harmony and honor their ancestors."] = "灵魂发出召唤，而你作出了回应。你行走于两个世界之间，与贝恩和灵魂行者们并肩而立，帮助修哈鲁恢复了和谐，并向他们的先祖致敬。"
L["The Spiritwalkers"] = "灵魂行者"
L["The Splintered Path"] = "崎岖小路"
L["The Sprites' Plight"] = "林精的困境"
L["The Stone That Started A Revolution"] = "公正堡的基石"
L["The Stoneborn"] = "石裔魔"
L["The Stormwind Extraction"] = "逃出暴风城"
L["The Strength of the Storm"] = "风暴的力量"
L["The Strike on Boralus"] = "突袭伯拉勒斯"
L["The Strongarm Airstrip"] = "铁腕机坪"
L["The Stuff of Dreams"] = "梦中之物"
L["The Sum is Greater than the Parts"] = "一加一大于二"
L["The Sunken Graveyard"] = "沉没的墓地"
L["The Sunken Vault"] = "水下宝库"
L["The Sword of Kings"] = "王者之剑"
L["The Tale of Ban-Lu"] = "班禄的故事"
L["The Temple of the Jade Serpent"] = "青龙寺"
L["The third Horseman would be the most controversial — High Inquisitor Whitemane of the Scarlet Crusade, a zealot who had burned the undead with holy fire for years. You led the assault on the Scarlet Monastery, cutting through fanatical defenders in a massacre that painted the halls red. When Whitemane fell, you raised her — and the woman who had sworn to destroy every death knight opened her eyes as one. The irony was not lost on anyone."] = "第三位骑士将是最具争议的人选——血色十字军的大检察官怀特迈恩，一个多年来以神圣之火焚烧亡灵的狂热信徒。你率军进攻血色修道院，在一场将大厅染红的屠杀中杀穿了狂热的守军。怀特迈恩倒下后，你唤起了她——这个曾发誓要消灭所有死亡骑士的女人，睁开双眼时自己也成了一名死亡骑士。这其中的讽刺，所有人都心知肚明。"
L["The Threads that Stick"] = "万千烦恼丝"
L["The Three Sisters"] = "三姐妹"
L["The time for subtlety had passed. You helped Oculeth build war machines, gathered supplies with Valtrois, trained civilian volunteers into a fighting force, and armed the rebellion with weapons taken from the Legion itself. When the trial by demonfire proved the rebels could hold their own, there was nothing left to do but march."] = "隐忍行事的时候已经过去了。你协助欧库勒斯制造战争机械，与瓦尔托伊丝一同收集物资，将平民志愿者训练成一支战斗部队，并用从军团手中夺来的武器武装反抗军。当恶魔之火的试炼证明反抗军足以自保后，剩下的就只有进军了。"
L["The time had come to strike at the Nightmare's heart. Keeper Remulos guided you through a rift into the Dream's darkest depths, where you relived the War of the Ancients — watching Archimonde the Defiler lay waste to the world ten thousand years ago. In that crucible of memory and shadow, you reached Malorne himself. The great white stag stirred, rose, and returned to the waking world. With the demi-god reborn and your weapon forged anew, the Cenarion Circle had become a force even the Legion feared."] = "直捣梦魇核心的时刻到了。守护者雷姆洛斯引导你穿过一道裂隙，进入梦境最黑暗的深处。你在那里重温了上古之战——目睹污染者阿克蒙德在一万年前将世界化为焦土。在这记忆与阴影交织的熔炉中，你找到了玛洛恩本尊。那头伟大的白色雄鹿苏醒过来，站起身，重返现实世界。半神重生，你的武器也重铸一新，塞纳里奥议会已成为一支连军团都忌惮的力量。"
L["The Tirisgarde needed power, and power came in the form of legends. Archmage Kalec — the blue dragon who once guarded the Sunwell — and Archmage Modera of the Council of Six both pledged their strength. Archmage Omniara trained troops while Archmage Melis provided the technical wizardry to keep the Hall of the Guardian running. The Tirisgarde was no longer a relic of history — it was a force."] = "提瑞斯法守护者需要力量，而力量以传奇的形式到来。大法师卡雷——曾经守护太阳之井的蓝龙——和六人议会的大法师茉德拉都宣誓效力。大魔法师欧妮娅拉负责训练部队，大法师麦丽丝则以她的奥术技艺维持守护者圣殿的运转。提瑞斯法守护者不再是历史的遗物——而是一股真正的力量。"
L["The Tirisgarde Reborn"] = "秘法会的重生"
L["The titans built Uldir to study the Old Gods — to understand the corruption before they tried to cure it. What they created instead was G'huun: a proto-god of blood and shadow, born in a lab, every safeguard bypassed. Sealed in stasis for millennia, fed by the blood trolls until he was strong enough to break containment himself. Uldir was not a dungeon. It was a prison that had started to answer back.\n\nYou fought through the facility's corrupted wards — past G'huun's lieutenants, through the experiments that had gone wrong in the age before trolls had language — and reached the heart of the prison. G'huun fell. The blood god's thousand-year campaign to break free ended in the same titan vault it began in. Nazmir would take generations to recover. The trolls who had given their lives feeding G'huun would never be fully redeemed. But the earth was quiet again, and the seal held."] = "泰坦建造奥迪尔，是为了研究上古之神——在尝试治愈腐化之前先理解它。然而他们最终造出的却是戈霍恩：一个由鲜血与暗影构成的原始之神，诞生于实验室中，所有防护措施都形同虚设。它在静滞中被封印了数千年，血巨魔不断献上鲜血喂养它，直到它强大到足以自行打破封印。奥迪尔不是地下城，而是一座开始反过来回应的监狱。\n\n你杀穿了设施中被腐化的防御结界——越过戈霍恩的副官，穿过那些在巨魔尚无语言的年代就已失控的实验——抵达了监狱的核心。戈霍恩倒下了。这位血神挣脱囚笼的千年征程，终结在了它开始的那座泰坦宝库里。纳兹米尔需要数代人的时间才能恢复。那些献出生命喂养戈霍恩的巨魔永远无法得到完全的救赎。但大地再次归于平静，封印依然稳固。"
L["The Tome of Blighted Implements"] = "毁灭利器之书"
L["The Touch of an Aspect"] = "龙神的触摸"
L["The trail leads to Azsuna, where a leyworm infestation masks something far more dangerous. Hemet Nesingwary lends his expertise."] = "线索指向阿苏纳，那里泛滥的魔网蠕虫掩盖着某种更加危险的东西。赫米特·奈辛瓦里将提供他的专业协助。"
L["The trail leads to Crusader's Run and the tower of High Priest Benedictus Voss. A daughter has come a long way to find her father — and what he says to her will determine everything."] = "线索指向十字军小径和高阶牧师本尼迪塔斯·沃斯的高塔。一位女儿跋涉千里来寻找她的父亲——而他对她说的话，将决定一切。"
L["The Trial of Ban-Lu"] = "班禄的试练"
L["The Trial of Rage"] = "怒火试炼"
L["The Truth of the Grave"] = "墓中的真相"
L["The Twilight Master"] = "暮光之主"
L["The Underrot"] = "地渊孢林"
L["The Underrot: Sealing G'huun's Corruption"] = "地渊孢林：封锁戈霍恩的腐化"
L["The Undersea Ledge"] = "海底礁石"
L["The Unkillable"] = "不灭不死"
L["The Unseen Blade"] = "无形之刃"
L["The Unseen Path"] = "隐秘通途"
L["The unthinkable happened — the Peak of Serenity, the monks' sacred mountain, fell to a Legion assault. As smoke rose from the ruins, you gathered the survivors and led them to the Temple of Five Dawns on the Wandering Isle. There, Fearsome Jang named you Grandmaster of the order, and you claimed an artifact weapon to carry into the war ahead. Iron-Body Ponshu began organizing the scattered monks into a fighting force."] = "难以想象的事情发生了——武僧们的圣山晴日峰在军团的进攻下沦陷。废墟上浓烟升起之际，你召集了幸存者，带领他们前往迷踪岛的五晨寺。在那里，蒋震魂任命你为武僧宗师，你也选取了一件神器武器，带着它投入即将到来的战争。金刚不坏彭戍开始将四散的武僧组织成一支战斗部队。"
L["The Val'kyr raise new Forsaken in the crypt of Deathknell. One of them is Lilian Voss — daughter of the Scarlet Crusade's High Priest, raised as the very thing she was trained to destroy."] = "瓦格里在丧钟镇的墓穴中复活了新的被遗忘者。其中之一便是莉莉安·沃斯——血色十字军高阶牧师的女儿，复生后成了她自幼受训要消灭的那种东西。"
L["The Valewalker's Burden"] = "山谷行者的重担"
L["The Valley of Echoes is a bowl of old Scourge work. Plague altars cough smoke into the wind; restless dead pace the rim by moonlight. Father Gustav wants scourgestones. The Ebon Watcher wants the altars cold. The Argent Crusade wants the road cleared north — to the Pinnacle, where Tirion Fordring has already set his banner. When the banner flies, the whole rim of Icecrown hears it, and the gunships in the northern sky start warming their engines."] = "回音谷是一处遗留着天灾军团旧日造物的洼地。瘟疫祭坛向风中喷吐着浓烟，不得安息的亡者在月光下沿着谷缘徘徊。古斯塔夫神父想要天灾石。黑锋观察者想让祭坛熄灭。银色北伐军则想清出一条向北的道路——通往北伐军之峰，提里奥·弗丁已在那里竖起了他的旗帜。当旗帜飘扬时，整个冰冠冰川都将闻讯，北方天空中的炮舰也开始预热引擎。"
L["The Vanguard's wreckage proved Anduin had survived, but it also pulled the Alliance into the Pearlfin jinyu's crisis. Taylor and Bold Karasshi had been captured by the Slingtail hozen, and the only way forward was through the pits. You freed prisoners, recovered waterspeaker relics, broke Kung Din's hold, and helped the Pearlfin decide whether the Alliance deserved their trust. SI:7's reports then made the bargain real: the Horde had armed the hozen, so Taylor trained the jinyu to fight back. When the trail finally led to Cho, the search changed shape. Tea, stories, and a strange brew opened the way to Anduin, who was already choosing curiosity over command."] = "先锋号的残骸证明安度因还活着，却也把联盟卷入了珠鳍锦鱼人的危机。泰勒和勇敢的卡拉什被投尾猢狲俘虏，唯一的出路是穿过猢狲的巢坑。你解救了囚犯，找回了水语者的圣物，粉碎了恐钉的控制，并帮助珠鳍锦鱼人判断联盟是否值得信任。军情七处的报告随后让这笔交易成了真：部落武装了猢狲，于是泰勒训练锦鱼人进行反击。当线索终于指向周卓时，搜寻也变了样。茶、故事和一杯奇特的佳酿为你打开了通往安度因的道路——而他已经选择了好奇，而非发号施令。"
L["The Vanishing Lord"] = "消失的勋爵"
L["The Vault of the Tirisgarde"] = "提瑞斯秘法会的宝库"
L["The Vile Hold"] = "邪恶城堡"
L["The Village of Glenbrook"] = "格伦布鲁克村"
L["The Vindicator's Plea"] = "守备官的请求"
L["The Violet Citadel, Dalaran"] = "紫罗兰城堡（达拉然）"
L["The VIP List"] = "贵宾名单"
L["The voice in the dark has a name now — Matthias Lehner. He claims to know the Lich King better than any living thing should. His memories run like a buried river through the Frozen Wastes. He leads you to a dragon's corpse. To a hunter and a prince. To the knowledge that cannot be unknown. Whether he can be trusted is a judgement you will make when the road ends — at the foot of the citadel, where Tirion Fordring lifts the Ashbringer and calls for one more charge."] = "黑暗中的那个声音如今有了名字——米斯希尔萨·阿奈尔。他声称自己对巫妖王的了解，远超任何活物所应知晓的程度。他的记忆如一条地下河流般贯穿冰冻废土。他带你找到一具巨龙的尸骸，找到一位猎人和一位王子，找到一旦知晓便无法遗忘的真相。他是否值得信任，要等这条路走到尽头时由你来判断——在那座城堡脚下，提里奥·弗丁将高举灰烬使者，号召发起最后一次冲锋。"
L["The Wakening"] = "苏醒"
L["The Wanderer's Companion"] = "云游者之友"
L["The Wanderers"] = "迷踪旅人"
L["The Waning Crescent"] = "残月酒馆"
L["The war at sea gave the Horde what blades on land could not: Derek Proudmoore, heir to Kul Tiras, dead at the bottom of the ocean. Hobart Grapplehammer put you in a diving suit and you went down. The ocean floor was littered with the wreckage of the battle — dog tags, sunken ships, the bones of sailors on both sides. You found Derek and hauled him up. No one said what Sylvanas would do with him. No one had to."] = "海上战争为部落带来了陆上刀剑无法夺得的东西：库尔提拉斯的继承人德里克·普罗德摩尔，已葬身海底。霍巴特·钩锤让你穿上潜水服，你潜入了深海。海床上散落着战斗的残骸——身份牌、沉船、双方水手的骸骨。你找到了德里克，把他拖了上来。没有人说希尔瓦娜斯会如何处置他。也没有人需要说。"
L["The war ended. Sylvanas was gone. And Lilian Voss led the Forsaken home.\n\nThey came back to ruins — streets flooded with Blight, Undercity dark and broken. Calia Menethil walked beside her, daughter of the last king of Lordaeron, and between the two of them they held the Forsaken together through all of it: the plague work, the dead to bury, the city to reclaim room by room. At the end they formed the Desolate Council — Lilian, Calia, Velonara, Belmont, Faranell — not a Dark Lady, not a warchief. A council. Their own.\n\nLilian Voss, who had spent her whole life as something to be used and discarded, had become the person her people followed home."] = "战争结束了。希尔瓦娜斯离去了。莉莉安·沃斯带领被遗忘者回到了家园。\n\n迎接他们的是一片废墟——街道被疫病淹没，幽暗城黑暗而残破。洛丹伦末代国王之女佳莉娅·米奈希尔走在她身旁，两人携手让被遗忘者撑过了这一切：清除瘟疫、埋葬死者、一间一间地收复城市。最终，她们组建了荒芜议会——莉莉安、佳莉娅、维洛娜拉、贝尔蒙特、法拉尼尔——不是黑暗女王，也不是大酋长，而是一个议会。属于他们自己的议会。\n\n莉莉安·沃斯一生都在被人利用、被人抛弃，如今却成了带领族人回家的那个人。"
L["The War for Silverpine"] = "银松森林之战"
L["The war in the Shadowlands is over. Sylvanas stands before those she has wronged — and must face what comes next."] = "暗影国度的战争已经结束。希尔瓦娜斯站在那些被她伤害过的人面前——她必须面对接下来的一切。"
L["The war moves to the Broken Shore. Aethas Sunreaver leads the Tirisgarde's assault, and you earn the Archmage's Prismatic Disc."] = "战火蔓延至破碎海滩。艾萨斯·夺日者率领提瑞斯法守护者发起进攻，你也将赢得大法师的棱彩法碟。"
L["The war moves to the Broken Shore. Contend with Magatha Grimtotem, secure Smolderon's flame, and earn a mount of living storm."] = "战火蔓延至破碎海滩。与玛加萨·恐怖图腾周旋，夺取斯摩德隆之焰，赢得一头由鲜活风暴化成的坐骑。"
L["The war moves to the Broken Shore. Lead the Unseen Path against the Legion's corrupted beasts and earn the trust of a loyal wolfhawk."] = "战火蔓延至破碎海滩。率领无形之路对抗军团腐化的野兽，赢得一只忠诚狼鹰的信任。"
L["The war moves to the Broken Shore. Rally the Valarjar for a final push, brave the depths of Helheim, and earn your war wyrm."] = "战火蔓延至破碎海滩。集结瓦拉加尔发起最后的攻势，勇闯冥狱深渊，赢得属于你的战争巨龙。"
L["The War of the Ancients"] = "上古之战"
L["The War of Thorns"] = "荆棘之战"
L["The war reaches the Broken Shore. Break a family curse, then forge the Highlord's Golden Charger at the Hammer of Dalaran."] = "战火燃至破碎海滩。破除一个家族诅咒，然后在达拉然之锤锻造大领主的金色战马。"
L["The war reaches the Broken Shore. Defend the wilds, recruit Thisalee Crow, and earn the Archdruid's Lunarwing flight form."] = "战火燃至破碎海滩。保卫荒野，招募希萨莉·黑鸦，赢得大德鲁伊的月翼飞行形态。"
L["The War Within"] = "地心之战"
L["The Warchief Cometh"] = "酋长驾到"
L["The Warchief sets her sights on Darkshore. What unfolds there will make the Fourth War impossible to contain."] = "大酋长将目光投向了黑海岸。那里发生的一切，将使第四次大战再也无法遏制。"
L["The Warchief's Fleet"] = "酋长的舰队"
L["The Warsong at the Wrathgate"] = "天谴之门的战歌氏族"
L["The Warswords of the Valarjar called to you — twin blades said to contain the fury of a hundred battles. Odyn sent you to Stormheim to hunt the hero-slayer who had stolen them. Through storm and fire, you tracked the thief to their lair and pried the swords from their grip. The runes along the blades blazed to life in your hands, as if they had been waiting."] = "瓦拉加尔战剑在召唤你——据说这对双刃中蕴藏着百场战斗的怒火。奥丁派你前往风暴峡湾，追猎盗走它们的英雄杀手。你穿越风暴与烈火，一路追踪窃贼直至其巢穴，从其手中夺回了双剑。剑身上的符文在你手中燃起光芒，仿佛它们一直在等待着你。"
L["The Way Back Home"] = "返程车票"
L["The Way of the Tiger"] = "白虎之道"
L["The Waycrest Daughter"] = "维克雷斯之女"
L["The Wayward Crone"] = "任性的老妪"
L["The Wayward Dead"] = "倔强的死者"
L["The White Pawn"] = "白卒"
L["The Will of the Naaru"] = "纳鲁的意志"
L["The Winter Queen needs anima, and Revendreth is supposed to be the realm that knows how to harvest it. Your request begins in Darkhaven, where every sin has a stone."] = "寒冬女王需要心能，而雷文德斯本该是最懂得如何收集心能的国度。你的请求从暗湾镇开始——在那里，每一桩罪孽都有对应的罪碑。"
L["The witch hunt turned on Lucille herself — Marshal Everit Reade accused the Waycrest daughter of sorcery. In a land gripped by paranoid suspicion, even nobility was not above the trials. You gathered proof of Lucille's innocence through the marshal's superstitious tests: walking through the woods that watched, enduring ambush, and passing the trial by superstition. A pungent alchemical solution revealed the true witches hiding in plain sight. The burden of proof was met, but the experience left its mark — in Drustvar, trust was a luxury no one could afford."] = "猎巫行动的矛头转向了露希尔本人——埃弗利·里德元帅指控这位维克雷斯家族的女儿施行巫术。在这片被多疑猜忌笼罩的土地上，即便是贵族也无法免于审判。你通过元帅那些迷信的考验，搜集了证明露希尔清白的证据：穿过那片仿佛在注视着你的树林，挺过伏击，并通过了迷信的试炼。一种气味刺鼻的炼金溶液揭露了那些藏身于众目睽睽之下的真正女巫。举证责任已尽，但这段经历留下了印记——在德鲁斯瓦，信任是谁也负担不起的奢侈品。"
L["The Witchwood of Drustvar"] = "德鲁斯瓦的女巫林地"
L["The Woods Have Eyes"] = "林中有眼"
L["The World is Not Enough"] = "黑日危机"
L["The Wrathgate"] = "天谴之门"
L["The Wrathsteed of Xoroth"] = "克索诺斯的愤怒战马"
L["The Zealot Rises"] = "狂热者重生"
L["The zone ends where its warning began: inside the Temple of the Jade Serpent. The sha has seeped into wisdom, memory, discipline, and flame. Wise Mari, Lorewalker Stonestep, Liu Flameheart, and the temple's defenders are all trapped in doubt's reflection. By cleansing the temple and defeating the Sha of Doubt, you do what the armies outside could not: stop feeding the darkness long enough to face it. The Jade Forest is not untouched anymore. It is wounded, changed, and still alive."] = "翡翠林的故事在当初发出警示的地方落幕：青龙寺之内。煞已渗入了智慧、记忆、戒律与火焰之中。贤者马里、游学者石步、刘·焰心和寺院的守卫者们，都被困在疑虑的倒影里。你净化了寺院，击败了疑之煞，做到了外面的军队无法做到的事：停止喂养黑暗，并坚持到足以直面它的那一刻。翡翠林已不再是净土。它受了伤，变了样，却依然活着。"
L["Theotar"] = "西塔尔"
L["Theotar, the Mad Duke, may know where Prince Renathal is. His ruined tea party leads through the Light-scarred Ember Ward and back to Sinfall."] = "疯狂公爵西塔尔或许知道雷纳索尔王子的下落。他那场被毁的茶会将带你穿过被圣光灼伤的灰烬荒野，再回到堕罪堡。"
L["Theotar's Mission"] = "西塔尔的托付"
L["Therazane"] = "塞拉赞恩"
L["Therazane the Stonemother sent a tremor through the Maelstrom — a cry for help. Deepholm, the elemental plane of earth, was being consumed by the Twilight's Hammer once more. You descended into the stone realm and found Therazane besieged, her domain crumbling. Together you destroyed the cult's forces, unmasked their master's plan, and unleashed the elements against them. Therazane promised the earth's strength to the Earthen Ring, and Muln Earthfury pledged himself as your champion."] = "石母塞拉赞恩的一阵震颤传遍了大漩涡——那是一声求救。土元素位面深岩之洲再度遭到暮光之锤的蚕食。你深入这片岩石国度，发现塞拉赞恩正被围困，她的领地正在崩塌。你们一同摧毁了邪教的部队，揭穿了其首领的阴谋，并让元素之力反噬敌人。塞拉赞恩承诺将大地的力量借给大地之环，穆恩·大地之怒也宣誓成为你的勇士。"
L["There is Another"] = "另有其神"
L["There Is No Plan \"B\""] = "没有替代方案"
L["Theryn"] = "泰林"
L["They Move Against Us"] = "他们成为了反抗势力"
L["They Will Know Fear"] = "传播恐惧"
L["They Won't Know What Hit Them"] = "无形之敌"
L["They're So Thorny!"] = "问题变得棘手了！"
L["Things Gaardoun Needs"] = "加尔顿的需求"
L["Thinly Veiled Threats"] = "露骨的威胁"
L["This Ain't Mine"] = "这不是地雷"
L["This Is Retribution"] = "释放惩戒"
L["This is the Hour of the Forsaken"] = "被遗忘者的时刻"
L["This Land is Ours"] = "这是我们的土地"
L["This Time, Leave a Trail"] = "雁过留痕"
L["This Was Home"] = "永远的家"
L["Thisalee Crow"] = "希萨莉·黑鸦"
L["Thomas Zelling"] = "托马斯·泽林"
L["Thomas Zelling was a dying tidesage who traded his humanity for undeath, desperate for a few more years with his family. You and Lilian performed the ritual that raised him — and then watched his wife recoil in horror from the husband she no longer recognized. Lilian stood in silence as the scene played out, seeing her own story reflected in Zelling's shattered face. To be Forsaken, she finally understood, was not just a curse of the body."] = "托马斯·泽林是一名垂死的潮汐贤者，他用人性换取了亡灵之躯，只为与家人多相守几年。你和莉莉安举行了将他复生的仪式——然后眼睁睁看着他的妻子惊恐地躲开那个她再也认不出的丈夫。莉莉安默默看着这一幕，在泽林破碎的面容中看到了自己的故事。她终于明白，身为被遗忘者，并不只是肉体上的诅咒。"
L["Thorim"] = "托里姆"
L["Those Scrying Eyes"] = "占卜之眼"
L["Thousands of Years Ago..."] = "千百年前……"
L["Thrall"] = "萨尔"
L["Thrall calls you to the Maelstrom, where the Earthen Ring fights to keep the world from tearing apart."] = "萨尔召唤你前往大漩涡，大地之环正在那里奋力阻止世界分崩离析。"
L["Thrall could no longer hear the elements. The Doomhammer — Orgrim's weapon, carried through the First and Second Wars — had gone silent in his hands. He passed it to you, and the moment your fingers closed around the haft, thunder split the sky. The elements had chosen a new wielder. The Doomhammer was yours."] = "萨尔再也听不见元素的声音了。毁灭之锤——奥格瑞姆的武器，曾历经第一次和第二次大战——在他手中陷入了沉寂。他将它交给了你，就在你的手指握住锤柄的那一刻，雷霆划破了天空。元素选择了新的持有者。毁灭之锤归你了。"
L["Thrall passes the Doomhammer to you — the weapon of Orgrim Doomhammer, carried through two wars and across worlds."] = "萨尔将毁灭之锤交给了你——这是奥格瑞姆·毁灭之锤的武器，历经两场大战，跨越了不同的世界。"
L["Thrall's summons brought you to the edge of the Maelstrom — the wound in the world where Deathwing had nearly torn Azeroth asunder. The Earthen Ring was losing the fight to hold it together. Farseer Nobundo stood at the eye of the storm, channeling what remained of the ring's power. You claimed an artifact weapon attuned to the elements, and Stormcaller Mylra and Duke Hydraxis pledged themselves as your first champions. The elements were restless — and they were listening."] = "萨尔的召唤将你带到了大漩涡的边缘——那是死亡之翼几乎将艾泽拉斯撕裂时留下的世界之伤。大地之环在维系世界完整的战斗中节节败退。预言者努波顿站在风暴之眼，引导着大地之环残存的力量。你获得了一件与元素共鸣的神器武器，风暴召唤者米尔拉和海达克西斯公爵也宣誓成为你的第一批勇士。元素躁动不安——而它们正在倾听。"
L["Three Horsemen rode, but the fourth seat remained empty. The Lich King demanded a champion of unmatched power — and the only candidate lay buried beneath Light's Hope Chapel itself. You stormed the most sacred ground on Azeroth, battling paladins and holy guardians, only for the assault to fail against the Chapel's consecrated power. In the end, it was Darion Mograine who knelt and gave himself — dying so he could rise as the Fourth Horseman. With your weapon forged anew and all four riders assembled, you were named Deathlord of the Ebon Blade."] = "三位骑士已经就位，但第四个位置依然空缺。巫妖王要求一位拥有无与伦比力量的勇士——而唯一的人选就埋葬在圣光之愿礼拜堂之下。你猛攻艾泽拉斯最神圣的土地，与圣骑士和神圣守护者交战，然而这次进攻却在礼拜堂的神圣之力面前功亏一篑。最终，达里安·莫格莱尼跪了下来，献出了自己——他以死亡为代价，作为第四骑士重新崛起。你的武器重铸一新，四位骑士全部集结，你被任命为黑锋骑士团的死亡领主。"
L["Throne of the Tides"] = "潮汐王座"
L["Thros, the Blighted Lands"] = "兹洛斯，枯败之界"
L["Through Ly'leth Lunastre's connections, you obtained a magical disguise and walked the gilded streets of Suramar City as one of the Nightborne elite. Behind the masks and pleasantries, you made first contact with sympathizers among the nobility — those who whispered against Elisande but dared not act alone."] = "借助莉莉丝·月郡的人脉，你获得了一套魔法伪装，以夜之子精英的身份行走在苏拉玛城金碧辉煌的街道上。在面具和寒暄背后，你与贵族中的同情者取得了初步联系——他们私下里低声反对艾利桑德，却不敢独自行动。"
L["Through the Emerald Dreamway, you discover the Dreamgrove: a sanctuary of nature hidden in Val'sharah. The Legion's war is spreading into places that should have been beyond its reach.\n\nAs Archdruid of the Cenarion Circle, heal the wounds of the Nightmare, gather ancient allies, and call on powers older than any mortal battlefield."] = "穿过翡翠梦境之路，你发现了梦境林地：一处隐藏在瓦尔莎拉的自然圣所。燃烧军团的战火正在蔓延到本应遥不可及的地方。\n\n作为塞纳里奥议会的大德鲁伊，治愈梦魇留下的创伤，召集古老的盟友，唤醒比任何凡人战场都更加古老的力量。"
L["Through the Eye"] = "巫妖王之眼"
L["Through the Old Roads"] = "穿越老路"
L["Through the Shattered Sky"] = "穿过破碎天空"
L["Through trogg-infested ruins, ancient records, and the heat of the forge, you helped restore a lost legacy and carry the mountain king's heritage into the present."] = "你穿过遍布穴居人的废墟，翻阅古老的记载，在熔炉的炽热中帮助恢复了一段失落的传承，并将山丘之王的遗产带入了当下。"
L["Throwing SI:7 Off the Trail"] = "混淆视听"
L["Thunder Bluff / Mulgore / Stonetalon"] = "雷霆崖 / 莫高雷 / 石爪山脉"
L["Thunderaan"] = "桑德兰"
L["Thurgaden's Designs"] = "瑟加登的设计图"
L["Thus Begins the War"] = "开始战斗"
L["Tian Monastery"] = "天禅院"
L["Tian Monastery is under siege. Fight alongside Taran Zhu and The Monkey King to drive back the Legion and rebuild the order."] = "天禅院遭到围攻。与祝踏岚和美猴王并肩作战，击退燃烧军团，重建武僧组织。"
L["Tian Monastery offered a different kind of strength. You entered as a guest, sat at the banquet, then trained under masters who cared as much about patience as power. You made a weapon with Groundskeeper Wu, learned precision from Instructor Xann, faced sparring partners who turned humility into bruises, and endured the Rumpus without mistaking chaos for victory. Flying Colors was more than a graduation. It was Pandaria quietly asking whether you could be taught."] = "天禅院展现了另一种力量。你以客人的身份进入，参加了宴席，随后在大师们的指导下接受训练——他们对耐心的重视不亚于力量。你与园丁老吴一同打造了武器，跟随夏教头学习精准，与那些把谦逊化为淤青的陪练对手过招，还熬过了一场大混战，却没有把混乱误当作胜利。“流光溢彩”不仅仅是一场结业仪式，更是潘达利亚在默默地询问：你是否可教。"
L["Tickets, Please?"] = "您好，检票"
L["Tide of Virmen"] = "兔妖之潮"
L["Tidesage Teachings"] = "海贤教诲"
L["Time Flies When Yer Havin' Rum!"] = "喝着朗姆，光阴飞逝！"
L["Time for Answers"] = "寻求答案"
L["Time is of the Essence"] = "时间宝贵"
L["Time to Hide"] = "藏匿行踪"
L["Time Yet Remains"] = "仍有时间"
L["Tiragarde Sound was rotting at its foundations. Priscilla Ashvane and the Ashvane Trading Company had corrupted the Admiralty's supply lines, bribed its officers, and turned institutional loyalty into a private racket — all while Katherine Proudmoore remained in the dark, managing the public appearances of a nation that was quietly being hollowed out beneath her. You dismantled the operation piece by piece, surfacing the evidence until the case against Ashvane was undeniable. Katherine met with Genn Greymane in Boralus Harbor. She still had not spoken to Jaina."] = "提拉加德海峡已从根基开始腐烂。普里西拉·艾什凡和艾什凡贸易公司腐蚀了海军部的补给线，贿赂其军官，把对体制的忠诚变成了私人敛财的勾当——而凯瑟琳·普罗德摩尔却始终被蒙在鼓里，维持着一个国家的体面，殊不知它正在她脚下被悄然掏空。你一步步瓦解了这个组织，将证据逐一揭露，直到对艾什凡的指控确凿无疑。凯瑟琳在伯拉勒斯港会见了吉恩·格雷迈恩。她仍然没有和吉安娜说过话。"
L["Tirion's Gambit"] = "提里奥的尝试"
L["Tirion's Help"] = "提里奥的帮助"
L["Tirisfal Glades / Kul Tiras / Lordaeron"] = "提瑞斯法林地 / 库尔提拉斯 / 洛丹伦"
L["Tirisfal Glades / Silverpine Forest"] = "提瑞斯法林地 / 银松森林"
L["Titan Keeper Hezrel"] = "泰坦守护者赫兹雷尔"
L["Titan Keeper Hezrel had been running containment protocols in Nazmir longer than any troll civilization had existed. His facility was damaged, his routines degraded, and the thing he was containing was actively working to get out. G'huun — a failed titan experiment, a blood god born in a lab and deemed too dangerous to destroy — had been sealed beneath Nazmir since before the trolls arrived. You helped Hezrel repair his systems, purified the corrupted earth, cleared the undead and void creatures that had crept into the facility, and restored the containment. For now. What had already escaped, and the blood trolls' true purpose — feeding G'huun until he broke free on his own terms — was only becoming clear."] = "泰坦守护者赫兹雷尔在纳兹米尔执行收容协议的时间，比任何巨魔文明存在的时间都要长。他的设施已经受损，程序逐渐失灵，而被他收容的东西正千方百计地试图逃脱。戈霍恩——一个失败的泰坦实验，一个诞生于实验室、因过于危险而无法被摧毁的血神——早在巨魔到来之前就被封印在纳兹米尔地下。你帮助赫兹雷尔修复了系统，净化了被腐化的大地，清除了潜入设施的亡灵和虚空生物，恢复了收容。至少暂时如此。而那些已经逃脱的东西，以及血巨魔的真正目的——喂养戈霍恩，直到它按自己的方式挣脱束缚——才刚刚开始浮出水面。"
L["Titanstrike"] = "泰坦之击"
L["To Be Forsaken"] = "被遗忘者"
L["To Bridge Earth and Sky"] = "沟通天地"
L["To Dai-Lo Farmstead"] = "前往大箩农场"
L["To Darkhaven"] = "前往暗湾镇"
L["To Falconhurst!"] = "前往隼林镇！"
L["To Faronaar"] = "挺进法罗纳尔"
L["To Fel and Back"] = "邪能之旅"
L["To Felblaze Ingress"] = "前往邪焰隘口"
L["To Fordragon Hold!"] = "前往弗塔根要塞！"
L["To Gloom Hollow"] = "前往林荫巨木"
L["To Kill a Loa"] = "弑神"
L["To Morning Breeze"] = "前往晨息村"
L["To Northshire"] = "驰援北郡"
L["To See Clearly"] = "启其明眸"
L["To Tame the Beast"] = "诱捕野兽"
L["To the Broken Shore"] = "前往破碎海滩"
L["To the Deeps"] = "深入海底"
L["To The Dreamgrove"] = "进入梦境林地"
L["To the Other Side"] = "打开大门"
L["To the Sepulcher"] = "前往瑟伯切尔"
L["To the Summit!"] = "到山顶去！"
L["Tol Dagor: The Fourth Key"] = "托尔达戈：第四把钥匙"
L["Tomb of Sargeras"] = "萨格拉斯之墓"
L["Tooki Tooki"] = "图奇图奇"
L["Torastrasza"] = "托拉斯塔萨"
L["Torga, ancient sea turtle loa of Nazmir, is dying. The blood trolls have bled him for decades. You arrive too late to save him — but not too late to release him."] = "托加，纳兹米尔古老的海龟洛阿，正奄奄一息。血巨魔已经放了他几十年的血。你来得太晚，已无法救他——但还来得及让他解脱。"
L["Torga, the Turtle Loa"] = "乌龟之神托加"
L["Torga's Eternal Return"] = "托加的不灭轮回"
L["Torghast, Tower of the Damned"] = "托加斯特，罪魂之塔"
L["Total Ohmage: The Valley of Lost Hope!"] = "长途轰炸：失落希望之谷！"
L["Totemic Restoration"] = "图腾恢复仪式"
L["Touching Ground"] = "天降神兵"
L["Toya"] = "托亚"
L["Track down the Fangs of Ashamane, twin daggers imbued with the spirit of the wild god of feral druids."] = "追寻阿莎曼之牙的下落——这对双匕首中蕴含着野性德鲁伊所尊奉的荒野之神的灵魂。"
L["Track down the legendary assassination daggers once wielded by Garona Halforcen, hidden away after the fall of a king."] = "追寻曾由半兽人迦罗娜挥舞的传奇刺杀匕首的下落，它们在一位国王陨落后被藏了起来。"
L["Track down Titanstrike, a legendary rifle forged by the titan keeper Mimiron, lost in the wilds of Ulduar."] = "追寻泰坦之击的下落——一把由泰坦守护者米米尔隆锻造的传奇步枪，遗失在奥杜尔的荒野之中。"
L["Tracking a Killer"] = "追踪凶手"
L["Tracking the Enemy"] = "追踪敌人"
L["Tracking Tidesages"] = "追踪海潮贤者"
L["Tracking Tipoff"] = "寻踪觅影"
L["Trail of Echoes"] = "回响轨迹"
L["Traitor!"] = "叛徒！"
L["Traitors In Our Midst"] = "内部叛徒"
L["Translation: Danger!"] = "翻译：危险！"
L["Trapped!"] = "被困住了！"
L["Traumatized Nectarbreeze Farmer"] = "受轻伤的蜜风果农"
L["Travel back to the hour that broke a prince — and make sure history unfolds as it always has."] = "回到那个令一位王子沉沦的时刻——确保历史一如既往地展开。"
L["Travel from the Exodar to Bloodmyst Isle and onward to the broken sky of Outland, retracing the long flight of a people who have lost more worlds than most have ever known. The past is not distant for the draenei; it is written into every refuge.\n\nStand on ground still marked by betrayal, ask what faith can carry through grief, and help forge a future worthy of draenei endurance."] = "从埃索达前往秘血岛，再前往外域支离破碎的天空之下，重走一个民族漫长的流亡之路——他们失去的世界，比大多数人见过的还要多。对德莱尼人而言，过去从不遥远；它铭刻在每一处避难所中。\n\n站在依然留有背叛印记的土地上，追问信仰能在悲痛中承载什么，并帮助铸就一个配得上德莱尼人坚韧精神的未来。"
L["Trial by Demonfire"] = "魔火试练"
L["Trial by Superstition"] = "迷信审判"
L["Trolling Them"] = "斡旋"
L["Troops in the Field"] = "部队出勤"
L["Trueshot Lodge / Broken Isles"] = "神射手营地 / 破碎群岛"
L["Truthguard"] = "真理守护者"
L["Tubbins"] = "塔宾斯"
L["Tubbins's Tea"] = "塔宾斯的茶"
L["Turtle Power"] = "海龟之力"
L["Turtle Powered"] = "海龟动力"
L["Twinblades of the Deceiver"] = "欺诈者的双刃"
L["Twinspire Keep"] = "双塔堡垒"
L["Tyrande Whisperwind"] = "泰兰德·语风"
