L["Under Ly'leth Lunastre's guidance, you plunged into the viper pit of Nightborne politics — buying votes, silencing rivals, and navigating a web of alliances that shifted with every whispered rumor. Through cunning and carefully applied force, Ly'leth secured her position among the nobility and opened the path to the Arcway, an ancient tunnel network running beneath the city."] = "在莉莉丝·月郡的指引下，你一头扎进了夜之子政坛的毒蛇窝——收买选票、让对手闭嘴，在随每一句流言而变化的同盟关系中周旋。凭借计谋和恰到好处的武力，莉莉丝稳固了她在贵族中的地位，并打开了通往魔法回廊的道路——那是一张在城市下方延伸的古老隧道网络。"
