L["Valeera Sanguinar led you on a hunt for the Raven's Eye, an ancient vrykul artifact capable of piercing any disguise. Your search took you through the Maw of Souls and into the haunted depths of Black Rook Hold, where you retrieved the artifact and deciphered a letter that revealed the true scope of the enemy's infiltration."] = "瓦莉拉·萨古纳尔带领你寻找渡鸦之眼——一件能看穿任何伪装的古老维库人神器。你的搜寻途经噬魂之喉，深入黑鸦堡垒闹鬼的深处，在那里找回了神器，并破译了一封信件，揭示了敌人渗透的真正规模。"
L["Valeera Sanguinar tracked a pair of shadow-forged blades to a demonic vault hidden between worlds. You fought through the Twisting Nether itself, confronting the demon Val'zuun who guarded the Fangs of the Devourer. The blades pulsed with hunger as you claimed them — weapons that devoured souls and grew stronger with every kill."] = "瓦莉拉·萨古纳尔追踪到一对暗影铸造的刀刃，它们藏在一座位于世界之间的恶魔宝库中。你一路杀穿扭曲虚空，与守护吞噬者之牙的恶魔瓦尔祖恩正面交锋。当你取得这对刀刃时，它们因饥渴而脉动——这是吞噬灵魂、每杀一人便更加强大的武器。"
L["Valewalker Farodin"] = "山谷行者法罗丁"
