L["Walk north through the ruin of Scourgeholme and onto the high plateau of Crusaders' Pinnacle."] = "向北穿过天灾城的废墟，登上北伐军之峰的高原。"
L["Walk of Faith"] = "与信仰同行"
L["Walk the long road that turned Prince Arthas Menethil into the Lich King, and the longer road taken by those who march north to face him. It begins in Stratholme, where a prince makes an unforgivable choice in the name of salvation.\n\nBetween that memory and Icecrown lie the dragon-haunted plains of Dragonblight, the howling reach of Northrend, and a campaign waged in the long shadow of Frostmourne."] = "走过那条让阿尔萨斯·米奈希尔王子变成巫妖王的漫长道路，以及那些挥师北上与他对决之人所走的更漫长的道路。一切始于斯坦索姆，一位王子以救赎之名做出了不可饶恕的抉择。\n\n在那段记忆与冰冠冰川之间，横亘着巨龙出没的龙骨荒野平原、狂风呼啸的诺森德大地，以及一场在霜之哀伤的漫长阴影下进行的战役。"
L["Walk the saronite tunnels below Ymirheim and test what the whispers can do to a soldier's mind."] = "走进伊米海姆地下的萨隆邪铁隧道，看看那些低语能对一名士兵的心智造成什么影响。"
L["Walk with Lor'themar through the memory of Quel'Thalas and what the Sin'dorei lost when Arthas marched on Silvermoon. The grief is older than many kingdoms, and the silence the Scourge left behind still has weight.\n\nStand where names are remembered, face old wounds with care, and honor the heritage of a people whose line endured even when the kingdom nearly did not."] = "与洛瑟玛一同重温奎尔萨拉斯的记忆，以及阿尔萨斯进军银月城时辛多雷所失去的一切。这份悲痛比许多王国还要古老，天灾军团留下的沉默至今依然沉重。\n\n站在那些名字被铭记的地方，以谨慎之心面对旧日的创伤，向一个民族的传承致敬——即便王国几近覆灭，他们的血脉依然延续。"
