L["When Smoochums was found in the woods, Abby was gone. In her place: a register listing every Glenbrook villager — most names struck through. Jonathan Hayes had his heart removed for a ritual. Samuel Hawthorne lay dead in the trees. Mary Hayes had turned witch and killed her own husband. Only Annie Warren survived, barely, imprisoned in a cave.\n\nAbby came back. She led you to a circle of candles with Smoochums — the cat, now sacrificed — at the center. She poured the tea. She said there was one more guest to meet. Then she ran, and the Conjured Horror arrived in her place."] = "人们在树林里找到亲亲的时候，艾比已经不见了。取而代之的是一本登记册，上面列着格伦布鲁克每一位村民的名字——大多数都被划掉了。乔纳森·海斯的心脏被挖出用于仪式。萨缪尔·霍索恩死在树林中。玛丽·海斯变成了女巫，杀死了自己的丈夫。只有安妮·沃伦勉强活了下来，被囚禁在一个山洞里。\n\n艾比回来了。她领着你来到一圈蜡烛前，中央摆着亲亲——那只猫，如今已成了祭品。她倒了茶。她说还有一位客人要见。然后她跑开了，召唤来的恐魔取代她出现在眼前。"
L["When Spirits Whisper"] = "灵魂低语之时"
L["When Spiritwalker Ussoh's vision revealed Baine's imminent execution, Lor'themar gathered a small band of rebels — Thrall, Saurfang, and others. You infiltrated Orgrimmar's depths, fought through Sylvanas's forces, and rescued Baine from his cell. Jaina Proudmoore, of all people, helped you escape. The Horde was fracturing, and this was just the beginning."] = "当灵魂行者乌索的幻象揭示贝恩即将被处决时，洛瑟玛召集了一小队反叛者——萨尔、萨鲁法尔，还有其他人。你潜入奥格瑞玛深处，杀穿希尔瓦娜斯的部队，把贝恩从牢房中救了出来。出人意料的是，帮助你们逃脱的竟是吉安娜·普罗德摩尔。部落正在分裂，而这仅仅是开始。"
L["When the gate went quiet and Sylvanas left, Lilian Voss was already in the room. Baine, Lor'themar, Ji Firepaw — all the leaders who had waited out the war with their doubts held close — and the question nobody wanted to be first to say: what do they do about the Warchief's throne? Before the full council assembled, Lilian stepped away from the main hall to arrange a quieter meeting — Forsaken leadership, Calia Menethil, and Derek Proudmoore. Hidden, necessary, and entirely hers to broker. Then she came back into the room and made the case for leaving the throne empty. No single voice. A council, where every people kept their own weight and no one leader could burn the world on a private conviction. She had spent years being used by the powerful as a tool. She knew exactly what concentrated authority looked like from the receiving end. The others listened. They agreed. It was the first time Lilian Voss had spoken in a room full of power and been heard."] = "当大门归于沉寂、希尔瓦娜斯离去时，莉莉安·沃斯早已身在那个房间里。贝恩、洛瑟玛、季·火掌——所有那些将疑虑深藏心底、熬过了这场战争的领袖都在场——还有一个谁都不愿第一个说出口的问题：大酋长的王座该怎么办？在全体议会召开之前，莉莉安离开主厅，安排了一场更隐秘的会面——被遗忘者的领袖们、佳莉娅·米奈希尔，以及德里克·普罗德摩尔。这场会面隐秘而必要，完全由她一手促成。随后她回到房间，力主让王座空悬。不要一个人说了算。要一个议会，让每个民族都保有自己的分量，任何一位领袖都无法凭一己之念焚毁世界。多年来，她一直被权贵当作工具利用。她太清楚身处集中的权力之下是什么滋味了。其他人听了进去，并且同意了。这是莉莉安·沃斯第一次在满是权势者的房间里开口，并被人倾听。"
L["When the Peak of Serenity falls to the Legion, the monks rally at the Temple of Five Dawns on the Wandering Isle. Their order bends, breathes, and returns to its center.\n\nAs Grandmaster, defend sacred training grounds, recruit legendary warriors, and seek the old brews and older lessons that turn discipline into strength."] = "当晴日峰落入燃烧军团之手，武僧们在迷踪岛的五晨寺重新集结。他们的组织弯而不折，调整呼吸，重归中心。\n\n作为宗师，保卫神圣的修行之地，招募传奇战士，寻访古老的酒酿和更古老的教诲，将自律化为力量。"
L["When There's a Will, There's a Way"] = "有志者事竟成"
L["Where Are They Coming From?"] = "它们从哪儿来的？"
L["Where Dragons Fell"] = "巨龙的墓地"
L["Where In the World is Mathias?"] = "马迪亚斯究竟在哪？"
L["Where is Prince Renathal?"] = "雷纳索尔王子在哪里？"
L["Where the Hammer Falls"] = "毁灭之锤的下落"
L["Whispers in the Void"] = "虚空低语"
L["Wicked Wikkets"] = "邪恶的无毛怪"
L["Will of the Valarjar"] = "瓦拉加尔的意志"
L["Will to Survive"] = "生存意志"
L["Win back the Anvil-Thane's designs and reforge Dark Iron pride through craft and grit."] = "夺回铁砧领主的设计图，以匠艺与坚毅重铸黑铁矮人的荣耀。"
L["Wings of the Red Flight"] = "红龙军团之翼"
L["Wintergarde Keep clings to the broken edge of the Dragonblight, pinned between Naxxramas overhead and the plaguebearers boiling up from the Carrion Fields. Duke August Foehammer holds what he can. The 7th Legion bleeds for every mile of frozen ground. High Commander Wyrmbane has orders from Highlord Bolvar Fordragon — push east, past the dragonshrines, toward a black gate in a black mountain."] = "暮冬要塞紧紧依附在龙骨荒野破碎的边缘，夹在头顶的纳克萨玛斯与从腐肉旷野涌出的瘟疫散播者之间。奥古斯特公爵竭力坚守着能守住的一切。第七军团为每一里冰冻的土地流血牺牲。高级指挥官龙誓接到了大领主伯瓦尔·弗塔根的命令——向东推进，越过龙族圣地，直抵一座黑色山脉中的黑色大门。"
L["Wise Mari"] = "贤者马里"
L["Witch Doctor Kejabu"] = "巫医克加布"
L["Witch Doctor Kejabu had a plan that required a certain willingness to look like the enemy. Disguised as blood trolls, you slipped into Zalamar, one of the blood cult's most fortified settlements. Inside you found something worse than blood trolls: Hir'eek, the bat loa, had turned. Corrupted by G'huun's influence, the loa now fed on his own people, demanding sacrifice. A corrupted loa was more dangerous than no loa at all. You poisoned the blood troll's brood, stripped away their rituals, and faced Hir'eek at the heart of his lair. The bat loa fell. It was not a victory to celebrate."] = "巫医克加布有一个计划，需要你甘愿装扮成敌人的模样。你伪装成血巨魔，潜入了血之教派戒备最森严的据点之一——扎拉玛。在里面，你发现了比血巨魔更糟糕的东西：蝙蝠之神希里克已经堕落。在戈霍恩的影响下，这位洛阿如今以自己的子民为食，索要献祭。一位堕落的洛阿比没有洛阿更加危险。你毒杀了血巨魔的幼崽，破坏了他们的仪式，在巢穴深处与希里克正面交锋。蝙蝠洛阿倒下了。这并不是一场值得庆祝的胜利。"
L["Witch Doctor Tzadah"] = "巫医特赛达"
L["Witch Hunt"] = "猎巫"
L["Witchrending"] = "裂巫行动"
L["With Air and Earth secured, Fire remained. You entered the Firelands — still scarred from Ragnaros' fall — and found a new Firelord reigning: Smolderon, younger and more calculating than his predecessor. Baron Scaldius served as intermediary while you proved yourself in trials of flame. The Brand of Damnation burned your skin as a mark of passage, and Smolderon's allegiance was won — grudgingly, but bound by elemental law. Rehgar Earthfury joined your champions, and your weapon was reforged with the power of all three elemental lords."] = "风与大地已经稳固，只剩下火焰。你进入了火焰之地——那里仍留着拉格纳罗斯陨落的伤痕——发现一位新的炎魔之王正在统治：斯摩德隆，比他的前任更年轻，也更工于心计。斯卡迪乌斯男爵充当中间人，而你则在烈焰试炼中证明了自己。诅咒烙印灼烧着你的皮肤，作为通行的印记，斯摩德隆的效忠也终于到手——尽管心不甘情不愿，却受元素法则的约束。雷加尔·大地之怒加入了你的勇士行列，你的武器也借三位元素领主的力量重铸一新。"
L["With clever engineering and fearless aerial operations, you dismantled a trogg-backed threat, defeated Sparkspanner, and proved Gnomeregan's ingenuity is stronger than ever."] = "你凭借巧妙的工程技术和无畏的空中行动，瓦解了一场有穴居人撑腰的威胁，击败了斯帕克斯潘纳，证明了诺莫瑞根的创造力比以往任何时候都更加强大。"
L["With Lordaeron newly reclaimed, old enemies resurfaced. The Scarlet Crusade established a foothold in Silverpine Forest, determined to purge the Forsaken from their ancestral lands. Under Lilian Voss's guidance, you gathered alchemical weapons, donned a stolen disguise, slipped into the enemy’s ranks, and opened the way for the Forsaken to strike back in force. When the dust settled, you stood as a proven champion — Forsaken by death, but not by purpose."] = "随着洛丹伦被重新夺回，旧敌再度浮现。血色十字军在银松森林站稳了脚跟，决心将被遗忘者从他们祖先的土地上清除出去。在莉莉安·沃斯的指导下，你收集了炼金武器，换上偷来的伪装，潜入敌人的队伍，为被遗忘者全力反击打开了道路。尘埃落定之后，你已成为一名久经考验的勇士——你因死亡而被遗弃，却从未被使命抛弃。"
L["With Niskara shattered, the Silver Hand stood triumphant. Arator the Redeemer — son of Turalyon and Alleria — joined your order, his half-elven heritage bridging every divide. Then came Lothraxion, a nathrezim infused with the Light itself — living proof that even demons could be redeemed. Lord Maxwell Tyrosus forged your weapon anew and bestowed the title of Highlord upon you — the first since the Lich King destroyed the original Silver Hand. A light in the darkness, brighter than ever."] = "尼斯卡拉粉碎之后，白银之手大获全胜。救赎者阿拉托尔——图拉扬与奥蕾莉亚之子——加入了你的骑士团，他的半精灵血统弥合了一切隔阂。随后到来的是洛萨克森，一位被圣光本身所浸润的纳斯雷兹姆——活生生地证明了即便是恶魔也能得到救赎。玛克斯韦尔·泰罗索斯男爵为你重铸了武器，并授予你大领主的头衔——这是自巫妖王摧毁最初的白银之手以来的第一位。黑暗曙光，比以往任何时候都更加耀眼。"
L["With Prince in Tow"] = "王子随行"
L["With Sinfall secured, the rebellion moves to rescue Prince Renathal from the ruins of his failed uprising."] = "堕罪堡已经稳固，反抗军着手从那场失败起义的废墟中营救雷纳索尔王子。"
L["With Sylvanas defeated and the war over, Lilian Voss and Calia Menethil lead the Forsaken back to Lordaeron. The city is choked with Blight, the halls of Undercity dark and half-collapsed. Together they fight to reclaim it — cleansing what can be saved, burying what cannot — and at the end, form the Desolate Council: a governing body the Forsaken chose for themselves."] = "希尔瓦娜斯被击败，战争结束，莉莉安·沃斯和佳莉娅·米奈希尔带领被遗忘者回到洛丹伦。城中疫病弥漫，幽暗城的厅堂黑暗而半已坍塌。她们并肩奋战，收复家园——净化尚能挽救的，埋葬无法挽回的——最终组建了荒芜议会：一个由被遗忘者自己选择的治理机构。"
L["With the Idol recovered, recruit Hamuul and Mylune as champions and power the Dreamgrove's portal to prepare for the final battle."] = "找回神像后，招募哈缪尔和米露恩成为勇士，并为梦境林地的传送门注入力量，为最终决战做好准备。"
L["With the Serpent's Heart restored, you travel to Yu'lon's temple and help the sages prepare for her rebirth."] = "神龙之心修复后，你前往玉珑的寺院，协助贤者们为她的重生做准备。"
L["With the south secured, Marshal Reade led the march on Corlain — the ancestral seat of House Waycrest, now a fortress of the Heartsbane Coven. The first watch was grim: the town was sealed behind a magical barrier that killed anything that touched it. Inquisitor Notley scouted the approach while you gathered precious metals and crafted an improvised arsenal of witchrending weapons. Lucille herself struck the final blow against the barrier, shattering it with the Order's combined power. The road to Waycrest Manor was open."] = "南部稳固之后，里德元帅率军向克莱因进发——那里是维克雷斯家族的祖传领地，如今已成了噬心女巫团的要塞。第一座塔楼的情况十分严峻：小镇被一道魔法屏障封锁，任何触碰它的东西都会丧命。审判官诺特利侦察了进军路线，你则收集贵金属，打造了一批临时的破巫武器。最终，露希尔亲自对屏障发出致命一击，以骑士团的合力将其粉碎。通往维克雷斯庄园的道路已经打开。"
L["With the Unseen Path established, you set about building its strength. Loren Stormhoof was the first to answer the call, pledging as champion. Tactician Tinderfell organized scouts and soldiers, dispatching them across the Broken Isles to gather intelligence and hold the line while you prepared for the greater battles ahead."] = "无形之路建立之后，你开始着手壮大它的力量。罗伦·雷蹄是第一个响应号召的人，宣誓成为你的勇士。战术家蒂德菲尔组织了斥候和士兵，将他们派往破碎群岛各地收集情报、坚守防线，而你则为前方更大的战斗做准备。"
L["Word came of monks captured by the vrykul in Stormheim. Angus Ironfist, a massive Pandaren brawler, led you into the frozen north where your brothers and sisters were being held. You quelled the tide of enemies, rebuilt the shattered defenses brick by brick, and freed every last monk. Hiro — a humble fighter who became a hero that day — and Sylara Steelsong joined your growing roster of champions. No monk would be left behind."] = "传来消息称有武僧被风暴峡湾的维库人俘虏。高大魁梧的熊猫人格斗家安古斯·铁拳带领你前往冰封的北方，你的兄弟姐妹们就被关押在那里。你遏止了敌人的攻势，一砖一瓦地重建了破碎的防御，并救出了每一位武僧。希罗——一位在那天成为英雄的谦逊战士——和赛莱拉·钢咏加入了你日益壮大的勇士名册。没有一位武僧会被抛下。"
L["Word on the Winds"] = "风中的话语"
L["Worthy of the Title"] = "名副其实"
L["Wounds Beyond Flesh"] = "超越血肉的伤口"
L["Wrath and Justice"] = "愤怒与正义"
L["Wrath of the Lich King"] = "巫妖王之怒"
L["Writing on the Wall"] = "天灾之祸"
L["Written in Stone"] = "铭撰于石"
L["Wyrmrest Temple, Dragonblight"] = "龙眠神殿（龙骨荒野）"
L["Xal'atath, Blade of the Black Empire"] = "萨拉塔斯，黑暗帝国之刃"
L["Xiao"] = "晓"
L["Xiao, the Eater"] = "贪吃的晓"
L["Yalia Sagewhisper"] = "雅丽亚·圣言者"
L["Years later, Lilian served the Horde on the shores of Kul Tiras. While Nathanos Blightcaller secured a mountain outpost, Lilian led you through Bridgeport — sabotaging foundries, planting explosives, and riding through the flames of your own making. She was efficient, ruthless, and completely in her element. The girl who once trembled in Deathknell was gone."] = "多年以后，莉莉安在库尔提拉斯的海岸为部落效力。纳萨诺斯·凋零者负责夺取一处山地前哨，莉莉安则带你穿过桥港——破坏铸造厂、安放炸药，在你们亲手点燃的烈焰中策马穿行。她干练、冷酷，如鱼得水。那个曾在丧钟镇瑟瑟发抖的女孩已经不复存在了。"
L["Years passed before Lilian surfaced again — this time as a hooded figure lurking inside the Scarlet Halls. She hired you to slaughter your way through the Crusade's ranks and steal their membership records. Every name on that list was a target. Lilian Voss was no longer running from the Crusade — she was hunting them down, one by one."] = "多年后，莉莉安才再次现身——这一次，她是一个潜伏在血色大厅中的兜帽人影。她雇用你杀穿十字军的队伍，偷走他们的成员名册。名单上的每一个名字都是一个目标。莉莉安·沃斯不再逃避十字军——她正在逐一追猎他们。"
L["Yeti to Rumble"] = "雪人来袭"
L["You answered Khadgar's call and journeyed into the ancient city of Suramar, finding it sealed behind a shimmering barrier of arcane power. Beyond the wall, you discovered First Arcanist Thalyssra — once a leader of the Nightborne, now exiled and starving for mana. Together you claimed the ruins of Shal'Aran as a hidden refuge, a fragile spark of rebellion in the shadow of the Grand Magistrix."] = "你响应卡德加的召唤，深入古城苏拉玛，却发现它被一道闪烁的奥术屏障所封锁。在屏障之外，你找到了首席奥术师塔莉萨——她曾是夜之子的领袖之一，如今却遭到放逐，饱受魔力饥渴的折磨。你们一同占据了沙尔艾兰的废墟，将其作为秘密的避难所——在大魔导师的阴影下，一点脆弱的反抗火花就此燃起。"
L["You built The Uncrowned from a whisper into a force, recruiting legendary rogues like Vanessa VanCleef and Garona Halforcen as champions. From the Chamber of Shadows beneath Dalaran, you established a network of operatives across the Broken Isles and ensured the order's school of roguery could train the next generation of shadows."] = "你将无冕者从一句低语壮大为一股力量，招募了梵妮莎·范克里夫和半兽人迦罗娜等传奇盗贼作为勇士。你以达拉然地下的暗影大厅为据点，在破碎群岛各地建立了特工网络，并确保了组织的盗贼学派能够培养下一代暗影行者。"
L["You Can't Take the Sky from Me"] = "别想夺走我的天空"
L["You infiltrated the arcwine vineyards that kept Suramar's populace docile and dependent on Elisande's generosity. Working with Vintner Iltheux and the defiant Margaux, you sabotaged the production, poisoned the supply, and struck at the very system of control the Grand Magistrix had built. When Margaux fell to the Duskwatch's retribution, you ensured her sacrifice was not in vain — the rebellion now had its own supply of arcwine and the loyalty of those she inspired."] = "你潜入了奥术酒葡萄园——正是这些葡萄园让苏拉玛的民众温顺驯服，依赖着艾利桑德的施舍。你与酿酒师伊苏克斯和不屈的玛尔迦合作，破坏生产，在供应中下毒，打击大魔导师亲手建立的控制体系。当玛尔迦倒在暮色卫队的报复之下时，你确保了她的牺牲没有白费——反抗军如今拥有了自己的奥术酒来源，也赢得了那些受她感召之人的忠诚。"
L["You located Chief Telemancer Oculeth in his ruined workshop, surrounded by the wreckage of his life's work. Together you restored fragments of the ancient telemancy network, reactivating portals that would allow the rebels to move unseen across Suramar. The old telemancer's genius may have dulled with hunger, but his loyalty to Thalyssra never wavered."] = "你在首席传送师欧库勒斯残破的工坊里找到了他，他身边满是毕生心血的残骸。你们一同修复了古老传送网络的碎片，重新激活了传送门，让反抗军能够在苏拉玛各处秘密行动。这位年迈传送师的天才也许已因饥饿而黯淡，但他对塔莉萨的忠诚从未动摇。"
L["You opened your eyes in the crypt of Deathknell, raised by the Val'kyr as one of the Forsaken. Among the newly risen was a young woman trembling with rage — Lilian Voss, daughter of the Scarlet Crusade's High Priest. While you accepted your new existence, she could not. She fled into the darkness, refusing to believe what she had become."] = "你在丧钟镇的墓穴中睁开双眼，被瓦格里复活为被遗忘者的一员。在新近复生的人中，有一位因愤怒而颤抖的年轻女子——莉莉安·沃斯，血色十字军高阶牧师的女儿。你接受了自己的新生，她却无法接受。她逃进了黑暗，拒绝相信自己变成了什么。"
L["You slipped into the Waning Crescent, a forgotten slum where nightfallen refugees huddled in the shadows of Suramar City. Working alongside Silgryn, you established supply lines, freed imprisoned allies, and built a network of safe houses right beneath the Duskwatch's nose. What began as a handful of desperate exiles became the backbone of an underground resistance."] = "你潜入了残月区——苏拉玛城中一片被遗忘的贫民窟，堕夜精灵难民蜷缩在阴影之中。你与希尔格林并肩合作，建立了补给线，解救了被囚禁的盟友，并在暮色卫队的眼皮底下建起了一张安全屋网络。起初只是寥寥几个走投无路的流亡者，最终却成了一支地下抵抗力量的中坚。"
L["You ventured into the ley line tunnels beneath Suramar, fighting corrupted creatures to restore the flow of ancient mana to Shal'Aran. The cavern hummed back to life as power surged through its crystalline conduits, giving the nightfallen refugees a lifeline against the withering that threatened to consume them all."] = "你深入苏拉玛地下的魔网隧道，与被腐化的生物战斗，让古老的魔力重新流向沙尔艾兰。随着能量涌过水晶导管，洞穴再度嗡鸣着恢复了生机，为堕夜精灵难民提供了一条生命线，使他们得以抵御那场险些吞噬所有人的枯萎。"
L["You're Either With Us Or..."] = "要么服从要么……"
L["Your Attention, Please"] = "请留意一下……"
L["Your Training Starts Now"] = "训练开始"
L["Yu'lon's rebirth did not end the war. It only made the cost clearer. The Alliance returned to Pearlfin Village; the Horde returned to Grookin Hill. Both sides prepared their local allies for the next blow, and Cho called for help with the last piece of an ancient puzzle. Then the seal broke. The Serpent's Heart cracked under the weight of fear, anger, and suspicion. Jade became weapon and prison, friends were scattered in the fallout, and the Sha of Doubt rose from the ruin. The Jade Forest's lesson had become impossible to ignore: the enemy was not only across the battlefield."] = "玉珑的重生并没有终结战争，只是让代价变得更加清晰。联盟回到了珠鳍村，部落回到了古鲁金猴山。双方都在为下一轮打击训练各自的本地盟友，而周卓则请求帮助，以拼好一个古老谜题的最后一块。然后，封印破碎了。神龙之心在恐惧、愤怒与猜疑的重压下裂开。玉石化为武器与牢笼，朋友们在余波中四散，疑之煞从废墟中升起。翡翠林的教训已无法忽视：敌人并不只在战场的另一边。"
L["Zabra Hexx"] = "扎布拉·海克斯"
