L["Executor Arren"] = "执行官阿伦"
L["Find Myranda"] = "寻找麦兰达"
L["For the Alliance, the Scarlet Crusade first looked like a distant Lordaeron problem: troubling enough for Brother Crowley to send word to Brother Anton, and troubling enough for Anton to send you onward. Raleigh the Devout understood what the red tabards meant. The Monastery was not merely a garrison. It was the heart of a militant faith losing its way."] = "对联盟而言，血色十字军起初看起来只是远在洛丹伦的麻烦：麻烦到足以让克罗雷修士给安东修士捎信，也麻烦到足以让安东把你继续派往前方。虔诚的莱雷恩明白那些红色战袍意味着什么。修道院不仅仅是一座驻军要塞，更是一个正在迷失方向的激进信仰的核心。"
L["Graveyard and Library"] = "墓地与图书馆"
L["Hearts of Zeal"] = "狂热之链"
L["Hearthglen, Western Plaguelands"] = "壁炉谷（西瘟疫之地）"
L["High Inquisitor Whitemane"] = "大检察官怀特迈恩"
L["In Dreams"] = "在梦中"
L["In the Name of the Light"] = "以圣光之名"
L["Into The Scarlet Monastery"] = "深入血色修道院"
L["Librarian Mae Paledust"] = "图书馆员麦伊·苍尘"
L["Mythology of the Titans"] = "泰坦神话"
L["Myranda the Hag"] = "巫女麦兰达"
L["Nijel's Point, Desolace"] = "尼耶尔前哨站（凄凉之地）"
