L["After the first foothold in Zereth Mortis was secured, Uther arrived in Haven with news from Oribos: Sylvanas had awakened. Her soul had been split since Frostmourne killed her, and the restored fragment forced her to face the Banshee Queen's atrocities as her own. In the vision Uther shared, the Ranger-General saw Teldrassil burn, rejected the comfort of pretending those crimes belonged to someone else, and chose to wake. The campaign then turned back to Zereth Mortis. Elder Ara led you through a pilgrimage to repair the ancient translocator to the Sepulcher. At the end, Sylvanas stood with Uther, Jaina, and Bolvar before the raid entrance. She knew Anduin was the key, and Uther convinced Jaina to let Sylvanas help free him."] = "在扎雷殁提斯站稳第一处立足点后，乌瑟尔带着奥利波斯的消息来到避难所：希尔瓦娜斯醒了。自从被霜之哀伤杀死以来，她的灵魂便一直处于分裂状态，而归位的碎片迫使她将女妖之王的暴行视为自己的罪孽。在乌瑟尔分享的幻象中，这位游侠将军目睹泰达希尔燃烧，拒绝以“那些罪行属于别人”来自我安慰，并选择了醒来。随后，战役重新转回扎雷殁提斯。长者亚莱带领你完成了一场朝圣之旅，修复了通往圣墓的古老传送装置。最后，希尔瓦娜斯与乌瑟尔、吉安娜和伯瓦尔一同站在团队副本入口前。她知道安度因是关键，而乌瑟尔说服了吉安娜，让希尔瓦娜斯帮助解救他。"
L["Aggressive Excavation"] = "积极发掘"
L["Anduin has been rescued, but the Jailer still commands Domination. Bolvar and the Primus seek a way to turn the broken helm into a weapon of free will."] = "安度因已被救出，但典狱长仍掌控着统御之力。伯瓦尔和兵主正在寻找方法，将破碎的头盔化为自由意志的武器。"
L["After Anduin was freed, the way forward was still blocked by the Jailer's Domination magic. Bolvar, Darion, Anduin, and Sylvanas all carried scars from the helm, the blade, or the will behind them. Their memories became part of the answer. In Bastion, Sylvanas faced the wound of what she had done and named the truth plainly: there was no absolution waiting inside a shard of memory, only the choice to keep resisting. The Primus reforged the Helm of Domination into the Crown of Wills, a symbol not of command, but of defiance. With it, Zovaal could finally be faced."] = "安度因获救后，前路依然被典狱长的统御魔法所阻断。伯瓦尔、达里安、安度因和希尔瓦娜斯身上都留着那顶头盔、那把剑或其背后意志所造成的伤痕。他们的记忆成了答案的一部分。在晋升堡垒，希尔瓦娜斯直面自己所作所为留下的伤口，坦然道出了真相：记忆碎片中并没有等待着她的赦免，只有继续抵抗的选择。兵主将统御头盔重铸为意志头盔——它所象征的不是支配，而是反抗。有了它，终于可以直面佐瓦尔了。"
L["A Gathering of Covenants"] = "盟约集会"
L["Anduin steals the Archon's sigil, and Sylvanas moves on Ardenweald. Tyrande finally catches her in the Heart of the Forest."] = "安度因盗走了执政官的印记，希尔瓦娜斯随即向炽蓝仙野进发。泰兰德终于在森林之心追上了她。"
L["Before the assault on the Sanctum, Bolvar saw fragments of what was happening inside Torghast. The Jailer forged Kingsmourne, a mourneblade shaped around Anduin's own weapon and a soul crystal. Sylvanas brought the blade to Anduin and demanded he join their cause willingly or be made to serve. Anduin saw the wound she was trying to hide: she kept offering him the choice Arthas had stolen from her. Blizzard later removed or auto-completed much of this Torghast questline for catch-up characters, but the vision is the emotional bridge into Chains of Domination."] = "在进攻圣所之前，伯瓦尔看到了托加斯特内部所发生之事的片段。典狱长锻造了王之哀伤——一把以安度因自己的武器和一块灵魂水晶为核心打造的哀伤之刃。希尔瓦娜斯把剑交给安度因，要求他心甘情愿地加入他们，否则就将被迫效命。安度因看穿了她试图隐藏的伤口：她一再给他的，正是阿尔萨斯从她手中夺走的那个选择。暴雪后来为追赶进度的角色移除或自动完成了这条托加斯特任务线的大部分内容，但这段幻象是通往统御之链的情感桥梁。"
L["Begins after your covenant campaign reaches The Search for Baine. Later characters may be offered a skip to Korthia; skipping completes this chapter."] = "在你的盟约战役进行到“寻找贝恩”后开始。较晚的角色可能会获得直接跳至刻希亚的选项；选择跳过将完成本章。"
L["Bolvar's visions reveal the Jailer's next weapon: Anduin, bound to a mourneblade. Sylvanas still tries to call it a choice."] = "伯瓦尔的幻象揭示了典狱长的下一件武器：被束缚在哀伤之刃上的安度因。希尔瓦娜斯仍试图将其称为一个选择。"
L["Can't Turn Our Backs"] = "绝不背弃"
L["Chains of Domination"] = "统御之链"
L["Complete Zereth Mortis campaign chapter 3, Forming an Understanding. This becomes available from Uther in Haven after The Way Forward."] = "完成扎雷殁提斯战役第3章“达成共识”。完成“前进之路”后，可从避难所的乌瑟尔处接取。"
