L["The assault on the Sanctum of Domination carried the covenants into the Jailer's seat of power. Sylvanas waited at the top of Torghast, fighting across shattered chains and the edge of the Maw while the Jailer dragged Oribos toward his prison. When Zovaal spoke of remaking reality so all would serve, Sylvanas finally heard Arthas in his words. She turned on him. The Jailer answered by returning the soul fragment Frostmourne had torn from her at Silvermoon, then left her unconscious at the mercy of those she had betrayed. She was defeated, but not judged. Not yet."] = "对统御圣所的进攻将各大盟约带入了典狱长的权力中枢。希尔瓦娜斯在托加斯特之巅等待着，在破碎的锁链和噬渊的边缘战斗，而典狱长则将奥利波斯拖向他的牢狱。当佐瓦尔说起要重塑现实、让万物为他效命时，希尔瓦娜斯终于从他的话语中听到了阿尔萨斯的声音。她转而反抗他。典狱长的回应是归还了当年霜之哀伤在银月城从她身上撕下的灵魂碎片，然后将昏迷的她丢给那些被她背叛的人发落。她被打败了，但尚未受审。还没有。"
L["The covenants assault the Jailer's fortress in Torghast. At the summit waits Sylvanas, and the battle ends with the choice that makes News from Oribos possible."] = "各大盟约向典狱长在托加斯特的堡垒发起进攻。希尔瓦娜斯在顶端等待着，而这场战斗最终以一个抉择收场，正是这个抉择让“奥利波斯的消息”成为可能。"
L["The path through the Sepulcher reaches Anduin at last. Freeing him from Kingsmourne sets the stage for the Crown of Wills."] = "穿越圣墓的道路终于抵达了安度因身边。将他从王之哀伤中解放出来，为意志头盔的诞生铺平了道路。"
L["Within the Sepulcher, the heroes found Anduin still bound to the Jailer's will. The fight was not only to defeat him, but to reach the part of him still resisting. In the end, Anduin found the strength to help shatter Kingsmourne from within. Sylvanas's warning had been true: saving Anduin was the key to opposing Zovaal's design."] = "在圣墓中，英雄们发现安度因仍被典狱长的意志所束缚。这场战斗不仅是为了击败他，更是为了触及他内心仍在抵抗的那一部分。最终，安度因找到了力量，从内部协助粉碎了王之哀伤。希尔瓦娜斯的警告没有错：拯救安度因正是对抗佐瓦尔计划的关键。"
L["Take Charge"] = "能量释放"
L["Testing One Two"] = "做个小测试"
L["The Broken Crown"] = "破碎冠冕"
L["The Battle of Ardenweald"] = "炽蓝仙野之战"
L["The Crown of Wills"] = "意志头盔"
L["The First Move"] = "第一步"
L["The Heart of Ardenweald"] = "炽蓝仙野之心"
L["The Jailer's next move began in Bastion. Anduin, dominated through Kingsmourne, struck down the Archon and took her sigil while Sylvanas watched the plan unfold. Bolvar gathered the covenants in Oribos, and the war rushed to Ardenweald before the Winter Queen's sigil could be taken next. There, beneath the Heart of the Forest, Tyrande Whisperwind caught Sylvanas at last. Elune's wrath burned through her, but the Night Warrior's power faded before the killing blow. Sylvanas escaped, and the covenants turned toward Korthia and the Sanctum of Domination."] = "典狱长的下一步行动始于晋升堡垒。通过王之哀伤被统御的安度因击倒了执政官，夺走了她的印记，而希尔瓦娜斯则在一旁注视着计划展开。伯瓦尔在奥利波斯召集了各大盟约，战火随即迅速蔓延至炽蓝仙野，要赶在寒冬女王的印记被夺走之前。在那里，在森林之心下方，泰兰德·语风终于追上了希尔瓦娜斯。艾露恩的怒火在她身上燃烧，但暗夜战士的力量在致命一击落下之前就消散了。希尔瓦娜斯逃脱了，各大盟约将目光转向了刻希亚和统御圣所。"
L["The Not-Scientific Method"] = "不科学的实验"
L["The Pilgrim's Journey"] = "朝圣之旅"
L["The Pilgrimage Ends"] = "朝圣终点"
L["The Primus"] = "兵主"
L["Torghast Visions"] = "托加斯特幻象"
L["Two Paths to Tread"] = "其它的道路"
L["Unchecked Growth"] = "失控蔓生"
L["Uther appears in Haven with news from Oribos. Sylvanas has awakened, but reaching the Sepulcher means earning the Enlightened's help first."] = "乌瑟尔带着奥利波斯的消息出现在避难所。希尔瓦娜斯已经醒来，但要抵达圣墓，必须先赢得开悟者的帮助。"
L["What Makes Us Strong"] = "我们强大的理由"
L["What We Overcome"] = "我们克服的困难"
L["What We Wish to Forget"] = "所愿遗忘之事"
L["Where the Memory Resides"] = "回忆留存之所"
L["Where There's a Pilgrim, There's a Way"] = "条条大路通圣地"
L["Voices of the Eternal"] = "永恒者之声"
L["overlook behind Pilgrim's Grace"] = "朝圣者之恩后方的瞭望点"
L["A Cage for Alleria"] = "奥蕾莉亚的笼子"
L["A vision of Quel'Thalas in shadow sends Arator looking for the Windrunners. His search reaches the Maw, where Sylvanas is still freeing the souls she condemned."] = "一幅暗影笼罩奎尔萨拉斯的幻象，促使阿拉托尔去寻找风行者家族。他的搜寻抵达了噬渊，希尔瓦娜斯仍在那里解救那些被她判下厄运的灵魂。"
L["A Void Test of Wills"] = "虚空意志试炼"
L["Alleria Windrunner"] = "奥蕾莉亚·风行者"
L["Arator"] = "阿拉托尔"
L["Be careful with the Threads of Fate choice from Fatescribe Roh-Tahl in Oribos. Choosing Threads of Fate skips the Shadowlands leveling campaign and marks Revendreth's main story quests complete, so use the replay storyline option if you want to play this chapter."] = "从奥利波斯的命运撰写师罗-塔尔那里选择“命运之线”时要小心。选择“命运之线”会跳过暗影国度的升级战役，并将雷文德斯的主线剧情任务标记为已完成；如果你想体验这一章，请选择重温故事线的选项。"
L["Blessings Be Upon You"] = "祝福降临于你"
L["Bringer of the Void"] = "虚空的使者"
L["Chaos Control"] = "混乱控制"
L["Determination"] = "坚定不移"
L["Distant Echoes"] = "遥远的回响"
