L["Tag, You're It"] = "给他贴标签"
L["The Eleventh Hour"] = "最后关头"
L["The Final Hazard"] = "终极隐患"
L["The Long Vigil"] = "漫长的守望"
L["The Parent Trap"] = "父母陷阱"
L["The Warning"] = "警告"
L["Those As Well"] = "那些也要"
L["To Cleanse Shadow's Stain"] = "清除暗影污秽"
L["Ve'nari"] = "威·娜莉"
L["Vereesa Windrunner"] = "温蕾萨·风行者"
L["Vereesa's Tale"] = "温蕾萨的故事"
L["What Might Come"] = "未知已至"
L["Where in K'aresh is Alleria Windrunner?"] = "奥蕾莉亚在何方？"
L["Your trainer sends you to Moonglade for lessons that cannot be taught in a city. The Cenarion Circle has work for young druids who are ready to listen to spirits, heal sick beasts, and follow the call of distant waters."] = "你的训练师派你前往月光林地，学习那些在城市里学不到的课程。塞纳里奥议会有一些任务，要交给那些已准备好倾听灵魂、治愈病兽、追随远方水域召唤的年轻德鲁伊。"
L["Speak with Duthorian Rall and take up the Tome of Valor. A paladin's lessons are not only prayers; they ask for aid given, judgment shown, and materials gathered with care.\n\nFollow the order's tests from early duty to the rites reserved for those who have carried the Light long enough to be trusted with more."] = "与达索瑞恩·拉尔交谈，接过勇气之书。圣骑士的课程不只是祈祷；它们要求你援助他人、展现公正的判断，并用心收集材料。\n\n从早期的职责开始，一路完成骑士团的考验，直至那些专为长久承载圣光、值得被托付更多的人所保留的仪式。"
L["Master Mathias Shaw and Shenthul do not teach by lecture. They send rogues into guarded places, locked boxes, and situations where an antidote matters as much as a blade.\n\nBegin with your faction's poison work, then follow the hints that lead beyond city trainers into a wider trade of signals and reputation."] = "马迪亚斯·肖尔大师和申苏尔不靠说教来教学。他们把盗贼派往戒备森严的地方、上锁的箱子前，以及那些解毒剂和刀刃同样重要的局面中。\n\n从你所属阵营的毒药任务开始，然后循着线索走出城市训练师的范围，进入一个由暗号与声望构成的更广阔的行当。"
L["Your first totem begins with a call, not a command. The elements answer through trials, offerings, and long walks between trainers, spirits, and hidden shrines.\n\nFollow earth, fire, water, and air as each power is earned in turn. Later, the same lessons point toward a deeper test of balance."] = "你的第一个图腾始于一声召唤，而非一道命令。元素通过试炼、供奉，以及在训练师、灵魂和隐秘神龛之间的漫长跋涉作出回应。\n\n追随大地、火焰、水与空气，依次赢得每一种力量。之后，同样的课程将指向一场更深层的平衡考验。"
L["Warlock trainers do not offer power freely. They give names, errands, and circles, then ask whether you can bind what answers.\n\nBegin with the first summons and follow the darker lessons through demons, tomes, mounts, and bargains that always ask for more than coin."] = "术士训练师不会白白赐予力量。他们给你名字、差事和法阵，然后问你能否束缚那些应召而来之物。\n\n从第一次召唤开始，循着更黑暗的课程，穿过恶魔、典籍、坐骑与交易——而这些交易索要的，永远不止金币。"
L["Your warrior trainer has a practical lesson first: learn to stand, endure, and fight with discipline. After that, older tests wait beyond the starting grounds.\n\nSeek the instructors who send warriors to brawls, islands, charms, and a windwatcher's summons. The reward is a weapon, but the road is the real trial."] = "你的战士训练师首先会给你上一堂务实的课：学会站稳、忍耐，并有纪律地战斗。在那之后，更古老的考验在新手区之外等待着你。\n\n去寻找那些教官，他们会把战士派去参加斗殴、前往海岛、寻找护符，并响应风之守望者的召唤。奖励是一把武器，但这条路本身才是真正的试炼。"
L["Apothecary Johaan has work in Brill, and it is not the sort of work the living would approve of. The Forsaken need samples, records, and willing hands if they are to learn what can still kill the dead.\n\nBegin with the Royal Apothecary Society's errands in Tirisfal and follow the plague work into Silverpine and Hillsbrad. Each vial answers one question and raises another."] = "药剂师乔汉在布瑞尔有活要干，而且不是活人会认可的那种。被遗忘者需要样本、记录和愿意出力的人手，才能弄清什么东西仍然能杀死亡者。\n\n从皇家药剂师协会在提瑞斯法林地的差事开始，循着瘟疫研究前往银松森林和希尔斯布莱德。每一个药瓶都解答了一个问题，又引出另一个问题。"
L["North of Brill, the Agamand Mills still carry the family name. Coleman Farthing wants proof of what happened there, Deathguard Dillinger wants the dead cleared out, and Magistrate Sevren has heard enough about the family crypt to be concerned.\n\nSearch the old estate, bring back what the Forsaken ask for, and see why Tirisfal's dead rarely stay where they are put."] = "在布瑞尔以北，阿加曼德磨坊仍冠着这个家族的姓氏。库勒曼·法席恩想要证明那里发生过什么，亡灵卫兵迪林格尔想清除那里的亡者，而执政官塞弗伦对家族墓穴的传闻已经听得够多，不由得忧心忡忡。\n\n搜索这座古老的庄园，带回被遗忘者要求的东西，看看为什么提瑞斯法林地的亡者很少安分地待在原地。"
L["Auberdine's watchers have seen trouble near the Tower of Althalaxx. Speak with Balthule Shadowstrike and learn what the Cult of the Dark Strand is doing on the northern coast.\n\nWhat begins as a report from Darkshore pulls you toward Ashenvale, where parchments, gems, and old corruption point to a threat still gathering strength."] = "奥伯丁的守望者们在奥萨拉克斯之塔附近发现了麻烦。与巴苏尔·影击交谈，查明黑暗之链教派在北部海岸有何图谋。\n\n起初只是一份来自黑海岸的报告，却将你引向灰谷——在那里，羊皮纸、宝石和古老的腐化都指向一个仍在积蓄力量的威胁。"
L["The Sepulcher needs help holding Silverpine Forest. Worgen stalk the roads, Dalaran mages keep their own counsel at Ambermill, and rumors from Shadowfang Keep have not grown quieter.\n\nTake the Forsaken orders one by one and learn why the forest still refuses to be claimed."] = "瑟伯切尔需要人手来守住银松森林。狼人在道路上潜行，达拉然法师在安伯米尔自行其是，而影牙城堡传来的流言也从未平息。\n\n逐一接下被遗忘者的命令，弄明白这片森林为何至今仍拒绝被征服。"
L["High Executor Darthalia has work for anyone willing to serve Tarren Mill. The humans of Hillsbrad still farm, trade, and guard the roads as if the Forsaken claim means nothing.\n\nReport for orders and carry the campaign from the fields to the mines and beyond. Darthalia will tell you who must fall next."] = "高级执行官达萨利亚为所有愿意为塔伦米尔效力的人准备了任务。希尔斯布莱德的人类仍在耕种、贸易和守卫道路，仿佛被遗忘者的领土主张毫无意义。\n\n前去报到领取命令，将战事从田野推进到矿井，乃至更远的地方。达萨利亚会告诉你下一个该倒下的是谁。"
L["Marlene Redpath asks you to find her niece Pamela in Darrowshire. In the ruins, a lonely child is still waiting for family and trying to remember where her doll has gone.\n\nBegin with Pamela's small request and follow the Redpath family through old grief, missing records, and the question of what really happened on Darrowshire's last night."] = "玛莱恩·雷德帕斯请你去达隆郡寻找她的侄女帕米拉。在废墟中，一个孤独的孩子仍在等待家人，努力回想她的娃娃去了哪里。\n\n从帕米拉的小小请求开始，追随雷德帕斯一家穿过往日的悲伤、遗失的记录，以及达隆郡最后一夜究竟发生了什么的谜团。"
L["Deputy Willem has a simple problem near Northshire: thieves in red masks have stolen from the abbey's vineyards. In Elwynn and Westfall, the same masks keep turning up in places they should not.\n\nHelp the local marshals and the People's Militia follow the Defias trail. What begins as bandit work soon asks who is organizing it, and why."] = "维里副队长在北郡附近遇到了一个简单的问题：戴红面具的盗贼从修道院的葡萄园里偷了东西。在艾尔文森林和西部荒野，同样的面具总是出现在它们不该出现的地方。\n\n帮助当地的治安官和人民军追踪迪菲亚的踪迹。起初只是对付土匪的活，但很快你就会追问：是谁在组织这一切，又是为了什么。"
L["Darkshire keeps its lanterns lit because the woods do not. Commander Althea Ebonlocke needs help with the Night Watch, and every road out of town seems to carry another rumor, corpse, or warning.\n\nTake up the town's work and follow Duskwood's troubles as the locals give them to you: graves, worgen, missing people, and names spoken carefully after dark."] = "夜色镇的灯笼始终亮着，因为森林里从不见光。指挥官阿尔泰娅·埃伯洛克需要人手协助守夜人，而每一条出镇的路似乎都会带来新的流言、尸体或警告。\n\n接下镇上的工作，跟随当地人交给你的线索，了解暮色森林的种种麻烦：坟墓、狼人、失踪的人，还有那些天黑后被小心翼翼提起的名字。"
L["At the edge of the Blasted Lands, a fallen hero still waits for orders that never came. His regiment is gone, and the demons beyond Nethergarde have had years to make use of what was left behind.\n\nListen to the dead man's account and follow the scattered trail of soldiers, relics, and old command. The road is long because the failure was not simple."] = "在诅咒之地的边缘，一位陨落的英雄仍在等待那从未到来的命令。他的部队早已不复存在，而守望堡外的恶魔有足足数年时间去利用那些被遗留下来的东西。\n\n倾听这位亡者的讲述，追寻士兵、遗物和旧日指挥留下的零散踪迹。这条路之所以漫长，是因为那场失败并不简单。"
L["Marshal Dughan has posted a bounty at Westbrook Garrison. A Riverpaw brute named Hogger is prowling the woods, and Stormwind wants proof that the roads are safer.\n\nTake the warrant, follow the ridge southwest, and see why the locals speak his name with more concern than a single gnoll should earn."] = "治安官杜汉在西泉要塞发布了悬赏。一个名叫霍格的河爪豺狼人蛮兵正在林中游荡，暴风城需要证据来证明道路变得更安全了。\n\n接下通缉令，沿着山脊向西南前进，看看为什么当地人提起他的名字时，那份担忧远超一只豺狼人应得的分量。"
L["Under the broken Thandol Span, a dwarf's remains lie where few travelers think to look. Among them is a letter that never reached the woman waiting in Ironforge.\n\nCarry Sully Balloo's words home and let Sara Balloo decide what should be done with them. Some duties begin after the battle is already over."] = "在残破的萨多尔大桥下，一名矮人的遗骸躺在少有旅人会留意的地方。遗骸中有一封信，始终没能送到那位在铁炉堡等待的女子手中。\n\n把萨利·巴鲁的话带回家，让萨拉·巴鲁决定该如何处置它们。有些职责，在战斗结束后才刚刚开始。"
L["At the Crossroads, Mankrik is looking for his wife. He last saw her on the Gold Road, and the Barrens offers little comfort to anyone searching through quillboar territory.\n\nTake his question with you into the heat and dust. What you find, if you find anything, belongs first to the husband still waiting."] = "在十字路口，曼科里克正在寻找他的妻子。他最后一次见到她是在黄金之路上，而对于在野猪人领地中搜寻的人来说，贫瘠之地几乎给不了任何安慰。\n\n带着他的疑问走进酷热与尘土。你所发现的一切——如果你能发现什么的话——首先属于那位仍在等待的丈夫。"
L["Feathermoon Stronghold expected a courier from Thalanaar. He never arrived, and the coast of Feralas has a way of swallowing small boats and easy answers.\n\nSearch the wreckage, carry back what proof you can, and follow the signs inland if the sea is not the whole story."] = "羽月要塞一直在等待一名从萨兰纳尔来的信使。他始终没有到达，而菲拉斯的海岸总会吞没小船与简单的答案。\n\n搜索残骸，尽可能带回证据；如果大海并非故事的全部，就循着线索深入内陆。"
L["Thomas has been asked to find an adventurer for Bishop DeLavey in Stormwind Keep. The bishop will not speak of the matter openly, only that discretion matters and the kingdom may have need of you.\n\nBegin in Stormwind and follow a quiet trail of favors, contacts, and rumors. What starts as a missing man soon points beyond a simple disappearance."] = "托马斯受托为暴风要塞的德拉维主教寻找一名冒险者。主教不愿公开谈论此事，只说需要谨慎行事，王国或许需要你的帮助。\n\n从暴风城出发，循着一条由人情、联络人和流言组成的隐秘线索前进。起初只是一个人的失踪，但很快就指向了远比简单失踪更复杂的事情。"
L["In the Burning Steppes, Helendis Riverhorn has orders for the Alliance against black dragonkin gathering near Morgan's Vigil. In Kargath, Warlord Goretooth has a command for the Horde that points into Blackrock Spire.\n\nTake the first report and follow your faction's chain of summons, proofs, and dangerous names. The amulet at the end of the road is not given to anyone who has only heard rumors of dragons."] = "在燃烧平原，赫林迪斯·河角向联盟下达了对付摩根的岗哨附近聚集的黑龙族的命令。在卡加斯，军官高图斯则向部落下达了一道指向黑石塔的指令。\n\n接下第一份报告，循着你所属阵营的召唤、证明与危险名号组成的任务链前进。这条路尽头的护符，不会交给那些只听过巨龙传闻的人。"
L["In Blackrock Depths, rumors about Princess Moira Bronzebeard have become too serious for Ironforge to ignore. The Dark Irons say one thing, the kingdom fears another, and no one outside the mountain has the full truth.\n\nEnter the depths on your faction's orders and find out what became of the princess. Rescue may not be as simple as it sounds."] = "在黑石深渊，有关铁炉堡公主茉艾拉·铜须的传闻已经严重到铁炉堡无法再置之不理。黑铁矮人说的是一回事，王国担心的又是另一回事，而山外没有人知道全部的真相。\n\n奉你所属阵营之命进入深渊，查明公主的下落。营救或许并不像听起来那么简单。"
L["Raene Wolfrunner sends you west from Astranaar to look for Teronis, who went searching for answers to the furbolg attacks and did not return.\n\nFollow his trail through Ashenvale's moonwells, ruins, and old magic. If the forest is being changed, Raene wants to know how, and who is helping it spread."] = "莱恩·狼行者派你从阿斯特兰纳向西出发，寻找特罗尼斯——他去探寻熊怪袭击的原因，却再也没有回来。\n\n循着他的足迹穿过灰谷的月亮井、废墟与古老魔法。如果这片森林正在发生变化，莱恩想知道变化是如何发生的，又是谁在助长它的蔓延。"
L["At Grom'gol, Nimboya asks after Yenniku, youngest son of the Darkspear chief. The Bloodscalp trolls may know where he was taken, but Stranglethorn rarely gives up a captive cleanly.\n\nPress the jungle tribes for answers, listen when older spirits are called, and keep following the trail even when it turns toward magic no troll should take lightly."] = "在格罗姆高，尼姆布亚打听着耶尼库的下落——他是暗矛部族酋长最小的儿子。血顶巨魔或许知道他被带到了哪里，但荆棘谷很少会干干净净地放走一名俘虏。\n\n向丛林部族逼问答案，在古老的灵魂被召唤时侧耳倾听，即便线索转向任何巨魔都不该掉以轻心的魔法，也要继续追寻下去。"
L["The Scarlet Crusade claims to defend Lordaeron from the undead, but its soldiers do not always wait to ask who is innocent. In Tirisfal, Southshore, and the Plaguelands, people have reasons to send you against the red tabard.\n\nFollow the Crusade's trail through farms, prisons, monasteries, and northern keeps. Each order you uncover makes their righteousness harder to trust."] = "血色十字军宣称要保卫洛丹伦免受亡灵侵害，但他们的士兵并不总会先问清楚谁是无辜的。在提瑞斯法林地、南海镇和瘟疫之地，人们都有理由派你去对付那些身穿红色战袍的人。\n\n循着十字军的踪迹，穿过农场、监狱、修道院和北方的要塞。你每揭露一道命令，他们的正义就更难令人信服。"
L["A battered raft in Un'Goro holds a few odd belongings: a compass, a map, a key, and a photograph. No one stands nearby to explain them. Only the crater, the wreckage, and the sense that someone lost more than supplies.\n\nFollow the clues from Marshal's Refuge and help piece together what happened to their owner. The trail is strange, old-fashioned, and not eager to explain itself."] = "安戈洛环形山的一只破旧木筏上放着几件古怪的物品：一个罗盘、一张地图、一把钥匙和一张照片。附近没有人能解释它们。只有环形山、残骸，以及一种感觉——有人失去的远不止补给。\n\n从马绍尔营地开始追寻线索，帮助拼凑出它们的主人究竟遭遇了什么。这条线索古怪、老派，而且并不急于解释自己。"
L["A small scroll waits aboard a Bloodsail ship south of Booty Bay. It bears no proper patron, only a riddle and enough direction to make you wonder what was hidden.\n\nTake Cortello's words seriously and follow the clues wherever they send you. The treasure is not marked for anyone who wants a straight road."] = "在藏宝海湾以南的一艘血帆海盗船上，一卷小小的卷轴正等待着你。它没有正式的委托人，只有一则谜语，以及恰好足以让你好奇究竟藏着什么的指引。\n\n认真对待科泰罗的话语，无论线索将你带往何处，都要追随下去。宝藏可不是为那些只想走捷径的人准备的。"
L["Abercrombie's requests sounded lonely before they sounded dangerous. Hair, juice, blossoms, ribs, and a stolen crate became Stitches on the road, and Darkshire learned what the hermit had been making."] = "亚伯克隆比的请求起初听来只是寂寞，后来才显出危险。头发、果汁、花朵、肋骨和一只被偷的箱子，最终变成了路上的斯迪克斯，夜色镇这才知道那位隐士一直在制造什么。"
L["Aid Gryan Stoutmantle in Westfall and seek Wiley the Black's note in Lakeshire."] = "协助西部荒野的格里安·斯托曼，并前往湖畔镇寻找黑衣威利的字条。"
L["Alliance priests carry word of Scarlet activity from Stormwind to Desolace, Southshore, and finally the Monastery."] = "联盟的牧师们将血色十字军的动向从暴风城一路传到凄凉之地、南海镇，最终传到修道院。"
L["Answer Archmage Xylem's request in Azshara and study the magic left by Warlord Krellian."] = "回应艾萨拉的大法师克希雷姆的请求，研究军阀克雷利安留下的魔法。"
L["Answer your trainer's summons, draw a voidwalker into the circle, and bind it to your will."] = "响应训练师的召唤，将一个虚空行者引入法阵，并让它服从你的意志。"
L["Apothecary Johaan began with blood, scales, and venom gathered from the creatures near Brill. In the tavern cellar, a captured mountaineer became the first proof that the new plague could be more than theory."] = "药剂师乔汉的研究始于从布瑞尔附近的生物身上采集来的血液、鳞片和毒液。在旅店的地窖里，一名被俘的山地人成为了第一个证明：这种新的瘟疫绝不只是纸上谈兵。"
L["At Fire Plume Ridge, the strange tools finally proved their worth. The Silver Totem stripped Blazerunner's shield, the sword found its purpose, and the Golden Flame was carried back to Marshal's Refuge. Linken's memory was still imperfect, but the road had given him a shape to follow: hero, blade, flame, and a companion brave enough to see it done."] = "在火羽山，那些奇怪的工具终于派上了用场。银色图腾剥除了火焰奔行者的护盾，那把剑找到了它的使命，金色火焰也被带回了马绍尔营地。林克的记忆仍不完整，但这段旅程已为他勾勒出一条可循的轨迹：英雄、利刃、火焰，以及一位勇于陪他走到最后的同伴。"
L["At the Deepwater Tavern, follow the man who listens too closely and make Tapoke Jahn tell what he knows."] = "在深水旅店，跟踪那个偷听得过于专注的男人，逼塔伯克·贾恩说出他知道的一切。"
L["At the Scarab Wall, Anachronos shows the old war and names the broken road a scepter bearer must follow."] = "在甲虫之墙，阿纳克洛斯为你展现了那场古老的战争，并指明了权杖持有者必须走过的那条破碎之路。"
L["Azuregos sends you to Narain Soothfancy, whose ledger runs through goggles, chops, ransom notes, Draconic pages, and the sea."] = "艾索雷苟斯让你去找纳瑞安，他的账本上记满了护目镜、肉排、勒索信、龙语书页，还有大海。"
L["Baristolth sends you to Anachronos and then to Blackwing Lair. Broodlord Lashlayer's head begins the work of earning Nozdormu's trust."] = "巴里斯托斯让你先去找阿纳克洛斯，再前往黑翼之巢。勒什雷尔的首级是赢得诺兹多姆信任的第一步。"
L["Before Tirion Fordring's search for his son, Hearthglen already stood as a military problem. Kirsta Deepshadow wanted the Scarlet Crusade measured in practical terms: medics, hunters, magi, knights, named officers, and the strength of the town itself. The reconnaissance made one thing clear. Hearthglen was not a remnant. It was an army still drilling under red banners."] = "早在提里奥·弗丁寻找儿子之前，壁炉谷就已经是一个棘手的军事难题。科尔斯塔·迪普沙东希望用务实的标准来衡量血色十字军：医师、猎手、法师、骑士、有名有姓的军官，以及这座城镇本身的实力。侦察结果清楚地表明了一件事：壁炉谷并非残部，而是一支仍在红色旗帜下操练的军队。"
L["Begin in the Burning Steppes with Helendis Riverhorn and carry the black dragon reports between Lakeshire, Stormwind, and Morgan's Vigil."] = "从燃烧平原的赫林迪斯·河角开始，在湖畔镇、暴风城和摩根的岗哨之间传递有关黑龙的报告。"
L["Begin Lord Grayson Shadowbreaker's rite and prepare yourself for the charger's judgment."] = "开始格雷森·沙东布瑞克公爵的仪式，做好接受军马评判的准备。"
L["Begin Mor'zul Bloodbringer's work, gather the ritual tools, and prepare the road to Xoroth."] = "着手莫苏尔·召血者交付的工作，收集仪式所需的器具，为前往索罗斯做好准备。"
L["Begin Nimboya's search by pressing the Bloodscalp trolls for any sign of Yenniku."] = "开始尼姆布亚的搜寻，向血顶巨魔施压，寻找耶尼库的任何踪迹。"
L["Begin with the red masks near Northshire and follow the same bandit sign through Elwynn."] = "从北郡附近的红面具着手，沿着同样的强盗标记一路追查整个艾尔文森林。"
L["Bodley was frightened, talkative, and deeply entangled in Lord Valthalak's fate. Through him, the armor work became a matter of flame, reputation, and a shattered amulet."] = "伯德雷胆小又多话，与瓦塔拉克公爵的命运纠缠极深。通过他，护甲的升级变成了一件关乎火焰、声望和一枚破碎护符的事情。"
L["Break the Stones of Binding and seek the last names left to the Fallen Hero: Corporal Thund Splithoof and Lieutenant Kirith."] = "摧毁束缚之石，去寻找英雄之魂仅存的最后两个名字：桑德·裂蹄下士和基利斯中尉。"
L["Bring a Dungeon Set 1 bracer to Deliana or Mokvar and accept the first upgrade work."] = "将一件地下城套装1的护腕交给德莉亚娜或莫克瓦尔，接下第一项升级工作。"
L["Bring General Drakkisath's blood to Rexxar and complete the Drakefire Amulet."] = "将达基萨斯将军之血交给雷克萨，完成龙火护符。"
L["Bring proof of the elements to the temple trial and show that the four powers can be held together."] = "将元素的证明带到神殿试炼，证明你能够同时驾驭这四种力量。"
L["Bring Raschal's knife to Quintis Jonespyre and let the blade show what ordinary searching could not."] = "将拉沙尔的匕首交给奎恩提斯，让这把刀揭示寻常搜索无法发现的线索。"
L["Bring the Ancient Petrified Leaf to Felwood and hear what the ancients require of a hunter."] = "将古树的石化叶片带到费伍德森林，聆听古树对一名猎人的要求。"
L["Bring the dead leaders to the cauldron and answer the price they demand before they speak."] = "将死去的首领们带到大锅前，在他们开口之前，先付出他们索要的代价。"
L["By the time you reached Brill, the Scarlet Crusade was no rumor. Deathguard Simmer's stolen pumpkins became Apothecary Johaan's experiment, and a captured Scarlet Zealot learned how the Royal Apothecary Society meant to answer holy certainty. Outside town, Executor Zygand sent you into the Scarlet camps again and again until their officers broke. Brill's campaign was not only defense. It was the Forsaken answer taking shape."] = "当你抵达布瑞尔时，血色十字军已不再只是传闻。亡灵卫兵希米尔被盗的南瓜成了药剂师乔汉的实验材料，一名被俘的血色狂热者也领教了皇家药剂师协会打算如何回应那份神圣的笃信。在镇外，执行官塞加德一次又一次地派你深入血色十字军的营地，直到他们的军官溃不成军。布瑞尔的战役不只是防御，被遗忘者的反击正在成形。"
L["Carlin and Chromie needed names made into relics: Horgus, Marduk, Davil, Joseph, and the marauders who joined the slaughter. Each recovered piece brought the last battle closer to being answered."] = "卡林和克罗米需要把这些名字化为遗物：霍古斯、马杜克、达维尔、约瑟夫，以及参与屠杀的掠夺者们。每找回一件，那最后一战就离得到回应更近一步。"
L["Carry Balthule's warning to Delgren and follow the Dark Strand's trail through Ashenvale."] = "将巴苏尔的警告带给德尔格伦，沿着黑暗之链的踪迹穿过灰谷。"
L["Carry Duthorian Rall's lesson to Westfall and prove that valor protects those who cannot stand alone."] = "将达索瑞恩·拉尔的教诲带到西部荒野，证明勇气守护的正是那些无法独自挺立的人。"
L["Carry the Azsharite to Galvan the Ancient so Felbane can be forged for the Blasted Lands."] = "将艾萨莱特水晶交给加尔文，让他为诅咒之地的战斗锻造出邪能克星。"
L["Carry the Silver Totem into Linken's final trial and see whether the old adventure can be finished."] = "带着银色图腾踏上林克的最终试炼，看看这段古老的冒险能否画上句号。"
L["Carry VanCleef's letter to Baros Alexston and follow the matter into the Stockade."] = "将范克里夫的信交给巴隆斯·阿历克斯顿，顺着这件事一路追查到暴风城监狱。"
L["Carry waters between distant places and learn why this totem asks for patience."] = "在相隔遥远的地方之间运送水源，领悟这个图腾为何需要耐心。"
L["Commander Gor'shak's message pulls the Horde into Blackrock Depths, where Moira's captivity may shape more than one kingdom."] = "指挥官哥沙克的消息将部落引入黑石深渊，茉艾拉被囚一事所影响的可能不止一个王国。"
L["Complete your first warrior trial and learn the stance that keeps you standing when blows fall."] = "完成你的第一次战士试炼，学会在攻击袭来时让你屹立不倒的姿态。"
L["Dalar Dawnweaver asks you to thin the Moonrage worgen and recover signs of Arugal's magic."] = "达拉尔·道恩维沃尔请你削减月怒狼人的数量，并找回阿鲁高魔法的痕迹。"
L["Dalar Dawnweaver wanted proof that Arugal's curse still stained Silverpine. You hunted Moonrage worgen, recovered the Remedy of Arugal, and struck down those most touched by the mage's work."] = "达拉尔·道恩维沃尔需要证据，证明阿鲁高的诅咒仍在玷污银松森林。你猎杀了月怒狼人，找回了阿鲁高的药剂，并击倒了那些受这名法师影响最深的人。"
L["Darkshire's first need was simple: more blades for the Night Watch. You answered Althea's call at Raven Hill and helped hold a town Stormwind could not easily protect."] = "夜色镇最初的需求很简单：为守夜人增添更多的战力。你在乌鸦岭响应了艾尔希娅的召唤，帮助守住了这座暴风城难以保护的小镇。"
L["Darthalia's first orders were plain: strike the farms, kill those who worked them, and leave the town afraid. Tarren Mill's campaign had begun."] = "达萨利亚最初的命令十分直白：袭击农场，杀死耕作的人，让整座小镇陷入恐惧。塔伦米尔的战役就此展开。"
L["Deathknell's newly risen are not alone. Strike the Scarlet converts and take the courier's message before it leaves the valley."] = "丧钟镇刚刚苏醒的亡灵并不孤单。袭击血色皈依者，在信使的消息离开山谷之前将其截获。"
L["Delgren sent you after the cult's soul gems and writings from Ordil'Aran to Fire Scar Shrine and Satyrnaar. Each recovered piece loosened the hold of the power behind Althalaxx."] = "德尔格伦派你从奥迪拉兰一路追查到火痕神殿和萨提纳尔，夺回邪教的灵魂宝石和文献。每找回一件，奥萨拉克斯背后那股力量的掌控就松动一分。"
L["Dun Garok stood as the last hard point in Darthalia's campaign. When its mountaineers, priests, riflemen, and Captain Ironhill were dead, her commendation could be carried to Varimathras."] = "丹加洛克是达萨利亚的战役中最后一座坚固据点。当那里的山地人、牧师、火枪手和达伦·铁山上尉全部倒下后，她的嘉奖令便可以呈交给瓦里玛萨斯了。"
L["Emberstrife demands the skulls of four dragons: Scryer, Somnus, Chronalis, and Axtroz."] = "埃博斯塔夫要求你取得四条龙的头骨：斯克瑞尔、索姆努斯、克鲁纳里斯和埃克托兹。"
L["Emberstrife's tests scattered the Horde across Azeroth. Scryer waited in Winterspring, Somnus haunted Swamp of Sorrows, Chronalis guarded the Caverns of Time, and Axtroz patrolled the road to Grim Batol. Each skull was trophy, key, and proof of strength. By the time the fourth dragon fell, Emberstrife's amulet was ready for the last transformation."] = "埃博斯塔夫的考验让部落的勇士们奔走于艾泽拉斯各地。斯克瑞尔在冬泉谷等候，索姆努斯盘踞在悲伤沼泽，克鲁纳里斯守卫着时光之穴，埃克托兹则在通往格瑞姆巴托的路上巡逻。每一个头骨既是战利品，也是钥匙，更是力量的证明。当第四条龙倒下时，埃博斯塔夫的护符已经准备好迎接最后的蜕变。"
L["Enter Dire Maul and recover the knowledge Lorekeeper Lydros keeps in the Athenaeum."] = "进入厄运之槌，从图书馆中寻回博学者莱德罗斯所保管的知识。"
L["Enter Shadowfang Keep for the missing deathstalkers, the Book of Ur, and the mage who rules above the forest."] = "进入影牙城堡，寻找失踪的死亡猎手、乌尔之书，以及那名高踞森林之上的法师。"
L["Enter the Deadmines beneath Moonbrook and confront the Brotherhood at the heart of its hideout."] = "进入月溪镇地下的死亡矿井，在兄弟会巢穴的核心与他们对峙。"
L["Enter the Monastery's graveyard and library for prisoners, forbidden books, and the records the Crusade keeps locked away."] = "进入修道院的墓地和图书馆，寻找囚犯、禁书，以及十字军锁藏起来的记录。"
L["Follow the last sign into the hive and learn whether Raschal's errand can still be answered."] = "循着最后的线索进入虫巢，看看拉沙尔的任务是否还能有个交代。"
L["Eris Havenfire's trial tested mercy under pressure. You kept the fallen moving, held shadow at bay, and earned Benediction through discipline and compassion."] = "艾瑞斯·哈文法的试炼考验的是压力之下的仁慈。你让倒下的人继续前行，抵御了暗影，并凭借自律与慈悲赢得了祈福。"
L["Escort Marshal Windsor back to Stormwind and stand with him when his proof is finally heard."] = "护送温德索尔元帅返回暴风城，在他的证据终于得到倾听时与他并肩而立。"
L["Falrin Treeshaper's vendetta turned Dire Maul's library into your next post. The creatures he named were hunted, the enchantment was made, and a challenge was prepared for Blackrock Depths."] = "法尔林·树影的复仇让厄运之槌的图书馆成了你的下一站。他点名的生物遭到了猎杀，附魔已经完成，一场挑战也已为黑石深渊准备就绪。"
L["Felwood gave the search older magic. Eridan Bluewind understood the silver heart Linken had been trying to make and sent you into Winterspring's old forests before Aquementas rose in Un'Goro. The elemental's power became a silver totem, the key to stripping away the final guardian's protection. The errand had strange humor about it, but the ritual was real."] = "费伍德森林为这次寻找带来了更古老的魔法。艾瑞丹·蓝风明白林克一直试图打造的银色之心是什么，在亚奎门塔斯于安戈洛现身之前，他先派你深入冬泉谷的古老森林。这个元素生物的力量化作了一个银色图腾，成为剥除最后一名守护者防护的关键。这趟差事带着几分奇怪的幽默，但那场仪式是真实的。"
L["Find Balthule Shadowstrike near the Tower of Althalaxx and learn what gathers on Darkshore's northern coast."] = "在奥萨拉克斯之塔附近找到巴苏尔·影击，了解黑海岸北部的海岸上正在聚集着什么。"
L["Find Bodley near Blackrock Spire and learn why Lord Valthalak's amulet matters."] = "在黑石塔附近找到伯德雷，了解瓦塔拉克公爵的护符为何如此重要。"
L["Find Pamela Redpath in Darrowshire and help gather the pieces of the doll she has lost."] = "在达隆郡找到帕米拉·雷德帕斯，帮她找齐她丢失的娃娃碎片。"
L["Find Ravenholdt Manor and present yourself to the rogues who keep their own company in the hills."] = "找到拉文霍德庄园，去见见那些在山中自成一派的盗贼。"
L["Find Rexxar and follow the trials he sets before the amulet can be completed."] = "找到雷克萨，完成他设下的试炼，护符才能最终完成。"
L["Fire asked for risk, offering, and obedience to the rite. When the brazier answered, the flame became a servant at your side."] = "火焰要求冒险、献祭和对仪式的服从。当火盆作出回应时，火焰便成了你身边的仆从。"
L["Follow Madame Eva's cards through old records, locked chests, and the trail of Stalvan Mistmantle."] = "追随伊瓦夫人的卡牌，翻阅旧日档案，打开上锁的箱子，追踪斯塔文·米斯特曼托的踪迹。"
L["Follow Pamela's family trail to Marlene, Carlin, and Chromie, who seeks the Annals of Darrowshire."] = "沿着帕米拉家人的线索找到玛莱恩、卡林和克罗米，克罗米正在寻找达隆郡年鉴。"
L["Follow Shael'dryn's guidance through old Ashenvale magic and the work left unfinished by Teronis."] = "在莎尔蒂恩的指引下，探寻灰谷古老的魔法，以及特洛尼斯未竟的事业。"
L["Follow Sven's grief, Jitters' journal, and the shadow that hangs over Raven Hill."] = "追寻斯温的悲痛、吉特斯的日记，以及笼罩着乌鸦岭的阴影。"
L["Follow the call of fire through offerings, reagents, and the flame that waits in Durotar."] = "追随火焰的召唤，准备祭品和材料，去寻找在杜隆塔尔等候的火焰。"
L["Follow the Circle's instructions, gather what is needed for a cure, and cleanse the sick beasts you find."] = "遵照塞纳里奥议会的指示，收集治疗所需的材料，净化你遇到的患病野兽。"
L["Follow the Devourer of Souls chain and prepare the binding of a subtler demon."] = "完成噬魂者系列任务，准备束缚一个更加狡诈的恶魔。"
L["Trust the musty scroll's final verse and search where Cortello chose to hide his prize."] = "相信那张发霉卷轴上的最后一句诗，到科尔特罗选择藏匿宝物的地方去搜寻。"
L["Follow Thelwater, Baros, Shaw, and Trias as the Defias trail returns to Stormwind."] = "追随塞尔沃特、巴隆斯、肖尔和崔亚斯的脚步，迪菲亚的线索重新指向了暴风城。"
L["Follow Watcher Backus to Addle's Stead and bring the Defias docket back to Trias."] = "跟随守夜人巴库斯前往腐草农场，将迪菲亚卷宗带回给崔亚斯。"
L["Follow your faction's rogue trainer into guarded ground, locked boxes, and the antidote work needed for poisons."] = "跟随你所在阵营的盗贼训练师，潜入戒备森严之地，开启上锁的箱子，并完成学习毒药所需的解毒剂任务。"
L["From Stonard or Nethergarde, the road ended at the same ghost. The Fallen Hero told what waited beyond the swamp: Razelikh's servants took his fallen regiment, denied them rest, and bound them to stones of demonic power. His regret became an order of its own. If his soldiers could not live, they could still be set free."] = "无论从斯通纳德还是守望堡出发，这条路最终都通向同一个幽魂。英雄之魂讲述了沼泽之外等待着的东西：拉瑟莱克的仆从夺走了他阵亡的部队，不让他们安息，并将他们束缚在蕴含恶魔力量的石头上。他的悔恨化作了一道命令：既然他的士兵已无法生还，至少还能让他们获得解脱。"
L["Gather ectoplasm, a power source, and goblin parts so Mux can finish his device."] = "收集灵质、一个能量源和地精零件，让穆克斯完成他的装置。"
L["Gather Johaan's ingredients around Brill and bring the mixture to the prisoner in the Gallows' End Tavern."] = "在布瑞尔周边收集乔汉需要的材料，将调好的药剂带给恐惧之末旅店里的囚犯。"
L["Gather Jordan Stilwell's materials from distant dangers and help forge Verigan's Fist."] = "从遥远的险地收集乔丹·斯迪威尔所需的材料，帮助他锻造维里甘之拳。"
L["Gather singing crystals and the Mind's Eye so Kin'weelay can make a Soul Gem for Yenniku."] = "收集歌唱水晶和心灵之眼，让肯维雷为耶尼库制作一枚灵魂宝石。"
L["Gather the final materials and ready the Brazier of Invocation for Upper Blackrock Spire."] = "收集最后的材料，为黑石塔上层准备好召唤火盆。"
L["Go north of Brill to the Agamand Mills, clear the dead, and recover what remains of the family."] = "前往布瑞尔以北的阿加曼德磨坊，清除那里的亡灵，找回这个家族的遗物。"
L["Go to Tabetha in Dustwallow Marsh, recover the knowledge she needs, and prepare a wand of your chosen school."] = "前往尘泥沼泽找塔贝萨，寻回她需要的知识，准备一根属于你所选学派的魔杖。"
L["Gryan Stoutmantle suspected that Westfall's troubles reached beyond scattered bandits. Wiley's note confirmed allies, machinery, hidden routes, and the old grievance of the Stonemasons."] = "格里安·斯托曼怀疑西部荒野的麻烦不只是零散的强盗。威利的字条证实了他的猜测：这里有盟友、机械、秘密通道，还有石匠工会的陈年积怨。"
L["Hear Ragged John's tale, find Marshal Windsor in Blackrock Depths, and recover the proof taken from him."] = "听狼狈不堪的约翰讲述他的故事，在黑石深渊找到温德索尔元帅，找回他被夺走的证据。"
L["Hear the old tale of Thaurissan, then enter Blackrock Depths to learn what the mountain is hiding."] = "聆听索瑞森的古老传说，然后进入黑石深渊，查明这座山中隐藏着什么。"
L["Help Calor and Carevin hunt the worgen moving through Brightwood Grove and the Rotting Orchard."] = "帮助卡洛尔和卡雷文猎杀在阳光树林和腐烂果园中出没的狼人。"
L["Help Lydon finish the Elixir of Agony and find a way to deliver it to the captured farmers upstairs."] = "帮助林度恩完成苦楚药剂，并设法将其送给楼上被俘的农夫。"
L["Help Tyrion prepare the spybot and learn what quiet meeting it was built to uncover."] = "帮助泰里恩准备侦察机器人，查明它要揭露的是一场怎样的秘密会面。"
L["High Executor Hadrec's missing deathstalkers, Bel'dugur's forbidden book, and Dalar's demand all led into Shadowfang Keep. Arugal fell there, and the Sepulcher received the proof it required."] = "高级执行官哈德瑞克失踪的死亡猎手、贝杜古尔的禁书和达拉尔的要求，全都指向了影牙城堡。阿鲁高在那里倒下，瑟伯切尔也得到了它所需的证据。"
L["Hillsbrad's strength lay in its smithy, leaders, registry, and mine. Darthalia sent you against each in turn, breaking the town by removing the people and records that held it together."] = "希尔斯布莱德的力量来自铁匠铺、领袖、户籍档案和矿洞。达萨利亚派你逐一打击这些目标，通过除掉维系小镇的人和记录来摧毁它。"
L["If the Eye of Divinity comes into your possession, seek Eris Havenfire in the Eastern Plaguelands. She has a trial that asks for more than quick hands and bright prayers.\n\nStand between panic and shadow, save who you can, and learn whether your faith holds when every mistake has a cost."] = "如果你得到了神圣之眼，就去东瘟疫之地寻找艾瑞斯·哈文法。她的试炼需要的不只是敏捷的身手和虔诚的祈祷。\n\n挡在恐慌与暗影之间，尽你所能拯救更多的人，看看当每个失误都要付出代价时，你的信仰是否依然坚定。"
L["In Brill, the Forsaken answer the Crusade with prisoners, poison, and attacks against the camps west of town."] = "在布瑞尔，被遗忘者以俘虏、毒药以及对镇西营地的攻击来回应十字军。"
L["In Kargath, take Warlord Goretooth's orders into Blackrock Spire and bring Rend Blackhand's command to Thrall."] = "在卡加斯接受军官高图斯的命令前往黑石塔，并将雷德·黑手的命令带给萨尔。"
L["In Silithus, the Bronze Dragonflight does not hand trust to strangers. Before anyone can challenge what waits behind Ahn'Qiraj's gates, someone must prove they are more than another mortal asking for legends.\n\nBegin with the Brood of Nozdormu and follow the old scepter's trail through dragonflights, hidden lairs, bargains, and errands that sound impossible until someone does them."] = "在希利苏斯，青铜龙军团不会轻易信任陌生人。在任何人能够挑战安其拉之门后等待的东西之前，必须有人证明自己不只是又一个前来打听传说的凡人。\n\n从诺兹多姆的子嗣开始，沿着古老权杖的线索，穿梭于各大龙族军团、隐秘的巢穴、一桩桩交易，以及那些在有人完成之前听起来都不可能的差事之间。"
L["In Stratholme, search the Scarlet Bastion for the archive and the truth hidden behind its holy face."] = "在斯坦索姆，搜索血色堡垒中的档案馆，揭开隐藏在其神圣外表之下的真相。"
L["In Theramore, find Private Hendel near Sentry Point and bring him in alive if you can."] = "在塞拉摩，到警戒哨岗附近找到亨德尔下士，尽可能把他活着带回来。"
L["Join Commander Althea's Night Watch and begin clearing the dead around Raven Hill."] = "加入指挥官艾尔希娅的守夜人，开始清理乌鸦岭周围的亡灵。"
L["King Magni sends the letter on to Grand Mason Marblesten, who needs Alterac Granite before Sully's memorial can stand."] = "麦格尼国王将信转交给大石匠玛布勒斯坦，他需要奥特兰克花岗石才能为苏利建起纪念碑。"
L["Kirsta Deepshadow sends you into the Scarlet lines around Hearthglen to kill their specialists and scout the fortress."] = "科尔斯塔·迪普沙东派你深入壁炉谷周围的血色防线，击杀他们的各类专业兵种并侦察要塞。"
L["Krellian's magic broke apart in curious ways, and Xylem knew what to make of it. The result was odd, useful, and unmistakably a mage's lesson."] = "克瑞里安的魔法以奇特的方式瓦解了，而塞雷姆知道该如何利用它。结果既古怪又实用，毫无疑问是一堂属于法师的课。"
L["Latronicus sends you to Ginro Hearthkindle, who needs the Feralas coast searched for Raschal's missing boat."] = "拉托尼库斯让你去找基恩诺·火花，他需要你搜索菲拉斯海岸，寻找拉沙尔失踪的船。"
L["Linken's memory did not return like a clean answer. It came through strange errands, ghostly meetings, and a sword that changed in flashes of light. Donova, Gaeriyan, and the grave outside Gadgetzan turned the lost gnome's fragments into a rite of recovery. By the time the sword was reforged, Linken still did not fully understand himself, but the road was opening before him again."] = "林克的记忆并没有像一个干脆利落的答案那样回归。它随着奇怪的差事、与幽魂的会面，以及一把在闪光中变化的剑，一点点地回来了。多诺瓦、加里杨和加基森外的那座坟墓，将这个失忆侏儒的记忆碎片变成了一场找回自我的仪式。当那把剑重铸完成时，林克仍未完全了解自己，但前方的道路已再次为他敞开。"
L["Lorekeeper Lydros entrusted you with a spell every company of adventurers comes to value. Power is not always flame and frost; sometimes it is preparation."] = "博学者莱德罗斯将一个每支冒险队伍都会珍视的法术托付给了你。力量并不总是火焰与冰霜，有时它就是未雨绸缪。"
L["Lydon's work in Tarren Mill turned research into local experiment. Tongues, ichor, and mountain lion blood became elixirs, and the tests on Umpi and Stanley showed how cruelly effective they could be."] = "林度恩在塔伦米尔的工作将研究变成了就地实验。舌头、脓液和山狮之血被制成药剂，而在乌比和斯坦利身上进行的测试则显示出它们何等残忍而有效。"
L["Magistrate Sevren knew the trouble went below the mills. In the family crypt you found older dead, wailing ancestors, and Captain Dargol's skull, ending the matter one grave at a time."] = "执政官塞弗伦知道麻烦来自磨坊之下。在家族墓穴里，你找到了更古老的亡者、哀嚎的先祖，以及达尔高上尉的头骨，一座坟墓接一座坟墓地平息了这场祸乱。"
L["Mankrik survived a quillboar attack on the Gold Road, but Olgra did not return. Search the road south of the Crossroads for his wife."] = "曼科里克在黄金之路上遭到野猪人袭击后幸存了下来，但奥尔格拉没有回来。到十字路口以南的道路上搜寻他的妻子。"
L["Mankrik's request was painfully plain: find his wife. The Barrens offered little direction and less mercy, only a long road south of the Crossroads and quillboar waiting in the dust. When Olgra was found, the search became grief. Mankrik had asked for hope and received a body. What followed was the only answer his pain could bear: Bristleback tusks, brought back one by one."] = "曼科里克的请求简单得令人心痛：找到他的妻子。贫瘠之地几乎不给人任何方向，更谈不上怜悯，只有十字路口以南那条漫长的道路，以及在尘土中守候的野猪人。找到奥尔格拉时，搜寻变成了哀悼。曼科里克盼来的不是希望，而是一具遗体。接下来的，是他的痛苦唯一能够承受的回应：一根接一根带回来的钢鬃獠牙。"
L["March on Dun Garok and bring Darthalia the victory she needs for her sealed commendation."] = "向丹加洛克进军，为达萨利亚赢得她换取密封嘉奖令所需的胜利。"
L["Marlene's request led you to Pamela Redpath, alone among the ruins and still asking after her doll. Returning the pieces brought comfort, and also the first hard truth of Darrowshire."] = "玛莱恩的请求将你引向帕米拉·雷德帕斯，她独自待在废墟中，仍在打听她的娃娃。交还碎片带来了慰藉，也揭开了达隆郡的第一个残酷真相。"
L["Meet Falrin Treeshaper in Dire Maul and gather what he needs for the next challenge."] = "在厄运之槌与法尔林·树影会面，为下一场挑战收集他需要的东西。"
L["Menethil Harbor made the conspiracy plain. Mikhail noticed a listener by the tavern door, and Tapoke \"Slim\" Jahn tried to run before the questions reached him. When he broke, the case changed completely. The Defias had not taken a mere diplomat. They had taken Stormwind's king, and Slim had helped place Hendel aboard the king's ship. Mikhail could only send you to Theramore before the trail disappeared into military silence."] = "米奈希尔港让这桩阴谋变得清晰起来。米克哈尔注意到旅店门边有人在偷听，而“干柴”塔伯克·贾恩试图在被盘问之前逃跑。当他终于招供，整个案件彻底变了样。迪菲亚绑走的并不只是一名外交官，而是暴风城的国王，而“干柴”曾帮助亨德尔登上国王的船。米克哈尔只能赶在线索消失于军方的沉默之前，派你前往塞拉摩。"
L["Moira's disappearance led backward to old Thaurissan and the War of the Three Hammers. Ironforge's old wound led straight into Blackrock Depths, where Kharan Mighthammer's prison cell held the news Magni did not want to hear. Moira was in the heart of the Dark Iron kingdom, and the rescue he wanted was already tangled in questions of love, control, succession, and inherited hatred."] = "茉艾拉的失踪将线索追溯回了古老的索瑞森和三锤之战。铁炉堡的旧伤直通黑石深渊，卡兰·巨锤的牢房里藏着麦格尼不愿听到的消息：茉艾拉身处黑铁王国的心脏，而他所期望的营救，早已与爱情、控制、继承和世代仇恨纠缠在一起。"
L["Mor'zul and Gorzeeki sent you through blood, stardust, Jaedenar, and Scholomance. In Dire Maul the rite opened, and the dreadsteed came through bound to your command."] = "莫苏尔和戈瑟奇让你为鲜血与星尘奔走，深入加德纳尔和通灵学院。仪式在厄运之槌中开启，恐惧战马应召而来，听从你的号令。"
L["Morgan Ladimore's grave led to a sorrow Darkshire had tried to bury. You ended Mor'Ladim's wandering and brought Sarah Ladimore the truth of her father."] = "摩根·拉迪莫尔的坟墓揭开了一段夜色镇试图埋葬的悲伤往事。你终结了摩拉迪姆的游荡，并将她父亲的真相告诉了莎拉·拉迪莫尔。"
L["Move from fields to town records, workers, leaders, and the mine that keeps Hillsbrad supplied."] = "从田野转向小镇的档案、工人、领袖，以及为希尔斯布莱德提供补给的矿洞。"
L["Mux Manascrambler's device required ghostly residue, strange power, and parts only a goblin would trust. Once complete, it pointed the armor work toward matters no smith could see unaided."] = "穆克斯·玛纳斯卡波的装置需要幽灵残渣、奇异的能量，以及只有地精才会信赖的零件。装置完成后，它将护甲的升级工作指向了任何铁匠都无法独自看清的领域。"
L["Pamela's family was scattered by grief: Marlene near Andorhal, Jessica far away, and Carlin at Light's Hope. Chromie gave their sorrow a shape by asking for the Annals of Darrowshire."] = "帕米拉的家人因悲伤而离散：玛莱恩在安多哈尔附近，杰西卡远在他乡，卡林则在圣光之愿礼拜堂。克罗米请求寻找达隆郡年鉴，为他们的哀伤找到了寄托。"
L["Push into the Armory and Cathedral, where the Crusade's champions guard the heart of the Monastery."] = "攻入军械库和大教堂，十字军的勇士们在那里守卫着修道院的核心。"
L["Ravenholdt opened a door beyond ordinary city training. There were signals to learn, reputations to mind, and thieves who knew the craft by its older rules."] = "拉文霍德为你打开了一扇超越寻常城市训练的大门。这里有暗号要学，有名声要顾及，还有一群按更古老的规矩行事的盗贼。"
L["Read the scroll found aboard the Bloodsail ship and follow only the clue Cortello left behind."] = "阅读在血帆船上找到的卷轴，只追随科尔特罗留下的线索。"
L["Read the wanted poster outside Westbrook Garrison and hunt Hogger, the Riverpaw gnoll terrorizing southwestern Elwynn."] = "阅读西泉要塞外的通缉令，猎杀霍格——这个在艾尔文森林西南部肆虐的河爪豺狼人。"
L["Read the weathered grave north of Raven Hill and learn why Mor'Ladim still walks."] = "查看乌鸦岭以北那块风化的墓碑，了解摩拉迪姆为何仍在游荡。"
L["Recover the amulet pieces and components Bodley names from the old dungeons of Azeroth."] = "从艾泽拉斯古老的地下城中，找回伯德雷所说的护符碎片和材料。"
L["Recover the relics and skulls tied to Darrowshire's old defenders, villains, and marauders."] = "找回与达隆郡昔日的守卫者、恶徒和掠夺者有关的遗物和头骨。"
L["Recover the waterlogged letter beneath the Thandol Span and carry its last words home."] = "在萨多尔大桥下找回那封被水浸透的信，将信中最后的话语带回家乡。"
L["Renferrel and Faranell carried the work beyond Brill. Berard's journal, Pyrewood's danger, and the samples from Lake Lordamere gave the apothecaries older knowledge to add to their new recipe."] = "伦费尔和法拉尼尔将这项工作推进到布瑞尔之外。贝拉德的日记、焚木村的危险，以及来自洛丹米尔湖的样本，为药剂师们的新配方增添了更古老的知识。"
L["Report to Apothecary Lydon in Hillsbrad and gather what he needs for his next field trials."] = "向希尔斯布莱德的药剂师林度恩报到，收集他下一轮实地测试所需的材料。"
L["Report to High Executor Darthalia and carry her first orders against the farms of Hillsbrad."] = "向高级执行官达萨利亚报到，执行她针对希尔斯布莱德农场的第一批命令。"
L["Return to Darrowshire with Chromie's relic bundle and stand with the town in its final battle."] = "带着克罗米的遗物包裹返回达隆郡，与小镇一同迎接最后的战斗。"
L["Return to Deliana or Mokvar for the final exchange and complete the armor upgrade."] = "回到德莉亚娜或莫克瓦尔那里进行最后的交换，完成护甲升级。"
L["Return to the tower with Balthule's command and face Athrikus Narassin at the summit."] = "带着巴苏尔的命令返回塔中，在塔顶面对埃瑟里克斯·纳拉辛。"
L["Return to Westfall, watch the Brotherhood's movements, and let the trail show where it leads."] = "返回西部荒野，监视兄弟会的动向，看看这条线索会通向哪里。"
L["Return to your trainer and receive the last totem needed to complete the circle of elements."] = "回到你的训练师那里，领取完成元素之环所需的最后一个图腾。"
L["Return with the lost command, or answer Nethergarde's summons, and hear what Razelikh did to the soldiers who crossed into the Blasted Lands."] = "带着遗失的命令返回，或者响应守望堡的召唤，听听拉瑟莱克对那些踏入诅咒之地的士兵做了什么。"
L["Run Abercrombie's errands near Raven Hill and learn what the old hermit means to build."] = "在乌鸦岭附近为亚伯克隆比跑腿，看看这位老隐士究竟想要造出什么。"
L["Search for Teronis near Lake Falathim and return with whatever remains of his work."] = "在法拉希姆湖附近寻找特洛尼斯，将他的工作所留下的一切带回来。"
L["Search the Woodpaw camps for Raschal's missing packs and any sign of where his errand went next."] = "搜查木爪豺狼人的营地，寻找拉沙尔丢失的背包，以及他接下来去向的任何线索。"
L["Search the wrecked raft in Un'Goro and bring the small pack to Linken at Marshal's Refuge."] = "搜查安戈洛环形山中那艘失事的木筏，将小背包交给马绍尔营地的林克。"
L["Follow the next names in Linken's tale and prepare the totem he will need."] = "追寻林克故事中出现的下一批名字，准备好他将需要的图腾。"
L["Seek Haleh in Winterspring and bring her General Drakkisath's blood to make the Drakefire Amulet."] = "前往冬泉谷寻找哈尔琳，将达基萨斯将军之血带给她，以制作龙火护符。"
L["Seek Loramus Thalipedes in Azshara. The demon hunter knows how Razelikh is warded, but he needs a name torn from the deep."] = "前往艾萨拉寻找洛拉姆斯·萨里比迪斯。这位恶魔猎手知道拉瑟莱克受到了怎样的守护，但他需要一个从深海中夺来的名字。"
L["Seek Strahad Farsan, assemble the Tome of the Cabal, and prepare the felhunter binding."] = "寻找斯坦哈德·法尔杉，拼合阴谋之书，为束缚地狱猎犬做好准备。"
L["Seek the earth's sapta, speak with its manifestation, and return with your first totem."] = "寻找大地灵符，与大地的化身交谈，然后带着你的第一个图腾返回。"
L["Seek the halves of the pendant across lake and sea so the form of the sea lion may be taught."] = "在湖泊与大海中寻找坠饰的两半，以便学会水栖形态。"
L["Seek the Islander, gather the charms, and answer Bath'rah's summons for the whirlwind weapon."] = "寻找岛民，收集护符，然后响应巴斯拉的召唤，以获得旋风武器。"
L["Sentinel Elissa's missing scout was alive, but Balthule's report was grave. Warlocks held the tower, their parchments spoke of the Dark Strand, and the warning had to reach Ashenvale."] = "哨兵艾丽萨失踪的斥候还活着，但巴苏尔的报告令人忧心。术士们占据了高塔，他们的羊皮纸上提到了黑暗之链，这个警告必须送到灰谷。"
L["Shaw's report gave Gryan a name, but the messenger gave him movement. The Defias Traitor then led you through Moonbrook to the hidden entrance beneath the ruined town."] = "肖尔的报告给了格里安一个名字，而那名信使则让他掌握了对方的动向。随后，迪菲亚叛徒带着你穿过月溪镇，来到这座废弃小镇下方的隐秘入口。"
L["Speak with the proper trainer and bind the felsteed that will carry you on darker roads."] = "与相应的训练师交谈，束缚一匹将载着你踏上更黑暗道路的地狱战马。"
L["Sven's murdered family and Jitters' fear showed that Raven Hill was being worked by a darker hand. With Morbent's Bane prepared, you ended the necromancer beyond the graves."] = "斯温惨遭杀害的家人和吉特斯的恐惧表明，有一只更黑暗的手在操纵着乌鸦岭。准备好莫本特克星后，你在坟墓的另一头终结了那名死灵法师。"
L["Tabetha's work asked for texts, materials, and a measure of field sense. When the ritual was complete, your studies had a proper focus in hand."] = "塔贝萨的工作需要典籍、材料，还有几分野外经验。仪式完成后，你的研习终于有了一件称手的法器。"
L["Take Coleman's concern to Magistrate Sevren and descend into the crypt beneath the mills."] = "将库勒曼的担忧转告执政官塞弗伦，然后深入磨坊下方的墓穴。"
L["Take Johaan's work to Silverpine, recover Berard's research, and bring Faranell the samples he requires."] = "将乔汉的成果带到银松森林，找回贝拉德的研究，并将法拉尼尔所需的样本带给他。"
L["Take the soggy clue at its word and look for the next scrap where the riddle says it waits."] = "相信那条湿透的线索所说的话，到谜语指示的地方寻找下一张纸片。"
L["The Agamand Mills still bore the family name, though the family itself had joined Tirisfal's dead. You brought Coleman Farthing the remains he asked for and helped clear the grounds for Brill."] = "阿加曼德磨坊仍沿用着这个家族的姓氏，尽管这个家族本身早已加入了提瑞斯法林地的亡者之列。你为库勒曼·法席恩带回了他要的遗骸，帮助布瑞尔清理了这片土地。"
L["The amulet hunt sent you after pieces, components, and summoned echoes in dangerous places. Each recovery brought Lord Valthalak's broken pride closer to being called forth."] = "为了寻找护符，你在危险之地追寻碎片、材料和被召唤出的回响。每找回一样，瓦塔拉克公爵那破碎的傲慢就离被召唤出来更近一步。"
L["The Ancient Petrified Leaf proved to be a summons. The ancients named the demons, and by hunting them alone you earned the right to carry Rhok'delar."] = "古树的石化叶片原来是一道召唤。古树们说出了恶魔的名字，你独自猎杀了它们，赢得了持有洛克迪拉尔的权利。"
L["The Armory and Cathedral were the Crusade's creed made flesh. Houndmaster Loksey guarded the Library with trained violence. Herod turned recruits into zealots through spectacle and blood. In the Cathedral, Scarlet Commander Mograine and High Inquisitor Whitemane embodied the order's shining lie: holy words wrapped around endless war. Whether sent by Varimathras or Raleigh, you cut through the Monastery's saints and executioners alike."] = "军械库和大教堂是十字军信条的化身。驯犬者洛克希以训练有素的暴力守卫着图书馆。赫洛德用表演与鲜血将新兵变成狂热者。在大教堂中，血色十字军指挥官莫格莱尼和大检察官怀特迈恩体现了这个组织光鲜的谎言：用神圣的言辞包裹无休止的战争。无论是受瓦里玛萨斯还是莱雷所托，你都一路杀穿了修道院中的圣徒与刽子手。"
L["The Azsharite was raw possibility: crystal from a dangerous coast, named by a demon hunter, and meant for a foe normal steel could not touch. Galvan the Ancient gave that possibility form. Felbane was not an heirloom or a trophy. It was a blade for one brutal task: wound Razelikh's protected servants, gather the shattered amulet, and open the way to the demon himself."] = "艾萨莱特水晶蕴含着原始的可能：它来自危险的海岸，由一位恶魔猎手指名，专为对付寻常钢铁无法伤及的敌人而生。加尔文为这份可能赋予了形态。邪能克星不是传家宝，也不是战利品，而是一把只为一项残酷任务而存在的利刃：伤及拉瑟莱克那些受到保护的仆从，收集破碎的护符，打开通往那个恶魔本身的道路。"
L["The blue shard hid grave purpose beneath impossible errands. Azuregos sent you to Narain, and Narain's ledger demanded Molten Core goggles, a great chimaerok meal, a stolen book, a ransom drop, pages from dragons, the fires of Onyxia and Ragnaros, and Neptulon's wrath off Azshara's coast. Strange as it was, each step pulled the shard closer to the scepter."] = "蓝色碎片将重大的使命隐藏在一连串匪夷所思的差事之下。艾索雷苟斯派你去找纳瑞安，而纳瑞安的账本要求你取得熔火之心的护目镜、一顿丰盛的奇美洛克大餐、一本被盗的书、一笔赎金的交付、龙族的书页、奥妮克希亚与拉格纳罗斯的火焰，以及艾萨拉海岸外耐普图隆的怒火。尽管一切都显得古怪，每一步都让碎片离权杖更近。"
L["The call of air was brief, but it completed what the earlier trials began. Earth, fire, water, and air now stood with you."] = "空气的召唤虽然短暂，却完成了之前的试炼所开启的一切。大地、火焰、水与空气，如今都与你同在。"
L["The call of water sent you farther than the earlier trials. Through Barrens dust and distant roads, you learned the patience the element required."] = "水的召唤带你走得比之前的试炼更远。穿过贫瘠之地的尘土，踏上遥远的道路，你学会了这种元素所要求的耐心。"
L["The charger's trial demanded sacrifice, craft, and courage in haunted places. At the end, the spirit answered the Light and came to your side."] = "军马的试炼要求你在闹鬼之地付出牺牲、技艺与勇气。最终，那个灵魂回应了圣光，来到了你的身旁。"
L["The Circle sent you from lesson to remedy. You found the source of the sickness, gathered the cure, and restored creatures that had been left to suffer."] = "塞纳里奥议会让你从学习走向治疗。你找到了疾病的源头，收集了解药，让那些被弃于痛苦之中的生物恢复了健康。"
L["The Dalaran wizards at Ambermill were moving supplies and waking old ley-work beneath Silverpine. Shadow Priest Allister and Dalar Dawnweaver followed the evidence until Archmage Ataeric stood exposed."] = "安伯米尔的达拉然巫师们正在运送补给，并唤醒银松森林地下古老的魔力线工程。暗影牧师奥利斯特和达拉尔·道恩维沃尔顺着证据追查下去，最终揭穿了大法师阿塔埃瑞克。"
L["The dead of Darrowshire rose to fight again. You held the line, faced the corrupted Joseph Redpath, and gave Pamela the peace of knowing her father had come home."] = "达隆郡的亡者再度起身作战。你坚守阵线，直面堕落的约瑟夫·雷德帕斯，让帕米拉得知父亲已经回家，内心终于归于平静。"
L["The Deadmines were mine, factory, shipyard, and fortress. At the heart of it all stood Edwin VanCleef, whose death ended Westfall's immediate crisis and left one final letter behind."] = "死亡矿井既是矿场、工厂、船坞，也是要塞。站在这一切核心的是艾德温·范克里夫，他的死结束了西部荒野迫在眉睫的危机，只留下了最后一封信。"
L["The device revealed Anthion Harmon, a ghost bound by his sister's danger. You entered Stratholme, reached Ysida in time, and returned to the brother who had waited outside its gates."] = "那个装置让安泰恩·哈尔蒙现出了身形，这个鬼魂因妹妹身陷险境而无法安息。你进入斯坦索姆，及时赶到了伊思达身边，然后回到了一直在城门外等候的哥哥那里。"
L["The Elixir of Agony passed from blossom to composite, from Faranell's decay to Lydon's final activation. With Dun Garok stout as the vessel, the inn itself became the last test."] = "苦楚药剂的制作从花朵到合成剂，从法拉尼尔的腐化处理到林度恩的最终激活，一步步完成。以丹加洛克烈性黑啤作为载体，旅店本身成了最后的试验场。"
L["The Fallen Hero speaks of a regiment lost waiting for orders. Begin in Stonard and search the southern swamps for the command that never reached him."] = "英雄之魂讲述了一支在等待命令中迷失的部队。从斯通纳德出发，在南方的沼泽中寻找那道始终没能送到他手中的命令。"
L["The Fallen Hero's grief began with obedience. He led his soldiers toward the Blasted Lands and waited for orders that never came. Dispatch Commander Ruag remembered the lost message, Bengor remembered the ambush, and the Swamp Talker still held the Warchief's command. The truth was bitter: the regiment had been told to withdraw. The order never reached them."] = "英雄之魂的悲伤始于服从。他率领士兵前往诅咒之地，等待着一道从未到来的命令。分队指挥官鲁尔格记得那条遗失的消息，本戈尔记得那场伏击，而沼泽语者手中仍握着大酋长的命令。真相令人心酸：部队早已被下令撤退，只是这道命令从未送达。"
L["The felsteed was not purchased like an ordinary mount. It was called, bound, and made to bear the one who mastered the ritual."] = "地狱战马不像普通坐骑那样可以买到。它需要被召唤、被束缚，并被迫载负那位掌握了仪式之人。"
L["The fight moved from ghostly remorse to demon-hunter craft. Loramus Thalipedes understood Razelikh's ward, but knowledge had to be earned. Lord Arkkoroc gave up the beast's name only after Hetaera's heads were brought from the Bay of Storms, and Loramus used the blood to name the enemy properly. The demon's protections were no longer a mystery. Felbane had to be made."] = "战斗从幽魂的悔恨转向了恶魔猎手的技艺。洛拉姆斯·萨里比迪斯了解拉瑟莱克的守护结界，但知识必须靠自己去赢得。直到你从风暴海湾带回赫塔拉的头颅，亚考罗克才说出那头野兽的名字，而洛拉姆斯用它的血准确地道出了敌人之名。恶魔的防护不再是谜团，邪能克星必须被锻造出来。"
L["The final clue led to the great falls on the Hinterlands coast. Under the water, after pirates, mud, and raptors, Cortello's chest waited with a reward fit for a traveler."] = "最后的线索指向辛特兰海岸边的大瀑布。在经历了海盗、泥泞和迅猛龙之后，科尔特罗的宝箱正在水下静候，里面是一份适合旅行者的奖赏。"
L["The final proof came from General Drakkisath himself. His blood completed the amulet's power, and Rexxar turned the long road of commands, disguises, skulls, and trials into a single key. The Horde had its answer to Onyxia: strength tested across the world and deep inside Blackrock Spire."] = "最后的证明来自达基萨斯将军本人。他的血完成了护符的力量，而雷克萨将那条由命令、伪装、头骨和试炼铺就的漫长道路化为了一把钥匙。部落终于有了对付奥妮克希亚的答案：在世界各地和黑石塔深处经受过考验的力量。"
L["The first binding taught the warlock's bargain clearly. A creature of the void answered, resisted, and was made to serve."] = "第一次束缚清楚地揭示了术士的交易。一个虚空生物回应了召唤，奋起反抗，最终被迫臣服。"
L["The first Defias were thieves in the vineyards and bandits on the roads. By the time Morgan the Collector's ring reached Marshal Dughan, the red masks looked less like chance and more like organization."] = "最初的迪菲亚只是葡萄园里的小偷和路上的强盗。等到收货人莫根的戒指送到治安官杜汉手中时，这些红面具看起来已不像是偶然，而更像是一个组织。"
L["The first exchange began with a worn class bracer and a simple test of readiness. Deliana or Mokvar made the first improvement and sent you onward to Gadgetzan."] = "第一次交换始于一件破旧的职业护腕和一次简单的准备测试。德莉亚娜或莫克瓦尔完成了第一次改良，然后让你前往加基森。"
L["The first scroll waited in the hold of a Bloodsail ship with no one to explain it. Its verse led you beneath a bridge in the Swamp of Sorrows, where the next clue lay in the mud."] = "第一张卷轴静静躺在一艘血帆船的货舱里，没有人能解释它的来历。上面的诗句将你引到悲伤沼泽的一座桥下，下一条线索就埋在泥里。"
L["The first signs of Onyxia's reach came from the Burning Steppes, where Helendis Riverhorn watched black dragonkin gathering strength. Magistrate Solomon treated the threat as a kingdom matter, Bolvar Fordragon weighed it from Stormwind Keep, and Marshal Maxwell became the Alliance's field anchor. The question was no longer whether dragons were moving. It was who in Stormwind had allowed the threat to spread."] = "奥妮克希亚势力渗透的最初迹象来自燃烧平原，赫林迪斯·河角在那里注视着黑龙族集结力量。所罗门镇长将这一威胁视为关乎王国的大事，伯瓦尔·弗塔根在暴风要塞中权衡局势，麦克斯韦尔元帅则成为联盟在前线的支柱。问题已不再是巨龙是否在行动，而是暴风城中是谁放任了威胁蔓延。"
L["The Graveyard and Library showed the Crusade's order from the inside. Vorrel Sengutz lay tortured by Interrogator Vishas. Scholars wanted books the Crusade had locked away. Horde agents wanted the Compendium of the Fallen, and Parqual Fintallas wanted the book the Crusade used to teach itself how to fight the dead. Alliance scholars wanted the Mythology of the Titans. Every shelf and cell told the same truth: the Scarlet Crusade did not only kill enemies. It controlled what its followers were allowed to know."] = "墓地和图书馆从内部展现了十字军的秩序。沃瑞尔·森加斯正遭受审讯员韦沙斯的折磨。学者们想要十字军锁藏起来的书籍。部落的密探想要《堕落者纲要》，帕科瓦·芬塔拉斯则想要十字军用来自学如何对付亡灵的那本书。联盟的学者们想要《泰坦神话》。每一个书架、每一间牢房都诉说着同一个真相：血色十字军不仅杀戮敌人，还控制着追随者被允许知道的一切。"
L["The green shard was not won by simple killing. Eranikus had fallen into nightmare, and Remulos needed the corruption named before it could be answered. The defense of Moonglade became a rite before all who came to stand there: shades pouring from the Dream, Remulos holding the line, and Tyrande's grace turning a dragon's rage toward redemption."] = "绿色碎片无法靠单纯的杀戮赢得。伊兰尼库斯已坠入梦魇，雷姆洛斯需要先为这份腐化命名，才能做出回应。月光林地的保卫战成了所有前来驻守者面前的一场仪式：阴影从梦境中倾泻而出，雷姆洛斯坚守防线，泰兰德的恩典将一头巨龙的狂怒引向了救赎。"
L["The Horde's road to Onyxia began with Blackrock command papers and the old wound of the Blackhand name. Warlord Goretooth demanded proof from Lower Blackrock Spire, Eitrigg weighed the report in Orgrimmar, and Thrall sent you to kill Warchief Rend Blackhand. Rend's death was a declaration that the Horde would not bow to a false warchief propped up by dragons."] = "部落通往奥妮克希亚的道路始于黑石氏族的命令文书，以及黑手之名留下的旧伤。军官高图斯要求你从黑石塔下层带回证据，伊崔格在奥格瑞玛审阅了报告，萨尔则派你去击杀大酋长雷德·黑手。雷德之死是一份宣言：部落绝不会向一个由巨龙扶持的伪大酋长低头。"
L["The Islander tested your mettle, Bath'rah named the charms, and Cyclonian answered the call. When the storm was defeated, the weapon was yours."] = "岛民考验了你的勇气，巴斯拉说出了护符的名字，塞克隆尼亚回应了召唤。当风暴被击败时，那件武器便归你所有。"
L["The last climb belonged to the dead as much as the living. Grol the Destroyer, Archmage Allistarj, and Lady Sevine each held a piece of Razelikh's power, and Felbane made them mortal enough to fall. The united ward opened the Rise of the Defiler. There, above the ruined land that had swallowed a Horde regiment, Razelikh finally answered for the souls he chained. The Fallen Hero could not undo his failure, but he saw the demon broken and his soldiers released."] = "最后的攀登既属于生者，也同样属于亡者。毁灭者格罗尔、大法师阿利斯塔加和瑟温女士各自掌握着拉瑟莱克的一部分力量，而邪能克星让他们变得足以被击倒。合一的结界打开了通往污染者高地的道路。在那里，在这片吞噬了一支部落部队的废土之上，拉瑟莱克终于为他所禁锢的灵魂付出了代价。英雄之魂无法挽回自己的过失，但他亲眼看到了恶魔被击溃，他的士兵获得了解脱。"
L["The last preparations made the brazier ready. After ghosts, goblins, gladiators, and dungeon shades, the path narrowed to the chamber where Valthalak could answer."] = "最后的准备让火盆就绪。在经历了鬼魂、地精、角斗士和地下城中的幽影之后，道路最终收窄，通向了瓦塔拉克能够现身回应的那间密室。"
L["The last step was not to kill Yenniku, but to reach him. At the Ruins of Aboraz, beside Zanzil's servants and the haunted Crystal Shore, the Soul Gem turned violence into rescue. Yenniku's soul was pulled free of Zanzil's control and carried back to Nimboya. The work that had begun with trophies and cauldron smoke ended as a Darkspear promise: the tribe would remember the one who brought the chief's son home."] = "最后一步不是杀死耶尼库，而是触及他。在阿博拉兹废墟，在赞吉尔的仆从和闹鬼的水晶海岸旁，灵魂宝石将暴力化为了营救。耶尼库的灵魂挣脱了赞吉尔的控制，被带回尼姆布亚身边。这项始于战利品和大锅烟雾的工作，最终化作了暗矛部族的承诺：部族将会铭记那位把酋长之子带回家的人。"
L["The notice at Westbrook Garrison named a gnoll and a claw. Forest's Edge taught the rest. Hogger stood among the Riverpaw with enough strength to make a simple bounty feel like a hard lesson in the wilds beyond Elwynn's roads. When Marshal Dughan received the claw, the border toward Westfall felt less like open countryside and more like a warning."] = "西泉要塞的告示上写着一个豺狼人和一只爪子。其余的，林边空地会让你明白。霍格屹立于河爪豺狼人之中，他的力量足以让一份简单的悬赏变成艾尔文森林道路之外荒野中的一堂艰难课程。当治安官杜汉收到那只爪子时，通往西部荒野的边境看起来不再像是开阔的乡野，而更像是一个警告。"
L["The Plaguelands proved the Crusade had become more than a monastery. Scarlet banners flew over towers and towns, Stratholme's living quarter hid the Fordring family painting, and Hearthglen stood as a fortress of certainty. Tirion Fordring, exiled and alone, still believed his son could be saved from it. Forgotten memories, lost honor, and the painting became weapons against fanatic teaching. Disguised as Scarlet, you reached Taelan and watched him remember who he was before the Crusade taught him whom to hate."] = "瘟疫之地证明了十字军早已不只是一座修道院。血色旗帜飘扬在塔楼和城镇上空，斯坦索姆的生者区藏着弗丁家族的画像，壁炉谷则是一座笃信不疑的堡垒。被流放、孤身一人的提里奥·弗丁仍然相信能把儿子从中救出。被遗忘的回忆、失落的荣誉和那幅画像，都成了对抗狂热教化的武器。你伪装成血色十字军的一员，见到了泰兰，看着他想起了在十字军教他去恨谁之前，自己究竟是谁。"
L["The raft in Un'Goro held a compass, a curled map, a lion-headed key, and a photograph of a gnome in green. Linken knew the belongings, but memory would not come with them. The crater had left him with fragments of an errand, a blade without its tale, and the sense that someone had once entrusted him with more than he could remember."] = "安戈洛环形山的木筏里有一个罗盘、一张卷起的地图、一把狮头钥匙，以及一张身穿绿衣的侏儒的照片。林克认得这些物品，但记忆并没有随之归来。这座环形山只给他留下了一段差事的碎片、一把没有故事的剑，以及一种感觉：曾有人托付给他的东西，远比他能记起的更多。"
L["The records, letters, and keepsakes led from Duskwood to Stormwind, Elwynn, Westfall, and back again. At Mistmantle Manor, Stalvan's legend ended with his ring in Madame Eva's hands."] = "那些档案、信件和信物从暮色森林一路指向暴风城、艾尔文森林、西部荒野，然后又折返回来。在米斯特曼托庄园，斯塔文的传说随着他的戒指落入伊瓦夫人手中而告终。"
L["The red shard was the bluntest path and perhaps the cruelest. Vaelastrasz, already broken by Nefarian, could only point toward the master of Blackwing Lair and set a clock running. The shard was taken from Nefarian under pressure, a raid victory folded into the long duty of the scepter."] = "红色碎片是最直接的道路，或许也是最残酷的。早已被奈法利安摧残的瓦拉斯塔兹只能指向黑翼之巢的主人，并开始倒计时。碎片是在重压之下从奈法利安手中夺得的，一场团队副本的胜利就此融入了权杖的漫长使命。"
L["The red tear outside Ahn'Qiraj was memory made visible. Anachronos let the past speak: the night elves, dragons, and qiraji locked in a war old enough to feel mythic. The scepter had broken across dragonflights and tragedies. To open the gates, the champion would have to follow those wounds into the Emerald Dream, Blackwing Lair, and Azshara's blue-dragon riddles."] = "安其拉外的红色裂隙是化为有形的记忆。阿纳克洛斯让过去自己开口：暗夜精灵、巨龙和其拉虫人陷入了一场古老得近乎神话的战争。权杖在各大龙族军团和一场场悲剧中破碎。要打开大门，勇士必须循着这些创伤深入翡翠梦境、黑翼之巢，以及艾萨拉的蓝龙谜题。"
L["The second clue turned the riddle into a journey across the sea. In Dustwallow, among Bloodfen raptors, another scrap waited for anyone stubborn enough to keep reading."] = "第二条线索将这个谜题变成了一场跨海之旅。在尘泥沼泽的血沼迅猛龙之间，另一张纸片正等待着任何足够执着、愿意继续读下去的人。"
L["The Stockade did not end the matter. Thelwater's visitor, Baros' warning, Shaw's caution, and Trias' quiet knowledge all pointed toward a dangerous friend of the Brotherhood inside Stormwind."] = "暴风城监狱并没有让事情告一段落。塞尔沃特的访客、巴隆斯的警告、肖尔的谨慎和崔亚斯不动声色的了解，全都指向了暴风城中一位与兄弟会交好的危险人物。"
L["The succubus trial warned that not every danger arrives with brute force. You gathered what was required and bound temptation to command."] = "魅魔的试炼提醒你，并非所有的危险都以蛮力降临。你收集了所需之物，让诱惑听命于你。"
L["The Sunken Temple trial asked you to carry the elements as one calling. When the proofs were gathered, your mastery had been tested in full."] = "沉没的神庙的试炼要求你将诸元素作为同一种召唤来承载。当证明全部收集齐全时，你的掌控力已经受了全面的考验。"
L["The Tome of the Cabal led through old contacts and dangerous errands. When the binding was done, the felhunter's hunger became your weapon against magic."] = "阴谋之书让你重拾旧日的人脉，奔走于危险的差事之间。束缚完成后，地狱猎犬的饥渴成为了你对抗魔法的武器。"
L["The Tome of Valor led you to Daphne Stilwell and a hard lesson in service. Valor was not spoken over you; it was proven on a dangerous road."] = "勇气之书将你引向达芙妮·斯迪威尔，并给了你一堂关于奉献的艰难课程。勇气不是别人赐予你的称号，而是在危险的道路上证明出来的。"
L["The trail began beneath the broken Thandol Span, beside a dwarf pinned in the riverbed. Sully Balloo's letter was not a weapon, a map, or a royal order. It was a husband's goodbye, written before war turned private love into public loss. Sara Balloo received the letter in Ironforge and asked for only one thing more: that her king know what had been given in his name."] = "线索始于断裂的萨多尔大桥之下，一名矮人被压在河床上。苏利·巴鲁的信不是武器、地图或王室命令，而是一位丈夫的诀别，写于战争将私人的爱化为公众的损失之前。萨拉·巴鲁在铁炉堡收到了这封信，她只提出了一个请求：让她的国王知道，有人以他的名义付出了什么。"
L["The water trial carried you beyond the safety of your trainer. When the pendant was made whole, the sea lion form answered, and deeper waters opened to you."] = "水之试炼带你离开了训练师身边的安全地带。当坠饰重新合而为一时，水栖形态回应了你，更深的水域也向你敞开。"
L["The Woodpaw trail looked at first like scavenging. Then you found Raschal's backpacks pinned to a tree, still bearing Feathermoon insignia. One parcel could be delivered to Thalanaar, a small duty completed in the middle of the search. The other evidence mattered more: a note about strange insect creatures south of the gnoll camps. Raschal had not merely been attacked. He had chosen to investigate a threat under Feralas."] = "起初，木爪豺狼人的踪迹看起来不过是拾荒的痕迹。随后你发现拉沙尔的背包被钉在一棵树上，上面还带着羽月的徽记。其中一个包裹可以送往萨兰纳尔，在搜寻途中完成了一项小小的职责。另一件证据则更为重要：一张字条，提到豺狼人营地以南有奇怪的昆虫生物。拉沙尔并不只是遭到了袭击，他是主动选择去调查菲拉斯地下的一个威胁。"
L["The worgen were another fear in the dark, hunting through grove and orchard. Calor tested you against them until Master Carevin accepted that you could help keep their teeth from Darkshire."] = "狼人是黑暗中的另一种恐惧，在树林与果园中游猎。卡洛尔让你与它们交手以考验你，直到卡雷文大师认可你能帮忙让夜色镇免受它们的獠牙之害。"
L["The Writhing Deep made the whole case larger. Raschal was alive, sealed inside an alien pod by the Zukk'ash, and his report confirmed that Feralas was facing something more dangerous than a local hive. Shandris Feathermoon sent the warning to Darnassus, where Gracina Spiritmight named the threat: silithid. What began as a missing courier ended as an early warning about the insect menace waiting beneath Azeroth's southern deserts."] = "痛苦深渊让整个事件的规模变得更大。拉沙尔还活着，被祖卡什封在一个异形茧中，而他的报告证实了菲拉斯面临的东西远比一个本地虫巢更危险。珊蒂斯·羽月将警告送往达纳苏斯，格拉希娜·灵风在那里说出了这个威胁的名字：异种虫。一起信使失踪事件，最终成为了对潜伏在艾泽拉斯南方沙漠之下的虫族威胁的早期警告。"
L["Theldren's challengers waited in the Ring of Law, where words meant little. You survived the arena, and Anthion had what he needed for the next pieces."] = "塞尔德林的挑战者们在法律之环中等候，在那里言语毫无意义。你在竞技场中幸存下来，安泰恩也得到了制作下一批部件所需的东西。"
L["Theramore brought the mystery into the open without solving it. Commander Samaul sent you to Sentry Point, Archmage Tervosh guided you to Private Hendel, and Hendel's guard post became the last fight of the trail. When Hendel yielded, Jaina Proudmoore appeared to take charge of the prisoner and thank you quietly for services that could not be publicly named. You had exposed the kidnapping of King Varian Wrynn, but the larger wound remained open: the king was still missing, and someone powerful enough to use the Defias had not yet shown their face."] = "塞拉摩让谜团浮出水面，却没有将其解开。指挥官萨穆尔派你前往警戒哨岗，大法师特沃什指引你找到亨德尔下士，而亨德尔的哨所成了这条线索上的最后一战。亨德尔投降后，吉安娜·普罗德摩尔现身接管了囚犯，并低调地感谢你那些无法公开提及的贡献。你揭露了瓦里安·乌瑞恩国王被绑架一事，但更大的创伤依然存在：国王仍然下落不明，而一个强大到足以利用迪菲亚的人还没有露出真面目。"
L["Thomas sends you quietly to Bishop DeLavey in Stormwind Keep, where a missing envoy has become a private matter."] = "托马斯悄悄地派你去暴风要塞找德拉维主教，一名使节的失踪已经成了一件不便声张的私事。"
L["Tirion Fordring asks for aid in a personal matter that leads through Stratholme and Scarlet-held country."] = "提里奥·弗丁请你帮忙处理一件私事，这件事将带你穿过斯坦索姆和血色十字军控制的地区。"
L["Travel to Moonglade, hear the Great Bear Spirit, and return ready for the trial of body and heart."] = "前往月光林地，聆听巨熊之灵的教诲，然后做好准备，迎接身与心的试炼。"
L["Trias sends you into Old Town after Dashel Stonefist, whose answers pull the matter beyond Stormwind."] = "崔亚斯派你前往旧城区寻找达舍尔·石拳，他的回答将这件事引向了暴风城之外。"
L["Turn from worgen to Dalaran, gathering crates, pendants, and rune-work around Ambermill."] = "从狼人转向达拉然，在安伯米尔周边收集板条箱、坠饰和符文器物。"
L["Turn stolen Scarlet orders against Tyr's Hand and use Nathanos' disguise to walk inside their ranks."] = "用偷来的血色命令对付提尔之手，借助纳萨诺斯提供的伪装混入他们的队伍。"
L["Tyrion's disguise and spybot drew Lord Gregor Lescovar and Marzon the Silent Blade into the open. Their deaths carried the truth back through Trias, Baros, and the king's court."] = "泰里恩的伪装和侦察机器人将葛瑞格·莱斯科瓦公爵和沉默之刃马尔松引了出来。他们的死让真相经由崔亚斯、巴隆斯传回了国王的宫廷。"
L["Use Dartol's Rod to reach Krolg and turn against Ran Bloodtooth's corrupted furbolg."] = "使用达托尔的变形之杖接近克罗尔格，转而对抗兰恩·血牙手下堕落的熊怪。"
L["Use Mux's device near Stratholme, then race the city to save Ysida Harmon from the baron."] = "在斯坦索姆附近使用穆克斯的装置，然后与时间赛跑穿越城市，从男爵手中救出伊思达·哈尔蒙。"
L["Carry Kin'weelay's Soul Gem into the jungle and look for the moment to free Yenniku."] = "带着肯维雷的灵魂宝石进入丛林，寻找解救耶尼库的时机。"
L["Use the taming rod on the beasts your trainer names, then return to learn how to keep a companion."] = "对训练师指定的野兽使用驯兽棒，然后返回学习如何留住一个伙伴。"
L["Follow Linken's memory through strange visions and help his sword remember what he cannot."] = "追寻林克的记忆，穿越奇异的幻象，帮助他的剑记起他自己记不起的事情。"
L["Vaelastrasz gives little time for ceremony. The red shard must be claimed before the chance is lost."] = "瓦拉斯塔兹没留多少时间给繁文缛节。必须在机会消失前夺取红色碎片。"
L["VanCleef's letter reached Baros Alexston, who remembered the Stonemasons better than most. His concern led to Warden Thelwater, Bazil Thredd, and the riot within the Stockade."] = "范克里夫的信送到了巴隆斯·阿历克斯顿手中，他比大多数人都更了解石匠工会。他的担忧将你引向了典狱官塞尔沃特、巴基尔·斯瑞德，以及暴风城监狱中的暴动。"
L["When the shards were whole, the matter no longer belonged to one champion. The Might of Kalimdor waited on the war effort, the armies at the wall, and all who had prepared for the gates to open. The gong turned a repaired scepter into history: Ahn'Qiraj opened, and the war beyond the Scarab Wall began."] = "当碎片合而为一时，这件事就不再只属于一位勇士。卡利姆多的力量正等待着战争物资的筹备、驻守城墙的大军，以及所有为大门开启做好准备的人。那面锣将修复的权杖化作了历史：安其拉的大门开启，甲虫之墙后的战争就此打响。"
L["When your hunter trainer turns from weapons to trust, learn how to tame and train a beast. Later, if an ancient leaf ever finds its way into your hands, answer the stranger calling from Felwood."] = "当你的猎人训练师不再只谈武器，而是开始谈论信任时，去学习如何驯服和训练一只野兽吧。之后，如果一片古老的叶子落入你的手中，就去回应那个来自费伍德森林的陌生人的召唤。"
L["When your old dungeon armor has seen enough battle, Deliana or Mokvar will offer work that sounds simple enough: bring the right pieces, prove you are ready, and keep following instructions.\n\nThe errands soon reach far beyond a single set of bracers. Expect old dungeons, stranger patrons, expensive favors, and a brazier whose purpose is not explained all at once."] = "当你那套旧的地下城护甲已经历过足够多的战斗时，德莉亚娜或莫克瓦尔会给你一份听起来相当简单的工作：带来正确的部件，证明你已准备就绪，然后按指示行事。\n\n这些差事很快就会远远超出一副护腕的范畴。等待你的将是古老的地下城、更加古怪的雇主、代价高昂的人情，以及一个用途不会一下子全部揭晓的火盆。"
L["Win Theldren's challenge in Blackrock Depths so Anthion can continue the armor work."] = "在黑石深渊赢得塞尔德林的挑战，让安泰恩能够继续护甲的升级工作。"
L["With Athrikus Narassin weakened, Balthule sent you back into Althalaxx. You climbed past the warlocks of the Dark Strand and ended their master where he had gathered them."] = "在埃瑟里克斯·纳拉辛被削弱之后，巴苏尔派你重返奥萨拉克斯之塔。你一路攀登，越过黑暗之链的术士们，在他们的首领召集他们的地方将其终结。"
L["With Felbane in hand, follow the last names the Fallen Hero gives you and prepare for the demon's reckoning."] = "手握邪能克星，追寻英雄之魂告诉你的最后几个名字，为恶魔的清算做好准备。"
L["With Onyxia exposed, the Alliance still needed a way into her lair. Bolvar sent you to Haleh, hidden in Winterspring, and Haleh named the final price: the blood of General Drakkisath from Upper Blackrock Spire. The black dragonflight's own champion became the material for the Drakefire Amulet. The court conspiracy was over. The assault on Onyxia could begin."] = "奥妮克希亚的身份被揭穿后，联盟仍需要一条进入她巢穴的途径。伯瓦尔派你去找隐居在冬泉谷的哈尔琳，而哈尔琳道出了最后的代价：来自黑石塔上层的达基萨斯将军之血。黑龙军团自己的勇士，成了制作龙火护符的材料。宫廷阴谋已经终结，对奥妮克希亚的进攻可以开始了。"
L["With the Eye of Divinity in hand, seek Eris Havenfire and protect the spirits entrusted to you."] = "带着神圣之眼去寻找艾瑞斯·哈文法，保护托付给你的灵魂。"
L["With the three shards restored, take up the Scepter of the Shifting Sands and return to the Scarab Gong."] = "三块碎片复原后，手持变换流沙权杖，返回甲虫之锣。"
L["You answered the call to Moonglade and learned from the Great Bear Spirit. When the final trial was done, the strength of the bear was yours to call upon in battle."] = "你响应了前往月光林地的召唤，向巨熊之灵求教。当最后的试炼完成时，熊的力量便可供你在战斗中驱使。"
L["You approached the wild as a hunter must: with patience, caution, and respect. When the final beast yielded, you were no longer meant to travel alone."] = "你以猎人应有的方式走进荒野：耐心、谨慎，心怀敬意。当最后一头野兽臣服时，你便注定不再独自旅行。"
L["You carried ore, gems, and other hard-won materials back to Jordan Stilwell. Verigan's Fist was not granted by ceremony alone; it was made through effort."] = "你将矿石、宝石和其他来之不易的材料带回给乔丹·斯迪威尔。维里甘之拳并非仅凭仪式就能获得，它是用汗水打造出来的。"
L["You carried the sapta, listened to the earth, and proved steady enough to bear its totem. The first element had answered."] = "你带着灵符，聆听大地的声音，证明自己足够沉稳，能够承载它的图腾。第一种元素已经作出了回应。"
L["You returned to the one who started the work with a full trail behind you: rescues, bargains, spirits, and old dungeons. The final pieces made the upgraded set a record of where you had been."] = "你回到了最初委托这项工作的人身边，身后是一整条完整的足迹：救援、交易、灵魂和古老的地下城。最后的部件让这套升级后的装备成为了你一路走来的见证。"
L["Your first warrior lesson was not about striking harder. You learned to take the blow, hold your ground, and live long enough to answer."] = "你的第一堂战士课并不是教你如何打得更狠。你学会了承受攻击、坚守阵地，并活得足够久，以便作出反击。"
L["Your mage trainer sends you to Tabetha in Dustwallow Marsh, where practical magic begins with travel, errands, and materials that will not gather themselves.\n\nFollow the lessons that turn study into tools: a wand, a strange polymorph, and food enough for hungry companions."] = "你的法师训练师派你去尘泥沼泽找塔贝萨，在那里，实用的魔法始于旅行、跑腿，以及那些不会自己凑齐的材料。\n\n跟随这些将学识化为工具的课程：一根魔杖、一种奇特的变形术，以及足够喂饱饥饿同伴的食物。"
L["Your poison training taught the trade plainly: enter unseen, open what is locked, and survive the danger you mean to wield."] = "你的毒药训练直白地传授了这门手艺：悄然潜入，打开上锁之物，并在你打算驾驭的危险中活下来。"
