L["Breaking the Stones of Binding turned battle into mercy. One by one, the servants of Razelikh, Grol, Allistarj, and Sevine lost their anchors, and the dead soldiers were released from a fate worse than death. Corporal Thund Splithoof appeared long enough to honor the work and leave a token behind. Then one name remained: Lieutenant Kirith. Finding him in the Serpent's Coil revealed the next truth. Razelikh could not be reached until his protections were understood."] = "摧毁束缚之石，让战斗化为了仁慈。拉瑟莱克的仆从格罗尔、阿利斯塔加和瑟温一个接一个地失去了他们的锚点，阵亡的士兵也从比死亡更可怕的命运中解脱出来。桑德·裂蹄下士现身片刻，向这份功绩致敬，并留下了一件信物。随后，只剩下一个名字：基利斯中尉。在盘蛇谷找到他后，下一个真相浮出水面：在弄清拉瑟莱克的防护之前，根本无法接近他。"
