L["Castle Nathria fell, but Revendreth was not finished with its former ruler. In the Sanguine Depths, General Draven found Z'rali, the naaru whose Light had wounded the realm and whose mercy might yet help contain its sins. Then Remornia, Denathrius's living blade, became the prison that would hold him. The rebellion did not simply execute its master. It chose the harsher, stranger work Revendreth was built for: to bind arrogance, preserve what could still be redeemed, and let time do what vengeance could not."] = "纳斯利亚堡已经陷落，但雷文德斯与它昔日的统治者之间还没有了结。在赤红深渊，德莱文将军找到了兹拉利——这位纳鲁的圣光曾伤害过这片国度，而它的仁慈或许仍能帮助遏制此地的罪孽。随后，德纳修斯的活体之刃蕾茉妮雅成为了囚禁他的牢笼。反抗军并没有简单地处决他们的主人，而是选择了雷文德斯为之而生的那项更严苛、更奇特的工作：束缚傲慢，保全仍可救赎之物，让时间去完成复仇无法做到的事。"
L["Castle Nathria's Aftermath"] = "纳斯利亚堡的余波"
