L["Dashel Stonefist was exactly the sort of contact Trias expected: violent, useful, and unwilling to talk until persuaded. Once subdued, he admitted that his part had ended when the first plan failed. The backup plan involved someone from Menethil Harbor, a man called Slim. Trias knew enough to send you across the sea before the trail went cold."] = "达舍尔·石拳正是崔亚斯所预料的那种联络人：暴力、有用，而且不吃点苦头就不肯开口。被制服后，他承认第一个计划失败时，他的任务就已经结束了。备用计划涉及米奈希尔港的一个人，一个叫“干柴”的家伙。崔亚斯掌握的情况足以让他赶在线索断掉之前，派你渡海而去。"
L["Dashel's Lead"] = "达舍尔的线索"
