L["Dead Man's Plea"] = "死人的请求"
L["Death did not make the Bloodscalp leaders cooperative. Nezzliok wanted trophy skulls stolen from the Skullsplitters. Gan'zulah wanted Ana'thek's broken armor and a tally of Skullsplitter hunters, headhunters, and berserkers. The spirits were not redeemed by the cauldron. They were bribed, threatened, and indulged until they finally gave up the truth: Yenniku had not died with the Bloodscalps. Zanzil the Outcast had taken him."] = "死亡并没有让血顶部族的首领们变得配合。耐兹里奥克想要从碎颅巨魔那里偷来的战利品头骨。甘祖拉想要安纳塞克破碎的护甲，以及一份碎颅猎手、猎头者和狂暴者的击杀清单。大锅并没有让这些灵魂得到救赎。它们被贿赂、被威胁、被纵容，直到最终吐露真相：耶尼库并没有和血顶部族一起死去，带走他的是被放逐者赞吉尔。"
