L["Deathguard Samsa"] = "亡灵卫兵沙穆萨"
L["Deathknell taught the Forsaken their first lesson about Lordaeron's living survivors: the Scarlet Crusade did not see people, only infection. Executor Arren sent you against Scarlet converts and their courier, then read the stolen intelligence and understood the warning. The Crusade was watching Deathknell, counting the dead, and preparing for war."] = "丧钟镇让被遗忘者上了关于洛丹伦幸存生者的第一课：血色十字军眼中没有人，只有感染。执行官阿伦派你去对付血色皈依者和他们的信使，然后阅读了截获的情报，明白了其中的警告：十字军正在监视丧钟镇，清点亡者，准备开战。"
