L["Duskwood supplied the first hard evidence. Watcher Backus remembered Defias agents gathering around Addle's Stead, and the small farmhouse held the proof: a docket official enough to worry even a veteran watchman. Backus sent it back to Trias, and Trias saw the shape of the next lead in one familiar word: Fist."] = "暮色森林提供了第一份确凿的证据。守夜人巴库斯记得迪菲亚的特工曾在腐草农场附近聚集，而那座小农舍里藏着证据：一份正式得足以让老练的守夜人都感到不安的卷宗。巴库斯将它送回给崔亚斯，崔亚斯从一个熟悉的字眼中看出了下一条线索的轮廓：“拳”。"
