L["Ginro's next idea was strange even by night elf standards: give the knife to Quintis Jonespyre and let psychometry do what ordinary tracking could not. Quintis saw Raschal taking two large leather backpacks inland, worrying over Woodpaw gnolls, and failing to notice water elementals forming behind him. The knife did not solve the mystery, but it gave the search a direction and a new fear: Raschal had found something worse than gnolls."] = "基恩诺的下一个主意即便以暗夜精灵的标准来看也很奇怪：把匕首交给奎恩提斯，让触物通灵完成寻常追踪做不到的事。奎恩提斯看到拉沙尔背着两个大皮背包向内陆走去，一路担心着木爪豺狼人，却没有注意到身后正在成形的水元素。匕首没有解开谜团，但它为搜寻指明了方向，也带来了新的恐惧：拉沙尔发现了比豺狼人更可怕的东西。"
