L["Jaina and Anduin brought the Alliance's hammer down on Lordaeron. The Horde fought from the walls, but the siege was overwhelming. When the gates could no longer hold, Sylvanas triggered the plague systems beneath the city — releasing the Blight on her own capital rather than let the Alliance take it. Soldiers on both sides choked and died. The Undercity was lost, left poisoned and empty behind her. The Forsaken had no home left. Again."] = "吉安娜和安度因率领联盟向洛丹伦发起了雷霆一击。部落在城墙上奋战，但围城的攻势势不可挡。当城门再也守不住时，希尔瓦娜斯启动了城市下方的瘟疫装置——宁可将魔药释放在自己的首都，也不让联盟夺取它。双方的士兵都窒息而死。幽暗城就此失陷，在她身后只剩下一片被毒害的空城。被遗忘者再一次无家可归。"
