L["Magni could not answer Sara's grief with victory, so he answered with remembrance. Grand Mason Marblesten took the commission seriously, sending you into the Darrow Hill cave for Alterac Granite worthy of the memorial. When the stone was cut and the work was done, the tribute no longer belonged only to Sully Balloo. It stood for every soldier whose death had been reduced to orders, borders, and reports until someone stopped long enough to read the letter."] = "麦格尼无法用胜利回应萨拉的悲伤，于是他以纪念作为回应。大石匠玛布勒斯坦郑重地接下了这项委托，派你深入达隆山的洞穴，寻找配得上这座纪念碑的奥特兰克花岗石。当石头切割完毕、工程完成时，这份致敬已不再只属于苏利·巴鲁。它代表着每一位士兵——他们的死曾被简化为命令、边界和报告，直到有人愿意停下脚步，读一读那封信。"
L["Magni orders a rescue, but Blackrock Depths may make it more complicated than an ordinary fight."] = "麦格尼下令营救，但黑石深渊可能会让这件事比一场普通的战斗复杂得多。"
