L["Marshal Windsor's return turned suspicion into spectacle. At the gates of Stormwind, he gathered himself for one last duty and marched through the city toward the keep. The guards, nobles, and courtiers saw what the dragon had hidden from them: Lady Katrana Prestor was no noble advisor. She was Onyxia, broodmother of the black dragonflight. Windsor died exposing her, but his sacrifice broke the illusion around Bolvar and gave the Alliance a clear enemy at last."] = "温德索尔元帅的归来让怀疑变成了一场公开的对峙。在暴风城门口，他振作起来去履行最后的职责，穿过城市向要塞进发。卫兵、贵族和朝臣们看到了巨龙一直对他们隐瞒的真相：女伯爵卡特拉娜·普瑞斯托并非什么贵族顾问，她就是黑龙军团的龙后奥妮克希亚。温德索尔在揭露她时牺牲了，但他的牺牲打破了笼罩在伯瓦尔身边的幻象，也终于让联盟有了一个明确的敌人。"
