L["Nathanos Blightcaller understood the Scarlet Crusade as an enemy of logistics as much as faith. The Crimson Courier carried command papers through the Plaguelands. Varimathras wanted them read. Nathanos wanted them used. With a rotten apple and a Scarlet disguise, you walked into Tyr's Hand as if you belonged there, then returned with enough truth to send Demetria and her escort to their deaths on the road."] = "纳萨诺斯·凋零者明白，血色十字军不仅是信仰上的敌人，也是后勤上的敌人。红衣信使带着命令文书穿越瘟疫之地。瓦里玛萨斯想要读到这些文书，纳萨诺斯则想利用它们。凭借一个烂苹果和一身血色伪装，你若无其事地走进提尔之手，然后带回了足够的情报，让德米提雅和她的护卫在路上丧命。"
L["Nathanos' Ruse"] = "纳萨诺斯的计谋"
