L["Nezzliok's answer made the rescue feel almost impossible. Zanzil controlled Yenniku body and soul, and ordinary weapons could not solve that. Kin'weelay found one thin chance in the legends of Stranglethorn: the Mind's Eye. Pulsing blue shards from Crystalvein Mine prepared the ritual, and Mai'Zoth's ogres guarded the Eye itself inside the Mosh'Ogg mound. With both in hand, Kin'weelay could reshape the magic into a Soul Gem."] = "耐兹里奥克的回答让营救看起来几乎不可能。赞吉尔控制了耶尼库的身体和灵魂，普通的武器无法解决这个问题。肯维雷在荆棘谷的传说中找到了一线渺茫的希望：心灵之眼。来自水晶矿洞的脉动蓝色碎片为仪式做好了准备，而麦佐斯的食人魔则在莫什奥格食人魔山中守护着心灵之眼本身。两样东西都到手后，肯维雷便能将这股魔法重塑为一枚灵魂宝石。"
L["Night Run, Ashenvale"] = "夜道谷（灰谷）"
L["Night Web Venom"] = "夜行蜘蛛毒液"
L["Nighthaven, Moonglade"] = "永夜港（月光林地）"
L["Nimboya"] = "尼姆布亚"
L["Nimboya's search began with a fear no Darkspear wanted confirmed. Yenniku, the chief's youngest son, had vanished after being given to the Gurubashi, and the Bloodscalp tribe looked like the only trail left. Tusks proved you could hunt them. Shrunken heads proved Yenniku was not among their trophies. Finally, Gan'zulah and Nezzliok had to die so their heads could be forced to answer from the cauldron at Grom'gol."] = "尼姆布亚的搜寻始于一种暗矛部族谁都不愿证实的恐惧：酋长的幼子耶尼库被送给古拉巴什人之后便下落不明，而血顶部族似乎是仅存的线索。收集来的獠牙证明了他们可以被猎杀；缩小的头颅则证明耶尼库并不在他们的战利品之中。最后，甘祖拉和耐兹利奥克必须死，好让他们的头颅在格罗姆高的大锅中被迫开口作答。"
