L["Raene Wolfrunner feared for Teronis, and Ashenvale answered with a corpse. The murlocs near Lake Falathim had killed him, but his journal survived, along with the trail to a glowing gem. Returning both to Astranaar changed the task. Teronis had died looking for a way to slow the furbolg attacks, and Raene asked you to carry that hope forward."] = "莱恩·狼行者为特罗尼斯忧心忡忡，而灰谷给出的回应却是一具尸体。法拉希姆湖附近的鱼人杀害了他，但他的日记留存了下来，还有一条通往一颗发光宝石的线索。将两者带回阿斯特兰纳之后，任务的性质随之改变。特罗尼斯是在寻找延缓熊怪攻势的办法时丧命的，莱恩请你将这份希望延续下去。"
L["Raene's Cleansing"] = "莱恩的净化"
L["Rage of Blood"] = "血之狂暴"
L["Ragged John gave the conspiracy a name and a survivor: Marshal Reginald Windsor. Finding Windsor in Blackrock Depths did not bring immediate victory. He had lost hope, and the proof had been torn away from him. A crumpled note and a shred of evidence changed that. Windsor remembered his duty, gathered the missing information, and prepared for the impossible part: walking out of Blackrock Depths alive."] = "狼狈不堪的约翰为这场阴谋提供了一个名字和一位幸存者：雷吉纳德·温德索尔元帅。在黑石深渊找到温德索尔并没有带来立竿见影的胜利。他早已心灰意冷，手中的证据也已被人夺走。一张揉皱的纸条和一份残缺的证据改变了这一切。温德索尔重拾职责，搜集了缺失的情报，并准备迎接最不可能完成的部分：活着走出黑石深渊。"
