L["Shael'dryn knew what Teronis had been chasing: Dartol's Rod, broken into pieces and hidden across Ashenvale's corrupted places. The iron shaft lay behind a key carried by twisted treants near Felwood. The iron pommel had passed through Dor'danil's dead and into the slime. When the rod was remade, a hidden shrine gave it power again. By then, Teronis' errand had become something stranger: not a weapon, but a way to speak across the line between the uncorrupted and the lost."] = "莎尔蒂恩知道特罗尼斯一直在追寻什么：达托尔的魔杖。它已碎成数段，散落在灰谷各处遭到腐化的地方。铁质杖身藏在一把钥匙之后，而那把钥匙由费伍德森林附近扭曲的树人携带。铁质杖首则辗转经过多丹尼尔的亡者之手，落进了软泥之中。魔杖重铸之后，一座隐秘的神龛再次为它注入了力量。到那时，特罗尼斯的使命已经变得更加奇特：它不是一件武器，而是一种跨越界限、让未被腐化者与迷失者彼此交谈的途径。"
