L["Sylvanas Windrunner was a Ranger-General, then a corpse, then a queen the Horde was never fully prepared for. Slain by Arthas at the gates of Silvermoon and raised as the first of his banshees, she clawed her way back to herself and built an undead kingdom from the ruins of Lordaeron.\n\nFollow her from Icecrown and Silverpine into wars that test leadership, vengeance, survival, freedom, and the question of what remains when a Windrunner can no longer run from what she has done."] = "希尔瓦娜斯·风行者曾是游侠将军，后来成了一具尸体，再后来，又成了部落从未真正准备好面对的女王。她在银月城门前被阿尔萨斯杀死，被复活为他麾下的第一个女妖，却硬生生挣回了自我，并在洛丹伦的废墟上建立起一个亡灵王国。\n\n从冰冠冰川和银松森林出发，追随她走进一场场战争。这些战争考验着领导、复仇、生存与自由，也拷问着一个问题：当一位风行者再也无法逃避自己的所作所为时，她还剩下什么？"
