L["The bronze dragonflight did not greet mortals as allies. Baristolth's trial led to Anachronos, then back through Blackwing Lair and into the Silithus hives. The Head of Broodlord Lashlayer proved strength; the carapace fragments proved endurance. Before the scepter could be repaired, a champion first had to become someone the Brood of Nozdormu would even address."] = "青铜龙军团并没有把凡人当作盟友来迎接。巴里斯托斯的试炼将你引向阿纳克洛斯，随后又让你折返黑翼之巢，再深入希利苏斯的虫巢。勒什雷尔的头颅证明了力量，甲壳碎片则证明了毅力。在节杖得以修复之前，一位勇士必须先成为诺兹多姆的子嗣愿意开口交谈的人。"
