L["The Horde path entered the same crisis through a different door: a commander in chains, a prisoner with information, and Thrall reading the politics beneath the dungeon walls. Freeing Moira was not mercy alone. It was strategy. If a Dark Iron child could inherit Ironforge, then Blackrock Depths was not only a prison. It was a future capital waiting in the dark."] = "部落一方则从另一扇门踏入了同一场危机：一位身陷囹圄的指挥官，一名掌握情报的囚犯，还有洞察地下城高墙之下政治暗流的萨尔。解救茉艾拉不只是出于仁慈，更是出于谋略。如果一个黑铁血脉的孩子能够继承铁炉堡，那么黑石深渊就不只是一座监狱，而是一座在黑暗中静候的未来王都。"
