L["The Hunter's Path"] = "猎人之道"
L["the Imperial Seat, Blackrock Depths"] = "帝王之座，黑石深渊"
L["The Instigator's Enchantment"] = "旗帜上的附魔"
L["The investigation began with resignation. Latronicus had already declared Raschal missing in action, and Ginro Hearthkindle had spent a week searching Feralas for nothing but gnoll teeth and disappointment. The wrecked row boat on the Forgotten Coast changed that. It was shredded almost in two, marked with Feathermoon's crest, and hiding one small clue in the mud: Raschal's knife."] = "调查始于一片无奈。拉托尼库斯已经宣布拉沙尔在执行任务时失踪，而基恩诺·火花在菲拉斯搜寻了整整一周，除了豺狼人的牙齿和失望，一无所获。被遗忘的海岸上那艘失事的划艇改变了这一切。它几乎被撕成两半，上面印着羽月的徽记，而淤泥里还藏着一条小小的线索：拉沙尔的匕首。"
L["The investigation began with secrecy, not ceremony. Thomas found you near the Cathedral and sent you to Bishop DeLavey, who admitted that a diplomat sent to meet Jaina Proudmoore had disappeared. DeLavey suspected the Defias but could not prove it, so he pulled in people outside the usual channels: Jorgen by the Valley of Heroes, then Elling Trias above the cheese shop. The case had already moved from church business to spy work."] = "调查始于秘密行动，而非隆重仪式。托马斯在大教堂附近找到你，把你引荐给德拉维主教。主教承认，一位被派去会见吉安娜·普罗德摩尔的外交官失踪了。德拉维怀疑是迪菲亚兄弟会所为，却拿不出证据，于是找来了一些不走寻常渠道的人：先是英雄谷旁的乔贞，然后是奶酪店楼上的埃林·提亚斯。此案早已从教会事务变成了间谍工作。"
