L["The order sounded simple because grief needed it to be simple: kill Thaurissan, spare Moira, bring the princess home. Blackrock Depths answered with something crueler. When the emperor fell, Moira did not thank her rescuers. She mourned her husband, named her unborn child heir to Ironforge, and sent Magni a future he could not command away."] = "这道命令听起来很简单，因为悲痛需要它简单：杀死索瑞森，饶过茉艾拉，把公主带回家。黑石深渊给出的回应却残酷得多。大帝倒下后，茉艾拉并没有感谢前来营救她的人。她为丈夫哀悼，宣布自己腹中的孩子是铁炉堡的继承人，并给麦格尼送去了一个他无法用命令驱散的未来。"
