L["The rod transformed more than your shape. It let you approach Krolg, an uncorrupted furbolg who still carried grief and anger for what had happened to his people. Krolg blamed the night elves, but he also knew Ran Bloodtooth had become a threat no one could ignore. Killing Ran and his guards did not cleanse Ashenvale, but it proved Teronis had not died for nothing. Raene kept the skull and the rod as proof that the forest could still be defended."] = "这根魔杖改变的不只是你的形态。它让你得以接近克罗尔格——一名未被腐化的熊怪，他仍为族人的遭遇满怀悲痛与愤怒。克罗尔格将这一切归咎于暗夜精灵，但他也清楚，兰恩·血牙已经成了谁都无法忽视的威胁。杀死兰恩和他的卫兵并没能净化灰谷，却证明了特罗尼斯没有白白牺牲。莱恩留下了那颗头骨和魔杖，作为这片森林仍能守护的证明。"
