L["the Ruins of Aboraz, along the Crystal Shore"] = "水晶海岸沿岸的阿博拉兹废墟"
L["the Scarab Wall, Silithus"] = "甲虫之墙（希利苏斯）"
L["The Scarlet Bastion in Stratholme did not only guard soldiers and sermons. Its archive held the evidence Duke Nicholas Zverenhoff wanted burned, and Balnazzar's fall showed the deeper rot under the Crusade's purity. The order's zeal was not merely human cruelty. Something worse had been wearing it like a vestment."] = "斯坦索姆的血色堡垒守护的不只是士兵与布道。它的档案室里藏着尼古拉斯·瑟伦霍夫公爵想要焚毁的证据，而巴纳扎尔的陨落则揭示了十字军所谓纯洁之下更深的腐朽。这个组织的狂热并不只是人类的残忍。某种更可怕的东西一直把它当作法衣一般披在身上。"
