L["The trail through Midnight returned to Windrunner Spire, the family home that still held the sisters' wounds in its stone. The halls were not only abandoned; they were haunted by memory, loyalty, resentment, and grief. For Sylvanas's story, the dungeon is context rather than command: a place where the Windrunner name still aches, and where the past keeps answering long after everyone tried to leave it behind."] = "至暗之夜的旅程回到了风行者之塔——这座家族故居的石墙里，仍刻着姐妹们的伤痕。这些厅堂不只是荒废了，更萦绕着回忆、忠诚、怨恨与悲伤。对希尔瓦娜斯的故事而言，这个地下城是背景，而非必经之路：在这里，风行者之名依然隐隐作痛；即便所有人都试图将过去抛在身后，它仍在不断回应。"
