L["The way into the Sepulcher opened, and the covenants carried the fight into the machinery of creation. With the Crown of Wills reforged and Anduin freed, the final battle moved deeper into the Sepulcher, where Zovaal tried to remake reality through the First Ones' design. He failed. The Jailer fell, and the Shadowlands war finally ended. Only then could Sylvanas be brought before those she had wronged."] = "通往圣墓的道路已经开启，各大盟约将战火带入了造物的机械核心。意志头盔重铸，安度因获得解放，最终决战深入初诞者圣墓，佐瓦尔企图借助初诞者的设计重塑现实。他失败了。典狱长倒下，暗影国度的战争终于落幕。直到这时，希尔瓦娜斯才被带到那些曾被她伤害的人面前。"
