L["Thrall knew Onyxia's threat reached beyond Blackrock Mountain, so he sent you to Rexxar. The champion of the Horde carried old knowledge and a hard road: find Myranda, wear an illusion, gather dragon eyes in Upper Blackrock Spire, and use that disguise to reach Emberstrife. Where the Alliance exposed a dragon in court, the Horde had to deceive a dragon servant into opening the next gate."] = "萨尔知道奥妮克希亚的威胁远不止于黑石山，于是派你去找雷克萨。这位部落的勇士掌握着古老的知识，也指明了一条艰难的道路：找到迈兰达，披上幻象，在黑石塔上层收集龙眼，再借这身伪装接近埃博斯塔夫。联盟是在宫廷中揭穿了一条龙的真面目，而部落则必须骗过一名龙族仆从，让它打开下一道大门。"
