L["Vereesa's visions showed Silvermoon under a shadowed sun, and Arator went looking for the family legacy that might answer it. Alleria was still hunting Xal'atath, and Sylvanas remained in the Maw, freeing the souls she had condemned. So Arator followed the trail no one else wanted to walk: through Ve'nari's gate and into the realm of the damned. The Devouring Host followed him there, and together he and Sylvanas cut them out of the Tremaculum. Arator asked her to come home. Sylvanas refused. Her duty was still among the dead, but she gave him the answer he needed: Silvermoon did need a Windrunner, and he could be one."] = "温蕾萨的幻象中，银月城笼罩在一轮暗影之日下，于是阿拉托尔开始寻找或许能给出答案的家族传承。奥蕾莉亚仍在追猎萨拉塔斯，而希尔瓦娜斯依旧留在噬渊，解救那些曾被她定罪的灵魂。于是，阿拉托尔踏上了一条无人愿走的路：穿过威·娜莉的大门，进入受诅者的国度。吞噬大军尾随他而至，他与希尔瓦娜斯并肩作战，将它们逐出了特雷玛库鲁姆。阿拉托尔请她回家。希尔瓦娜斯拒绝了。她的职责仍在亡者之间，但她给了他所需要的答案：银月城确实需要一位风行者，而他就可以成为那个人。"
