L["Yiska"] = "伊斯卡"
L["You Are Rakh'likh, Demon"] = "恶魔拉瑟莱克"
L["You fought through the Ruins of Gilneas — sabotage, ambushes, a cat-and-mouse hunt through a shattered city — and cornered Godfrey, the man who had betrayed everyone at least once. Sylvanas raised him without ceremony. Then came the final push: Lorna Crowley was captured and brought before her. Sylvanas offered terms. The Gilneas Liberation Front could keep fighting and watch everything turn to dust, or stand aside. It was not a bluff. It was cold, precise, and entirely in character."] = "你一路杀穿吉尔尼斯废墟——破坏、伏击，在一座支离破碎的城市里展开猫鼠游戏——最终将高弗雷逼入绝境，这个人至少背叛过每个人一次。希尔瓦娜斯不加任何仪式便复活了他。随后是最后的攻势：罗娜·克罗雷被俘，押到了她面前。希尔瓦娜斯开出了条件：吉尔尼斯解放阵线可以继续战斗，眼看着一切化为尘土；也可以就此让开。这并非虚张声势。这一手冷酷、精准，完全符合她的作风。"
L["Ysida Harmon"] = "伊思达·哈尔蒙"
L["Yvette Farthing"] = "伊维特·法席恩"
L["Zanzil's Hold"] = "赞吉尔的据点"
L["Zekhan"] = "泽坎"
L["Zombie Juice"] = "僵尸"
L["Zukk'ash Pod"] = "祖卡什虫茧"
L["A Few Handfuls of Oats"] = "几把燕麦"
L["Gather oats from the farms of Westfall and bring them back to Verna Furlbrow for Old Blanchy."] = "从西部荒野的农场收集燕麦，带回给弗娜·法布隆，喂给老马布兰契。"
L["Jansen Stead, Westfall"] = "詹森农场，西部荒野"
L["Old Blanchy"] = "老马布兰契"
L["Poor Old Blanchy"] = "老马布兰契"
L["The Furlbrows had fled their farm with little more than a broken wagon and a hungry old horse. Eight handfuls of oats were not much against the trouble in Westfall, but for Blanchy and the people still trying to leave, it was enough to make the road feel possible again."] = "法布隆一家逃离农场时，几乎只剩下一辆坏掉的马车和一匹饥肠辘辘的老马。面对西部荒野的种种困境，八把燕麦算不了什么；但对布兰契和那些仍在设法离开的人来说，这已足以让前路重新变得可以走下去。"
L["Verna Furlbrow"] = "弗娜·法布隆"
L["Verna Furlbrow and her husband left their farm in a hurry, only for their wagon to break near the road into Westfall. Their old horse, Blanchy, has carried more than her share already.\n\nGather what oats you can from the nearby farms. It is a small kindness, but on a hard road even that can matter."] = "弗娜·法布隆和丈夫匆忙离开了农场，谁知马车却在通往西部荒野的路边坏了。他们的老马布兰契早已不堪重负。\n\n尽量从附近的农场收集些燕麦吧。这只是一点小小的善意，但在艰难的路上，哪怕这样也很重要。"
L["Defias camps around Elwynn Forest"] = "艾尔文森林各处的迪菲亚营地"
L["Farmer Furlbrow"] = "农夫法布隆"
L["Furlbrow's Deed"] = "法布隆的地契"
L["Recover the Furlbrows' watch from the pumpkin farm, return any stolen deed you find, and gather oats for Old Blanchy."] = "从南瓜农场找回法布隆家的怀表，交还你找到的被盗地契，并为老马布兰契收集燕麦。"
L["The Forgotten Heirloom"] = "遗失的怀表"
L["The Furlbrows had fled their farm with a broken wagon, a hungry old horse, and too little room for memory. The pocket watch was only a small thing, but it carried a wedding day and a home they might never see again. The oats were just as small, yet for Old Blanchy and the people still trying to leave Westfall, they made the road feel possible again."] = "法布隆一家逃离农场时，只带着一辆坏掉的马车和一匹饥饿的老马，再也装不下多少回忆。那块怀表只是件小东西，却承载着他们的婚礼之日，以及一个他们也许再也见不到的家。燕麦同样微不足道，但对老马布兰契和那些仍在设法离开西部荒野的人来说，它们让前路重新有了希望。"
L["Verna Furlbrow and her husband left their farm in a hurry, only for their wagon to break near the road into Westfall. Behind them are thieves in the fields, a farmhouse they may never see again, and a few keepsakes left in the rush.\n\nRecover what the Furlbrows could not carry, then gather oats for Blanchy. It is a small kindness on the edge of a larger ruin."] = "弗娜·法布隆和丈夫匆忙离开了农场，谁知马车却在通往西部荒野的路边坏了。在他们身后，是田间出没的盗贼、一座也许再也回不去的农舍，以及仓促间遗落的几件纪念品。\n\n找回法布隆一家没能带走的东西，再为布兰契收集些燕麦。在一场更大的浩劫边缘，这只是一点小小的善意。"
L["What They Left Behind"] = "遗落之物"
L["Westfall"] = "西部荒野"
L["Apothecary Faustin"] = "药剂师法奥斯丁"
L["Beggar's Haunt"] = "乞丐鬼屋"
L["Beggar's Haunt, Duskwood"] = "乞丐鬼屋（暮色森林）"
L["Deathstalker Zraedus"] = "亡灵哨兵莱度斯"
L["Deepstrider Giants"] = "深水行者巨人"
L["Duskwood / Swamp of Sorrows / Desolace"] = "暮色森林 / 悲伤沼泽 / 凄凉之地"
L["eastern Swamp of Sorrows"] = "悲伤沼泽东部"
L["Faustin's Serum"] = "法奥斯丁的药剂"
L["Infiltrator Marksen"] = "间谍玛克森"
L["Meet the Forsaken agents hidden in Duskwood and help prepare a truth serum for Stonard's prisoner."] = "与潜伏在暮色森林的被遗忘者特工会面，协助为斯通纳德的囚犯调制吐真剂。"
L["Mire Lord"] = "泥沼之王"
L["Misty Valley, Swamp of Sorrows"] = "迷雾谷（悲伤沼泽）"
L["North of the road into Deadwind Pass, two Forsaken agents keep a quiet post at Beggar's Haunt. A human infiltrator has seen too much, and Stonard's orcs have taken him alive before the matter could be settled.\n\nWork with Deathstalker Zraedus and Apothecary Faustin on a serum meant to draw out the truth. They are very particular about whose truth reaches the Horde."] = "在通往逆风小径的道路以北，两名被遗忘者特工在乞丐鬼屋悄然驻守。一名人类渗透者知道得太多了，而在此事了结之前，斯通纳德的兽人就已将他生擒。\n\n与亡灵哨兵莱度斯和药剂师法奥斯丁合作，调制一种能逼出真相的药剂。至于哪些真相能传到部落耳中，他们可是相当讲究。"
L["Nothing But The Truth"] = "真言药水"
L["Shadow Panthers"] = "暗影豹"
L["Stonard's Prisoner"] = "斯通纳德的囚犯"
L["The Truth Serum"] = "吐真剂"
L["the coast near Ethel Rethor, Desolace"] = "埃瑟雷索附近的海岸，凄凉之地"
L["Zraedus and Faustin called it help for their orcish allies, but every errand served the same purpose: keep the captive in Stonard from saying too much. The serum needed panther hearts, rare fungus, and a giant's tumor before Faustin could finish it. By the time Marksen drank the disguised brew, the truth was already losing its chance to be heard."] = "莱度斯和法奥斯丁声称这是在帮助他们的兽人盟友，但每一项差事都服务于同一个目的：让斯通纳德的俘虏没法说太多。法奥斯丁需要猎豹的心脏、稀有的真菌和巨人的肿瘤，才能完成这剂药。等到马克森喝下这剂经过伪装的药水时，真相已经快要失去被人听到的机会了。"
L["Zraedus's Request"] = "莱度斯的请求"
L["The Shady Rest Inn"] = "树荫旅店"
L["On the road between Dustwallow Marsh and the Barrens, the Shady Rest Inn is nothing but ash, hoofprints, a scorched shield, and a guard badge that should not be there.\n\nFollow the clues before faction blame buries the truth. What begins as a burned waystation becomes an investigation through evidence that may have been left to tell too simple a story."] = "在尘泥沼泽与贫瘠之地之间的路上，树荫旅店只剩下灰烬、蹄印、一面烧焦的盾牌，以及一枚本不该出现在那里的卫兵徽章。\n\n在阵营间的互相指责掩埋真相之前，追查这些线索。一座被焚毁的驿站，将引出一场调查——而那些证据，或许正是有人故意留下，好讲述一个过于简单的故事。"
L["Dustwallow Marsh"] = "尘泥沼泽"
L["World of Warcraft"] = "World of Warcraft"
L["Suspicious Hoofprints"] = "可疑的蹄印"
L["Hoofprints"] = "蹄印"
L["the ruins of the Shady Rest Inn, Dustwallow Marsh"] = "树荫旅店废墟，尘泥沼泽"
L["Foothold Citadel, Theramore Isle"] = "塞拉摩堡垒（塞拉摩岛）"
L["Lost Point, Dustwallow Marsh"] = "废弃哨塔（尘泥沼泽）"
L["North Point Tower, Dustwallow Marsh"] = "北点哨塔（尘泥沼泽）"
L["the Theramore blacksmith, Dustwallow Marsh"] = "塞拉摩的铁匠铺，尘泥沼泽"
L["Brackenwall Village, Dustwallow Marsh"] = "蕨墙村（尘泥沼泽）"
L["Theramore Isle, Dustwallow Marsh"] = "塞拉摩岛（尘泥沼泽）"
L["outside the ruins of the Shady Rest Inn, Dustwallow Marsh"] = "树荫旅店废墟外，尘泥沼泽"
L["Tabetha's Farm, Dustwallow Marsh"] = "塔贝萨的农场（尘泥沼泽）"
L["inside the ruins of the Shady Rest Inn, Dustwallow Marsh"] = "树荫旅店废墟内，尘泥沼泽"
L["The Ruins"] = "废墟"
L["Captain Garran Vimes sends you to the burned inn, where the first clues point in several uncomfortable directions."] = "盖兰·维米斯队长派你前往被焚毁的旅店，在那里，最初的线索指向了好几个令人不安的方向。"
L["The ruins did not offer a clean answer. Hoofprints marked the ash outside the inn, a blackened shield suggested a tauren hand, and a Theramore badge tied the scene to Lieutenant Paval Reethe. Even Smiling Jim's grief only sharpened the question: who wanted everyone looking at the wrong enemy?"] = "废墟并没有给出明确的答案。旅店外的灰烬中留着蹄印，一面烧黑的盾牌暗示着出自牛头人之手，而一枚塞拉摩徽章又将现场与帕瓦尔·雷瑟上尉联系在一起。就连微笑的吉姆的悲痛，也只让问题变得更加尖锐：是谁想让所有人都盯着错误的敌人？"
L["Inspecting the Ruins"] = "调查废墟"
L["Captain Garran Vimes"] = "盖兰·维米斯队长"
L["They Call Him Smiling Jim"] = "微笑的吉姆"
L["Guard Byron"] = "卫兵拜伦"
L["The Black Shield"] = "黑色盾牌"
L["Follow the scorched shield from the ruined fireplace back through Theramore's smiths."] = "从废墟的壁炉中找到那面烧焦的盾牌，再到塞拉摩的铁匠那里追查它的来历。"
L["The black shield looked like the simplest clue, and so it became the most dangerous one. Caz Twosprocket could tell it was not made in Theramore, and the size suggested a tauren bearer, but certainty stayed out of reach. The clue was real, yet it still felt planted to push anger toward the Horde."] = "黑色盾牌看似是最简单的线索，也因此成了最危险的线索。卡兹·双链看得出它并非塞拉摩所造，尺寸也暗示持盾者是一名牛头人，但确凿的结论依然遥不可及。这条线索是真的，却仍让人觉得是有人故意留下，好把怒火引向部落。"
L["Black Shield"] = "黑色盾牌"
L["The Black Shield: Caz Twosprocket"] = "黑色盾牌：卡兹·双链"
L["The Black Shield: Vimes' Report"] = "黑色盾牌：维米斯的报告"
L["Caz Twosprocket"] = "卡兹·双链"
L["Paval Reethe"] = "帕瓦尔·雷瑟"
L["Trace the Theramore Guard badge to Paval Reethe and the deserters at Lost Point."] = "循着塞拉摩卫兵徽章，追查帕瓦尔·雷瑟和废弃哨塔的逃兵。"
L["The guard badge led away from the inn and into Theramore's own troubles. Paval Reethe had deserted, and Balos Jacken's men at Lost Point had little love left for their old command. Reethe looked guilty enough to be useful, but not guilty enough to be the answer."] = "卫兵徽章将线索引离旅店，引向了塞拉摩自身的麻烦。帕瓦尔·雷瑟早已叛逃，而废弃哨塔里巴鲁斯·加科因的手下对他们的旧上司也没剩多少好感。雷瑟看上去有足够的嫌疑可供利用，却又没有足够的嫌疑成为真正的答案。"
L["Lieutenant Paval Reethe"] = "帕瓦尔·雷瑟上尉"
L["Theramore Guard Badge"] = "塞拉摩卫兵徽章"
L["Lieutenant Paval Reethe: Records"] = "帕瓦尔·雷瑟上尉：记录"
L["Daelin's Men"] = "戴林的下属"
L["Adjutant Tesoran"] = "泰索兰副官"
L["The Deserters"] = "背叛者"
L["The Deserters: Lost Point"] = "背叛者：废弃哨塔"
L["The Deserters: Balos' Account"] = "背叛者：巴鲁斯的说法"
L["Balos Jacken"] = "巴鲁斯·加科因"
L["The Hidden Hand"] = "幕后黑手"
L["The evidence carries you north to one more camp, then south to Tabetha for a clearer look at the hand behind the fire."] = "证据将你引向北方的另一座营地，然后再往南去找塔贝萨，看清这场大火背后的黑手。"
L["The missing piece was not a deserter or a city guard, but a Grimtotem move meant to poison Theramore and the Horde against each other. Captain Darill's evidence exposed Blackhoof Village as part of the plot, while Tabetha pointed to Direhorn Post as the real source of the attack. When the camp burned, the Shady Rest finally had an answer."] = "缺失的那一环既不是逃兵，也不是城中卫兵，而是恐怖图腾的一步棋，意在挑拨塞拉摩与部落反目成仇。达利尔上尉的证据揭露了黑蹄村是这场阴谋的一部分，而塔贝萨则指出恐角岗哨才是袭击的真正源头。当那座营地燃起大火时，树荫旅店终于有了答案。"
L["A Grim Connection"] = "恐怖的联系"
L["Confirming the Suspicion"] = "寻找证据"
L["Captain Darill"] = "达利尔上尉"
L["Arms of the Grimtotems"] = "恐怖图腾的武器"
L["Tabetha's Assistance"] = "塔贝萨的协助"
L["Raze Direhorn Post!"] = "摧毁恐角岗哨！"
L["Justice for the Hyals"] = "为希亚尔一家讨回公道"
L["Peace at Last"] = "终得安宁"
L["Krog has orders to investigate the burned inn, but the real clues are waiting in the ash."] = "克罗格奉命调查被焚毁的旅店，但真正的线索就埋在灰烬之中。"
L["The ruins were not merely Alliance grief. Hoofprints, a scorched shield, and a Theramore badge could all be read as accusations, and Krog wanted the Horde's answers before Theramore wrote the story for everyone. The evidence pointed at tauren ironwork and Paval Reethe, but neither trail felt complete."] = "这片废墟不只是联盟的伤痛。蹄印、烧焦的盾牌和塞拉摩徽章都可能被解读为指控，克罗格希望在塞拉摩替所有人定下说法之前，先为部落找到答案。证据指向了牛头人的铁器和帕瓦尔·雷瑟，但哪一条线索都不完整。"
L["Krog"] = "克罗格"
L["Carry the blackened shield through Brackenwall and Thunder Bluff until Mosarn can place the craft."] = "带着那面烧黑的盾牌前往蕨墙村和雷霆崖，直到莫萨恩认出它的工艺来历。"
L["The shield should have settled the matter, but it only made the case stranger. Krog, Do'gol, and Mosarn could follow the iron's story, yet the shield alone did not prove who set the fire. It was a clue with enough truth to be useful and enough ambiguity to start a war."] = "这面盾牌本该让事情水落石出，却只让案情变得更加离奇。克罗格、杜高尔和莫萨恩能够追溯这块铁的来历，但仅凭这面盾牌无法证明是谁放的火。这条线索真实到足以派上用场，也模糊到足以挑起一场战争。"
L["The Black Shield: Do'gol"] = "黑色盾牌：杜高尔"
L["The Black Shield: Do'gol's Findings"] = "黑色盾牌：杜高尔的发现"
L["Do'gol"] = "杜高尔"
L["The Black Shield: Return to Krog"] = "黑色盾牌：回到克罗格那里"
L["The Black Shield: Mosarn"] = "黑色盾牌：莫萨恩"
L["Track Paval Reethe with Ogron's help and see why the badge was left behind."] = "在奥格隆的帮助下追踪帕瓦尔·雷瑟，弄清那枚徽章为何会被留下。"
L["Paval Reethe was real, cornered, and dangerous, but the speed of his death made him look less like the murderer and more like a man someone needed silenced. The badge at the inn had not solved the case. It had revealed how badly someone wanted a convenient suspect."] = "帕瓦尔·雷瑟确有其人，走投无路，也很危险，但他死得如此之快，让他看起来不像凶手，倒更像是一个被人灭口的人。旅店里的徽章并没有让案子水落石出，反而暴露出有人多么迫切地想要一个现成的嫌疑人。"
L["Questioning Reethe"] = "盘问雷瑟"
L["Ogron"] = "奥格隆"
L["Mosarn's new lead brings the investigation back to Krog, then south to Tabetha for a clearer look at the hand behind the fire."] = "莫萨恩的新线索将调查带回克罗格那里，再往南去找塔贝萨，看清这场大火背后的黑手。"
L["Mosarn's memory reopened the case and pulled the scattered clues into one line: the Grimtotem had used the inn to inflame Theramore and the Horde. Krog's evidence and Tabetha's certainty led to Direhorn Post. Burning it down did not restore the Shady Rest, but it stopped the lie from doing more work."] = "莫萨恩的回忆让此案重新展开，也把零散的线索串成了一条线：恐怖图腾利用这家旅店，煽动塞拉摩与部落之间的怒火。克罗格的证据和塔贝萨的笃定将你引向恐角岗哨。烧毁那里并不能让树荫旅店恢复原貌，却让这个谎言无法再继续作祟。"
L["Return to Krog"] = "回到克罗格那里"
L["Mosarn"] = "莫萨恩"
L["More than Coincidence"] = "不止是巧合"
L["The Grimtotem Plot"] = "恐怖图腾的阴谋"
L["Seek Out Tabetha"] = "寻找塔贝萨"
L["Justice Dispensed"] = "正义得以伸张"
L["The Hakkari Trail"] = "哈卡莱的踪迹"
L["At Steamwheedle Port, Yeh'kinya asks for help with old troll spirits and older tablets. The work sounds archaeological at first, but the names on the tablets are not harmless history.\n\nFollow the trail from Feralas and Zul'Farrak to Jintha'Alor, the Temple of Atal'Hakkar, Blackrock Spire, and finally Yojamba Isle. What begins as a favor for a lone troll becomes a warning about the Soulflayer's return."] = "在热砂港，叶基亚请你帮忙处理一些古老的巨魔灵魂，以及更加古老的石板。起初，这听起来像是考古工作，但石板上的那些名字可不是无害的历史。\n\n沿着线索，从菲拉斯和祖尔法拉克前往辛萨罗、阿塔哈卡神庙、黑石塔，最终抵达尤亚姆巴岛。起初只是帮一个孤身巨魔的小忙，最终却成了夺灵者即将归来的警告。"
L["Tanaris / Feralas / Zul'Farrak / The Hinterlands / Sunken Temple / Blackrock Spire / Stranglethorn Vale"] = "塔纳利斯 / 菲拉斯 / 祖尔法拉克 / 辛特兰 / 沉没的神庙 / 黑石塔 / 荆棘谷"
L["Zul'Farrak"] = "祖尔法拉克"
L["Screecher Spirits"] = "尖啸者的灵魂"
L["Yeh'kinya"] = "叶基亚"
L["Steamwheedle Port, Tanaris"] = "热砂港（塔纳利斯）"
L["Zul'Farrak, near Gahz'rilla's pool"] = "祖尔法拉克，加兹瑞拉的水池附近"
L["the summit cave at Jintha'Alor, The Hinterlands"] = "辛萨罗山顶的洞穴，辛特兰"
L["the Sanctum of the Fallen God, Temple of Atal'Hakkar"] = "堕落之神圣殿，阿塔哈卡神庙"
L["Zul'Mashar, Eastern Plaguelands"] = "祖玛沙尔（东瘟疫之地）"
L["Lower Blackrock Spire"] = "黑石塔下层"
L["Yojamba Isle, Stranglethorn Vale"] = "尤亚姆巴岛（荆棘谷）"
L["Yeh'kinya sends you into Feralas to question the spirits of Vale Screechers."] = "叶基亚派你前往菲拉斯，向山谷尖啸者的灵魂问话。"
L["The first clue was not written on stone. Yeh'kinya's bramble drew memories from dead screechers in Feralas, and those spirits pointed toward an old troll prophecy. The errand had opened a door into Hakkari history."] = "第一条线索并未刻在石头上。叶基亚的荆棘从菲拉斯死去的尖啸者身上唤出了记忆，而这些灵魂指向了一则古老的巨魔预言。这趟差事为你打开了一扇通往哈卡莱历史的大门。"
L["The Prophecy of Mosh'aru"] = "摩沙鲁的预言"
L["Recover the first two Mosh'aru tablets from Zul'Farrak, then seek the ancient egg hidden in Jintha'Alor."] = "从祖尔法拉克取回前两块摩沙鲁石板，然后去寻找藏在辛萨罗的远古之卵。"
L["Zul'Farrak held the first tablets: one with Theka the Martyr, one near Hydromancer Velratha and the sacred pool. Their prophecy named an ancient egg, a relic from the age of troll empires. At Jintha'Alor, the egg waited behind the amphitheater at the top of the city, guarded by the kind of history that still had teeth."] = "祖尔法拉克藏着最初的石板：一块在殉教者塞卡身上，另一块在水占师维蕾萨和圣池附近。石板上的预言提到了一枚远古之卵，那是巨魔帝国时代的遗物。在辛萨罗，这枚蛋就在城市顶端的圆形剧场后面，守护它的，是一段依然锋利致命的历史。"
L["The Ancient Egg"] = "远古之卵"
L["The God Hakkar"] = "神灵哈卡"
L["Carry the egg into the Temple of Atal'Hakkar and bind the avatar's essence inside it."] = "将蛋带入阿塔哈卡神庙，把化身的精华封入其中。"
L["The temple in the Swamp of Sorrows gave the prophecy its true weight. The egg was not merely a container for old magic; it was a vessel for Hakkar's essence. In the Sanctum of the Fallen God, the avatar rose, fell, and left behind power Yeh'kinya had asked you to gather."] = "悲伤沼泽中的这座神庙让预言显露出真正的分量。那枚蛋不只是盛放古老魔法的容器，更是承载哈卡精华的器皿。在堕落之神圣殿中，化身现身、倒下，留下了叶基亚要你收集的力量。"
L["The Final Tablets"] = "最后的石板"
L["Prospector Ironboot reveals the missing tablets and sends you to Eastern Plaguelands and Lower Blackrock Spire."] = "勘查员詹斯·铁靴透露了缺失石板的下落，并派你前往东瘟疫之地和黑石塔下层。"
L["Prospector Ironboot saw the lie in the work Yeh'kinya had given you. There were six tablets, not two, and the rest changed the meaning of the prophecy. Zul'Mashar held the third and fourth; Lower Blackrock Spire held the final pair. Piece by piece, the tablets stopped sounding like a way to contain Hakkar and started sounding like a way to bring him back."] = "勘查员詹斯·铁靴看穿了叶基亚交给你的差事中的谎言。石板一共有六块，而不是两块，其余几块彻底改变了预言的含义。第三块和第四块在祖玛沙尔，最后两块则在黑石塔下层。随着石板一块块集齐，它们听起来不再像是封印哈卡的方法，反倒像是让他回归的途径。"
L["The Lost Tablets of Mosh'aru"] = "失落的摩沙鲁石板"
L["Prospector Ironboot"] = "勘查员詹斯·铁靴"
L["The Hand of Rastakhan"] = "拉斯塔哈之手"
L["Confront Yeh'kinya, then carry Ironboot's warning to Molthor on Yojamba Isle."] = "面对叶基亚，然后将铁靴的警告带给尤亚姆巴岛上的莫托尔。"
L["Yeh'kinya had not been preserving the world from Hakkar. He had sped the Soulflayer's return. The truth turned a long dungeon trail into a Zandalar summons, and Molthor received the warning on Yojamba Isle. The fight had moved beyond tablets and temples. Zul'Gurub was waiting."] = "叶基亚并非在保护世界免遭哈卡之害，而是在加速夺灵者的回归。真相将这条漫长的地下城之路化作了赞达拉的召唤，莫托尔在尤亚姆巴岛上收到了警告。战斗已不再局限于石板与神庙。祖尔格拉布正在等待。"
L["Confront Yeh'kinya"] = "面对叶基亚"
L["Maraudon"] = "玛拉顿"
L["The crystal caverns beneath Desolace are holy ground, burial ground, and wound all at once. Satyrs, centaur spirits, corrupted plants, and an earth princess all pull at the same buried story.\n\nEnter Maraudon from the orange and purple passages, recover the Scepter of Celebras, and follow the descent to Princess Theradras and the remains of Zaetar."] = "凄凉之地地下的水晶洞穴既是圣地，也是墓地，更是一道伤口。萨特、半人马的灵魂、被腐化的植物，还有一位大地公主，都在拉扯着同一段被埋藏的往事。\n\n从橙色和紫色通道进入玛拉顿，取回塞雷布拉斯节杖，然后一路深入，去面对瑟莱德丝公主和扎尔塔的遗骸。"
L["Desolace / Maraudon / Moonglade"] = "凄凉之地 / 玛拉顿 / 月光林地"
L["The Pariah's Instructions"] = "贱民的指引"
L["Centaur Pariah"] = "半人马贱民"
L["southern Desolace"] = "凄凉之地南部"
L["southern Desolace, near the Valley of Spears"] = "凄凉之地南部，长矛谷附近"
L["Kormek's Hut, Desolace"] = "考米克小屋（凄凉之地）"
L["Shadowprey Village, Desolace"] = "葬影村（凄凉之地）"
L["the orange crystal passage, Maraudon"] = "橙色水晶通道，玛拉顿"
L["south of Shadowprey Village, Desolace"] = "葬影村以南，凄凉之地"
L["Earth Song Falls, Maraudon"] = "大地之歌瀑布，玛拉顿"
L["The Pariah and the Prophet"] = "贱民与先知"
L["Follow the Centaur Pariah's instructions and heed Willow's request for Maraudon's carved crystals."] = "按照半人马贱民的指引行事，并留意维洛索要玛拉顿雕刻水晶的请求。"
L["Before the inner caverns, Maraudon offered two warnings. The Centaur Pariah named the khans and the Nameless Prophet, a path through the centaur dead. Willow, far less trustworthy, wanted Theradric carvings from the same twisted place. Both errands made the caverns feel older than Desolace's current wars."] = "在深入内部洞穴之前，玛拉顿给出了两个警告。半人马贱民说出了诸位可汗与无名先知的名号，那是一条穿过半人马亡者的道路。远不如他可信的维洛，则想要从这片扭曲之地取得瑟莱德丝水晶雕刻。这两项差事都让人觉得，这些洞穴远比凄凉之地如今的战争更加古老。"
L["Twisted Evils"] = "扭曲的邪恶"
L["Willow"] = "维洛"
L["Vyle Corruption"] = "邪秽腐化"
L["Cleanse Vylestem vines in the orange caverns and gather shadowshards from the purple side."] = "净化橙色洞穴中的邪茎藤蔓，并在紫色区域收集暗影碎片。"
L["Vyletongue's corruption was not only demonic; it had soaked into Maraudon's plants and crystals. Talendria or Vark sent you to fill a vial at the orange pool and draw the poison out plant by plant. The shadowshards outside the purple passage told the same story in stone: the caverns were sick, and the sickness had useful fragments for people outside."] = "维利塔恩的腐化不只是恶魔之力，它已经渗入了玛拉顿的植物与水晶之中。塔琳德莉亚或瓦克派你去橙色水池装满一瓶池水，再一株一株地吸出植物中的毒素。紫色通道外的暗影碎片则用石头讲述着同样的故事：这些洞穴病了，而这场病孕育出的碎片，对外面的人来说却大有用处。"
L["Vyletongue Corruption"] = "维利塔恩的污染"
L["Talendria"] = "塔琳德莉亚"
L["Vark Battlescar"] = "瓦克·战痕"
L["Shadowshard Fragments"] = "暗影残片"
L["Theramore, Dustwallow Marsh"] = "塞拉摩，尘泥沼泽"
L["Uthel'nay"] = "尤塞尔奈"
L["The Scepter of Celebras"] = "塞雷布拉斯节杖"
L["Recover the Celebrian rod and diamond, free Celebras, and restore the scepter."] = "取回塞雷布拉斯之杖和塞雷布拉斯钻石，解救塞雷布拉斯，并修复节杖。"
L["Cavindra's plea gave the dungeon its heart. Noxxion held the rod, Lord Vyletongue held the diamond, and Celebras himself wandered under corruption. Once the keeper was defeated and redeemed, the two pieces could become a scepter again, not only a shortcut through Maraudon but a sign that some part of the place could still be restored."] = "凯雯德拉的恳求赋予了这座地下城真正的核心。诺克赛恩持有魔杖，维利塔恩领主持有钻石，而塞雷布拉斯本人则在腐化中游荡。守护者一旦被击败并得到救赎，这两件物品便能重新合为一根节杖——它不只是穿越玛拉顿的捷径，更证明了这里仍有一部分能够得到复原。"
L["Legends of Maraudon"] = "玛拉顿的传说"
L["Cavindra"] = "凯雯德拉"
L["Celebras the Redeemed"] = "赎罪的塞雷布拉斯"
L["Corruption of Earth and Seed"] = "大地的污染"
L["Slay Princess Theradras, learn what became of Zaetar, and carry the Seed of Life to Remulos."] = "杀死瑟莱德丝公主，查明扎尔塔的下落，并将生命之种带给雷姆洛斯。"
L["At the bottom of Maraudon, Princess Theradras guarded both destruction and grief. Zaetar's remains had fed the place into strange life, and his spirit asked for something gentler than vengeance: a seed carried to his brother in Moonglade. The dungeon ended not with a clean victory over the centaur's origin, but with proof that Zaetar had become part of the land."] = "在玛拉顿的最深处，瑟莱德丝公主守护着毁灭，也守护着悲伤。扎尔塔的遗骸滋养着这里，孕育出奇异的生命，而他的灵魂所求的比复仇更加温和：将一颗种子带给他身在月光林地的兄弟。这座地下城的终点并非对半人马起源的干脆胜利，而是证明了扎尔塔已化为这片大地的一部分。"
L["Keeper Marandis"] = "守护者玛兰迪斯"
L["Selendra"] = "瑟琳德拉"
L["Seed of Life"] = "生命之种"
L["Zaetar's Spirit"] = "扎尔塔的灵魂"
L["Scarlet Monastery Library, Tirisfal Glades"] = "血色修道院图书馆，提瑞斯法林地"
L["Retrieve %s from %s and return to %s in %s."] = "取回%s（%s），然后返回%s处（%s）。"
L["the Monastery in Tirisfal Glades"] = "提瑞斯法林地的修道院"
L["Going, Going, Guano!"] = "蝙蝠的粪便"
L["Caer Darrow's ruined school is locked behind more than a door. The Scourge has made Scholomance a place of experiments, ghosts, noble inheritance, and old betrayals that refuse to stay buried.\n\nForge the Skeleton Key, then follow the stories waiting inside: Eva Sarkhoff's revenge, Kirtonos, Ras Frostwhisper's lost humanity, and the Barov family's poisoned fortune."] = "凯尔达隆这所废弃的学院，锁住它的远不止一扇门。天灾军团将通灵学院变成了一个充斥着实验、幽魂、贵族遗产和陈年背叛的地方，而那些往事始终不肯安息。\n\n锻造骷髅钥匙，然后去追寻学院内等待着你的故事：艾瓦·萨克霍夫的复仇、基尔图诺斯、莱斯·霜语失落的人性，以及巴罗夫家族那笔贻害无穷的家产。"
L["Western Plaguelands / Tanaris / Un'Goro Crater / Scholomance"] = "西瘟疫之地 / 塔纳利斯 / 安戈洛环形山 / 通灵学院"
L["the ruins of Andorhal, Western Plaguelands"] = "安多哈尔废墟，西瘟疫之地"
L["Doctor Theolen Krastinov's room, Scholomance"] = "瑟尔林·卡斯迪诺夫教授的房间，通灵学院"
L["the Chamber of Summoning, Scholomance"] = "召唤之厅，通灵学院"
L["near the Bulwark, Tirisfal Glades"] = "亡灵壁垒附近，提瑞斯法林地"
L["The Skeleton Key"] = "骷髅钥匙"
L["After proving yourself in the Plaguelands, forge the Skeleton Key that opens Scholomance."] = "在瘟疫之地证明自己之后，锻造能开启通灵学院的骷髅钥匙。"
L["Scholomance was not simply entered. Arbington or Dithers sent you through bones from Andorhal, a costly goblin mold in Gadgetzan, a forging at Fire Plume Ridge, and Araj's scarab in the ruined city. The finished Skeleton Key turned Caer Darrow's locked academy from a rumor into a place you could finally confront."] = "通灵学院并非想进就能进。阿尔宾顿或迪瑟斯让你一步步完成了准备：从安多哈尔取来骨头，在加基森弄到一个昂贵的地精模具，在火羽山完成锻造，再到那座废城中夺取阿拉基的圣甲虫。完成的骷髅钥匙让凯尔达隆这座紧锁的学院不再只是传闻，而成了你终于可以直面的地方。"
L["Skeletal Fragments"] = "骸骨碎片"
L["Alchemist Arbington"] = "化学家阿尔比顿"
L["Apothecary Dithers"] = "药剂师迪瑟斯"
L["Mold Rhymes With..."] = "昂贵的模具"
L["Fire Plume Forged"] = "火羽山"
L["Krinkle Goodsteel"] = "克林科·古德斯迪尔"
L["Araj's Scarab"] = "阿拉基的圣甲虫"
L["The Key to Scholomance"] = "通灵学院的钥匙"
L["The Sarkhoffs"] = "萨克霍夫夫妇"
L["Eva Sarkhoff asks you to punish Krastinov, recover his bag, and summon Kirtonos."] = "艾瓦·萨克霍夫请你惩罚卡斯迪诺夫，取回他的袋子，并召唤基尔图诺斯。"
L["Eva Sarkhoff's grief had been waiting outside the school. Doctor Theolen Krastinov had butchered her family, and Jandice Barov guarded the next proof. When the Blood of Innocents called Kirtonos to the balcony, Scholomance answered with one of its own monsters, and Eva's vengeance finally had form."] = "艾瓦·萨克霍夫的悲痛一直在学院外等待着。瑟尔林·卡斯迪诺夫教授屠戮了她的家人，而詹迪斯·巴罗夫则守护着下一份证据。当无辜者之血将基尔图诺斯召唤到阳台上时，通灵学院以它自己的一头怪物作出了回应，艾瓦的复仇终于有了具体的形态。"
L["Doctor Theolen Krastinov, the Butcher"] = "瑟尔林·卡斯迪诺夫教授"
L["Eva Sarkhoff"] = "艾瓦·萨克霍夫"
L["Krastinov's Bag of Horrors"] = "卡斯迪诺夫的恐惧之袋"
L["Kirtonos the Herald"] = "传令官基尔图诺斯"
L["Ras Frostwhisper"] = "莱斯·霜语"
L["Learn who Ras Frostwhisper was, restore the memory of his death, and face the lich in Scholomance."] = "了解莱斯·霜语生前的身份，重现他死亡时的记忆，并在通灵学院与这名巫妖对决。"
L["Ras Frostwhisper was not born a lich. Magistrate Marduke and Artist Renfray helped recover the human truth beneath the monster: a keepsake, a memory at Menethil's Gift, and a ritual strong enough to pull Ras back toward mortality. In Scholomance, the keepsake made him vulnerable. Killing him ended a lich and returned a human head to Caer Darrow."] = "莱斯·霜语并非生来就是巫妖。马杜克镇长和画家瑞弗蕾帮助你找回了这头怪物之下属于人类的真相：一件纪念品，一段在米奈希尔的礼物留下的记忆，以及一场足以将莱斯拉回凡人之躯的仪式。在通灵学院中，那件纪念品让他变得脆弱。杀死他，终结了一名巫妖，也将一颗人类的头颅带回了凯尔达隆。"
L["The Human, Ras Frostwhisper"] = "莱斯·霜语"
L["Magistrate Marduke"] = "马杜克镇长"
L["The Dying, Ras Frostwhisper"] = "亡灵莱斯·霜语"
L["Menethil's Gift"] = "米奈希尔的礼物"
L["Soulbound Keepsake"] = "禁锢灵魂的遗物"
L["The Lich, Ras Frostwhisper"] = "巫妖莱斯·霜语"
L["Barov Family Fortune"] = "巴罗夫家族的宝藏"
L["Recover the Barov deeds from Scholomance, then choose which heir becomes the last Barov."] = "从通灵学院中找回巴罗夫家族的地契，然后选择哪位继承人将成为最后的巴罗夫。"
L["The Barov fortune was scattered through Scholomance in deeds to Brill, Tarren Mill, Southshore, and Caer Darrow. Alexi and Weldon each claimed the inheritance and each wanted the other dead. When the papers were recovered, the family matter became murder by proxy, and one brother's claim ended at the other's feet."] = "巴罗夫家族的财富以地契的形式散落在通灵学院各处，涉及布瑞尔、塔伦米尔、南海镇和凯尔达隆。阿莱克斯和维尔顿都声称自己才是继承人，也都想置对方于死地。地契找回之后，这桩家务事变成了借刀杀人，其中一位兄弟的继承之争，最终在另一人的脚下画上了句号。"
L["Weldon Barov"] = "维尔顿·巴罗夫"
L["Alexi Barov"] = "阿莱克斯·巴罗夫"
L["The Last Barov"] = "巴罗夫的继承人"
L["Near Ashenvale's northern border, the Howling Vale is full of wolf-men that should not be there. Sentinel Melyria Frostshadow believes the Tome of Mel'Thandris may explain why.\n\nFollow Velinde Starsong's trail from Ashenvale to Darnassus, Ratchet, Booty Bay, and Duskwood. The scythe's story is not tidy, but it is one of Classic's clearest windows into the first mysteries of the worgen."] = "在灰谷北部边境附近，狼嚎谷里满是本不该出现在那里的狼人。哨兵梅丽瑞亚·霜影认为，《梅尔萨兰迪斯之书》或许能解释其中缘由。\n\n追随维琳德·星歌的足迹，从灰谷前往达纳苏斯、棘齿城、藏宝海湾和暮色森林。这把镰刀的故事并不简单明了，但它是经典旧世中最清晰地揭示狼人最初谜团的窗口之一。"
L["Ashenvale / Darnassus / The Barrens / Stranglethorn Vale / Duskwood"] = "灰谷 / 达纳苏斯 / 贫瘠之地 / 荆棘谷 / 暮色森林"
L["The Howling Vale"] = "狼嚎谷"
L["Sentinel Melyria Frostshadow"] = "哨兵梅丽瑞亚·霜影"
L["Forest Song, Ashenvale"] = "林歌神殿（灰谷）"
L["the Howling Vale, Ashenvale"] = "狼嚎谷（灰谷）"
L["the Warrior's Terrace, Darnassus"] = "战士区，达纳苏斯"
L["the Sentinels' bunkhouse, Darnassus"] = "哨兵营房，达纳苏斯"
L["Ratchet, The Barrens"] = "棘齿城（贫瘠之地）"
L["Booty Bay, Stranglethorn Vale"] = "藏宝海湾（荆棘谷）"
L["Darkshire Town Hall, Duskwood"] = "夜色镇议政厅，暮色森林"
L["Roland's Doom, Duskwood"] = "罗兰之墓（暮色森林）"
L["Study the Tome of Mel'Thandris and learn why worgen have appeared near the Felwood border."] = "研读《梅尔萨兰迪斯之书》，查明狼人为何会出现在费伍德森林边境附近。"
L["The Tome of Mel'Thandris did not give a plain report. It showed Velinde Starsong praying for help against demons and receiving the Scythe of Elune in answer. The worgen in the Howling Vale were no local accident. They were tied to a night elf priestess, a weapon, and a call that had gone wrong."] = "《梅尔萨兰迪斯之书》给出的并不是一份直白的报告。书中记载了维琳德·星歌祈求援助以对抗恶魔，并得到了艾露恩之镰作为回应。狼嚎谷里的狼人绝非当地的偶然事件。它们与一位暗夜精灵女祭司、一件武器，以及一次出了差错的召唤紧密相连。"
L["Velinde Starsong"] = "维琳德·星歌"
L["Carry Melyria's concern to Darnassus and search Velinde's stored effects."] = "将梅丽瑞亚的担忧带到达纳苏斯，并搜查维琳德留存的遗物。"
L["Darnassus remembered Velinde as a trusted priestess, not a villain. Thyn'tel Bladeweaver opened her stored belongings, and the journal inside changed the search from a military report into a missing-person trail. Velinde had used the scythe, lost control of the worgen, and disappeared while seeking help far from Ashenvale."] = "在达纳苏斯，人们记得的维琳德是一位值得信赖的女祭司，而非恶人。塞恩提尔·刃纹打开了她存放的物品，其中的日记让这场调查从一份军事报告变成了一次寻找失踪者的追查。维琳德使用了那把镰刀，却失去了对狼人的控制，随后在远离灰谷寻求帮助时失踪了。"
L["Velinde's Effects"] = "维琳德的日记"
L["Thyn'tel Bladeweaver"] = "塞恩提尔·刃纹"
L["Across the Sea"] = "远渡重洋"
L["Follow Velinde's travel records from Ratchet to Booty Bay and onto the roads north."] = "循着维琳德的旅行记录，从棘齿城前往藏宝海湾，再踏上北去的道路。"
L["Velinde's journal sent the trail across the world instead of deeper into Ashenvale. Ratchet remembered her passage to Booty Bay, and Booty Bay's caravan records pointed north toward Duskwood. The scythe had crossed continents, leaving only ship ledgers, goblin memory, and a road through dangerous country."] = "维琳德的日记没有把线索引向灰谷深处，而是引向了世界的另一端。棘齿城的人记得她搭船前往藏宝海湾，而藏宝海湾的商队记录又指向北方的暮色森林。那把镰刀横跨了大陆，只留下船只的账簿、地精的记忆，以及一条穿越险境的道路。"
L["The Barrens Port"] = "贫瘠之地的港口"
L["Passage to Booty Bay"] = "藏宝海湾的航道"
L["Wharfmaster Dizzywig"] = "码头管理员迪兹维格"
L["The Caravan Road"] = "商队通路"
L["Caravaneer Ruzzgot"] = "旅行者拉兹戈特"
L["The Carevin Family"] = "卡尔文家族"
L["Ask Darkshire's records and the Carevin family what they know about worgen in Duskwood."] = "查阅夜色镇的记录，并向卡尔文家族打听他们对暮色森林狼人的了解。"
L["Darkshire had no clean record of Velinde, but it had worgen. Clerk Daltry pointed to Jonathan Carevin, whose family made a business of hunting the forest's monsters. Carevin's suspicion gave way to a practical bargain: if the trail led into Roland's Doom, then any answer found there should be shared with Darkshire."] = "夜色镇没有关于维琳德的确切记录，但这里有狼人。书记员达尔塔指点你去找乔纳森·卡尔文，他的家族以猎杀森林里的怪物为业。卡尔文的疑心最终让位于一桩务实的交易：如果线索通往罗兰之墓，那么在那里找到的任何答案都应与夜色镇分享。"
L["Jonathan Carevin"] = "乔纳森·卡尔文"
L["Answered Questions"] = "回复珊蒂斯"
L["Return to Darnassus with what the Duskwood cave revealed about Velinde and the scythe."] = "带着暮色森林洞穴中关于维琳德和镰刀的发现，返回达纳苏斯。"
L["Roland's Doom gave no triumphant recovery, only signs of what the scythe had unleashed and where Velinde's trail had broken. Thyn'tel accepted the report with gratitude and unease. The worgen could be contained for now, but the Scythe of Elune remained out of night elf hands, waiting for another chapter."] = "罗兰之墓中并没有凯旋般的寻回，只有镰刀所释放之物的痕迹，以及维琳德的踪迹中断之处。塞恩提尔怀着感激与不安接受了这份报告。狼人暂时可以得到控制，但艾露恩之镰仍不在暗夜精灵手中，等待着下一个篇章。"
L["Travel to Darkshore and speak with Zidormi outside Lor'danel to view the time before the burning of Teldrassil."] = "前往黑海岸，与洛达内尔外的希多尔米交谈，即可查看泰达希尔焚毁之前的时间线。"
L["Play or replay this scenario from Archivist Sylvia in Orgrimmar's Valley of Wisdom. If you still have the original quest, begin with High Overlord Saurfang in Grommash Hold."] = "在奥格瑞玛智慧谷的档案员希尔薇亚处体验或重温此场景战役。如果你仍持有原始任务，请从格罗玛什要塞的萨鲁法尔大王处开始。"
L["Complete Stay of Execution, then follow the path you chose: loyalists continue with Nathanos Blightcaller in Grommash Hold, while rebels continue with Lor'themar Theron at the Dranosh'ar Blockade outside Orgrimmar."] = "完成“刀下留人”，然后沿着你所选择的道路继续：效忠者前往格罗玛什要塞找纳萨诺斯·凋零者，反抗者则前往奥格瑞玛城外的德拉诺什尔封锁线找洛瑟玛·塞隆。"
L["Speak with Highlord Bolvar Fordragon in the Ring of Fates, Oribos, and follow the Torghast campaign until the Anduin and Kingsmourne vision. If Bolvar no longer offers the chain, the game has already moved this character past it."] = "在命运之环（奥利波斯）与大领主伯瓦尔·弗塔根交谈，然后跟随托加斯特战役，直到出现安度因与王者之哀的幻象。如果伯瓦尔不再提供这一系列任务，说明游戏已经让这个角色跳过了这部分内容。"
L["Secrets of Uldaman"] = "奥达曼的秘密"
L["The Badlands dig site is more than a ruin full of troggs and Dark Iron dwarves. Uldaman holds titan records, old dwarven fears, and relics that both factions are willing to chase through the dust.\n\nFollow Hammertoe's warning, the Shattered Necklace, and the Platinum Discs to uncover what the Titans left beneath the stone."] = "荒芜之地的挖掘场可不只是一片满是穴居人和黑铁矮人的废墟。奥达曼保存着泰坦的记录、矮人古老的恐惧，以及两大阵营都甘愿冒着风沙去追寻的遗物。\n\n循着铁趾的警告、破碎的项链和白金圆盘，揭开泰坦埋藏在岩石之下的秘密。"
L["Badlands / Ironforge / Orgrimmar / Thunder Bluff / Uldaman"] = "荒芜之地 / 铁炉堡 / 奥格瑞玛 / 雷霆崖 / 奥达曼"
L["A Sign of Hope"] = "一线希望"
L["Crumpled Map"] = "弄皱的地图"
L["Hammertoe's Digsite, Badlands"] = "铁趾挖掘场（荒芜之地）"
L["the outer Uldaman caves, Badlands"] = "奥达曼外围洞穴，荒芜之地"
L["Angor Fortress, Badlands"] = "苦痛堡垒（荒芜之地）"
L["Galgann Firehammer's chamber, Uldaman"] = "加加恩·火锤的房间，奥达曼"
L["the Mystic Ward, Ironforge"] = "秘法区（铁炉堡）"
L["Droffers and Son Salvage, Orgrimmar"] = "德罗弗父子回收站，奥格瑞玛"
L["near Revelosh's chamber, Uldaman"] = "鲁维罗什的房间附近，奥达曼"
L["the treasure chamber beyond Archaedas, Uldaman"] = "阿扎达斯后方的宝藏室，奥达曼"
L["the Vault, Ironforge"] = "宝库，铁炉堡"
L["Hammertoe's Warning"] = "铁趾的警告"
L["Find Hammertoe Grez, stop the Shadowforge search, and recover the titan-inscribed Tablet of Will."] = "找到铁趾格雷兹，阻止暗炉氏族的搜寻，并取回刻有泰坦文字的意志石板。"
L["A crumpled map turned a dig-site rumor into a rescue. Hammertoe Grez had been taken into Uldaman because he knew too much about titan relics and Dark Iron plans. His amulet reached Ironforge, Belgrum sent you against Ambassador Infernus, and the Tablet of Will was recovered before the Shadowforge could turn titan knowledge into stronger golems."] = "一张揉皱的地图让挖掘场的传闻变成了一场营救。铁趾格雷兹被掳进了奥达曼，因为他对泰坦遗物和黑铁矮人的计划知道得太多了。他的护符被送到了铁炉堡，贝尔格鲁姆派你去对付因弗努斯大使，而在暗炉氏族将泰坦知识化为更强大的魔像之前，意志石板终于被夺了回来。"
L["Prospector Ryedol"] = "勘察员雷杜尔"
L["Amulet of Secrets"] = "铁趾的护符"
L["Hammertoe Grez"] = "铁趾格雷兹"
L["Prospect of Faith"] = "铁趾的遗愿"
L["Passing Word of a Threat"] = "亡者的警告"
L["Historian Karnik"] = "史学家卡尼克"
L["An Ambassador of Evil"] = "邪恶的使者"
L["The Lost Tablets of Will"] = "意志石板"
L["The Shattered Necklace"] = "破碎的项链"
L["Trace the broken necklace through Uldaman's gems, journals, and power source."] = "循着奥达曼的宝石、日志和能量源，追查那条断裂项链的下落。"
L["The shattered necklace made Uldaman personal in two different ways. Alliance characters traced Talvash's old work and restored the piece through gems and Archaedas' power source. Horde characters followed Droffers and Son Salvage into a bargain with Jarkal Mossmeld. Either way, the dungeon became a puzzle of ruby, sapphire, topaz, and a construct's heart."] = "破碎的项链以两种不同的方式，让奥达曼与你产生了切身的联系。联盟角色追寻塔瓦斯德的旧作，借助宝石和阿扎达斯的能量源修复了这件饰物。部落角色则跟随德罗弗父子回收站的线索，与加卡尔做了一笔交易。无论哪一方，这座地下城都成了一道由红宝石、蓝宝石、黄玉和一颗构造体之心组成的谜题。"
L["Shattered Necklace"] = "破碎的项链"
L["Lore for a Price"] = "昂贵的知识"
L["Talvash del Kissel"] = "塔瓦斯德·基瑟尔"
L["Back to Uldaman"] = "回到奥达曼"
L["Find the Gems"] = "寻找宝石"
L["Restoring the Necklace"] = "修复项链"
L["Necklace Recovery"] = "搜寻项链"
L["Dran Droffers"] = "德兰·杜佛斯"
L["Necklace Recovery, Take 2"] = "搜寻项链，再来一次"
L["Translating the Journal"] = "翻译日记"
L["Remains of a Paladin"] = "圣骑士的遗体"
L["Jarkal Mossmeld"] = "加卡尔"
L["Find the Gems and Power Source"] = "寻找宝贝"
L["Deliver the Gems"] = "交付宝石"
L["Necklace Recovery, Take 3"] = "项链任务的终结"
L["The Platinum Discs"] = "白金圆盘"
L["Defeat Archaedas, consult the stone watcher, and carry the miniature discs to your faction's scholar."] = "击败阿扎达斯，向石头看守者请教，然后将微型圆盘交给你所属阵营的学者。"
L["Behind Archaedas, the Discs of Norgannon spoke with the calm weight of titan memory. They named the Creators, the Earthen, and the deep history beneath dwarven stone. The portable discs went from Uldaman to Ironforge or Thunder Bluff, where scholars understood that the find was not only treasure. It was origin."] = "在阿扎达斯身后，诺甘农圆盘以泰坦记忆特有的沉静与厚重娓娓道来。它们提到了造物者、土灵，以及矮人岩石之下深藏的历史。便携的圆盘从奥达曼被带往铁炉堡或雷霆崖，学者们在那里意识到，这一发现不只是财宝，更是起源。"
L["Discs of Norgannon"] = "诺甘农圆盘"
L["High Explorer Magellas"] = "资深探险家麦格拉斯"
L["Mourning Rise"] = "哀念高地"
L["The Stonevault"] = "矶石宝库"
L["Korgran has cared for Mourning Rise longer than his failing memory can reliably hold. The memorial grounds still need tending, kobolds have begun looting the dead, and Urtago is trying to help him hand over a duty he is not ready to lose.\n\nFollow Korgran through the last traditions of his post: honoring the fallen, forging a lantern, and choosing how an earthen says farewell."] = "科格兰照管哀念高地的岁月，已经长到他日渐衰退的记忆难以承载。纪念场地仍需打理，狗头人开始劫掠死者，而乌尔塔格正试着帮他交出这份他尚未准备好放下的职责。\n\n跟随科格兰完成他职守中的最后几项传统：缅怀逝者，锻造一盏提灯，并选择一名土灵告别的方式。"
L["Isle of Dorn"] = "多恩岛"
L["Before I Depart"] = "未遂之愿"
L["Korgran"] = "科格兰"
L["Mourning Rise, Isle of Dorn"] = "哀念高地（多恩岛）"
L["Optional breadcrumb: To Mourning Rise may point you here first. The story itself begins with Korgran at Mourning Rise."] = "可选引导任务：“前往哀念高地”可能会先将你引到这里。故事本身从哀念高地的科格兰开始。"
L["Korgran knows his mind is fading, but the Rise still needs a caretaker. Help him and Urtago drive out the kobolds, honor the fallen, and prepare the lantern that will carry his final choice."] = "科格兰知道自己的神智正在衰退，但高地仍需要一位看守人。帮助他和乌尔塔格赶走狗头人，缅怀逝者，并准备好那盏将承载他最终抉择的提灯。"
L["Korgran still called himself caretaker of Mourning Rise, even as Urtago quietly did more and more of the work. Together you cleared kobolds from the memorial, recovered what they had stolen, and saw how often Korgran lost the thread of the present. The duties that defined him were slipping away.\n\nWhen the time came, Korgran chose one more tradition. He forged a lantern, searched for a lost earthen, cleaned ashes from the memorial, and walked toward the coast with Urtago beside him. His farewell was not treated as defeat. It was a final act of care, made in the place he had guarded for so long."] = "科格兰仍自称哀念高地的看守人，尽管乌尔塔格已在默默分担越来越多的工作。你们一起将狗头人赶出了纪念地，找回了被它们偷走的东西，也看到了科格兰有多么频繁地与当下失去联系。那些定义了他的职责正在悄然溜走。\n\n时候到了，科格兰选择再践行一项传统。他锻造了一盏提灯，寻找一位失落的土灵，清扫纪念地上的灰烬，然后在乌尔塔格的陪伴下走向海岸。他的告别并未被视为失败，而是在他守护了如此之久的地方，献上的最后一份关怀。"
L["Honor Their Memories"] = "献礼纪念"
L["Urtago"] = "乌尔塔格"
L["You No Take Plunder!"] = "你不能拿走我的宝贝！"
L["Laws Apply to All"] = "法必责众"
L["The Great Collapse"] = "大崩塌"
L["Cutting the Wick"] = "剪除烛芯"
L["Who Runs This Fine Establishment?"] = "谁是当家的？"
L["One More Tradition"] = "另一个传统"
L["The Forging of Memories"] = "铸造回忆"
L["The Last Journey"] = "最后一程"
L["The Lost Earthen"] = "走失的土灵"
L["A Change of Tradition"] = "传统的转变"
L["Tools of Declaration"] = "宣言的工具"
L["Cleansing Ashes"] = "净秽灰烬"
L["As He Departs"] = "他的辞别"
L["The Weight of Duty"] = "责任的重量"
L["Stay a While"] = "英雄留步"
L["Ruby Life Pools"] = "红玉新生法池"
L["At the Ruby Lifeshrine, Veritistrasz asks for something rare in an adventurer's life: time. No army waits, no world-ending machine is counting down, and no one needs a hundred trophies from the local wildlife.\n\nSit with an old red dragon in dwarf form, listen to what he remembers, and help him face the name he has spent ages trying not to say."] = "在红玉新生圣地，维里提斯塔萨向你提出了一个在冒险者生涯中难得的请求：时间。没有军队在等待，没有毁天灭地的机器在倒计时，也没有人需要你从当地野生动物身上收集一百件战利品。\n\n陪这位化身为矮人的红色巨龙坐一坐，听听他的回忆，帮助他直面那个他花了漫长岁月都不愿说出口的名字。"
L["The Waking Shores"] = "觉醒海岸"
L["Veritistrasz"] = "维里提斯塔萨"
L["Ruby Lifeshrine, The Waking Shores"] = "红玉新生圣地（觉醒海岸）"
L["Obsidian Citadel, The Waking Shores"] = "黑曜堡垒（觉醒海岸）"
L["Veritistrasz only asks you to sit, listen, and look out over the Waking Shores. What begins as memory becomes grief, and a hidden diary gives him one last truth to carry."] = "维里提斯塔萨只请你坐下来，听他说话，一同眺望觉醒海岸。回忆渐渐化为悲伤，而一本隐藏的日记给了他最后一个需要背负的真相。"
L["Veritistrasz sat at the Ruby Lifeshrine and asked you to stay. His stories moved gently at first: old homes, old meals, the strange way places change when you are gone too long. Then the memories turned toward the black dragonflight, toward the friend he loved, and toward the betrayal that broke both his family and his certainty.\n\nLater, a damaged diary from the Obsidian Citadel brought the name he could not reach: Distyia. It did not undo what happened, but it gave his grief shape. Veritistrasz remembered the person beneath the corruption, and for a moment the old wound was not quite so alone."] = "维里提斯塔萨坐在红玉新生圣地，请你留下来。起初，他的故事娓娓道来：旧日的家园、旧日的饭菜，还有离开太久之后，那些地方发生的奇妙变化。随后，回忆转向了黑龙军团，转向了他深爱的朋友，也转向了那场既击碎了他的家庭、也击碎了他信念的背叛。\n\n后来，一本来自黑曜堡垒的残破日记带来了那个他始终无法触及的名字：迪斯缇娅。它无法改变已经发生的事，却让他的悲伤有了形状。维里提斯塔萨记起了腐化之下的那个人，在那一刻，那道旧伤不再那么孤单。"
L["Memories"] = "回忆"
L["Memories Revived"] = "复活的记忆"
L["Partially Destroyed Diary"] = "部分损毁的日记"
L["Runas the Shamed"] = "可耻的鲁纳斯"
L["Azurewing Repose is under pressure from withered nightborne, hungry leyline abuse, and a prince who sees dragons as a resource to drain. In the middle of it all is Runas, a withered exile who still has just enough wit, shame, and courage left to choose who he wants to be.\n\nBegin with Stellagosa's search for the missing whelpling and follow Runas through one last useful, heartbreaking day."] = "蓝翼栖地正承受着重重压力：沦为枯法者的夜之子、对魔网贪婪的滥用，还有一位把巨龙视为可供吸取之资源的王子。在这一切的中心，是鲁纳斯——一名遭到放逐的枯法者，他仍保留着恰好足够的机智、羞耻与勇气，去选择自己想成为什么样的人。\n\n从丝黛拉苟萨寻找失踪幼龙的任务开始，陪伴鲁纳斯度过他最后一个有意义、也令人心碎的日子。"
L["Azsuna"] = "阿苏纳"
L["Eye of Azshara"] = "艾萨拉之眼"
L["Azurewing Repose, Azsuna"] = "蓝翼栖地（阿苏纳）"
L["Stellagosa sends you after a missing whelpling and you meet Runas, a withered exile who knows the Repose's enemies better than anyone wants to admit."] = "丝黛拉苟萨派你去寻找一只失踪的幼龙，你由此遇见了鲁纳斯——一名遭到放逐的枯法者，他对栖地之敌的了解，超出了所有人愿意承认的程度。"
L["Stellagosa's missing whelpling led you to Runas the Shamed, a withered nightborne with a sharp tongue and a hunger he could barely hold back. He had been cast out, diminished, and written off, but he still understood the leylines, the withered, and the danger gathering around Azurewing Repose.\n\nRunas helped you recover the whelpling and find Stellagosa, even as his own cravings returned. He was not safe. He knew it. Still, he kept choosing to help."] = "丝黛拉苟萨失踪的幼龙将你引向了可耻的鲁纳斯，一名牙尖嘴利、几乎压抑不住饥渴的枯法者。他被放逐、被削弱、被所有人放弃，但他依然了解魔网、了解枯法者，也了解正在蓝翼栖地周围聚集的危险。\n\n鲁纳斯帮助你找回了幼龙，并找到了丝黛拉苟萨，尽管他自己的渴望又卷土重来。他并不安全，他自己也清楚。但他依然一次次选择伸出援手。"
L["The Consumed"] = "精疲力尽"
L["Mana-Drained Whelpling"] = "法力枯竭的幼龙"
L["Projection of Senegos"] = "塞纳苟斯的投影"
L["Runas Knows the Way"] = "鲁纳斯认识路"
L["The Hunger Returns"] = "饥渴难耐"
L["Leyline Abuse"] = "滥用魔网"
L["The Nightborne Prince"] = "夜之子王子"
L["Runas guides you into the prince's territory, bargains with his own hunger, and helps expose what the nightborne are doing to the dragons."] = "鲁纳斯带你潜入王子的领地，与自己的饥渴讨价还价，并帮助揭露夜之子对巨龙的所作所为。"
L["Runas knew the prince's camp from the inside: the habits, the arrogance, and the weak points. With his guidance, you sabotaged the nightborne, stole what you needed, and found Stellagosa alive but endangered. Runas kept laughing, kept deflecting, and kept moving because stopping would mean feeling the pull of the hunger too clearly.\n\nBy the time you returned to Azurewing Repose, Runas had given the dragons what they needed most: a path to strike back before the prince could feast on them."] = "鲁纳斯对王子的营地了如指掌：那里的习惯、傲慢和弱点。在他的指引下，你破坏了夜之子的行动，偷到了所需之物，并找到了还活着却身处险境的丝黛拉苟萨。鲁纳斯一直在笑，一直在岔开话题，一直在前进，因为一旦停下来，他就会太清楚地感受到饥渴的拉扯。\n\n等你回到蓝翼栖地时，鲁纳斯已经给了巨龙们最需要的东西：一条在王子享用它们之前发起反击的道路。"
L["You Scratch My Back..."] = "互帮互助"
L["Still Alive"] = "生命延续"
L["Hunger's End"] = "饥渴结束"
L["Khadgar and Stellagosa rally the defense. Runas spends his last strength making sure his final hours matter."] = "卡德加和丝黛拉苟萨组织起防御。鲁纳斯用尽最后的力气，让自己生命的最后时刻变得有意义。"
L["The nightborne assault reached Azurewing Repose. Khadgar, Stellagosa, and the blue dragons fought to protect Senegos while the withered closed in. Runas was almost out of time. He knew what was coming, and he chose to spend his last clear moments helping instead of hiding.\n\nAt the end, he thanked you for letting his final hours mean something. Then the hunger took him. The victory at Azurewing Repose came with a quiet loss, and Runas the Shamed earned a better name than the one he had carried."] = "夜之子的攻势抵达了蓝翼栖地。卡德加、丝黛拉苟萨和蓝龙们奋力保护塞纳苟斯，而枯法者则步步逼近。鲁纳斯的时间所剩无几。他知道接下来会发生什么，于是选择把最后清醒的时刻用来帮忙，而不是躲藏。\n\n最后，他感谢你让他生命的最后时刻有了意义。随后，饥渴吞噬了他。蓝翼栖地的胜利伴随着一份无声的失去，而可耻的鲁纳斯，也赢得了一个比他背负的称号更好的名字。"
L["Feasting on the Dragon"] = "享用巨龙魔力"
L["On the Brink"] = "灭族危机"
L["Cursed to Wither"] = "该死的枯法者"
L["Rhea's Last Egg"] = "瑞亚的最后一枚龙蛋"
L["Blackrock Caverns"] = "黑石岩窟"
L["In the Badlands, a red dragon hides behind a simple name and a very dangerous plan. Rhea wants to save the future of the black dragonflight from Deathwing's madness, and she needs samples, secrecy, and one gnome scientist who is just strange enough to help.\n\nFollow Rhea's work from Lethlor Ravine to the Hidden Clutch, then stay for the Badlands locals arguing over what really happened when Deathwing came."] = "在荒芜之地，一头红龙藏身于一个简单的名字和一项极其危险的计划背后。瑞亚想要从死亡之翼的疯狂中拯救黑龙军团的未来，为此她需要样本、需要保密，还需要一位古怪到恰好愿意帮忙的侏儒科学家。\n\n跟随瑞亚的工作，从莱瑟罗峡谷一路前往隐秘龙巢，然后留下来，听听荒芜之地的居民们争论死亡之翼到来时究竟发生了什么。"
L["Badlands"] = "荒芜之地"
L["Cataclysm"] = "大地的裂变"
L["First Sample: Wild Eggs"] = "第一份样本：狂野黑龙卵"
L["Rhea"] = "瑞亚"
L["Lethlor Ravine, Badlands"] = "莱瑟罗峡谷（荒芜之地）"
L["Easily Swayed"] = "撼动军心"
L["Dolph Blastus"] = "道尔夫·柏拉木"
L["A Strange Request"] = "奇怪的请求"
L["Fuselight, Badlands"] = "熔光镇（荒芜之地）"
L["Agmond's End, Badlands"] = "阿戈莫德的营地（荒芜之地）"
L["Dustwind Dig, Badlands"] = "尘风挖掘场（荒芜之地）"
L["Bloodwatcher Point, Badlands"] = "血望者营地（荒芜之地）"
L["Scar of the Worldbreaker, Badlands"] = "灭世者之痕（荒芜之地）"
L["The Maker's Terrace, Badlands"] = "造物者遗迹（荒芜之地）"
L["New Kargath, Badlands"] = "新卡加斯（荒芜之地）"
L["Rhea's Work"] = "瑞亚的工作"
L["If Rhea does not offer these quests yet, complete the Fuselight intro through A Strange Request first."] = "如果瑞亚尚未提供这些任务，请先完成熔光镇的开场任务，直到“奇怪的请求”。"
L["Rhea asks for black dragon samples and slowly reveals why she is risking everything in the Badlands."] = "瑞亚请你收集黑龙样本，并渐渐揭示她为何要在荒芜之地孤注一掷。"
L["Rhea's errands looked like field work at first: wild eggs, whelps, implanted eggs, and a strange fog that hid more than geography. Then she revealed the truth. She was Rheastrasza, a red dragon trying to rescue the future of the black dragonflight before Deathwing's corruption consumed it forever.\n\nThe samples were not trophies. They were the last chance to create an uncorrupted black dragon egg."] = "起初，瑞亚交代的差事看起来像是野外考察：野生的龙蛋、雏龙、被植入的龙蛋，还有一团遮蔽的远不止地形的奇怪迷雾。随后，她揭示了真相。她是瑞亚斯塔萨，一头红龙，试图在死亡之翼的腐化永远吞噬黑龙军团之前，拯救它的未来。\n\n这些样本并不是战利品，而是创造一枚未被腐化的黑龙蛋的最后机会。"
L["Second Sample: Whelps"] = "第二份样本：雏龙"
L["Lifting the Veil"] = "掀起面纱"
L["Third Sample: Implanted Eggs"] = "第三份样本：尼希昂卓拉的龙卵"
L["Rhea Revealed"] = "瑞亚的身份"
L["The Venerable Doctor Blam"] = "尊敬的布拉姆博士"
L["The Hidden Clutch"] = "隐藏的龙巢"
L["Dr. Blam takes over the science. Alliance and Horde routes split through rival dig sites before converging on the clutch Rhea is trying to protect."] = "布拉姆博士接手了科研工作。联盟与部落的路线分别经过彼此竞争的挖掘场，最后汇聚到瑞亚试图保护的龙巢。"
L["Dr. Hieronymus Blam was exactly the kind of scientist Rhea needed: brilliant, excitable, and only partly reassuring. His work sent you through trogg trouble, dusty titan ruins, and faction rivalries at Dustwind Dig or Bloodwatcher Point. Stone watchers, ancient games, and old machinery all became part of the same desperate experiment.\n\nEverything pointed back to one thing: a hidden clutch that Deathwing could not be allowed to find."] = "耶柔米·布拉姆博士正是瑞亚需要的那种科学家：才华横溢、容易激动，只能让人放心一半。他的工作让你应付了穴居人的麻烦、穿过了尘土飞扬的泰坦遗迹，还在尘风挖掘场或血望者营地卷入了阵营之争。石头看守者、古老的游戏和陈旧的机械，全都成了同一场孤注一掷的实验的一部分。\n\n一切都指向同一件事：一处绝不能让死亡之翼发现的隐秘龙巢。"
L["Troggish Troubles"] = "穴居人的麻烦"
L["Dr. Hieronymus Blam"] = "耶柔米·布拉姆博士"
L["Dustwind Dig"] = "尘风挖掘场"
L["Bloodwatcher Point"] = "血望者营地"
L["All's Fair in Love, War, and Archaeology"] = "爱情、战争和考古学都是不择手段的"
L["Lead Prospector Durdin"] = "首席勘探员杜尔林"
L["It's Not About History, It's About Power"] = "无关历史，能量而已"
L["High Examiner Tae'thelan Bloodwatcher"] = "高阶考察者泰瑟兰·血望者"
L["The Warden's Pawn"] = "戒卫的棋卒"
L["The Sentinel's Pawn"] = "哨兵的棋卒"
L["The Warden's Game"] = "戒卫的游戏"
L["Stone Slab"] = "石板"
L["The Sentinel's Game"] = "哨兵的游戏"
L["Marble Slab"] = "大理石板"
L["Ancient Protectors"] = "远古的保卫者"
L["The Titans' Trove"] = "泰坦的宝藏"
L["Return to Blam"] = "返回布拉姆身边"
L["Trove of the Watchers"] = "看守者的宝藏"
L["Into the Dragon's Mouth"] = "前往巨龙峡口"
L["New Kargath"] = "新卡加斯"
L["Rheastrasza's Gift"] = "瑞亚丝塔萨的礼物"
L["Rhea gathers unlikely guards for the clutch, but Deathwing's shadow falls over the plan before the egg can be safe."] = "瑞亚为龙巢召集了一群意想不到的守卫，但在龙蛋得到安全之前，死亡之翼的阴影便已笼罩了整个计划。"
L["Rhea's defense force was improvised in true Badlands fashion. Alliance adventurers recruited Eric, Baelog, and Olaf. Horde adventurers recruited Amakkar, Jurrix, and Gargal. The work was strange, dangerous, and somehow hopeful.\n\nThen Deathwing came. The clutch was exposed, Rhea's plan became a sacrifice, and the last egg had to survive without the dragon who had made it possible."] = "瑞亚的防御力量完全是以荒芜之地的风格临时拼凑而成的。联盟冒险者招募了埃里克、巴尔洛戈和奥拉夫，部落冒险者则招募了阿玛卡尔、朱里克斯和加戈尔。这份工作古怪又危险，却不知怎的让人心怀希望。\n\n随后，死亡之翼来了。龙巢暴露，瑞亚的计划化为一场牺牲，而最后一枚龙蛋必须在失去那头成就了它的巨龙之后独自存活下去。"
L["The Swift, the Fierce, and the Stout"] = "三位矮人"
L["Eric, the Utility Dwarf"] = "全能的埃瑞克"
L["Eric \"The Swift\""] = "迅捷的埃瑞克"
L["Baelog, the Glass Cannon"] = "玻璃弓箭手巴尔洛戈"
L["Baelog"] = "巴尔洛戈"
L["Olaf, the Big Fella'"] = "大胖子奥拉夫"
L["Olaf"] = "奥拉夫"
L["The Wrath of a Dragonflight"] = "龙群之怒"
L["Their Hunt Continues"] = "永无止尽的搜寻"
L["The Sorrow and the Fury"] = "悲痛与愤怒"
L["The Bad Dogs"] = "恶狗团"
L["Amakkar, Jack of All Trades"] = "全能的阿玛卡尔"
L["Amakkar"] = "阿玛卡尔"
L["Jurrix the Striker"] = "主攻手朱里克斯"
L["Jurrix Whitemane"] = "朱里克斯·白鬃"
L["Gargal, the Behemoth"] = "大块头加戈尔"
L["Gargal"] = "加戈尔"
L["The Egg Lives On"] = "龙蛋仍在成长"
L["Dr. Blam reveals Rhea's final deception and the secret she preserved: one uncorrupted black dragon egg."] = "布拉姆博士揭露了瑞亚最后的骗局，以及她守护下来的秘密：一枚未被腐化的黑龙蛋。"
L["Deathwing believed he had destroyed Rhea's work. Dr. Blam revealed the truth: Rhea had hidden the real egg and left a false trail behind. Her last act was not only sacrifice, but misdirection.\n\nThe egg lived. Somewhere beyond Deathwing's reach, the future black dragon Wrathion had a chance to exist."] = "死亡之翼以为自己已经摧毁了瑞亚的心血。布拉姆博士揭示了真相：瑞亚藏起了真正的龙蛋，留下了一条虚假的线索。她最后的举动不只是牺牲，更是声东击西。\n\n龙蛋活了下来。在死亡之翼无法触及的某个地方，未来的黑龙拉希奥有了诞生的机会。"
L["Devastation"] = "毁灭"
L["The Day that Deathwing Came"] = "死亡之翼降临之日"
L["Theldurin, Lucien, and Martek each explain how they personally survived Deathwing. The stories get less reliable and much funnier as they go."] = "塞尔杜林、卢希恩和马特克各自讲述了自己如何从死亡之翼手下幸存。故事越讲越不靠谱，也越讲越好笑。"
L["After the tragedy of Rhea's story, the Badlands gave you its strangest form of grief relief: three locals trying to outdo each other with increasingly impossible versions of the day Deathwing came. Theldurin punched the Destroyer. Lucien improved the story. Martek improved it even more.\n\nNone of it was reliable history. All of it was Badlands truth: when the world breaks, sometimes people survive by turning terror into a story they can laugh at."] = "在瑞亚的悲剧之后，荒芜之地用最古怪的方式帮你排解悲伤：三个当地人争先恐后，用一个比一个离谱的版本讲述死亡之翼到来的那一天。塞尔杜林一拳打中了毁灭者。卢希恩把故事又润色了一番。马特克则润色得更加夸张。\n\n这些全都不是可靠的历史，却全都是荒芜之地的真相：当世界破碎时，人们有时正是靠着把恐惧变成能够一笑置之的故事，才得以活下去。"
L["Theldurin the Lost"] = "迷失者塞尔杜林"
L["The Day that Deathwing Came: The Real Story"] = "死亡之翼降临之日：真实的故事"
L["Lucien Tosselwrench"] = "卢希恩·枪穗"
L["The Day that Deathwing Came: What Really Happened"] = "死亡之翼降临之日：真正发生的事"
L["Martek the Exiled"] = "流放者马特克"
L["A Blue Dawn"] = "碧蓝黎明"
L["The Azure Vault"] = "碧蓝魔馆"
L["The blue dragonflight survived Malygos, the Nexus War, and years of grief by scattering across Azeroth. Kalecgos can lead an Aspect's flight again, but only if the blues choose to become a family instead of a memory.\n\nAnswer Kalecgos's call, search for the lost blue dragons, and help each branch decide whether there is still a home worth returning to."] = "蓝龙军团挺过了玛里苟斯、魔枢战争和多年的悲痛，代价是四散于艾泽拉斯各地。卡雷苟斯可以再次以守护巨龙的身份领导龙群，但前提是蓝龙们选择成为一个家庭，而不只是一段回忆。\n\n回应卡雷苟斯的召唤，寻找失散的蓝龙，帮助每一支龙族分支决定，是否还有一个值得回归的家。"
L["The Azure Span / Thaldraszus / Azeroth"] = "碧蓝林海 / 索德拉苏斯 / 艾泽拉斯"
L["Keeper of the Ossuary"] = "藏骨堂守护者"
L["The Azure Archives, The Azure Span"] = "碧蓝档案馆，碧蓝林海"
L["Algeth'ar Academy, Thaldraszus"] = "艾杰斯亚学院（索德拉苏斯）"
L["Borean Tundra"] = "北风苔原"
L["Crystalsong Forest"] = "晶歌森林"
L["Booty Bay, The Cape of Stranglethorn"] = "藏宝海湾（荆棘谷海角）"
L["Kalecgos begins at the Veiled Ossuary, where memories of Sindragosa, Malygos, Azuregos, and Senegos show how much the blue dragonflight has lost."] = "卡雷苟斯从雾纱藏骨堂开始，在那里，关于辛达苟萨、玛里苟斯、艾索雷苟斯和塞纳苟斯的记忆揭示了蓝龙军团失去了多少。"
L["Kalecgos called you to the Veiled Ossuary to help tend the memories of the blue dragonflight. With Senegos and Azuregos drawn into the work, the archives became more than a vault. They became a place to face what the blues had survived: Malygos, Sindragosa, exile, war, and the long habit of grieving separately.\n\nBy the time the first memories returned, Kalecgos understood the real task. The flight could not be restored by duty alone. The missing blues had to be found, heard, and invited home."] = "卡雷苟斯召你前往雾纱藏骨堂，帮忙照看蓝龙军团的记忆。随着塞纳苟斯和艾索雷苟斯也加入其中，这座档案馆不再只是一座宝库，而成了直面蓝龙们所经历之事的地方：玛里苟斯、辛达苟萨、流亡、战争，以及长久以来各自悲伤的习惯。\n\n当最初的记忆回归时，卡雷苟斯明白了真正的任务。仅凭责任无法让龙群重获新生。必须找到那些失散的蓝龙，倾听他们的声音，并邀请他们回家。"
L["On the Trail Again"] = "追寻踪迹"
L["Senegos"] = "塞纳苟斯"
L["Rolling Out"] = "出发"
L["Lest We Forget"] = "永志不忘"
L["Archives Return"] = "返回碧蓝档案馆"
L["Azuregos's Support"] = "艾索雷苟斯的支援"
L["Unusual Disruptions"] = "奇怪的扰动"
L["Archival Arrival"] = "抵达档案馆"
L["Where in the World is a Lost Blue Dragon?"] = "失踪的蓝龙在哪里？"
L["Sindragosa and Malygos's Rest"] = "辛达苟萨和玛里苟斯的安息"
L["Memories of Sindragosa and Malygos"] = "辛达苟萨和玛里苟斯的回忆"
L["The Search for Blue Dragons"] = "寻找蓝龙。"
L["Kalecgos begins the search in earnest, naming the scattered blues and sending you across Azeroth to bring their stories back together."] = "卡雷苟斯正式展开搜寻，列出了那些散落各地的蓝龙的名字，并派你走遍艾泽拉斯，将他们的故事重新汇聚在一起。"
L["The archives gave Kalecgos names, but names were not enough. The missing blues had built separate lives, separate loyalties, and separate ways of surviving. Some were hiding from pain. Some were trapped in old debts. Some had made peace with never returning.\n\nKalecgos chose to ask rather than command. The blue dragonflight's renewal would be a gathering, not a summons."] = "档案馆给了卡雷苟斯一些名字，但光有名字还不够。失散的蓝龙们各自建立了自己的生活、自己的忠诚和自己的生存之道。有的在逃避痛苦，有的被旧债所困，有的早已坦然接受了永不回归。\n\n卡雷苟斯选择了请求，而非命令。蓝龙军团的复兴将是一场相聚，而不是一道召令。"
L["Lost Blue Dragons"] = "失踪的蓝龙"
L["A Pair of Blue Dragons"] = "一对蓝龙"
L["The Last Missing Blue Dragon"] = "最后一只失踪的蓝龙"
L["Those We Left Behind"] = "涂炭之地"
L["Lanigosa and Surigosa carry the cost of the Nexus War. Help them face a legacy that was never only history."] = "兰妮苟萨和苏睿苟萨背负着魔枢战争的代价。帮助她们直面这份从来不只是历史的遗产。"
L["Lanigosa's branch of the search led to Crystalsong Forest and Dustwallow Marsh, where grief had hardened around the Nexus War. The losses were personal, not abstract: shattered legacy, arcane echoes, old banners, and survivors who had learned to keep moving because stopping hurt too much.\n\nWith Surigosa and Kalecgos, you helped turn remembrance into release. The past was not erased, but it no longer had to be a prison."] = "兰妮苟萨这条搜寻线索通往晶歌森林和尘泥沼泽，在那里，悲伤早已围绕着魔枢战争凝固成形。这些失去是切身的，而非抽象的：破碎的传承、奥术的回响、陈旧的旗帜，还有那些学会了不停前行的幸存者，因为一旦停下，痛苦便太过沉重。\n\n在苏睿苟萨和卡雷苟斯的陪伴下，你帮助他们将缅怀化为释怀。过去并未被抹去，但它不必再是一座牢笼。"
L["Lanigosa"] = "兰妮苟萨"
L["A Shattered Legacy"] = "碎裂的遗产"
L["An Arcane Requiem"] = "奥术镇魂曲"
L["Creative Solutions"] = "创造性方案"
L["Aftershocks"] = "劫后余生"
L["Surigosa"] = "苏睿苟萨"
L["The Sound of Silence"] = "寂静之声"
L["Regrets in Crystal"] = "水晶中的悔恨"
L["The Sullied Banner"] = "污旗党"
L["A Moment of Reflection"] = "反思时刻"
L["No Such Thing as Bad Luck"] = "时来运转"
L["Zeros has a debt problem in Booty Bay, which means the blue dragonflight's reunion briefly becomes paperwork, bribery, and goblin accounting."] = "泽洛斯在藏宝海湾惹上了债务麻烦，于是蓝龙军团的重聚一度变成了文书、贿赂和地精式的算账。"
L["Zeros did not need a grand speech. He needed out of debt. Booty Bay wrapped the search in ledgers, bribes, crystals, and the kind of bargaining that makes dragons wonder why mortals invented money.\n\nSenegos treated the mess with surprising patience, and Zeros eventually found a path back that did not involve running forever. Even the ridiculous errands served the larger truth: every scattered blue had a different reason to stay away."] = "泽洛斯需要的不是慷慨激昂的演说，而是摆脱债务。藏宝海湾让这场搜寻陷入了账簿、贿赂、水晶，以及那种会让巨龙纳闷凡人为何要发明金钱的讨价还价之中。\n\n塞纳苟斯以出人意料的耐心处理了这团乱麻，泽洛斯最终找到了一条无需永远逃亡的归途。就连那些荒唐的差事也印证了一个更大的事实：每一头散落在外的蓝龙，都有各自远离的理由。"
L["Zeros"] = "泽洛斯"
L["Information is King"] = "情报为王"
L["Blixrez Goodstitch"] = "布里克雷兹·古斯提"
L["Anyway, I Started Bribing"] = "金诚所至"
L["Zeroing Debt"] = "清偿债务"
L["Money, Money, Money!"] = "财源滚滚！"
L["Crystals Shmystals"] = "有人黑了我的水晶"
L["Settled with the Baron"] = "与大财主钱债两清"
L["The Booty Bay Journal"] = "藏宝海湾杂志"
L["Booty Bay"] = "藏宝海湾"
L["Warm Winds and Water"] = "风暖水清"
L["Kalecgos visits Kirygosa in the Jade Forest, where care, quiet work, and old friendship matter more than speeches."] = "卡雷苟斯前往翡翠林拜访姬蕾苟萨，在那里，关怀、默默的劳作和旧日的友谊比任何演说都更重要。"
L["Kirygosa's life in the Jade Forest was not a problem to solve. It was a life she had made. Kalecgos helped with carp, deliveries, and simple comforts because asking someone to come home means respecting the home they already have.\n\nThe visit became a gentle reminder that the blue dragonflight could be wider than one place. Returning did not have to mean abandoning what had healed them."] = "姬蕾苟萨在翡翠林的生活并不是一个需要解决的问题，而是她亲手建立起来的生活。卡雷苟斯帮忙捕鲤鱼、送货，打点一些简单的舒适琐事，因为邀请一个人回家，就意味着要尊重对方已经拥有的家。\n\n这次拜访温和地提醒了大家：蓝龙军团的归属可以不止一处。回归，并不一定意味着抛弃那些曾治愈过他们的东西。"
L["Carp Care"] = "照顾锦鲤"
L["Kirygosa"] = "姬蕾苟萨"
L["Self Care"] = "照顾自己"
L["Local Deliveries"] = "本地派送"
L["Up, Up, and Home"] = "翱翔回家"
L["A Drink with Kalecgos"] = "与卡雷苟斯喝一杯"
L["A Protector of Magic"] = "魔法守护者"
L["Sindragosa's simulacrum sends you to Winterspring, where Haleh and old arcane tests reconnect another piece of blue dragon history."] = "辛达苟萨的幻象派你前往冬泉谷，在那里，哈尔琳和古老的奥术试炼将蓝龙历史的又一块碎片重新连接起来。"
L["The Winterspring branch carried a colder kind of memory. Sindragosa's simulacrum guided the search, Haleh guarded her own piece of the flight's story, and the work moved through tests, artifacts, and old magic rather than open confession.\n\nStill, the pattern held. The scattered blues were not being collected. They were being remembered, respected, and invited to stand together again."] = "冬泉谷这条线索承载着一种更加冰冷的记忆。辛达苟萨的幻象指引着搜寻，哈尔琳守护着属于她自己的那段龙群往事，而这项工作依靠的是试炼、古物和古老的魔法，而非坦诚的倾诉。\n\n尽管如此，规律依然如故。那些散落各地的蓝龙并不是被收拢起来，而是被铭记、被尊重，并被邀请再次并肩而立。"
L["Winterspring"] = "冬泉谷"
L["Sindragosa"] = "辛达苟萨"
L["Test Subject"] = "测试对象"
L["Owl of a Sudden"] = "突如其来的枭兽"
L["A Wyrm Rest"] = "巨龙之憩"
L["Jade Forest"] = "翡翠林"
L["Blue is My Favorite Color"] = "蓝色是我最爱的颜色"
L["Artifacts Abound"] = "神器遍野"
L["Back with the Blues"] = "同归碧蓝"
L["Reunited Again"] = "再度团聚"
L["The final trouble at the Veiled Ossuary brings the blues home, not as Malygos left them, but as a flight ready to choose its own future."] = "雾纱藏骨堂的最后一场危机让蓝龙们回到了家——不再是玛里苟斯留下的那副模样，而是一个准备好选择自己未来的龙群。"
L["The Veiled Ossuary's final crisis forced the reunited blues to act together. Azuregos, Senegos, Sindragosa's memory, Kalecgos, and the scattered branches all carried different hurts, but they were no longer isolated by them.\n\nWhen the last conflict ended, the farewell was peaceful. The blue dragonflight did not return to the past. It stepped into a new dawn with grief acknowledged, bonds restored, and Kalecgos no longer trying to hold the flight together alone."] = "雾纱藏骨堂的最后一场危机迫使重聚的蓝龙们携手行动。艾索雷苟斯、塞纳苟斯、辛达苟萨的记忆、卡雷苟斯，以及各个散落的分支，都背负着不同的伤痛，但这些伤痛不再将他们彼此隔绝。\n\n当最后的冲突结束时，告别是平静的。蓝龙军团并没有回到过去，而是迈入了新的黎明：悲伤得到了正视，羁绊得以修复，卡雷苟斯也不再独自一人苦苦维系整个龙群。"
L["Veiled Trouble"] = "雾纱之患"
L["Veiled Ossuary Chaos"] = "雾纱藏骨堂之乱"
L["Memories of Old"] = "古老的回忆"
L["What Still Remains"] = "残余之物"
L["Swiftly to the Archives"] = "飞奔档案馆"
L["The Last Conflict"] = "最终的争斗"
L["A Peaceful Farewell"] = "平静的告别"
